/// Work staged by a sharded-table timestamp DML statement.
pub struct TimestampWritePlan {
    /// SQL command result to return after a successful timestamp commit.
    pub result: QueryResult,
    /// Row/index intents prewritten and resolved by the timestamp participant.
    pub writes: Vec<TimestampWrite>,
    /// Extra durable ops folded into the timestamp commit decision batch.
    pub commit_ops: Vec<crabka_pgkv::WriteOp>,
}

/// SP40: the foreign-table read context threaded through the SELECT pipeline.
///
/// It carries the registered scanner (the `kafka_fdw` seam) and the current
/// user, which resolves the per-user `UserMapping`. One borrowed struct holds
/// both, so the already-wide read signatures gain a single argument and not
/// two. Paths that never reach a registered scanner (`describe`, the
/// schema-only build) use `ForeignCtx::none()`. A foreign `SELECT` with no
/// scanner registered returns `0A000` ("foreign tables require the `kafka`
/// feature").
#[derive(Clone, Copy)]
pub(crate) struct ForeignCtx<'a> {
    pub scanner: Option<&'a Arc<dyn ForeignScanner>>,
    pub current_user: &'a str,
    /// The role the session authenticated as, which `SET ROLE` does not move.
    ///
    /// It rides alongside [`ForeignCtx::current_user`] because `SESSION_USER`
    /// and `CURRENT_USER` are different grantees under `SET ROLE`, and a
    /// grantee resolved from the wrong one writes the grant to the wrong role.
    pub session_user: &'a str,
    /// The session's name-resolution scope, so every DDL statement resolves an
    /// unqualified name against the same `search_path` a `SELECT` does.
    pub resolution: &'a crate::relname::ResolutionScope,
    /// The session's catalog handle, so a DDL-time expression can read the
    /// catalog. A `DEFAULT 'name'::regclass` has a relation to resolve. `None`
    /// outside a session, where such an expression keeps its 0A000.
    pub catalog: Option<&'a Arc<dyn Kv>>,
    /// Table ids the session claimed from the shared counter, drained from the
    /// back as this statement creates relations.
    ///
    /// A list rather than a single id because one statement can create many
    /// relations: `IMPORT FOREIGN SCHEMA` creates one per table the scanner
    /// discovers. `None` outside a session, where every id comes from the
    /// counter.
    pub reserved_table_ids: Option<&'a std::sync::Mutex<Vec<crabka_pgcatalog::TableId>>>,
    /// The xid of the open transaction, when this DDL runs inside one.
    ///
    /// A unique-index backfill must see the rows its OWN transaction has written
    /// but not yet committed: `BEGIN; CREATE TABLE t; INSERT …; CREATE UNIQUE
    /// INDEX ON t;` must back-validate against those rows, and the engine must
    /// reject a later insert of a duplicate. Without this the backfill scanned
    /// only committed rows, so the index was built empty and the duplicate was
    /// accepted and then committed. That left a table that violates its own
    /// unique index.
    pub own_xid: Option<u64>,
    /// The session's `row_security` GUC. `false` makes a query that a policy
    /// would have filtered fail with 42501 instead.
    ///
    /// It rides here rather than on `EvalCtx` for a reason worth keeping: this
    /// struct has two construction sites, `EvalCtx` has seventeen across nine
    /// files, and a security input that seventeen call sites must remember to
    /// set is one that some of them will not.
    pub row_security: bool,
}

impl ForeignCtx<'_> {
    /// A context with no scanner and the conventional `"public"` user, for
    /// paths that never reach a registered scanner (schema-only describe).
    pub(crate) fn none() -> Self {
        Self {
            scanner: None,
            current_user: "public",
            session_user: "public",
            resolution: crate::relname::ResolutionScope::default_scope(),
            catalog: None,
            reserved_table_ids: None,
            own_xid: None,
            row_security: true,
        }
    }

    /// The role this session acts as for ownership and row security.
    ///
    /// `PUBLIC` is a pseudo-role that owns nothing and holds no attributes; a
    /// session carrying it authenticated as nobody and is acting as the
    /// bootstrap superuser, which is the role its decisions must be made under.
    pub(crate) fn effective_role(&self) -> &str {
        if self.current_user == crabka_pgcatalog::PUBLIC_ROLE {
            crabka_pgcatalog::BOOTSTRAP_ROLE
        } else {
            self.current_user
        }
    }

    /// The next reserved id, or the shared counter when there is no block or the
    /// block is spent.
    fn table_id(&self) -> crabka_pgcatalog::TableIdSource {
        self.reserved_table_ids
            .and_then(|reserved| reserved.lock().expect("table ids").pop())
            .map_or(
                crabka_pgcatalog::TableIdSource::Counter,
                crabka_pgcatalog::TableIdSource::Reserved,
            )
    }

    /// Ownership and id allocation for a relation this statement creates. Every
    /// `CREATE` path in `execute_ddl` goes through here, so a new relation
    /// cannot acquire an owner other than the session's own without naming one.
    fn table_creation(&self) -> crabka_pgcatalog::TableCreation<'_> {
        crabka_pgcatalog::TableCreation {
            owner: self.effective_role(),
            id: self.table_id(),
            // `CREATE MATERIALIZED VIEW` builds its own `TableCreation` so it can
            // attach the query; every other creation here makes an ordinary
            // relation.
            materialized: None,
        }
    }
}

/// Map a refused blocking acquire to its statement-level error (both 40P01).
pub(crate) fn lock_acquire_error(error: crate::lockmgr::AcquireError) -> ExecError {
    match error {
        crate::lockmgr::AcquireError::Deadlock => ExecError::Deadlock,
        crate::lockmgr::AcquireError::CapExpired => ExecError::LockWaitCapExpired,
    }
}

#[derive(Clone, Copy)]
pub(crate) struct WriteContext<'a> {
    pub catalog_kv: &'a dyn Kv,
    pub kv: &'a dyn Kv,
    pub global: &'a dyn Kv,
    pub global_snapshot: &'a crabka_pgmvcc::visibility::Snapshot,
    pub procarray: &'a crate::procarray::ProcArray,
    pub lockmgr: &'a crate::lockmgr::RowLockManager,
    pub lock_owner: crate::lockmgr::LockOwner,
    pub seq: &'a crate::seq::SequenceManager,
    pub snapshot: &'a crabka_pgmvcc::visibility::Snapshot,
    pub xid: u64,
    pub repeatable_read: bool,
    pub eval_ctx: &'a crate::clock::EvalCtx,
    /// `Some(garbage horizon)` iff this statement may opportunistically prune
    /// dead versions of the rows it writes. The session computes it once per
    /// statement. A prune happens only where a row's chain was re-read under
    /// its exclusive lock, which is UPDATE, DELETE, and `INSERT … ON CONFLICT
    /// DO UPDATE`. So a plain INSERT never prunes whatever this carries. `None`
    /// disables pruning entirely, for callers with no horizon to offer. The
    /// prune deletes ride this statement's own commit batch, so they replicate
    /// and replay like any other write.
    pub prune_horizon: Option<u64>,
    /// Bound on every lock wait this statement performs (`None` waits
    /// indefinitely under the engine-local deadlock detector). Set for
    /// sessions that can be enlisted in a cross-range transaction, whose
    /// deadlock cycles span engines and are invisible to any one engine's
    /// wait-for graph.
    pub lock_wait_cap: Option<std::time::Duration>,
    /// SP40: the foreign-table read context, forwarded so a query feeding a
    /// write (`INSERT … SELECT`, `UPDATE … FROM`, `MERGE … USING`) can read
    /// through the registered scanner.
    pub fctx: ForeignCtx<'a>,
    /// The ordinary-table scanner seam the same feeding queries read through.
    pub range_scanner: &'a dyn crate::scanner::RangeScanner,
    /// Memory available to blocking reads that feed this write.
    pub blocking_query_memory: crabka_units::ByteSize,
    /// The CTE scope the statement starts from (empty for a plain statement).
    pub ctes: &'a crate::cte::CteContext,
    /// The open transaction's deferred referential checks, which the
    /// end-of-statement drain promotes into and `COMMIT` drains.
    ///
    /// `None` in autocommit, where the statement *is* the transaction: nothing
    /// is promoted, because no later statement could repair a violation and the
    /// end-of-statement drain and a commit-time one would report the same thing
    /// at the same moment.
    pub deferred_fk: Option<&'a std::sync::Mutex<crate::fk::DeferredConstraints>>,
    /// The row-security recursion guard for the queries that feed this write.
    pub policy_stack: &'a crate::rls::PolicyStack,
    /// The `WITH CHECK OPTION`s of the views this statement was rewritten
    /// through, empty for a statement that named a relation directly.
    ///
    /// It rides on the write context rather than being threaded as an argument
    /// because the rewrite hands the base-relation statement back to
    /// [`execute_write_body`], and from there the checks have to reach whichever
    /// of the seven write paths that statement takes — every one of which
    /// already builds its per-row check through [`WriteContext::row_check`].
    pub view_checks: &'a [crate::viewwrite::ViewCheck],
    /// The relation whose privileges and row-security policies decide this
    /// write, when the rows it touches are stored in a different one.
    ///
    /// `UPDATE parent` over an inheritance tree or a partitioned table writes
    /// each descendant's own storage, but `PostgreSQL` takes both decisions
    /// from the relation the statement *named*. A role holding `UPDATE` on the
    /// parent and nothing at all on a child still writes the child's rows
    /// through the parent, and the parent's policies filter those rows even
    /// when the child has row security disabled — so resolving either against
    /// the relation being physically written denies writes `PostgreSQL` allows
    /// and shows rows it hides.
    ///
    /// The qual this yields is bound by column *name* against whichever
    /// relation is actually being scanned, so a child that stores the parent's
    /// columns in a different order is still filtered on the right ones.
    ///
    /// `None` — the ordinary case — means the written relation governs itself.
    pub governing: Option<&'a Table>,
}

impl<'a> WriteContext<'a> {
    /// The relation whose ACL and policies this write answers to: the one the
    /// statement named, which is the written relation itself unless a tree
    /// write set [`WriteContext::governing`].
    fn governor<'b>(&'b self, written: &'b Table) -> &'b Table {
        self.governing.unwrap_or(written)
    }
    /// The read context a write's feeding query runs under: the write's own
    /// snapshot and xid, so it sees this transaction's earlier statements but
    /// not this statement's own (uncommitted, unwritten) rows.
    fn read_ctx<'b>(&'b self, ctes: &'b crate::cte::CteContext) -> crate::subquery::SubCtx<'b>
    where
        'a: 'b,
    {
        crate::subquery::SubCtx {
            catalog_kv: self.catalog_kv,
            kv: self.kv,
            global: self.global,
            gsnap: self.global_snapshot,
            snapshot: self.snapshot,
            own: Some(self.xid),
            ctes,
            eval_ctx: self.eval_ctx,
            fctx: self.fctx,
            range_scanner: self.range_scanner,
            blocking_query_memory: self.blocking_query_memory,
            security_role: self.fctx.effective_role(),
            policy_stack: self.policy_stack,
            refs: None,
        }
    }

    /// The row-security decision context this write makes its decisions in.
    /// The check a row this statement writes into `table` must satisfy, for the
    /// policy command the statement runs under.
    ///
    /// Also where the privilege to write that row at all is tested. Every write
    /// path already compiles a check here before it writes anything, including
    /// the `INSERT` paths that never reach `write_candidate_rows` — a plain
    /// `INSERT`, `INSERT … SELECT`, a partition-routed insert, `MERGE`'s insert
    /// action, and `COPY … FROM`. Putting the test anywhere else would mean
    /// finding all of them again.
    ///
    /// `modified` names the columns the statement supplied values for, which
    /// only matters if a check option rejects a row and the caller may not read
    /// the relation — see [`crate::rls::describe_row`].
    fn row_check(
        &self,
        table: &Table,
        command: crabka_pgcatalog::policy::PolicyCommand,
        modified: &[String],
    ) -> Result<crate::rls::WriteChecks, ExecError> {
        let governor = self.governor(table);
        crate::privilege::require(
            &self.privileges(),
            &governor.name,
            &governor.owner,
            crate::privilege::RelationKind::Table,
            crate::privilege::Privilege::for_written_row(command),
        )?;
        let security = crate::rls::RowSecurityCheck::compile(
            &self.rls(),
            governor,
            command,
            crate::rls::CheckSubject::NewRow,
        )?;
        Ok(crate::rls::WriteChecks::through_views(
            security,
            self.view_checks.to_vec(),
            modified.to_vec(),
            self.describer(),
        ))
    }

    /// The columns `target_idx` names, which is what a statement "supplied
    /// values for" — upstream's `modifiedCols`, by name so the set survives the
    /// permutation of a row into a leaf partition's own column order.
    fn modified_columns(table: &Table, target_idx: &[usize]) -> Vec<String> {
        target_idx
            .iter()
            .filter_map(|ordinal| table.columns.get(*ordinal))
            .map(|column| column.name.clone())
            .collect()
    }

    /// Whose eyes a rejected row would be described to — `CURRENT_USER`, not
    /// the role whose rights the statement borrows, for the reason
    /// [`crate::rls::Describer`] gives.
    ///
    /// `PUBLIC` normalizes to the bootstrap superuser here exactly as it does
    /// in [`ForeignCtx::effective_role`]: a session that authenticated as
    /// nobody is acting as that role, and comparing the pseudo-role against a
    /// relation's owner would answer "no" for every relation in the database.
    fn describer(&self) -> crate::rls::Describer {
        let role = if self.eval_ctx.current_user == crabka_pgcatalog::PUBLIC_ROLE {
            crabka_pgcatalog::BOOTSTRAP_ROLE
        } else {
            &self.eval_ctx.current_user
        };
        crate::rls::Describer::new(role, self.fctx.row_security)
    }

    fn rls(&self) -> crate::rls::RlsCtx<'_> {
        crate::rls::RlsCtx::new(
            self.catalog_kv,
            self.fctx.effective_role(),
            self.fctx.row_security,
        )
    }

    /// The privilege decision context this write makes its decisions in.
    fn privileges(&self) -> crate::privilege::PrivilegeCtx<'_> {
        crate::privilege::PrivilegeCtx::new(self.catalog_kv, self.fctx.effective_role())
    }
}

#[derive(Clone, Copy)]
struct MvccReadContext<'a> {
    kv: &'a dyn Kv,
    global: &'a dyn Kv,
    global_snapshot: &'a crabka_pgmvcc::visibility::Snapshot,
    snapshot: &'a crabka_pgmvcc::visibility::Snapshot,
    own: Option<u64>,
}

impl WriteContext<'_> {
    fn mvcc_read(&self) -> MvccReadContext<'_> {
        MvccReadContext {
            kv: self.kv,
            global: self.global,
            global_snapshot: self.global_snapshot,
            snapshot: self.snapshot,
            own: Some(self.xid),
        }
    }
}

struct MutationContext<'a> {
    kv: &'a dyn Kv,
    global: &'a dyn Kv,
    procarray: &'a crate::procarray::ProcArray,
    snapshot: &'a crabka_pgmvcc::visibility::Snapshot,
    xid: u64,
    repeatable_read: bool,
    /// Carried so that [`eval_plan_qual`] can fill in the virtual generated
    /// columns of the version it re-reads from storage.
    eval_ctx: &'a crate::clock::EvalCtx,
}

impl WriteContext<'_> {
    fn mutation(&self) -> MutationContext<'_> {
        MutationContext {
            kv: self.kv,
            global: self.global,
            procarray: self.procarray,
            snapshot: self.snapshot,
            xid: self.xid,
            repeatable_read: self.repeatable_read,
            eval_ctx: self.eval_ctx,
        }
    }

    /// [`WriteContext::mutation`] reading through the statement's pending write
    /// batch layered over the store.
    ///
    /// The one caller is a referential action's re-read of the row it is about
    /// to change. `PostgreSQL` runs the action as a query of its own, once the
    /// command's rows exist, so the version it operates on is the one the
    /// command itself last wrote, an image that is only staged here. A read of
    /// the store instead would stamp a version the command has already
    /// superseded and leave its replacement live.
    fn staged_mutation<'b>(&'b self, staged: &'b StagedKv<'b>) -> MutationContext<'b> {
        MutationContext {
            kv: staged,
            ..self.mutation()
        }
    }
}

/// Read a table's durable next-rowid (1 if unset). Single source of truth for
/// the sequence read.
pub(crate) fn read_seq_kv(kv: &dyn Kv, table: TableId) -> Result<u64, ExecError> {
    match kv.get(&crabka_pgkv::key::seq_key(table))? {
        Some(b) => {
            let (v, _) = U64::read_from_prefix(b.as_slice())
                .map_err(|_| crabka_pgkv::KvError::CorruptRow("sequence is not u64".into()))?;
            Ok(v.get())
        }
        None => Ok(1),
    }
}

/// DDL (CREATE/DROP TABLE) reads the catalog and builds its write batch WITHOUT
/// persisting it. The session routes the returned ops through the durable-write
/// seam, so DDL replicates too. The session holds the catalog lock across the
/// read and the commit, which serializes DDL globally. Non-DDL is unreachable
/// here, because `run_one` routes it, but this handles it defensively to keep
/// the match total. Validation (42P07 on duplicate, 42P01 on a missing drop) is
/// unchanged. Only the write destination moved.
pub(crate) fn execute_ddl(
    kv: &dyn Kv,
    stmt: &Statement,
    fctx: ForeignCtx,
) -> Result<(QueryResult, Vec<crabka_pgkv::WriteOp>), ExecError> {
    let resolution = fctx.resolution;
    match stmt {
        Statement::Utility(UtilityStatement::TextSearch(ddl)) => {
            let (tag, ops) = crate::text_search_catalog::execute(kv, ddl)?;
            Ok((command(tag), ops))
        }
        Statement::CreateTrigger(trigger) => {
            let table =
                resolve_relation(kv, resolution, &trigger.table, SchemaDisposition::Reference)?;
            let referenced = trigger
                .referenced_table
                .as_ref()
                .map(|name| resolve_relation(kv, resolution, name, SchemaDisposition::Reference))
                .transpose()?;
            crate::trigger::create(kv, trigger, table, referenced)
        }
        Statement::AlterTrigger {
            name,
            table,
            action,
        } => crate::trigger::alter(
            kv,
            name,
            resolve_relation(kv, resolution, table, SchemaDisposition::Reference)?,
            action,
        ),
        Statement::DropTrigger {
            name,
            table,
            if_exists,
            ..
        } => crate::trigger::drop(
            kv,
            name,
            resolve_relation(kv, resolution, table, SchemaDisposition::Reference)?,
            *if_exists,
        ),
        Statement::CreatePolicy(policy) => crate::policy_ddl::create(
            kv,
            policy,
            resolve_relation(kv, resolution, &policy.table, SchemaDisposition::Reference)?,
            fctx,
        ),
        Statement::AlterPolicy {
            name,
            table,
            action,
        } => crate::policy_ddl::alter(
            kv,
            name,
            resolve_relation(kv, resolution, table, SchemaDisposition::Reference)?,
            action,
            fctx,
        ),
        Statement::DropPolicy {
            name,
            table,
            if_exists,
            ..
        } => crate::policy_ddl::drop(
            kv,
            name,
            resolve_relation(kv, resolution, table, SchemaDisposition::Reference)?,
            *if_exists,
            fctx,
        ),
        Statement::CreateEventTrigger(trigger) => {
            crate::trigger::create_event(kv, trigger, fctx.current_user)
        }
        Statement::AlterEventTrigger { name, action } => {
            crate::trigger::alter_event(kv, name, action)
        }
        Statement::DropEventTrigger {
            name, if_exists, ..
        } => crate::trigger::drop_event(kv, name, *if_exists),
        // P2: SQL routines. Definition, lifecycle and catalog storage live in
        // `routine`; only the DDL routing is here.
        Statement::CreateRoutine(routine) => crate::routine::create(kv, routine, fctx.current_user),
        Statement::DropRoutine {
            object,
            if_exists,
            routines,
            cascade,
        } => crate::routine::drop_routines(kv, *object, *if_exists, routines, *cascade),
        Statement::AlterRoutine {
            object,
            routine,
            action,
        } => crate::routine::alter(kv, *object, routine, action),
        // P6: user-defined aggregates. Stored as routines, so only the
        // definition-time rules and the aggregate evaluator are new.
        Statement::CreateAggregate(aggregate) => {
            crate::useragg::create(kv, aggregate, fctx.current_user)
        }
        Statement::DropAggregate {
            if_exists,
            aggregates,
            cascade,
        } => crate::useragg::drop_aggregates(kv, *if_exists, aggregates, *cascade),
        Statement::AlterAggregate { aggregate, action } => {
            crate::useragg::alter(kv, aggregate, action)
        }
        // T5: user-defined types. Definition, lifecycle and catalog storage
        // live in `usertype`; only the DDL routing is here.
        Statement::CreateType { name, definition } => crate::usertype::create_type(
            kv,
            resolution,
            &resolve_relation(kv, resolution, name, SchemaDisposition::Creation)?,
            definition,
        ),
        Statement::AlterType { name, action } => {
            crate::usertype::alter_type(kv, &resolve_user_type(kv, resolution, name)?, action)
        }
        Statement::DropType {
            names,
            if_exists,
            cascade,
        } => crate::usertype::drop_types(
            kv,
            &resolve_user_types(kv, resolution, names)?,
            *if_exists,
            *cascade,
            false,
        ),
        Statement::CreateDomain {
            name,
            base,
            collation,
            constraints,
        } => {
            // The collation itself has no effect — every collation the engine
            // has orders text by byte value — but writing one over a base type
            // that cannot carry one is PostgreSQL's 42804, reported before the
            // domain is created.
            if collation.is_some() {
                crate::eval::require_collatable(*base)?;
            }
            crate::usertype::create_domain(
                kv,
                &resolve_relation(kv, resolution, name, SchemaDisposition::Creation)?,
                *base,
                constraints,
            )
        }
        Statement::AlterDomain { name, action } => {
            crate::usertype::alter_domain(kv, &resolve_user_type(kv, resolution, name)?, action)
        }
        Statement::DropDomain {
            names,
            if_exists,
            cascade,
        } => crate::usertype::drop_types(
            kv,
            &resolve_user_types(kv, resolution, names)?,
            *if_exists,
            *cascade,
            true,
        ),
        Statement::CreateTable {
            name,
            columns,
            constraints,
            sharded,
            sharding,
            if_not_exists,
            temporary,
            like,
            inherits,
            on_commit,
            partition_by,
            partition_of,
            tablespace,
        } => {
            if (partition_by.is_some() || partition_of.is_some()) && *sharded {
                return Err(crate::partition::reject_sharded_partitioned());
            }
            let disposition = if *temporary {
                SchemaDisposition::TemporaryCreation
            } else {
                SchemaDisposition::Creation
            };
            let name = &resolve_relation(kv, resolution, name, disposition)?;
            // `CREATE TABLE pg_temp.t` and a `search_path` whose creation slot
            // is the temporary namespace both make a temporary relation without
            // the keyword, so persistence follows the schema the name landed in
            // rather than the keyword that was written.
            let temporary = crabka_pgcatalog::is_temp_schema(&name.schema);
            if on_commit.is_some() && !temporary {
                return Err(ExecError::InvalidTableDefinition(
                    "ON COMMIT can only be used on temporary tables".into(),
                ));
            }
            if *if_not_exists && crabka_pgcatalog::get_table(kv, name).is_ok() {
                return Ok((command("CREATE TABLE"), Vec::new()));
            }
            crate::usertype::ensure_relation_type_name_available(kv, name)?;
            let ddl_ctx = crate::clock::EvalCtx::for_ddl(resolution, fctx.catalog);
            let inheritance_parents = inherits
                .iter()
                .map(|parent| {
                    resolve_relation(kv, resolution, parent, SchemaDisposition::Reference)
                })
                .collect::<Result<Vec<_>, _>>()?;
            // A partition declares no columns of its own: it inherits the
            // parent's list, along with the parent's CHECK constraints, and may
            // only add qualifiers to what it inherits.
            let (cols, checks, serial_sequences, pending_indexes, pending_foreign_keys) =
                match partition_of {
                    Some(spec) => {
                        partition_definition(kv, name, spec, constraints, like, &ddl_ctx)?
                    }
                    None if inheritance_parents.is_empty() => create_table_definition(
                        kv,
                        name,
                        columns,
                        constraints,
                        like,
                        &[],
                        &ddl_ctx,
                    )?,
                    None => inherited_table_definition(
                        kv,
                        name,
                        &inheritance_parents,
                        columns,
                        constraints,
                        like,
                        &ddl_ctx,
                    )?,
                };
            // `fk::resolve_foreign_key` refuses a sharded relation itself, but
            // `Table` carries no partition flag, so this is the only place that
            // knows a partitioned relation is being defined.
            if (partition_by.is_some() || partition_of.is_some())
                && let Some(pending) = pending_foreign_keys.first()
            {
                return Err(reject_partitioned_foreign_key(&pending.name));
            }
            let partition_scheme = partition_by
                .as_ref()
                .map(|spec| partition_scheme_from_ast(spec, &cols, &pending_indexes))
                .transpose()?;
            let attachment = partition_of
                .as_ref()
                .map(|spec| partition_attachment(kv, name, spec, &cols, &ddl_ctx))
                .transpose()?;
            if *sharded && !pending_indexes.is_empty() {
                return Err(ExecError::Unsupported(
                    "PRIMARY KEY and UNIQUE constraints on sharded tables are not supported until global enforcement exists".into(),
                ));
            }
            let sharding = sharding.as_ref().map(hash_sharding_from_ast).transpose()?;
            ensure_hash_shard_key_types_are_supported(&cols, sharding.as_ref())?;
            let (id, mut ops) = crabka_pgcatalog::create_table_with_sharding_ops(
                kv,
                name,
                cols.clone(),
                crabka_pgcatalog::TableOptions {
                    sharded: *sharded,
                    row_security: false,
                    force_row_security: false,
                },
                sharding.as_ref(),
                checks.clone(),
                fctx.table_creation(),
            )?;
            if let Some(tablespace) = tablespace {
                let oid = resolve_relation_tablespace_oid(kv, tablespace)?;
                ops.push(crabka_pgcatalog::set_relation_tablespace_op(name, oid));
            }
            let table = crabka_pgcatalog::Table {
                id,
                name: name.clone(),
                owner: fctx.effective_role().to_string(),
                columns: cols,
                sharded: *sharded,
                row_security: false,
                force_row_security: false,
                sharding,
                foreign: None,
                materialized: None,
                checks,
            };
            for index in &pending_indexes {
                if !matches!(
                    index.method,
                    crabka_pgcatalog::IndexMethod::Btree | crabka_pgcatalog::IndexMethod::Hash
                ) {
                    continue;
                }
                for column in &index.columns {
                    let column = table
                        .columns
                        .iter()
                        .find(|candidate| candidate.name == *column)
                        .ok_or_else(|| ExecError::UndefinedColumn(column.clone()))?;
                    validate_default_index_opclass(column.ty, index.method)?;
                }
            }
            let index_ops =
                crabka_pgcatalog::create_indexes_on_table_ops(kv, &table, &pending_indexes)?;
            let staged_indexes = staged_indexes_of(&index_ops, &pending_indexes);
            ops.extend(index_ops);
            if !pending_foreign_keys.is_empty() {
                // Resolved here rather than in `create_table_definition`
                // because `CREATE TABLE t (… REFERENCES t …)` names a relation
                // no catalog read can find: the in-flight column and index
                // lists, under the ids this batch allocates, are the parent.
                let relation = crate::fk::FkRelation {
                    id,
                    name,
                    columns: &table.columns,
                    indexes: &staged_indexes,
                    sharded: *sharded,
                };
                // One cursor for the whole statement: every clause reads the
                // same stored counter, so the ids have to ascend in memory or
                // two constraints on one column would tie.
                let mut foreign_key_ids = crabka_pgcatalog::ForeignKeyIds::default();
                for pending in &pending_foreign_keys {
                    let foreign_key = crate::fk::resolve_foreign_key(
                        kv,
                        resolution,
                        &relation,
                        &crate::fk::ForeignKeyRequest {
                            id: foreign_key_ids.allocate(kv)?,
                            name: Some(&pending.name),
                            columns: &pending.columns,
                            reference: &pending.reference,
                            attributes: pending.attributes,
                            // PostgreSQL ignores NOT VALID here: a relation
                            // being created has no stored rows to validate.
                            validated: true,
                            self_reference: Some(&relation),
                        },
                    )?;
                    ops.extend(crabka_pgcatalog::create_foreign_key_ops(kv, &foreign_key)?);
                }
            }
            for (sequence_name, sequence) in serial_sequences {
                ops.extend(crabka_pgcatalog::create_sequence_ops(
                    kv,
                    &sequence_name,
                    sequence,
                )?);
            }
            if let Some(scheme) = &partition_scheme {
                ops.extend(crate::partition::put_scheme_ops(name, scheme));
            }
            if let Some((parent, bound)) = &attachment {
                ops.extend(crate::partition::attach_ops(parent, name, bound));
                let parent = crabka_pgcatalog::get_table(kv, parent)?;
                ops.extend(crate::trigger::clone_new_partition_triggers(
                    kv, &parent, &table,
                )?);
            }
            if !inheritance_parents.is_empty() {
                ops.extend(crate::inheritance::attach_ops(name, &inheritance_parents));
            }
            if temporary {
                ops.splice(..0, ensure_schema_ops(kv, &name.schema)?);
            }
            Ok((
                QueryResult::Command {
                    tag: "CREATE TABLE".into(),
                },
                ops,
            ))
        }
        Statement::DropTable {
            names,
            if_exists,
            cascade,
        } => {
            // All-or-nothing across the name list, matching PostgreSQL: ops are
            // only applied after every name resolves (or is skipped by
            // IF EXISTS), so a missing name without IF EXISTS drops nothing.
            let mut ops = Vec::new();
            let mut tag = "DROP TABLE";
            // A foreign key whose CHILD is itself being dropped never blocks:
            // `DROP TABLE p, c` and a mutually referencing pair dropped together
            // both succeed. The whole set is resolved before any name is
            // processed, because the list is all-or-nothing.
            // `DROP SEQUENCE` reaches this arm with its names tagged. The tag
            // rides the relation's own name, so it comes off before the
            // qualifier is resolved and goes back on afterwards: `DROP SEQUENCE
            // public.s` has to reach the same sequence as `DROP SEQUENCE s`.
            let mut targets = Vec::with_capacity(names.len());
            for reference in names {
                let tagged = reference.name.strip_prefix("__crabka_sequence__:");
                let bare = crabka_pgparser::ast::RelationRef {
                    schema: reference.schema.clone(),
                    name: tagged.unwrap_or(&reference.name).to_string(),
                };
                match resolve_relation(kv, resolution, &bare, SchemaDisposition::Utility) {
                    Ok(resolved) => targets.push((resolved, tagged.is_some())),
                    // `DROP TABLE IF EXISTS nope.t` skips that one name and
                    // still drops the rest of the list, as PostgreSQL does.
                    Err(error) if *if_exists && is_missing_schema(&error) => {}
                    Err(error) => return Err(error),
                }
            }
            let dropping: std::collections::HashSet<_> =
                targets.iter().map(|(name, _)| name.clone()).collect();
            // What the statement takes away, which is more than what it names:
            // a partition goes with its parent. The inheritance links are
            // settled against this whole set once the loop below has run, so
            // that a child of two departing parents is rewritten from the set
            // rather than once per parent.
            let mut removed = dropping.clone();
            for (name, is_sequence) in &targets {
                if !is_sequence {
                    removed.extend(crate::partition::descendants(kv, name)?);
                }
            }
            for (name, is_sequence) in &targets {
                if *is_sequence {
                    tag = "DROP SEQUENCE";
                    if let Some(error) = drop_kind_mismatch(kv, name, "sequence") {
                        return Err(error);
                    }
                    match crabka_pgcatalog::drop_sequence_ops(kv, name) {
                        Ok(sequence_ops) => ops.extend(sequence_ops),
                        Err(crabka_pgcatalog::CatalogError::UndefinedSequence(_)) if *if_exists => {
                        }
                        Err(error) => return Err(error.into()),
                    }
                } else {
                    // A relation of another kind is 42809 whether or not
                    // IF EXISTS was written: the relation exists, so there is
                    // nothing for IF EXISTS to waive.
                    if let Some(error) = drop_kind_mismatch(kv, name, "table") {
                        return Err(error);
                    }
                    // The kind matched, so a synthesised catalog relation that
                    // reaches here is a system catalog, and `PostgreSQL`'s
                    // `DropErrorMsgWrongType` has already had its say: what is
                    // left is the privilege refusal, which `IF EXISTS` does not
                    // waive either.
                    if let Some(error) = system_catalog_wrong_kind(name) {
                        return Err(error);
                    }
                    match crabka_pgcatalog::get_table(kv, name) {
                        Ok(table) => ops.extend(drop_table_and_dependents_ops(
                            kv, &table, &dropping, *cascade,
                        )?),
                        Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) if *if_exists => {}
                        Err(crabka_pgcatalog::CatalogError::UndefinedTable(missing)) => {
                            return Err(ExecError::UndefinedRelationOfKind {
                                kind: "table",
                                name: missing,
                            });
                        }
                        Err(error) => return Err(error.into()),
                    }
                }
            }
            ops.extend(crate::inheritance::drop_metadata_ops(kv, &removed)?);
            Ok((command(tag), ops))
        }
        Statement::CreateSchema {
            name,
            authorization,
            if_not_exists,
            elements,
        } => {
            // `CREATE SCHEMA AUTHORIZATION role` names the schema after the
            // role, so the keyword spellings have to be resolved before the
            // name is taken: `AUTHORIZATION CURRENT_ROLE` names the schema
            // after the session's role, not after the word `current_role`.
            let owner = match authorization {
                Some(spec) => resolve_new_owner(kv, fctx, spec)?,
                None => fctx.current_user.to_string(),
            };
            let name = match name {
                Some(name) => name.clone(),
                None => owner.clone(),
            };
            if !elements.is_empty() {
                return Err(ExecError::Unsupported(
                    "CREATE SCHEMA with a schema-element list is not supported: DDL commits one \
                     catalog batch at a time here, so the schema and its contents could not be \
                     created atomically"
                        .into(),
                ));
            }
            // `IF NOT EXISTS` waives only the duplicate: an unacceptable name is
            // still unacceptable, so the reserved-prefix refusal has to come out
            // of `create_schema_ops` rather than be short-circuited before it.
            let ops = match crabka_pgcatalog::create_schema_ops(kv, &name, &owner) {
                Err(crabka_pgcatalog::CatalogError::DuplicateSchema(_)) if *if_not_exists => {
                    Vec::new()
                }
                result => result?,
            };
            Ok((command("CREATE SCHEMA"), ops))
        }
        Statement::AlterSchema { name, action } => {
            use crabka_pgparser::ast::AlterSchemaAction;
            let ops = match action {
                AlterSchemaAction::OwnerTo(owner) => {
                    // A schema's new owner is checked the way a relation's is.
                    // Before this shared a resolver with `ALTER TABLE`, a
                    // schema could be handed to a name no role held, leaving it
                    // owned by something no ownership test can match.
                    let owner = resolve_new_owner(kv, fctx, owner)?;
                    crabka_pgcatalog::set_schema_owner_ops(kv, name, &owner)?
                }
                AlterSchemaAction::RenameTo(_) => {
                    if !crabka_pgcatalog::schema_exists(kv, name)? {
                        return Err(ExecError::Catalog(
                            crabka_pgcatalog::CatalogError::UndefinedSchema(name.clone()),
                        ));
                    }
                    return Err(ExecError::Unsupported(
                        "ALTER SCHEMA … RENAME TO is not supported: a relation's catalog name \
                         carries its schema, so the rename would have to move every relation key \
                         in the schema"
                            .into(),
                    ));
                }
            };
            Ok((command("ALTER SCHEMA"), ops))
        }
        Statement::DropSchema {
            names,
            if_exists,
            cascade,
        } => {
            let mut schemas = Vec::new();
            for name in names {
                if *if_exists && !crabka_pgcatalog::schema_exists(kv, name)? {
                    continue;
                }
                schemas.push((name, crabka_pgcatalog::drop_schema_ops(kv, name, *cascade)?));
            }
            let mut ops = Vec::new();
            for (name, schema_ops) in schemas {
                if *cascade {
                    ops.extend(drop_schema_contents_ops(kv, name)?);
                }
                ops.extend(schema_ops);
            }
            Ok((command("DROP SCHEMA"), ops))
        }
        Statement::AlterTable {
            table,
            if_exists,
            only,
            actions,
        } => match resolve_relation(kv, resolution, table, SchemaDisposition::Utility) {
            Ok(name) => alter_table_ops(kv, &name, *if_exists, *only, actions, fctx),
            // `ALTER TABLE IF EXISTS nope.t` skips rather than reporting the
            // schema, as PostgreSQL does.
            Err(error) if *if_exists && is_missing_schema(&error) => {
                Ok((command("ALTER TABLE"), Vec::new()))
            }
            Err(error) => Err(error),
        },
        Statement::Comment {
            object_kind,
            object_name,
            comment,
        } => comment_ops(kv, resolution, object_kind, object_name, comment.as_deref()),
        Statement::CreateView {
            name,
            definition,
            query,
            or_replace,
            temporary,
            columns: aliases,
            options,
        } => {
            // The body is analysed before the view's own name is placed,
            // because what it reads decides where the view can go: a view over
            // a temporary relation is itself temporary whether or not `TEMP`
            // was written, so a qualifier naming an ordinary schema is refused.
            // `postgres:18.4` reports the two in that order.
            let sources = validate_view_definition(kv, resolution, query)?;
            let temporary = *temporary
                || sources
                    .iter()
                    .any(|source| crabka_pgcatalog::is_temp_schema(&source.schema));
            let disposition = if temporary {
                SchemaDisposition::TemporaryCreation
            } else {
                SchemaDisposition::Creation
            };
            let name = &resolve_relation(kv, resolution, name, disposition)?;
            crate::usertype::ensure_relation_type_name_available(kv, name)?;
            let described = crate::query::describe_query_expr(kv, resolution, query)?;
            // `VIEW name (a, b, c)` renames the output columns positionally; too
            // many names is PostgreSQL's own 42P10.
            if let Some(aliases) = aliases
                && aliases.len() > described.len()
            {
                return Err(ExecError::InvalidColumnReference(
                    "CREATE VIEW specifies more column names than columns".into(),
                ));
            }
            let columns = described
                .into_iter()
                .enumerate()
                .map(|(index, field)| {
                    let name = aliases
                        .as_ref()
                        .and_then(|aliases| aliases.get(index).cloned())
                        .unwrap_or(field.name);
                    Ok(Column::new(name, column_type_from_oid(field.type_oid)?))
                })
                .collect::<Result<Vec<_>, ExecError>>()?;
            // Two output columns of the same name would define a relation whose
            // columns cannot be told apart, so PostgreSQL refuses the view (42701)
            // before creating anything — the same rule `CREATE TABLE AS` applies.
            let mut seen = std::collections::HashSet::new();
            for column in &columns {
                if !seen.insert(column.name.as_str()) {
                    return Err(ExecError::DuplicateOutputColumn(column.name.clone()));
                }
            }
            // `OR REPLACE` over an existing VIEW redefines it in place, provided
            // the new query keeps every existing output column. A non-view
            // relation of that name is still 42P07, as it is without OR REPLACE.
            let options = crabka_pgcatalog::ViewOptions {
                security_invoker: options.security_invoker,
                security_barrier: options.security_barrier,
                check_option: options.check_option.map(catalog_check_option),
            };
            // A check option is a promise about writes, so it may only be made
            // by a view writes can be rewritten through. PostgreSQL raises this
            // at CREATE time rather than leaving a view whose option can never
            // fire, and puts the disqualifying clause in the HINT.
            if options.check_option.is_some()
                && let Some(detail) = crate::viewwrite::query_refusal(query)
            {
                return Err(ExecError::CheckOptionUnsupported(detail));
            }
            let ops = if *or_replace && crabka_pgcatalog::get_view(kv, name).is_ok() {
                let existing = crabka_pgcatalog::get_view(kv, name)?;
                check_view_columns_replaceable(&existing.columns, &columns, name)?;
                // `OR REPLACE` redefines a view rather than creating one, so it
                // keeps the owner it already had — PostgreSQL's `CREATE OR
                // REPLACE VIEW` does not transfer ownership, and letting it
                // would let anyone who may replace a view also take its grants.
                vec![crabka_pgcatalog::put_view_op(&crabka_pgcatalog::View {
                    name: name.clone(),
                    definition: definition.clone(),
                    owner: existing.owner,
                    columns,
                    options,
                })]
            } else {
                let mut created = ensure_schema_ops(kv, &name.schema)?;
                created.extend(crabka_pgcatalog::create_view_ops(
                    kv,
                    name,
                    definition.clone(),
                    columns,
                    options,
                    fctx.effective_role(),
                )?);
                created
            };
            Ok((command("CREATE VIEW"), ops))
        }
        Statement::DropView {
            name,
            if_exists,
            cascade,
        } => {
            let name = &match resolve_relation(kv, resolution, name, SchemaDisposition::Utility) {
                Ok(name) => name,
                Err(error) if *if_exists && is_missing_schema(&error) => {
                    return Ok((command("DROP VIEW"), Vec::new()));
                }
                Err(error) => return Err(error),
            };
            if let Some(error) = drop_kind_mismatch(kv, name, "view") {
                return Err(error);
            }
            let ops = match drop_view_with_triggers_ops(kv, name) {
                Ok(mut ops) => {
                    // A view may itself be read by other views. PostgreSQL
                    // refuses the drop unless CASCADE is written, and then drops
                    // the dependents too.
                    let dependents = dependent_view_chain(kv, name, None)?;
                    if !dependents.is_empty() {
                        if !*cascade {
                            return Err(dependent_objects_error(
                                kv,
                                &format!(
                                    "cannot drop view {name} because other objects depend on it"
                                ),
                                &dependents,
                            ));
                        }
                        for (view, _) in &dependents {
                            ops.extend(drop_dependent_relation_ops(kv, view)?);
                        }
                    }
                    ops
                }
                Err(ExecError::Catalog(crabka_pgcatalog::CatalogError::UndefinedTable(_)))
                    if *if_exists =>
                {
                    Vec::new()
                }
                Err(error) => return Err(error),
            };
            Ok((command("DROP VIEW"), ops))
        }
        // The relation half of `CREATE MATERIALIZED VIEW`: the heap, its column
        // list, and the query it will be refilled from, created unpopulated. The
        // session drives the data half — running the query and flipping the
        // flag — because that is a write, and DDL here commits one catalog batch
        // that cannot also carry rows.
        Statement::CreateMaterializedView {
            name,
            if_not_exists,
            columns: aliases,
            definition,
            query,
            tablespace,
            with_data: _,
        } => {
            let _ = tablespace;
            let name = &resolve_relation(kv, resolution, name, SchemaDisposition::Creation)?;
            if *if_not_exists && crabka_pgcatalog::get_table(kv, name).is_ok() {
                return Ok((command("CREATE MATERIALIZED VIEW"), Vec::new()));
            }
            crate::usertype::ensure_relation_type_name_available(kv, name)?;
            let described = crate::query::describe_query_expr(kv, resolution, query)?;
            if let Some(aliases) = aliases
                && aliases.len() > described.len()
            {
                return Err(ExecError::Syntax(
                    "too many column names were specified".into(),
                ));
            }
            let columns = described
                .into_iter()
                .enumerate()
                .map(|(index, field)| {
                    let name = aliases
                        .as_ref()
                        .and_then(|aliases| aliases.get(index).cloned())
                        .unwrap_or(field.name);
                    Ok(Column::new(name, column_type_from_oid(field.type_oid)?))
                })
                .collect::<Result<Vec<_>, ExecError>>()?;
            let mut seen = std::collections::HashSet::new();
            for column in &columns {
                if !seen.insert(column.name.as_str()) {
                    return Err(ExecError::DuplicateOutputColumn(column.name.clone()));
                }
            }
            // Created unpopulated whatever `WITH DATA` said: the flag is what
            // makes a scan legal, and it is only true once the rows are actually
            // there. A `WITH DATA` create that fails partway therefore leaves
            // nothing readable rather than an empty relation claiming to hold
            // the query's answer.
            // The text as written is stored, exactly as `CREATE VIEW` stores
            // its own: `REFRESH` re-runs it, so whatever schema qualification
            // the author supplied has to survive to be re-resolved.
            let matview = crabka_pgcatalog::MaterializedView {
                definition: definition.clone(),
                populated: false,
            };
            let mut ops = ensure_schema_ops(kv, &name.schema)?;
            let (_, created) = crabka_pgcatalog::create_table_with_options_ops(
                kv,
                name,
                columns,
                crabka_pgcatalog::TableOptions::default(),
                Vec::new(),
                crabka_pgcatalog::TableCreation {
                    owner: fctx.effective_role(),
                    id: fctx.table_id(),
                    materialized: Some(&matview),
                },
            )?;
            ops.extend(created);
            Ok((command("CREATE MATERIALIZED VIEW"), ops))
        }
        // The catalog half of `REFRESH MATERIALIZED VIEW`: the population flag,
        // nothing else. The session has already emptied and (for `WITH DATA`)
        // refilled the heap, so this is what makes the new contents readable —
        // or, for `WITH NO DATA`, what makes the emptied relation an error to
        // scan rather than a relation that answers zero rows.
        Statement::RefreshMaterializedView {
            name,
            concurrently: _,
            with_data,
        } => {
            let name = &resolve_relation(kv, resolution, name, SchemaDisposition::Utility)?;
            let table = require_materialized_view(kv, name)?;
            Ok((
                command("REFRESH MATERIALIZED VIEW"),
                vec![crabka_pgcatalog::set_materialized_populated_op(
                    &table, *with_data,
                )],
            ))
        }
        // A materialized view is a stored relation, so it drops through the
        // table batteries — the heap, its indexes and its privileges all have to
        // go — while the *name* it answers to is checked against `relkind` first,
        // exactly as `DROP TABLE` and `DROP VIEW` check theirs.
        Statement::DropMaterializedView {
            names,
            if_exists,
            cascade,
        } => {
            let mut targets = Vec::with_capacity(names.len());
            for reference in names {
                match resolve_relation(kv, resolution, reference, SchemaDisposition::Utility) {
                    Ok(resolved) => targets.push(resolved),
                    Err(error) if *if_exists && is_missing_schema(&error) => {}
                    Err(error) => return Err(error),
                }
            }
            let dropping: std::collections::HashSet<_> = targets.iter().cloned().collect();
            let mut ops = Vec::new();
            for name in &targets {
                if let Some(error) = drop_kind_mismatch(kv, name, "materialized view") {
                    return Err(error);
                }
                match crabka_pgcatalog::get_table(kv, name) {
                    Ok(table) => ops.extend(drop_table_and_dependents_ops(
                        kv, &table, &dropping, *cascade,
                    )?),
                    Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) if *if_exists => {}
                    Err(crabka_pgcatalog::CatalogError::UndefinedTable(missing)) => {
                        return Err(ExecError::UndefinedRelationOfKind {
                            kind: "materialized view",
                            name: missing,
                        });
                    }
                    Err(error) => return Err(error.into()),
                }
            }
            // No syntax makes a materialized view inherit, be inherited from, or
            // be partitioned, so the targets are the whole removal set and this
            // sweep finds nothing. It stays because dropping a stored relation
            // without it is the mistake this batch exists to prevent, and one
            // statement quietly exempt from it is how that mistake returns.
            ops.extend(crate::inheritance::drop_metadata_ops(kv, &dropping)?);
            Ok((command("DROP MATERIALIZED VIEW"), ops))
        }
        Statement::CreateIndex {
            name,
            table,
            keys,
            unique,
            placement,
            if_not_exists,
            concurrently,
            method,
            include,
            predicate,
            tablespace,
        } => {
            let _ = concurrently;
            // `CREATE SEQUENCE` borrows this variant, naming the sequence in
            // `name` and tagging `table` with a sentinel no relation can carry.
            if table.schema.is_none() && table.name == "__crabka_sequence__" {
                let encoded: Vec<String> = keys.iter().map(|key| key.text.clone()).collect();
                let sequence = sequence_from_encoded_options(&encoded)?;
                let name = name
                    .as_ref()
                    .ok_or_else(|| ExecError::Syntax("CREATE SEQUENCE requires a name".into()))?;
                let name = &resolve_relation(kv, resolution, name, SchemaDisposition::Creation)?;
                if *if_not_exists && crabka_pgcatalog::get_sequence(kv, name).is_ok() {
                    return Ok((command("CREATE SEQUENCE"), Vec::new()));
                }
                crate::usertype::ensure_relation_type_name_available(kv, name)?;
                let ops = crabka_pgcatalog::create_sequence_ops(kv, name, sequence)?;
                return Ok((command("CREATE SEQUENCE"), ops));
            }
            let table = &resolve_relation(kv, resolution, table, SchemaDisposition::Utility)?;
            // `DefineIndex` opens the relation, refuses the relkinds that carry
            // no index, and only then consults `allowSystemTableMods`, so the
            // kind is reported ahead of the privilege for a relation that is
            // both.
            if let Some(error) = create_index_wrong_kind(kv, table) {
                return Err(error);
            }
            if let Some(error) = system_catalog_wrong_kind(table) {
                return Err(error);
            }
            // An index name is never qualified: an index lands in its table's
            // schema, so only the sequence spelling above can carry one.
            let index = name
                .as_ref()
                .map(|name| resolve_relation(kv, resolution, name, SchemaDisposition::Utility))
                .transpose()?;
            let name = table.sibling(index_name_or_default(
                index.as_ref().map(|name| name.name.as_str()),
                table,
                keys,
            ));
            let index_method = match method.as_deref() {
                None | Some("btree") => crabka_pgcatalog::IndexMethod::Btree,
                Some("hash") => crabka_pgcatalog::IndexMethod::Hash,
                Some("gist") => crabka_pgcatalog::IndexMethod::Gist,
                Some("gin") => crabka_pgcatalog::IndexMethod::Gin,
                Some("spgist") => crabka_pgcatalog::IndexMethod::Spgist,
                Some(method) => {
                    return Err(ExecError::Unsupported(format!(
                        "index access method \"{method}\" is not supported"
                    )));
                }
            };
            let columns = index_key_columns(keys, predicate.as_deref())?;
            if !include.is_empty() {
                return Err(ExecError::Unsupported(
                    "CREATE INDEX … INCLUDE is not supported: index entries carry only key \
                     columns"
                        .into(),
                ));
            }
            if *if_not_exists && crabka_pgcatalog::get_index(kv, &name).is_ok() {
                return Ok((command("CREATE INDEX"), Vec::new()));
            }
            crate::usertype::ensure_index_name_available(kv, &name)?;
            let name = &name;
            let columns = &columns;
            let placement = match placement {
                crabka_pgparser::ast::IndexPlacement::Local => {
                    crabka_pgcatalog::IndexPlacement::Local
                }
                crabka_pgparser::ast::IndexPlacement::Global => {
                    crabka_pgcatalog::IndexPlacement::Global
                }
            };
            if *unique && placement == crabka_pgcatalog::IndexPlacement::Global {
                return Err(ExecError::Unsupported(
                    "unique global indexes are not supported until global enforcement exists"
                        .into(),
                ));
            }
            let table_meta = crabka_pgcatalog::get_table(kv, table)?;
            reject_index_over_virtual_generated(&table_meta, columns, None)?;
            validate_index_opclasses(kv, resolution, &table_meta, keys, index_method)?;
            validate_index_expressions(&table_meta, keys, *unique, placement, index_method)?;
            validate_index_method(&table_meta, columns, *unique, placement, index_method)?;
            let (id, mut ops) = crabka_pgcatalog::create_index_with_method_ops(
                kv,
                &name.name,
                table,
                columns.clone(),
                *unique,
                placement,
                index_method,
            )?;
            if let Some(tablespace) = tablespace {
                let oid = resolve_relation_tablespace_oid(kv, tablespace)?;
                ops.push(crabka_pgcatalog::set_relation_tablespace_op(name, oid));
            }
            if placement == crabka_pgcatalog::IndexPlacement::Local {
                reject_unwritable_local_index(&table_meta)?;
                let index = crabka_pgcatalog::Index {
                    id,
                    name: name.name.clone(),
                    table: table.clone(),
                    table_id: table_meta.id,
                    columns: columns.clone(),
                    unique: *unique,
                    placement,
                    method: index_method,
                    constraint: None,
                    clustered: false,
                    without_overlaps: false,
                };
                ops.extend(local_index_backfill_ops(
                    kv,
                    &table_meta,
                    &index,
                    fctx.own_xid,
                )?);
            }
            Ok((command("CREATE INDEX"), ops))
        }
        Statement::DropIndex {
            name,
            if_exists,
            cascade,
        } => {
            let name = &match resolve_relation(kv, resolution, name, SchemaDisposition::Utility) {
                Ok(name) => name,
                Err(error) if *if_exists && is_missing_schema(&error) => {
                    return Ok((command("DROP INDEX"), Vec::new()));
                }
                Err(error) => return Err(error),
            };
            if let Some(error) = drop_kind_mismatch(kv, name, "index") {
                return Err(error);
            }
            let (index, mut ops) = match crabka_pgcatalog::drop_index_ops(kv, name) {
                Ok(result) => result,
                Err(crabka_pgcatalog::CatalogError::UndefinedIndex(_)) if *if_exists => {
                    return Ok((command("DROP INDEX"), Vec::new()));
                }
                Err(error) => return Err(error.into()),
            };
            if index.placement == crabka_pgcatalog::IndexPlacement::Global {
                return Err(ExecError::Unsupported(
                    "dropping global indexes is not supported until distributed index cleanup exists"
                        .into(),
                ));
            }
            // A foreign key that chose this index as the one proving its
            // referenced columns unique depends on it; CASCADE drops the
            // referencing constraint, not the referencing relation.
            let dependents = crate::fk::dependents_blocking_index_drop(kv, &index)?;
            if !dependents.is_empty() {
                if !*cascade {
                    return Err(ExecError::DependentForeignKeys(Box::new(
                        crate::error::ForeignKeyDependents {
                            dropped: crate::error::DroppedObject::Index(index.name.clone()),
                            dependents,
                        },
                    )));
                }
                for dependent in &dependents {
                    let child = crabka_pgcatalog::get_table(kv, &dependent.table)?;
                    let (_, drop_ops) = crabka_pgcatalog::drop_foreign_key_ops(
                        kv,
                        child.id,
                        &dependent.constraint,
                    )?;
                    ops.extend(drop_ops);
                }
            }
            for (key, _) in kv.scan_prefix(&crabka_pgkv::key::secondary_index_prefix(
                index.table_id,
                index.id,
            ))? {
                ops.push(crabka_pgkv::WriteOp::Delete { key });
            }
            Ok((command("DROP INDEX"), ops))
        }
        Statement::AlterIndexTablespace { name, tablespace } => {
            let name = &resolve_relation(kv, resolution, name, SchemaDisposition::Utility)?;
            if let Some(error) = system_catalog_wrong_kind(name) {
                return Err(error);
            }
            // A relation of another kind is 42809 naming what was asked for,
            // not the index catalog's 42704: `ALTER INDEX t` on a table has to
            // say `"t" is not an index` rather than claim no index is there.
            // No `HINT` rides this one — that is `DROP`'s family alone.
            if let Some(error) = wrong_kind(kv, name, |kind| {
                (kind != "index").then(|| {
                    ExecError::WrongObjectType(format!("\"{}\" is not an index", name.name))
                })
            }) {
                return Err(error);
            }
            crabka_pgcatalog::get_index(kv, name)?;
            let oid = resolve_relation_tablespace_oid(kv, tablespace)?;
            Ok((
                command("ALTER INDEX"),
                vec![crabka_pgcatalog::set_relation_tablespace_op(name, oid)],
            ))
        }
        Statement::AlterView {
            name,
            if_exists,
            action,
        } => {
            use crabka_pgparser::ast::{AlterViewAction, ViewOptionName, ViewOptionSetting};

            let name = &match resolve_relation(kv, resolution, name, SchemaDisposition::Utility) {
                Ok(name) => name,
                Err(error) if *if_exists && is_missing_schema(&error) => {
                    return Ok((command("ALTER VIEW"), Vec::new()));
                }
                Err(error) => return Err(error),
            };
            let mut view = match crabka_pgcatalog::get_view(kv, name) {
                Ok(view) => view,
                Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) if *if_exists => {
                    return Ok((command("ALTER VIEW"), Vec::new()));
                }
                // A relation of that name which is not a view is PostgreSQL's
                // 42809, not a missing-relation report: `ALTER VIEW t` on a
                // table must say so rather than claim `t` does not exist. The
                // system-catalog refusal outranks it, as it does for every
                // other `ALTER` spelling.
                Err(error @ crabka_pgcatalog::CatalogError::UndefinedTable(_)) => {
                    return Err(system_catalog_wrong_kind(name).unwrap_or_else(|| {
                        // A synthesised *view* is the one kind that reaches
                        // here and is not a mismatch: it is a view with no
                        // record to rewrite, so it keeps the lookup's own
                        // error rather than being told it is not a view.
                        match relation_kind(kv, name) {
                            Some(kind) if kind != "view" => ExecError::WrongObjectType(format!(
                                "\"{}\" is not a view",
                                name.name
                            )),
                            _ => error.into(),
                        }
                    }));
                }
                Err(error) => return Err(error.into()),
            };
            // Owner-only, like every other statement that redefines what a
            // relation means. It matters more here than for a table: the
            // owner is the identity the view's body reads under, so a role
            // that could rewrite it could hand its own rights to anyone.
            crate::privilege::require_ownership(
                kv,
                &view.name,
                &view.owner,
                crate::privilege::RelationKind::View,
                fctx.effective_role(),
            )?;
            match action {
                AlterViewAction::OwnerTo(role) => {
                    view.owner = resolve_new_owner(kv, fctx, role)?;
                }
                // `SET` moves only the options written; `RESET` returns the
                // ones written to their default — false for the booleans and
                // unset for the check option, which is what makes a parent's
                // cascade stop reaching a view whose option has been reset.
                AlterViewAction::SetOptions(settings) => {
                    for setting in settings {
                        match setting {
                            ViewOptionSetting::SecurityInvoker(value) => {
                                view.options.security_invoker = *value;
                            }
                            ViewOptionSetting::SecurityBarrier(value) => {
                                view.options.security_barrier = *value;
                            }
                            ViewOptionSetting::CheckOption(level) => {
                                view.options.check_option = Some(catalog_check_option(*level));
                            }
                        }
                    }
                }
                AlterViewAction::ResetOptions(names) => {
                    for option in names {
                        match option {
                            ViewOptionName::SecurityInvoker => {
                                view.options.security_invoker = false;
                            }
                            ViewOptionName::SecurityBarrier => {
                                view.options.security_barrier = false;
                            }
                            ViewOptionName::CheckOption => view.options.check_option = None,
                        }
                    }
                }
            }
            Ok((
                command("ALTER VIEW"),
                vec![crabka_pgcatalog::put_view_op(&view)],
            ))
        }
        Statement::CreateRole {
            name,
            can_login,
            member_of,
            options,
        } => {
            crate::privilege::require_role_create(kv, fctx.effective_role(), *options)?;
            // `IN ROLE r` writes exactly the membership `GRANT r TO …` writes,
            // so it passes exactly the same gate. Every named role is checked
            // before the first membership is written.
            for role in member_of {
                crate::privilege::require_role_grant(
                    kv,
                    fctx.effective_role(),
                    role,
                    crate::privilege::RoleGrant::Grant,
                )?;
            }
            let mut attributes = crabka_pgcatalog::RoleAttributes::default();
            let login = apply_role_options(&mut attributes, *can_login, *options);
            let ops = crabka_pgcatalog::create_role_with_memberships_ops(
                kv, name, login, attributes, member_of,
            )?;
            Ok((command("CREATE ROLE"), ops))
        }
        Statement::AlterRole { name, options } => {
            // The name is resolved first: `PostgreSQL` reports an unknown role
            // as unknown even when the session could not have altered it.
            let role = crabka_pgcatalog::get_role(kv, name)?;
            crate::privilege::require_role_alter(kv, fctx.effective_role(), name, *options)?;
            let mut attributes = role.attributes;
            let login = apply_role_options(&mut attributes, role.can_login, *options);
            let ops = crabka_pgcatalog::alter_role_ops(kv, name, login, attributes)?;
            Ok((command("ALTER ROLE"), ops))
        }
        Statement::DropRole { name, if_exists } => {
            crate::privilege::require_role_drop(kv, fctx.effective_role())?;
            let ops = match crabka_pgcatalog::drop_role_ops(kv, name) {
                Ok(ops) => ops,
                Err(crabka_pgcatalog::CatalogError::UndefinedObject(_)) if *if_exists => Vec::new(),
                Err(error) => return Err(error.into()),
            };
            Ok((command("DROP ROLE"), ops))
        }
        Statement::GrantTablePrivileges {
            privileges,
            tables,
            grantees,
        } => {
            let names = resolve_grantable_relations(kv, resolution, tables)?;
            let grantees = resolve_grantees(kv, fctx, grantees)?;
            let mut ops = Vec::new();
            for name in &names {
                ops.extend(privilege_grant_ops(
                    kv,
                    name,
                    &grantees,
                    privileges,
                    PrivilegeGrant::Grant,
                )?);
            }
            Ok((command("GRANT"), ops))
        }
        // `WITH ADMIN OPTION` / `ADMIN OPTION FOR` are dropped: a membership is
        // stored as a bare key with no payload, so there is nowhere to record
        // the admin right and nothing that would read it back.
        Statement::GrantRoles {
            roles,
            members,
            admin_option: _,
        } => {
            let members = require_role_memberships(
                kv,
                fctx,
                roles,
                members,
                crate::privilege::RoleGrant::Grant,
            )?;
            let ops = crabka_pgcatalog::grant_role_memberships_ops(kv, roles, &members)?;
            Ok((command("GRANT ROLE"), ops))
        }
        Statement::RevokeRoles {
            roles,
            members,
            admin_option,
        } => {
            let members = require_role_memberships(
                kv,
                fctx,
                roles,
                members,
                crate::privilege::RoleGrant::Revoke,
            )?;
            // The names are checked either way; `ADMIN OPTION FOR` then keeps
            // the membership and strips only the admin right, which is all this
            // catalog does not hold, so it writes nothing.
            let ops = crabka_pgcatalog::revoke_role_memberships_ops(kv, roles, &members)?;
            let ops = if *admin_option { Vec::new() } else { ops };
            Ok((command("REVOKE ROLE"), ops))
        }
        Statement::GrantSchemaPrivileges {
            privileges,
            schemas,
            grantees,
        } => {
            let grantees = resolve_grantees(kv, fctx, grantees)?;
            let ops =
                crabka_pgcatalog::grant_schema_privileges_ops(kv, schemas, &grantees, privileges)?;
            Ok((command("GRANT"), ops))
        }
        Statement::RevokeTablePrivileges {
            privileges,
            tables,
            grantees,
        } => {
            let names = resolve_grantable_relations(kv, resolution, tables)?;
            let grantees = resolve_grantees(kv, fctx, grantees)?;
            let mut ops = Vec::new();
            for name in &names {
                ops.extend(privilege_grant_ops(
                    kv,
                    name,
                    &grantees,
                    privileges,
                    PrivilegeGrant::Revoke,
                )?);
            }
            Ok((command("REVOKE"), ops))
        }
        Statement::RevokeSchemaPrivileges {
            privileges,
            schemas,
            grantees,
        } => {
            let grantees = resolve_grantees(kv, fctx, grantees)?;
            let ops =
                crabka_pgcatalog::revoke_schema_privileges_ops(kv, schemas, &grantees, privileges)?;
            Ok((command("REVOKE"), ops))
        }
        Statement::CreateFdw { name, options } => {
            let ops = crabka_pgcatalog::create_fdw_ops(kv, name, options.clone())?;
            Ok((command("CREATE FOREIGN DATA WRAPPER"), ops))
        }
        Statement::DropFdw {
            name,
            if_exists,
            cascade: _,
        } => {
            // No object can depend on this one in this engine, so CASCADE and
            // RESTRICT are indistinguishable; both are accepted.

            let ops = ignore_missing_ops(crabka_pgcatalog::drop_fdw_ops(kv, name), *if_exists)?;
            Ok((command("DROP FOREIGN DATA WRAPPER"), ops))
        }
        Statement::CreateServer {
            name,
            wrapper,
            options,
        } => {
            let ops = crabka_pgcatalog::create_server_ops(kv, name, wrapper, options.clone())?;
            Ok((command("CREATE SERVER"), ops))
        }
        Statement::DropServer {
            name,
            if_exists,
            cascade: _,
        } => {
            // No object can depend on this one in this engine, so CASCADE and
            // RESTRICT are indistinguishable; both are accepted.

            let ops = ignore_missing_ops(crabka_pgcatalog::drop_server_ops(kv, name), *if_exists)?;
            Ok((command("DROP SERVER"), ops))
        }
        Statement::CreateUserMapping {
            user,
            server,
            options,
        } => {
            // Normalize `FOR CURRENT_USER` and `FOR PUBLIC` to the catalog key
            // `"public"` — the same key that the scan path looks up via
            // `get_user_mapping(kv, fctx.current_user, …)` where
            // `current_user` is always `"public"` under trust-auth.
            // Per-named-user mappings await real SQL authentication (phase-2).
            let resolved_user = normalize_mapping_user(user);
            let ops = crabka_pgcatalog::create_user_mapping_ops(
                kv,
                resolved_user,
                server,
                options.clone(),
            )?;
            Ok((command("CREATE USER MAPPING"), ops))
        }
        Statement::DropUserMapping {
            user,
            server,
            if_exists,
            cascade: _,
        } => {
            // No object can depend on this one in this engine, so CASCADE and
            // RESTRICT are indistinguishable; both are accepted.

            // Same normalization as CreateUserMapping so DROP matches CREATE.
            let resolved_user = normalize_mapping_user(user);
            let ops = ignore_missing_ops(
                crabka_pgcatalog::drop_user_mapping_ops(kv, resolved_user, server),
                *if_exists,
            )?;
            Ok((command("DROP USER MAPPING"), ops))
        }
        Statement::CreateForeignTable {
            name,
            columns,
            server,
            options,
        } => {
            let name = resolve_relation(kv, resolution, name, SchemaDisposition::Creation)?;
            crate::usertype::ensure_relation_type_name_available(kv, &name)?;
            let cols = columns
                .iter()
                .map(|c| Column::new(c.name.clone(), c.ty))
                .collect();
            let (_id, ops) = crabka_pgcatalog::create_foreign_table_ops(
                kv,
                &name,
                cols,
                server,
                options.clone(),
                fctx.table_creation(),
            )?;
            Ok((command("CREATE FOREIGN TABLE"), ops))
        }
        Statement::DropForeignTable {
            name,
            if_exists,
            cascade: _,
        } => {
            // No object can depend on this one in this engine, so CASCADE and
            // RESTRICT are indistinguishable; both are accepted.

            // A foreign table shares the ordinary table catalog key, so `drop_table`
            // removes it (catalog entry + sequence + any rows).
            let name = &resolve_relation(kv, resolution, name, SchemaDisposition::Utility)?;
            // Sharing that key is exactly why the kind has to be checked here:
            // without it `DROP FOREIGN TABLE t` dropped an ordinary table, and
            // `DROP FOREIGN TABLE mv` a materialized view, where `PostgreSQL`
            // reports the kind and points at the command that would have
            // worked. `IF EXISTS` does not waive it — the relation exists.
            if let Some(error) = drop_kind_mismatch(kv, name, "foreign table") {
                return Err(error);
            }
            let ops = match crabka_pgcatalog::drop_table_ops(kv, name) {
                Ok(ops) => ops,
                Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) if *if_exists => Vec::new(),
                Err(e) => return Err(e.into()),
            };
            Ok((command("DROP FOREIGN TABLE"), ops))
        }
        // The catalog has no ALTER for foreign objects, and phase-1 querying does
        // not need one — surface a clear 0A000 rather than silently no-op'ing.
        Statement::AlterServer { .. } | Statement::AlterUserMapping { .. } => {
            Err(ExecError::CompatibilityRefusal(
                stmt.compatibility_refusal()
                    .expect("ALTER refusal metadata is centralized on the AST"),
            ))
        }
        // SP40: IMPORT FOREIGN SCHEMA discovers the server's tables through the
        // registered scanner (the `kafka_fdw` seam enumerates Kafka topics and
        // derives each topic's value columns from its Schema Registry subject),
        // then materializes a foreign table per discovered table through the same
        // write-op seam as local DDL.
        //
        // `remote_schema` is accepted but unused in phase 1 (Kafka has no
        // nested schemas). `INTO <schema>` names the local schema every
        // discovered table lands in, which must exist — 3F000 otherwise, as for
        // any other qualifier.
        Statement::ImportForeignSchema {
            remote_schema: _,
            selector,
            server,
            into_schema,
        } => {
            // Resolve the server (42704 if undefined) and the current user's
            // optional mapping (no mapping → no credentials).
            let srv = crabka_pgcatalog::get_server(kv, server)?;
            let mapping = crabka_pgcatalog::get_user_mapping(kv, fctx.current_user, server).ok();
            // A scanner must be registered (the `kafka` feature is built in).
            let scanner = fctx.scanner.ok_or_else(|| {
                ExecError::Unsupported("foreign tables require the `kafka` feature".into())
            })?;
            let filter = crate::foreign::ImportFilter::from_selector(selector);
            let tables = scanner.import_schema(&srv, mapping.as_ref(), &filter)?;
            let mut ops = Vec::new();
            // Every table lands in one batch, so the counter cannot be read
            // again between them — an unapplied bump is invisible to the next
            // read, and each table would be created under the same id. The
            // batch allocates from a cursor of its own and owes exactly one
            // bump, which is sound because the session holds the counter lock
            // for the whole statement.
            let mut cursor: Option<crabka_pgcatalog::TableId> = None;
            for table in tables {
                let into = resolve_relation(
                    kv,
                    resolution,
                    &crabka_pgparser::ast::RelationRef::qualified(into_schema, &table.name),
                    SchemaDisposition::Creation,
                )?;
                crate::usertype::ensure_relation_type_name_available(kv, &into)?;
                let id = match cursor {
                    Some(next) => next,
                    None => crabka_pgcatalog::read_next_table_id(kv)?,
                };
                cursor = Some(id + 1);
                let (_id, mut table_ops) = crabka_pgcatalog::create_foreign_table_ops(
                    kv,
                    &into,
                    table.columns,
                    &srv.name,
                    table.options,
                    crabka_pgcatalog::TableCreation {
                        owner: fctx.effective_role(),
                        id: crabka_pgcatalog::TableIdSource::Reserved(id),
                        materialized: None,
                    },
                )?;
                ops.append(&mut table_ops);
            }
            if let Some(next) = cursor {
                ops.push(crabka_pgcatalog::set_next_table_id_op(next));
            }
            Ok((command("IMPORT FOREIGN SCHEMA"), ops))
        }
        _ => Err(ExecError::Unsupported("not a DDL statement".into())),
    }
}

/// Resolve an existing user type through the type catalog, not relation
/// existence. Types and relations share namespaces, but only the former tells
/// an unqualified `ALTER TYPE`/`DROP TYPE` which visible schema owns the target.
fn resolve_user_type(
    kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    reference: &crabka_pgparser::ast::RelationRef,
) -> Result<crabka_pgcatalog::RelationName, ExecError> {
    if reference.schema.is_some() {
        return resolve_relation(kv, resolution, reference, SchemaDisposition::Utility);
    }
    let user_types = crabka_pgcatalog::list_user_types(kv)?;
    for schema in resolution.visible_schemas(kv)? {
        let candidate = crabka_pgcatalog::RelationName::new(schema, reference.name.clone());
        if candidate.schema == "pg_catalog" && is_builtin_catalog_type_name(&candidate.name) {
            return Ok(candidate);
        }
        let identity = (candidate.schema.clone(), candidate.name.clone());
        if crabka_pgcatalog::get_user_type(kv, &candidate)?.is_some()
            || user_types
                .iter()
                .any(|ty| ty.multirange_identity() == Some(identity.clone()))
        {
            return Ok(candidate);
        }
    }
    resolve_relation(kv, resolution, reference, SchemaDisposition::Utility)
}

fn resolve_user_types(
    kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    references: &[crabka_pgparser::ast::RelationRef],
) -> Result<Vec<crabka_pgcatalog::RelationName>, ExecError> {
    references
        .iter()
        .map(|reference| resolve_user_type(kv, resolution, reference))
        .collect()
}

/// PostgreSQL's `checkViewColumns`: a replacement query may APPEND output
/// columns but may not drop, rename, or retype any that already exist.
///
/// The order matters and is per column, not per rule: the count is checked
/// first, then each existing column in position order has its name checked and
/// then its type, and the FIRST offending column decides the error. A global
/// name pass followed by a global type pass would report the wrong column when
/// one column changes type and a later one changes name.
fn check_view_columns_replaceable(
    existing: &[Column],
    replacement: &[Column],
    view: &crabka_pgcatalog::RelationName,
) -> Result<(), ExecError> {
    if replacement.len() < existing.len() {
        return Err(ExecError::InvalidTableDefinition(
            "cannot drop columns from view".into(),
        ));
    }
    for (old, new) in existing.iter().zip(replacement) {
        if old.name != new.name {
            return Err(ExecError::Remote(
                crabka_pgwire::error::PgError::error(
                    "42P16",
                    format!(
                        "cannot change name of view column \"{}\" to \"{}\"",
                        old.name, new.name
                    ),
                )
                .with_hint(
                    "Use ALTER VIEW ... RENAME COLUMN ... to change name of view column instead.",
                ),
            ));
        }
        if old.ty != new.ty {
            return Err(ExecError::InvalidTableDefinition(format!(
                "cannot change data type of view column \"{}\" from {} to {}",
                old.name,
                old.ty.name(),
                new.ty.name()
            )));
        }
    }
    // An appended column may not collide with one of the existing names, which is
    // the same 42701 `check_for_column_name_collision` raises for a table.
    for appended in &replacement[existing.len()..] {
        if existing.iter().any(|old| old.name == appended.name) {
            return Err(ExecError::DuplicateColumn {
                column: appended.name.clone(),
                table: view.to_string(),
            });
        }
    }
    Ok(())
}

/// Check a view body against what this engine can store, and report the
/// relations it reads.
///
/// The caller needs those relations, not just the verdict: a view over a
/// temporary relation is itself temporary, so where the view lands is decided
/// by what its body names — and by `PostgreSQL`'s rule, *anywhere* it names
/// them, join arm and subquery included.
///
/// The body's shape is not otherwise constrained. A view is stored as its SQL
/// text and handed back to the ordinary query executor on every scan, so any
/// query that executor can run is a body it can hold. What remains are the two
/// things `PostgreSQL` itself refuses and one this engine cannot yet run:
///
/// * A query parameter has nothing to bind to once the text is stored —
///   `PostgreSQL` reports `42P02 there is no parameter $n`.
/// * A data-modifying `WITH` entry would write on every read (`0A000`).
/// * A locking clause. `PostgreSQL` accepts one and locks the underlying rows
///   when the view is read; this engine's read path has no way to take those
///   locks (`query_to_relation` refuses a locking body outright), so storing
///   one would build a view that cannot be selected from.
fn validate_view_definition(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    query: &crabka_pgparser::ast::QueryExpr,
) -> Result<Vec<crabka_pgcatalog::RelationName>, ExecError> {
    if query.locking.is_some() {
        return Err(ExecError::Unsupported(
            "CREATE VIEW does not support locking SELECT".into(),
        ));
    }
    let mut references = Vec::new();
    let mut refusal = None;
    crate::viewdeps::walk_query(query, &mut |node| {
        let found = match node {
            crate::viewdeps::Node::Relation(source) => {
                references.push(source.reference);
                return;
            }
            crate::viewdeps::Node::Expr(Expr::Param(number)) => {
                ExecError::Remote(crabka_pgwire::error::PgError::error(
                    "42P02",
                    format!("there is no parameter ${number}"),
                ))
            }
            crate::viewdeps::Node::DataModifyingCte => ExecError::Unsupported(
                "views must not contain data-modifying statements in WITH".into(),
            ),
            crate::viewdeps::Node::Expr(_) | crate::viewdeps::Node::ComputedFrom => return,
        };
        // The first refusal in tree order is the one reported, which is the
        // order PostgreSQL reports them in too.
        if refusal.is_none() {
            refusal = Some(found);
        }
    });
    if let Some(refusal) = refusal {
        return Err(refusal);
    }
    let mut sources: Vec<crabka_pgcatalog::RelationName> = Vec::new();
    for reference in references {
        let name = resolve_relation(
            catalog_kv,
            resolution,
            reference,
            SchemaDisposition::Reference,
        )?;
        if !sources.contains(&name) {
            sources.push(name);
        }
    }
    Ok(sources)
}

/// A `QueryResult::Command` with the given PostgreSQL completion tag.
fn command(tag: &str) -> QueryResult {
    QueryResult::Command { tag: tag.into() }
}

fn resolve_relation_tablespace_oid(kv: &dyn Kv, name: &str) -> Result<u32, ExecError> {
    if name == "pg_global" {
        return Err(ExecError::Remote(crabka_pgwire::error::PgError::error(
            "0A000",
            "only shared relations can be placed in pg_global tablespace",
        )));
    }
    crabka_pgcatalog::tablespace_oid(kv, name).map_err(|error| match error {
        crabka_pgcatalog::CatalogError::UndefinedObject(_) => {
            ExecError::Remote(crabka_pgwire::error::PgError::error(
                "42704",
                format!("tablespace \"{name}\" does not exist"),
            ))
        }
        other => other.into(),
    })
}

fn create_table_constraint_index(
    table_name: &crabka_pgcatalog::RelationName,
    columns: &[String],
    primary_key: bool,
    without_overlaps: bool,
) -> crabka_pgcatalog::NewIndex {
    let suffix = if primary_key { "pkey" } else { "key" };
    // The relation's own name, never its qualified spelling: `PostgreSQL` names
    // the index for `s1.t`'s primary key `t_pkey`, in schema `s1`.
    let table = &table_name.name;
    let name = if primary_key {
        format!("{table}_pkey")
    } else {
        format!("{table}_{}_{suffix}", columns.join("_"))
    };
    crabka_pgcatalog::NewIndex {
        name,
        columns: columns.to_vec(),
        unique: true,
        placement: crabka_pgcatalog::IndexPlacement::Local,
        // A temporal key is compared with `&&` on its last column, which only
        // GiST offers — `PostgreSQL` builds it as a unique GiST index, and the
        // access method is what `pg_get_indexdef` and `\d` echo back.
        method: if without_overlaps {
            crabka_pgcatalog::IndexMethod::Gist
        } else {
            crabka_pgcatalog::IndexMethod::Btree
        },
        constraint: Some(if primary_key {
            crabka_pgcatalog::IndexConstraint::PrimaryKey
        } else {
            crabka_pgcatalog::IndexConstraint::Unique
        }),
        without_overlaps,
    }
}

/// Check the key of a `PRIMARY KEY`/`UNIQUE (…, c WITHOUT OVERLAPS)` against
/// the table's columns.
///
/// `PostgreSQL` refuses, in this order: a key that is nothing but the temporal
/// column (42601 — such a key would forbid every overlap in the table rather
/// than every overlap *within* a scalar key), a temporal column the relation
/// does not have (42703), and one whose type has no `&&` to compare it with
/// (42804). A domain over a range passes: the domain's base type is what the
/// operator resolves against.
fn validate_without_overlaps_key(
    columns: &[String],
    table_columns: &[Column],
) -> Result<(), ExecError> {
    let Some((temporal, leading)) = columns.split_last() else {
        return Err(ExecError::WithoutOverlapsNeedsTwoColumns);
    };
    if leading.is_empty() {
        return Err(ExecError::WithoutOverlapsNeedsTwoColumns);
    }
    let column = table_columns
        .iter()
        .find(|column| column.name == *temporal)
        .ok_or_else(|| ExecError::UndefinedIndexColumn(temporal.clone()))?;
    if !matches!(
        column.ty.storage_type(),
        crabka_pgtypes::ColumnType::Range(_) | crabka_pgtypes::ColumnType::Multirange(_)
    ) {
        return Err(ExecError::WithoutOverlapsNotRange(temporal.clone()));
    }
    Ok(())
}

/// The columns a `CREATE TABLE` marks NOT NULL because they are part of its
/// primary key, whether declared inline or as a table constraint.
fn create_table_primary_key_columns<'a>(
    columns: &'a [crabka_pgparser::ast::ColumnDef],
    constraints: &'a [crabka_pgparser::ast::TableConstraint],
) -> HashSet<&'a str> {
    let mut primary_key_columns = HashSet::new();
    for column in columns {
        if column.constraints.iter().any(|constraint| {
            matches!(
                constraint.kind,
                crabka_pgparser::ast::ColumnConstraintKind::PrimaryKey
            )
        }) {
            primary_key_columns.insert(column.name.as_str());
        }
    }
    for constraint in constraints {
        if let crabka_pgparser::ast::TableConstraintKind::PrimaryKey { columns, .. } =
            &constraint.kind
        {
            primary_key_columns.extend(columns.iter().map(String::as_str));
        }
    }
    primary_key_columns
}

/// Which datum a column DEFAULT stores: the one the statement wrote, or the one
/// that coercing it to the column type produced.
///
/// `PostgreSQL` stores a default as the EXPRESSION, with the coercion wrapped
/// around the literal, so `pg_get_expr` — which hides a binary-coercible cast —
/// prints the literal's own type. crabka stores the value, so the only
/// surviving record of what the statement wrote is the datum's own flavour.
///
/// For a bit string that record is free to keep. `bit` and `bit varying` are
/// binary-coercible in both directions, and `BitString::varying` changes no
/// rendered bit, so the written datum and the coerced one print the same text
/// and only the deparsed type differs. That is what makes `B'0101'` in a `bit
/// varying(5)` column deparse `'0101'::"bit"` while a bare `'1001'` deparses
/// `'1001'::bit varying`. Requiring the two to compare equal is what keeps the
/// LENGTH coercion, which does change bits: `B'101'` in a `bit(5)` column is
/// still the 22026 `PostgreSQL` raises, not a default of the wrong width.
///
/// It stops at bit strings deliberately. `inet`/`cidr` share a datum the same
/// way and their flag is excluded from equality the same way, but
/// `Inet::is_cidr` DOES change the rendered text — a `/32` prints its mask as a
/// `cidr` and hides it as an `inet` — so keeping the written flavour there
/// would change the value and not merely its label.
fn stored_default_value(written: Datum, coerced: Datum) -> Datum {
    match (&written, &coerced) {
        (Datum::BitString(_), Datum::BitString(_)) if written == coerced => written,
        _ => coerced,
    }
}

fn column_from_ast(
    table_name: &crabka_pgcatalog::RelationName,
    column: &crabka_pgparser::ast::ColumnDef,
    ctx: &crate::clock::EvalCtx,
    serial_sequences: &mut Vec<(crabka_pgcatalog::RelationName, Sequence)>,
    primary_key_columns: &HashSet<&str>,
) -> Result<Column, ExecError> {
    let mut catalog_column = Column::new(column.name.clone(), column.ty);
    // A written `COLLATE` is only legal on a collatable type. The parser has
    // already refused a name no `pg_collation` row has (42704); what is left is
    // PostgreSQL's type rule, and it is the same one the postfix operator
    // applies, so it is asked of the same helper.
    if let Some(collation) = &column.collation {
        crate::eval::require_collatable(column.ty)?;
        catalog_column.collation = Some(collation.clone());
    }
    if primary_key_columns.contains(column.name.as_str()) {
        catalog_column.not_null = true;
    }
    if column.serial.is_some() {
        let sequence_name = table_name.sibling(format!("{}_{}_seq", table_name.name, column.name));
        catalog_column.not_null = true;
        catalog_column.default = Some(ColumnDefault::NextVal(sequence_name.to_string()));
        serial_sequences.push((
            sequence_name,
            Sequence::new(1, 1, None, None, Some(1), false),
        ));
    }
    for constraint in &column.constraints {
        match &constraint.kind {
            crabka_pgparser::ast::ColumnConstraintKind::NotNull => catalog_column.not_null = true,
            crabka_pgparser::ast::ColumnConstraintKind::Null => catalog_column.not_null = false,
            crabka_pgparser::ast::ColumnConstraintKind::Default(expr) => {
                let value = eval_assignment_value(expr, column.ty, &Scope::empty(), &[], ctx)?;
                let coerced = coerce(value.clone(), column.ty, ctx)?;
                ensure_default_can_be_persisted(&coerced)?;
                catalog_column.default =
                    Some(ColumnDefault::Value(stored_default_value(value, coerced)));
            }
            crabka_pgparser::ast::ColumnConstraintKind::PrimaryKey => {
                catalog_column.not_null = true;
            }
            crabka_pgparser::ast::ColumnConstraintKind::Unique { nulls_not_distinct } => {
                if *nulls_not_distinct {
                    return Err(ExecError::Unsupported(
                        "UNIQUE NULLS NOT DISTINCT is not supported: unique indexes use \
                         PostgreSQL's default NULLS DISTINCT semantics"
                            .into(),
                    ));
                }
            }
            crabka_pgparser::ast::ColumnConstraintKind::Identity(spec) => {
                let sequence_name =
                    table_name.sibling(format!("{}_{}_seq", table_name.name, column.name));
                catalog_column.not_null = true;
                catalog_column.identity = Some(if spec.always {
                    crabka_pgcatalog::IdentityKind::Always
                } else {
                    crabka_pgcatalog::IdentityKind::ByDefault
                });
                catalog_column.default = Some(ColumnDefault::NextVal(sequence_name.to_string()));
                serial_sequences.push((sequence_name, sequence_from_options(&spec.options)));
            }
            crabka_pgparser::ast::ColumnConstraintKind::Generated(spec) => {
                if catalog_column.generated.is_some() {
                    return Err(ExecError::Syntax(format!(
                        "multiple generation clauses specified for column \"{}\" of table \"{}\"",
                        column.name, table_name.name
                    )));
                }
                catalog_column.generated = Some(crabka_pgcatalog::GeneratedColumn {
                    expr: spec.predicate.text.clone(),
                    kind: match spec.kind {
                        crabka_pgparser::ast::GeneratedKind::Stored => {
                            crabka_pgcatalog::GeneratedKind::Stored
                        }
                        crabka_pgparser::ast::GeneratedKind::Virtual => {
                            crabka_pgcatalog::GeneratedKind::Virtual
                        }
                    },
                });
            }
            // A column-level CHECK or REFERENCES contributes a constraint, not a
            // column property; `create_table_definition` collects both.
            crabka_pgparser::ast::ColumnConstraintKind::Check(_)
            | crabka_pgparser::ast::ColumnConstraintKind::References(_) => {}
        }
    }
    // A generated column's value comes from its expression and from nowhere
    // else, so a second source for it is a contradiction rather than a
    // precedence question. Identity is tested first because it plants a
    // `nextval` default of its own.
    if catalog_column.generated.is_some() {
        if catalog_column.identity.is_some() {
            return Err(ExecError::Syntax(format!(
                "both identity and generation expression specified for column \"{}\" of table \
                 \"{}\"",
                column.name, table_name.name
            )));
        }
        if catalog_column.default.is_some() {
            return Err(ExecError::Syntax(format!(
                "both default and generation expression specified for column \"{}\" of table \
                 \"{}\"",
                column.name, table_name.name
            )));
        }
    }
    Ok(catalog_column)
}

/// A `GENERATED … AS IDENTITY` sequence, from the parsed option list.
fn sequence_from_options(options: &crabka_pgparser::ast::SequenceOptions) -> Sequence {
    let increment = options.increment.unwrap_or(1);
    Sequence::new(
        options.start.unwrap_or(if increment > 0 { 1 } else { -1 }),
        increment,
        options.min,
        options.max,
        options.cache,
        options.cycle.unwrap_or(false),
    )
}

/// `PostgreSQL`'s default index name: `<table>_<key>_…_idx`, with `expr` for a
/// key that is not a bare column reference.
fn index_name_or_default(
    explicit: Option<&str>,
    table: &crabka_pgcatalog::RelationName,
    keys: &[crabka_pgparser::ast::IndexKey],
) -> String {
    if let Some(name) = explicit {
        return name.to_string();
    }
    let parts: Vec<&str> = keys
        .iter()
        .map(|key| key.column.as_deref().unwrap_or("expr"))
        .collect();
    format!("{}_{}_idx", table.name, parts.join("_"))
}

/// The durable key list an index can be built from. Expression source uses the
/// catalog's NUL-prefixed encoding, which cannot collide with a SQL identifier.
fn index_key_columns(
    keys: &[crabka_pgparser::ast::IndexKey],
    predicate: Option<&str>,
) -> Result<Vec<String>, ExecError> {
    if predicate.is_some() {
        return Err(ExecError::Unsupported(
            "partial indexes (CREATE INDEX … WHERE) are not supported: the scanner would treat \
             the index as covering every row"
                .into(),
        ));
    }
    keys.iter()
        .map(|key| {
            if key.descending || key.nulls_first == Some(true) {
                return Err(ExecError::Unsupported(
                    "DESC and NULLS FIRST index keys are not supported: index entries are \
                     stored in ascending, NULLS-LAST order"
                        .into(),
                ));
            }
            Ok(key
                .column
                .clone()
                .unwrap_or_else(|| crabka_pgcatalog::expression_index_key(&key.text)))
        })
        .collect()
}

fn validate_index_expressions(
    table: &Table,
    keys: &[crabka_pgparser::ast::IndexKey],
    unique: bool,
    placement: crabka_pgcatalog::IndexPlacement,
    method: crabka_pgcatalog::IndexMethod,
) -> Result<(), ExecError> {
    use crabka_pgparser::ast::Expr;

    let expressions: Vec<&str> = keys
        .iter()
        .filter_map(|key| key.column.is_none().then_some(key.text.as_str()))
        .collect();
    if expressions.is_empty() {
        return Ok(());
    }
    // Expression indexes are exact-scan metadata today, so they need no
    // physical entry evaluator. Hash/GIN remain physical-only methods.
    if unique
        || placement != crabka_pgcatalog::IndexPlacement::Local
        || !matches!(
            method,
            crabka_pgcatalog::IndexMethod::Btree
                | crabka_pgcatalog::IndexMethod::Gist
                | crabka_pgcatalog::IndexMethod::Spgist
        )
    {
        return Err(ExecError::Unsupported(
            "expression indexes currently require a non-unique local B-tree, GiST, or SP-GiST index"
                .into(),
        ));
    }
    let scope = Scope::single(table, &table.name.name);
    for source in expressions {
        let expr = crabka_pgparser::parser::parse_expression(source)?;
        crate::eval::infer_type(&expr, &scope)?;
        let mut invalid = false;
        crate::grouping::visit_expr(&expr, &mut |node| {
            invalid |= matches!(
                node,
                Expr::ScalarSubquery(_)
                    | Expr::Exists(_)
                    | Expr::InSubquery { .. }
                    | Expr::Quantified { .. }
            ) || matches!(node, Expr::Func(call) if !is_immutable_function(&call.name));
        });
        if invalid || crate::agg::contains_aggregate(&expr) {
            return Err(ExecError::InvalidObjectDefinition(
                "functions in index expression must be marked IMMUTABLE".into(),
            ));
        }
    }
    Ok(())
}

fn validate_index_opclasses(
    kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    table: &Table,
    keys: &[crabka_pgparser::ast::IndexKey],
    method: crabka_pgcatalog::IndexMethod,
) -> Result<(), ExecError> {
    let method_name = index_method_name(method);
    let method_oid = match method {
        crabka_pgcatalog::IndexMethod::Btree => crate::catalog_rel::BTREE_AM_OID,
        crabka_pgcatalog::IndexMethod::Hash => crate::catalog_rel::HASH_AM_OID,
        crabka_pgcatalog::IndexMethod::Gist => crate::catalog_rel::GIST_AM_OID,
        crabka_pgcatalog::IndexMethod::Gin => crate::catalog_rel::GIN_AM_OID,
        crabka_pgcatalog::IndexMethod::Spgist => crate::catalog_rel::SPGIST_AM_OID,
    };
    let user_classes = crabka_pgcatalog::list_operator_classes(kv)?;
    let visible_schemas = resolution.visible_schemas(kv)?;
    for key in keys {
        let Some(written) = key.opclass.as_deref() else {
            let ty = match key.column.as_deref() {
                Some(column) => {
                    table
                        .columns
                        .iter()
                        .find(|candidate| candidate.name == column)
                        .ok_or_else(|| ExecError::UndefinedColumn(column.into()))?
                        .ty
                }
                None => crate::eval::infer_type(
                    &crabka_pgparser::parser::parse_expression(&key.text)?,
                    &Scope::single(table, &table.name.name),
                )?,
            };
            validate_default_index_opclass(ty, method)?;
            continue;
        };
        let (schema, name) = written
            .split_once('.')
            .map_or((None, written), |(schema, name)| (Some(schema), name));
        let builtin_input_oid = || {
            crate::builtin_opclasses::BUILTIN_OPERATOR_CLASSES
                .iter()
                .find(|(_, am_oid, class_name, _, _, _, _)| {
                    *am_oid == method_oid && *class_name == name
                })
                .map(|(_, _, _, _, input_oid, _, _)| *input_oid as u32)
        };
        let user_input_oid = |schema: &str| {
            user_classes
                .iter()
                .find(|class| {
                    class.method == method_name
                        && class.name.name == name
                        && class.name.schema == schema
                })
                .map(|class| class.input_type_oid)
        };
        let input_oid = match schema {
            Some("pg_catalog") => builtin_input_oid(),
            Some(schema) => user_input_oid(schema),
            None => visible_schemas.iter().find_map(|schema| {
                if schema == "pg_catalog" {
                    builtin_input_oid()
                } else {
                    user_classes
                        .iter()
                        .find(|class| {
                            class.method == method_name
                                && class.name.name == name
                                && class.name.schema == *schema
                        })
                        .map(|class| class.input_type_oid)
                }
            }),
        }
        .ok_or_else(|| {
            ExecError::UndefinedObject(format!(
                "operator class \"{written}\" does not exist for access method \"{method_name}\""
            ))
        })?;
        let Some(column) = key.column.as_deref() else {
            return Err(ExecError::Unsupported(
                "operator classes on expression index keys are not supported".into(),
            ));
        };
        let column = table
            .columns
            .iter()
            .find(|candidate| candidate.name == column)
            .ok_or_else(|| ExecError::UndefinedColumn(column.into()))?;
        let column_oid = column.ty.oid();
        let binary_text_compatible = input_oid == crabka_pgtypes::oids::TEXT
            && matches!(column.ty, ColumnType::Text | ColumnType::Varchar(_));
        if input_oid != column_oid && input_oid != 2277 && !binary_text_compatible {
            return Err(ExecError::TypeMismatch(format!(
                "operator class \"{written}\" does not accept data type {}",
                crate::func::format_type(i64::from(column_oid), -1)
            )));
        }
    }
    Ok(())
}

fn validate_default_index_opclass(
    ty: ColumnType,
    method: crabka_pgcatalog::IndexMethod,
) -> Result<(), ExecError> {
    // `json` and `xml` have no operator class for ANY access method — neither
    // has an equality operator to build one on — so unlike `jsonpath` they are
    // not limited to btree and hash. This is also what makes `j json UNIQUE`
    // and `j json PRIMARY KEY` fail, since both build a btree index.
    if matches!(ty.storage_type(), ColumnType::Json | ColumnType::Xml) {
        return Err(ExecError::UndefinedObject(format!(
            "data type {} has no default operator class for access method \"{}\"",
            ty.name(),
            index_method_name(method)
        )));
    }
    if ty.storage_type() == ColumnType::JsonPath
        && matches!(
            method,
            crabka_pgcatalog::IndexMethod::Btree | crabka_pgcatalog::IndexMethod::Hash
        )
    {
        return Err(ExecError::UndefinedObject(format!(
            "data type {} has no default operator class for access method \"{}\"",
            ty.name(),
            index_method_name(method)
        )));
    }
    // `xid` and `cid` are the reverse of `jsonpath`: they have a HASH opclass
    // but no btree one, because transaction ids compare with modular
    // arithmetic and so have no sort order for a btree to hold. `x xid UNIQUE`
    // and `x xid PRIMARY KEY` fail for the same reason, since both build one.
    if matches!(ty.storage_type(), ColumnType::Xid | ColumnType::Cid)
        && method == crabka_pgcatalog::IndexMethod::Btree
    {
        return Err(ExecError::UndefinedObject(format!(
            "data type {} has no default operator class for access method \"{}\"",
            ty.name(),
            index_method_name(method)
        )));
    }
    Ok(())
}

fn validate_index_method(
    table: &Table,
    columns: &[String],
    unique: bool,
    placement: crabka_pgcatalog::IndexPlacement,
    method: crabka_pgcatalog::IndexMethod,
) -> Result<(), ExecError> {
    if method == crabka_pgcatalog::IndexMethod::Btree {
        return Ok(());
    }
    if method != crabka_pgcatalog::IndexMethod::Gin {
        if unique {
            return Err(ExecError::Unsupported(format!(
                "access method {} does not support unique indexes",
                index_method_name(method)
            )));
        }
        return Ok(());
    }
    // ponytail: one stored tsvector column keeps maintenance on the existing
    // row path; add expression/multicolumn GIN only when queries require it.
    if unique {
        return Err(ExecError::Unsupported(
            "access method gin does not support unique indexes".into(),
        ));
    }
    if placement != crabka_pgcatalog::IndexPlacement::Local {
        return Err(ExecError::Unsupported(
            "global GIN indexes are not supported".into(),
        ));
    }
    let [column] = columns else {
        return Err(ExecError::Unsupported(
            "GIN indexes currently require exactly one tsvector column".into(),
        ));
    };
    let column = table
        .column_index(column)
        .ok_or_else(|| ExecError::UndefinedColumn(column.clone()))?;
    if table.columns[column].ty != ColumnType::TsVector {
        return Err(ExecError::Unsupported(
            "GIN indexes currently support only tsvector columns".into(),
        ));
    }
    Ok(())
}

fn index_method_name(method: crabka_pgcatalog::IndexMethod) -> &'static str {
    match method {
        crabka_pgcatalog::IndexMethod::Btree => "btree",
        crabka_pgcatalog::IndexMethod::Hash => "hash",
        crabka_pgcatalog::IndexMethod::Gist => "gist",
        crabka_pgcatalog::IndexMethod::Gin => "gin",
        crabka_pgcatalog::IndexMethod::Spgist => "spgist",
    }
}

fn ensure_default_can_be_persisted(value: &Datum) -> Result<(), ExecError> {
    if matches!(
        value,
        Datum::Null
            | Datum::Bool(_)
            | Datum::Int4(_)
            | Datum::Int8(_)
            | Datum::Text(_)
            | Datum::JsonPath(_)
            | Datum::Float8(_)
            | Datum::Numeric(_)
            | Datum::Json(_)
            | Datum::Xml(_)
            | Datum::Jsonb(_)
            | Datum::TsVector(_)
            | Datum::TsQuery(_)
            // Stored as its bare oid, with the relation name re-derived on read.
            | Datum::Regclass(_)
            // An array carries its elements in the row encoding, so an element
            // of a type that cannot be a *column* default (a date, say) still
            // persists inside one.
            | Datum::Array(_)
            // Both have a `write_default` encoding: `money` as its `i64`, a
            // bit string through the row encoder, which keeps its length.
            | Datum::Money(_)
            | Datum::BitString(_)
    ) {
        return Ok(());
    }
    // The catalog's schema serializer has no encoding for these default values
    // (`crabka_pgcatalog::serde::write_default`), so they are refused at DDL
    // time rather than written and lost.
    Err(ExecError::Unsupported(
        "defaults for date/time, interval, bytea, composite and enum columns are not persisted yet"
            .into(),
    ))
}

/// Normalize the `user` spec from `CREATE / DROP USER MAPPING FOR <user>` to
/// the catalog key used by the scan path.
///
/// The parser emits `"current_user"` for `FOR CURRENT_USER` and `"public"` for
/// `FOR PUBLIC`.  Under trust-auth crabgresql has no authenticated SQL user, so
/// the scan path always looks up the mapping under `"public"`.  Both variants
/// must therefore resolve to the same catalog key so that a `FOR CURRENT_USER`
/// mapping is actually found at scan time.
fn normalize_mapping_user(user: &str) -> &str {
    if user.eq_ignore_ascii_case("current_user") || user.eq_ignore_ascii_case("public") {
        "public"
    } else {
        user
    }
}

/// Swallow a missing foreign-object error when `IF EXISTS` was given and return
/// an empty write batch, so DDL still flows through the committer seam.
fn ignore_missing_ops(
    r: Result<Vec<crabka_pgkv::WriteOp>, crabka_pgcatalog::CatalogError>,
    if_exists: bool,
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    match r {
        Ok(ops) => Ok(ops),
        Err(crabka_pgcatalog::CatalogError::UndefinedObject(_)) if if_exists => Ok(Vec::new()),
        Err(e) => Err(e.into()),
    }
}

fn sequence_from_encoded_options(encoded: &[String]) -> Result<Sequence, ExecError> {
    let mut start = None;
    let mut increment = None;
    let mut min = None;
    let mut max = None;
    let mut cache = None;
    let mut cycle = None;
    for option in encoded {
        let Some((key, value)) = option.split_once('=') else {
            return Err(ExecError::Syntax("invalid encoded sequence option".into()));
        };
        match key {
            "start" => start = Some(parse_sequence_i64(value)?),
            "increment" => increment = Some(parse_sequence_i64(value)?),
            "min" => min = Some(parse_sequence_i64(value)?),
            "max" => max = Some(parse_sequence_i64(value)?),
            "cache" => cache = Some(parse_sequence_i64(value)?),
            "cycle" => cycle = Some(value == "true"),
            _ => return Err(ExecError::Syntax("invalid encoded sequence option".into())),
        }
    }
    let increment = increment.unwrap_or(1);
    let start = start.unwrap_or(if increment > 0 { 1 } else { -1 });
    Ok(Sequence::new(
        start,
        increment,
        min,
        max,
        cache,
        cycle.unwrap_or(false),
    ))
}

fn parse_sequence_i64(value: &str) -> Result<i64, ExecError> {
    value
        .parse::<i64>()
        .map_err(|_| ExecError::Syntax("invalid encoded sequence option".into()))
}

/// Resolve INSERT target column indices: explicit `(cols...)` mapped to their
/// catalog positions (42703 on miss), or all columns in declared order.
fn resolve_targets(t: &Table, columns: &Option<Vec<String>>) -> Result<Vec<usize>, ExecError> {
    match columns {
        Some(cols) => {
            let mut seen = std::collections::HashSet::new();
            if let Some(repeated) = cols.iter().find(|column| !seen.insert(*column)) {
                // 42701: naming a column twice makes the statement's intent
                // undecidable, and PostgreSQL says so rather than letting the
                // second value quietly win.
                return Err(ExecError::DuplicateOutputColumn(repeated.clone()));
            }
            cols.iter()
                .map(|c| {
                    t.column_index(c)
                        .ok_or_else(|| ExecError::UndefinedColumn(c.clone()))
                })
                .collect::<Result<_, _>>()
        }
        None => Ok((0..t.columns.len()).collect()),
    }
}

/// The column slots an `INSERT` fills, given how many expressions its source
/// supplies per row.
///
/// `PostgreSQL` (`transformInsertRow`) checks the two directions differently. Too
/// many expressions is always an error. Too few is an error only when the
/// statement wrote an explicit column list. With no list, the implicit target
/// list is truncated to the source width, and the columns past it take their
/// defaults. This is why `INSERT INTO t3 SELECT a, b FROM s` is legal against a
/// three-column table.
fn resolve_insert_targets(
    t: &Table,
    columns: &Option<Vec<String>>,
    width: usize,
) -> Result<Vec<usize>, ExecError> {
    let mut target_idx = resolve_targets(t, columns)?;
    if width > target_idx.len() {
        return Err(ExecError::Syntax(
            "INSERT has more expressions than target columns".into(),
        ));
    }
    if width < target_idx.len() {
        if columns.is_some() {
            return Err(ExecError::Syntax(
                "INSERT has more target columns than expressions".into(),
            ));
        }
        target_idx.truncate(width);
    }
    Ok(target_idx)
}

/// The row a write path starts from: every column's `DEFAULT`, evaluated only
/// for the columns the statement did not supply a value for.
///
/// A skip of the supplied ones is not just saved work. A `DEFAULT` can be a
/// side effect. `nextval('s')` is one, and it is what a `SERIAL` column and both
/// flavours of `GENERATED … AS IDENTITY` desugar to. `PostgreSQL` advances the
/// sequence only for a column it actually defaults. So `INSERT INTO t (id, b)
/// VALUES (100, 'x')` leaves the sequence untouched, and the next generated id is
/// the one that insert would otherwise have burned. The choice is per row and
/// per column: in `VALUES (100, 'a'), (DEFAULT, 'b')` only the second row
/// advances, and a supplied identity column does not stop a *different*
/// identity column in the same row from advancing. All verified against
/// `postgres:18.4`.
///
/// A supplied slot is left `Null` here and overwritten by the caller, which is
/// also how an explicit `DEFAULT` keyword gets its value. That one does advance
/// the sequence, because the column really is taking its default.
fn unsupplied_defaults(
    table: &Table,
    target_idx: &[usize],
    ctx: &crate::clock::EvalCtx,
) -> Result<Vec<Datum>, ExecError> {
    let mut supplied = vec![false; table.columns.len()];
    for &slot in target_idx {
        supplied[slot] = true;
    }
    table
        .columns
        .iter()
        .zip(supplied)
        .map(|(column, supplied)| {
            if supplied {
                Ok(Datum::Null)
            } else {
                default_value(column, ctx)
            }
        })
        .collect()
}

fn build_insert_row(
    table: &Table,
    target_idx: &[usize],
    row_exprs: &[Expr],
    ctx: &crate::clock::EvalCtx,
) -> Result<Vec<Datum>, ExecError> {
    let mut row = unsupplied_defaults(table, target_idx, ctx)?;
    for (slot, expr) in target_idx.iter().zip(row_exprs.iter()) {
        // A `GENERATED ALWAYS` column takes its value from its expression, so
        // the only value a statement may name for it is `DEFAULT`.
        if table.columns[*slot].generated.is_some() && !matches!(expr, Expr::Default) {
            return Err(ExecError::GeneratedColumnWrite {
                message: format!(
                    "cannot insert a non-DEFAULT value into column \"{}\"",
                    table.columns[*slot].name
                ),
                column: table.columns[*slot].name.clone(),
            });
        }
        let value = match expr {
            Expr::Default => default_value(&table.columns[*slot], ctx)?,
            _ => {
                let target = table.columns[*slot].ty;
                let value = eval_assignment_value(expr, target, &Scope::empty(), &[], ctx)?;
                coerce(value, target, ctx)?
            }
        };
        row[*slot] = value;
    }
    finish_written_row(table, &mut row, ctx)?;
    Ok(row)
}

fn build_copy_row(
    table: &Table,
    target_idx: &[usize],
    row: &crate::copyfmt::CopyRow<'_>,
    ctx: &crate::clock::EvalCtx,
) -> Result<Vec<Datum>, ExecError> {
    let mut built = unsupplied_defaults(table, target_idx, ctx)?;
    for (slot, value) in target_idx.iter().zip(row.values.iter()) {
        let column = &table.columns[*slot];
        let target = column.ty;
        let converted = match value {
            Some(value) if let Some(base) = jsonpath_assignment_base(target) => {
                crate::eval::cast_value_in(&Datum::Text(value.clone()), base, ctx.output_style())
                    .and_then(|value| coerce(value, target, ctx))
            }
            // A COPY field runs the column type's input function under
            // *assignment* rules, so an over-long `varchar(n)` is 22001 rather
            // than the silent truncation an explicit cast would do — and the
            // date arms read the session's `DateStyle` field order.
            Some(value) => crabka_pgtypes::cast::cast_assign_in(
                &Datum::Text(value.clone()),
                target,
                ctx.output_style(),
            )
            .map_err(ExecError::from),
            None => coerce(Datum::Null, target, ctx),
        };
        // An input conversion is the one failure PostgreSQL can name a column
        // for: it is running that column's input function and holds the field
        // it was handed. Everything after this loop judges the assembled row,
        // and reports the line alone.
        built[*slot] = converted.map_err(|error| {
            copy_row_context(
                error,
                &table.name.name,
                row,
                crate::copyfmt::CopyContext::Column {
                    name: &column.name,
                    value: value.as_deref(),
                },
            )
        })?;
    }
    finish_written_row(table, &mut built, ctx).map_err(|error| {
        copy_row_context(
            error,
            &table.name.name,
            row,
            crate::copyfmt::CopyContext::Line { raw: row.raw },
        )
    })?;
    Ok(built)
}

/// Refuse a row whose field count does not match the columns being copied into.
///
/// `PostgreSQL` reports the two directions differently and gives both 22P04:
/// too few fields names the first column left unsupplied, too many says only
/// that there were more. Both carry the whole line as `CONTEXT`, because
/// neither failure belongs to a column that was read.
fn copy_row_width(
    table: &Table,
    target_idx: &[usize],
    row: &crate::copyfmt::CopyRow<'_>,
) -> Result<(), ExecError> {
    if row.values.len() == target_idx.len() {
        return Ok(());
    }
    let error = match target_idx.get(row.values.len()) {
        Some(slot) => ExecError::Remote(crabka_pgwire::error::PgError::error(
            "22P04",
            format!(
                "missing data for column \"{}\"",
                table.columns[*slot].name.clone()
            ),
        )),
        None => ExecError::Remote(crabka_pgwire::error::PgError::error(
            "22P04",
            "extra data after last expected column",
        )),
    };
    Err(copy_row_context(
        error,
        &table.name.name,
        row,
        crate::copyfmt::CopyContext::Line { raw: row.raw },
    ))
}

/// Attach the `CONTEXT` a per-row `COPY … FROM` failure carries.
///
/// The relation is named unqualified whatever the statement wrote, because this
/// is `RelationGetRelationName` and not a regclass.
///
/// A context already on the error is kept and this line goes *below* it, which
/// is how a `plpgsql` trigger firing on a copied row reports both its own frame
/// and the row that reached it. Contexts stack outward, so each frame appends.
fn copy_row_context(
    error: ExecError,
    relation: &str,
    row: &crate::copyfmt::CopyRow<'_>,
    at: CopyContext<'_>,
) -> ExecError {
    with_copy_context(error, crate::copyfmt::copy_context(relation, row.line, at))
}

/// Add `context` below whatever context `error` already carried.
pub(crate) fn with_copy_context(error: ExecError, context: String) -> ExecError {
    let reported = error.into_pg();
    let stacked = match reported
        .diagnostics
        .as_ref()
        .and_then(|fields| fields.context.clone())
    {
        Some(existing) => format!("{existing}\n{context}"),
        None => context,
    };
    ExecError::Remote(reported.with_context(stacked))
}

/// The per-row work every write path shares once the target values are in
/// place.
///
/// Compute `GENERATED … STORED` columns, then enforce `NOT NULL`, then the
/// table's `CHECK` constraints. That is `PostgreSQL`'s order, and the reason a
/// generated column can satisfy a `CHECK` that references it.
pub(crate) fn finish_written_row(
    table: &Table,
    row: &mut [Datum],
    ctx: &crate::clock::EvalCtx,
) -> Result<(), ExecError> {
    apply_generated_columns(table, row, ctx)?;
    // The constraints are checked against a *logically* complete row: `row`
    // itself keeps the NULL placeholder a virtual column stores, and the
    // expansion happens on a copy only when a constraint could read it.
    let checked = if virtual_generated_needed_for_constraints(table) {
        let mut expanded = row.to_vec();
        expand_virtual_generated_row(table, &mut expanded, ctx)?;
        std::borrow::Cow::Owned(expanded)
    } else {
        std::borrow::Cow::Borrowed(&*row)
    };
    for (column, value) in table.columns.iter().zip(checked.iter()) {
        crate::usertype::check_domain(column.ty, value, ctx)?;
    }
    enforce_not_null(table, &checked)?;
    if table.checks.is_empty() {
        return Ok(());
    }
    let checks = compile_check_constraints(table)?;
    enforce_check_constraints(table, &checks, &checked, ctx)
}

fn enforce_not_null(table: &Table, row: &[Datum]) -> Result<(), ExecError> {
    for (column, value) in table.columns.iter().zip(row.iter()) {
        if column.not_null && value.is_null() {
            return Err(ExecError::NotNullViolation {
                column: column.name.clone(),
                // Unqualified whatever schema the relation is in and whatever
                // the statement wrote: PostgreSQL builds this message from
                // `RelationGetRelationName`, which is the bare `relname`.
                table: table.name.name.clone(),
            });
        }
    }
    Ok(())
}

fn default_value(column: &Column, ctx: &crate::clock::EvalCtx) -> Result<Datum, ExecError> {
    let Some(default) = &column.default else {
        return Ok(Datum::Null);
    };
    match default {
        // A stored `regclass` default holds only the oid, so the name it prints
        // is derived here — the same output-time resolution a scanned value
        // gets, which is what lets `RETURNING` print the relation's current
        // name rather than the bare number.
        ColumnDefault::Value(Datum::Regclass(value)) => match ctx.catalog() {
            Some(catalog) => regclass_by_oid(catalog, value.oid).map(Datum::Regclass),
            None => Ok(Datum::Regclass(value.clone())),
        },
        ColumnDefault::Value(value) => Ok(value.clone()),
        ColumnDefault::NextVal(sequence) => {
            let runtime = ctx.sequence.as_ref().ok_or_else(|| {
                ExecError::Unsupported("sequence defaults require a SQL session".into())
            })?;
            let (value, staged) =
                runtime
                    .manager
                    .nextval(&*runtime.kv, ctx.resolution(), sequence)?;
            if let Some(staged) = staged {
                runtime
                    .pending
                    .lock()
                    .expect("pending sequences")
                    .stage(staged);
            }
            runtime
                .currvals
                .lock()
                .expect("sequence currvals")
                .insert(sequence.clone(), value);
            coerce(Datum::Int8(value), column.ty, ctx)
        }
    }
}

/// The write path (INSERT/UPDATE/DELETE) with concurrent writers (SP6).
///
/// It builds the version write ops tagged with the transaction's `xid` and
/// returns them WITHOUT a write. The session assembles the final batch (clog
/// for autocommit) and writes once. INSERT allocates rowids with the
/// `SequenceManager`, which persists the sequence durably itself. UPDATE/DELETE
/// lock each candidate row exclusively with the `RowLockManager`. That lock
/// blocks until it is granted, or reports 40P01 on a deadlock. They then
/// re-check the row's current state under EvalPlanQual: a concurrent committed
/// change is a 40001 under REPEATABLE READ, or a re-find under READ COMMITTED.
/// Reads resolve with `satisfies_mvcc` and the txn's own xid
/// (read-your-writes).
pub(crate) async fn execute_write(
    write_ctx: &WriteContext<'_>,
    stmt: &Statement,
) -> Result<(QueryResult, Vec<crabka_pgkv::WriteOp>), ExecError> {
    let span = execute_write_span(write_ctx, stmt);
    let triggers_before = crate::trigger::fired_count();
    let mut writes = StatementWrites::default();
    let written = execute_write_with_ctes(write_ctx, write_ctx.ctes, stmt, &mut writes)
        .instrument(span.clone())
        .await;
    let (outcome, ops) = match written {
        Ok(written) => written,
        Err(error) => {
            let rendered = error.clone().into_pg();
            crate::telemetry::record_error(&span, &rendered.code, &rendered.message);
            return Err(error);
        }
    };
    record_write_outcome(
        &span,
        &outcome,
        &ops,
        crate::trigger::fired_count().saturating_sub(triggers_before),
    );
    Ok((outcome.into_result(write_ctx.eval_ctx), ops))
}

/// Build the span covering one data-modifying statement's execution.
///
/// This is guarded, not built unconditionally. A resolution of the target
/// relation costs a name resolution and a catalog read, and a span macro's
/// field expressions evaluate whether or not the callsite is enabled.
fn execute_write_span(write_ctx: &WriteContext<'_>, stmt: &Statement) -> tracing::Span {
    if !tracing::enabled!(target: crate::telemetry::EXEC_TARGET, tracing::Level::DEBUG) {
        return tracing::Span::none();
    }
    let span = tracing::debug_span!(
        target: crate::telemetry::EXEC_TARGET,
        "pg.execute_write",
        otel.kind = "internal",
        otel.status_code = tracing::field::Empty,
        otel.status_description = tracing::field::Empty,
        db.response.status_code = tracing::field::Empty,
        "error.type" = tracing::field::Empty,
        db.collection.name = tracing::field::Empty,
        pg.table_id = tracing::field::Empty,
        pg.rows_affected = tracing::field::Empty,
        pg.write_ops = tracing::field::Empty,
        pg.index_ops = tracing::field::Empty,
        pg.fk_checks = tracing::field::Empty,
        pg.triggers_fired = tracing::field::Empty,
        pg.returning = tracing::field::Empty,
    );
    if let Some(relation) = crate::telemetry::statement_relation(stmt) {
        span.record("db.collection.name", relation.name.as_str());
        // A statement whose target does not resolve — a `CREATE TABLE AS`, a
        // name that is about to fail — records the name it wrote and no id,
        // rather than failing the span build.
        if let Ok(resolved) = resolve_relation(
            write_ctx.catalog_kv,
            write_ctx.fctx.resolution,
            relation,
            SchemaDisposition::Reference,
        ) && let Ok(table) = crabka_pgcatalog::get_table(write_ctx.catalog_kv, &resolved)
        {
            span.record("pg.table_id", crate::telemetry::integer(table.id));
        }
    }
    span
}

/// Fold a write's outcome onto its span.
///
/// `pg.fk_checks` is deliberately absent here: the referential drain records it
/// itself, onto whichever span encloses it, because only the drain knows how
/// many checks a cascade grew the batch to.
fn record_write_outcome(
    span: &tracing::Span,
    outcome: &WriteOutcome,
    ops: &[crabka_pgkv::WriteOp],
    triggers_fired: u64,
) {
    if span.is_disabled() {
        return;
    }
    if let Some(rows) = crate::telemetry::command_tag_row_count(&outcome.tag) {
        span.record("pg.rows_affected", crate::telemetry::integer(rows));
    }
    span.record("pg.write_ops", crate::telemetry::integer(ops.len()));
    span.record("pg.index_ops", crate::telemetry::integer(index_ops(ops)));
    span.record(
        "pg.triggers_fired",
        crate::telemetry::integer(triggers_fired),
    );
    span.record("pg.returning", outcome.returning.is_some());
}

/// How many of a write's ops maintain a secondary index rather than the heap.
///
/// The split an operator wants when a write is slower than its row count
/// explains: index maintenance is per index per row, so it is what a wide
/// index set costs.
fn index_ops(ops: &[crabka_pgkv::WriteOp]) -> usize {
    ops.iter()
        .filter(|op| {
            let key = match op {
                crabka_pgkv::WriteOp::Put { key, .. }
                | crabka_pgkv::WriteOp::ConditionalPut { key, .. }
                | crabka_pgkv::WriteOp::Delete { key } => key,
            };
            matches!(
                crabka_pgkv::key::classify_key(key),
                crabka_pgkv::key::KeyClass::SecondaryIndex { .. }
            )
        })
        .count()
}

/// The write state every part of one statement shares: the `WITH` list's
/// data-modifying items and the statement body.
///
/// `PostgreSQL` runs all of those parts as ONE command. They read one snapshot,
/// but they are not independent writers. Three rules only hold if this state is
/// per statement and not per part:
///
/// - a unique index is enforced across the whole command, so
///   `WITH i AS (INSERT INTO t VALUES (1)) INSERT INTO t VALUES (1)` is 23505;
/// - a row one part modified is never modified again by another (`UPDATE` and
///   `DELETE` skip it, `MERGE` and `ON CONFLICT DO UPDATE` raise 21000);
/// - a unique key a part freed is available to a later part, because
///   `PostgreSQL`'s uniqueness check ignores a tuple its own command superseded.
#[derive(Debug, Default)]
struct StatementWrites {
    /// Unique-index keys claimed by rows this statement staged. They live only
    /// in the pending op batch, which a KV probe cannot see.
    pending_unique_keys: HashSet<PendingUniqueKey>,
    /// Exclusion keys staged by this statement, which are not visible in KV
    /// until the statement's batch commits.
    pending_exclusion_keys: HashMap<crabka_pgcatalog::IndexId, Vec<(u64, Vec<Datum>)>>,
    /// `(index, rowid)` pairs whose key this statement freed — a deleted row, or
    /// an updated row whose indexed values changed. A row holds exactly one key
    /// per index, so the rowid identifies the freed key. The superseded version
    /// is still in the KV, so the probe still finds it and must discount it.
    released_unique_keys: HashSet<(crabka_pgcatalog::IndexId, u64)>,
    /// Every `(table, rowid)` this statement has already updated or deleted,
    /// whether by its own DML or by a referential action.
    row_claims: HashSet<(TableId, u64)>,
    /// Which `(table, rowid, constraint)` triples a referential action has
    /// already written. See [`StatementWrites::claim_row_for_action`].
    action_claims: HashSet<(TableId, u64, String)>,
    /// The referential checks this statement owes, appended by the write hooks
    /// and drained once, after the `WITH` list AND the body, because
    /// `PostgreSQL` treats the whole command as one trigger-firing unit.
    fk_checks: crate::fk::FkCheckQueue,
    /// The relations a `TRUNCATE` is emptying, empty for every other statement.
    ///
    /// `TRUNCATE` desugars to one unfiltered `DELETE` per relation, and those
    /// deletes must not fire `ON DELETE CASCADE`: `PostgreSQL`'s `TRUNCATE`
    /// refuses a child outside the set and `CASCADE` widens the *set* instead.
    /// Carried here so the desugared `DELETE` can suppress exactly the
    /// parent-side keys whose child is being truncated too.
    truncate_set: BTreeSet<TableId>,
}

impl StatementWrites {
    /// Claim a row for the command's own DML. `false` means anything else in
    /// this statement already modified it, which is what stops this part from
    /// modifying it a second time.
    ///
    /// `PostgreSQL`'s "a command modifies a given row at most once" rule is
    /// about the command's own `ModifyTable` nodes, and every one of them runs
    /// before the trigger queue does, so a referential action can never be what
    /// this refuses.
    fn claim_row(&mut self, table: TableId, rowid: u64) -> bool {
        self.row_claims.insert((table, rowid))
    }

    /// Claim a row for one constraint's referential action. `false` means *that
    /// constraint's* action has already written this row.
    ///
    /// A referential action is not one of the command's `ModifyTable` nodes: it
    /// runs as a separate query the trigger queue issues, so it reaches a row
    /// the command itself already modified, and so does a *second* constraint's
    /// action reach a row the first one has just rewritten. This is how one
    /// `DELETE` of a doubly-referenced parent key nulls both referencing
    /// columns and not one.
    ///
    /// This refuses one constraint that comes back around to a row its own
    /// action already wrote. The drain folds each action's ops into the view it
    /// reads, so a cascade cycle already terminates on the data exactly as
    /// `PostgreSQL`'s does. A deleted row reads as gone, and a re-keyed one no
    /// longer matches. This bounds the work at one write per
    /// `(row, constraint)` whatever the data does.
    fn claim_row_for_action(&mut self, table: TableId, rowid: u64, constraint: &str) -> bool {
        if !self
            .action_claims
            .insert((table, rowid, constraint.to_string()))
        {
            return false;
        }
        self.row_claims.insert((table, rowid));
        true
    }

    /// Has anything in this command already modified this row? The predicate
    /// `ON CONFLICT DO UPDATE` raises 21000 on, where *what* touched the row
    /// makes no difference. The upsert may not be the second thing to reach it.
    fn is_claimed(&self, table: TableId, rowid: u64) -> bool {
        self.row_claims.contains(&(table, rowid))
    }

    /// Does the probe's `holder` still hold the key it was found under, or did
    /// an earlier part of this statement free it?
    fn holder_still_holds(&self, index: crabka_pgcatalog::IndexId, rowid: u64) -> bool {
        !self.released_unique_keys.contains(&(index, rowid))
    }

    /// Record the unique keys `rowid` gives up: every one when the row is
    /// deleted (`next` is `None`), and only the ones whose indexed values change
    /// when it is updated.
    fn release_row_keys(
        &mut self,
        table: &Table,
        indexes: &[crabka_pgcatalog::Index],
        rowid: u64,
        old_row: &[Datum],
        next: Option<&[Datum]>,
    ) -> Result<(), ExecError> {
        for index in indexes.iter().filter(|index| index.unique) {
            let old_values = indexed_values(table, index, old_row)?;
            if let Some(next) = next
                && indexed_values(table, index, next)? == old_values
            {
                continue;
            }
            self.released_unique_keys.insert((index.id, rowid));
        }
        Ok(())
    }
}

impl<'a> WriteContext<'a> {
    /// The context the foreign-key drain probes and scans through.
    ///
    /// The row store it reads is `staged`, this statement's write batch layered
    /// over the real one. The drain's whole premise is that the statement's rows
    /// already exist, and they only reach the KV when the session commits the
    /// batch.
    fn fk_exec<'b>(&'b self, staged: &'b StagedKv<'b>) -> crate::fk::FkExecContext<'b>
    where
        'a: 'b,
    {
        crate::fk::FkExecContext {
            catalog_kv: self.catalog_kv,
            kv: staged,
            global: self.global,
            global_snapshot: self.global_snapshot,
            snapshot: self.snapshot,
            xid: self.xid,
            eval_ctx: self.eval_ctx,
        }
    }

    /// Move the transaction's deferred-check store out of its mutex for the
    /// duration of a drain, which needs it by `&mut` across `await` points. The
    /// lock is held only for the swap, never across an await; the store is put
    /// back by [`WriteContext::restore_deferred_fk`] on every exit path.
    fn take_deferred_fk(&self) -> Option<crate::fk::DeferredConstraints> {
        self.deferred_fk
            .map(|store| std::mem::take(&mut *store.lock().expect("deferred constraints mutex")))
    }

    fn restore_deferred_fk(&self, store: Option<crate::fk::DeferredConstraints>) {
        if let Some(slot) = self.deferred_fk
            && let Some(store) = store
        {
            *slot.lock().expect("deferred constraints mutex") = store;
        }
    }
}

/// Both sides of a foreign key name the same lock identity, the referenced
/// index's entry prefix. That is exactly what the uniqueness check already
/// locks, so this is a [`crate::lockmgr::LockKey::UniqueKey`] acquire in the
/// row-lock manager and no new lock mode exists.
///
/// The child side takes it SHARED, so many rows that reference one parent key
/// never convoy. The parent side takes it EXCLUSIVE, because it removes or
/// moves the key. Key locks and row locks share one wait-for graph, so the
/// engine still reports a cycle across both as 40P01, and it releases both
/// together at COMMIT/ROLLBACK.
impl crate::fk::FkKeyLocks for WriteContext<'_> {
    async fn lock_key(&self, key: Vec<u8>, mode: crate::fk::FkLockMode) -> Result<(), ExecError> {
        let mode = match mode {
            crate::fk::FkLockMode::Shared => crate::lockmgr::LockMode::Shared,
            crate::fk::FkLockMode::Exclusive => crate::lockmgr::LockMode::Exclusive,
        };
        self.lockmgr
            .acquire_key_as(
                crate::lockmgr::LockKey::UniqueKey(key),
                mode,
                self.lock_owner,
                self.lock_wait_cap,
            )
            .await
            .map_err(lock_acquire_error)
    }
}

/// The write path a referential action re-enters, over the *outer statement's*
/// [`StatementWrites`].
///
/// `PostgreSQL` runs each referential action as its own query over the row's
/// current image, so neither an earlier `UPDATE` in the same command nor another
/// constraint's action exempts a child row from the action its parent's deletion
/// fires. Each action's ops are folded straight back into the staged view before
/// it returns, which is what makes "current image" true here: the next action to
/// reach the row reads what this one wrote, and a cascade cycle terminates
/// because the row it comes back to reads as deleted or off-key.
///
/// [`claim_row_for_action`] then only bounds the work, and refuses one
/// constraint a second write of the same row.
///
/// [`claim_row_for_action`]: StatementWrites::claim_row_for_action
struct StatementCascade<'a, 'w> {
    write_ctx: &'a WriteContext<'w>,
    writes: &'a mut StatementWrites,
    /// The view both this and the drain read through: the statement's pending
    /// batch over the store, grown by every op an action produces. An action
    /// re-reads its row here rather than in the store, so it changes the image
    /// the command, or an earlier action, last wrote.
    staged: &'a StagedKv<'a>,
    /// One index-set read per cascaded *relation*, not per cascaded row: a
    /// cascade walks a chain of relations and revisits each many times.
    indexes: HashMap<TableId, Vec<crabka_pgcatalog::Index>>,
}

impl crate::fk::FkCascade for StatementCascade<'_, '_> {
    fn begin_action(
        &mut self,
        table: &Table,
        delete: bool,
        updated: &[usize],
    ) -> Result<(), ExecError> {
        let event = if delete {
            crate::trigger::DmlEvent::Delete
        } else {
            crate::trigger::DmlEvent::Update
        };
        let columns = updated
            .iter()
            .filter_map(|index| table.columns.get(*index))
            .map(|column| column.name.clone())
            .collect::<Vec<_>>();
        crate::trigger::fire_statement(
            self.write_ctx.catalog_kv,
            table,
            event,
            crabka_pgcatalog::trigger::TriggerTiming::Before,
            &columns,
            self.write_ctx.eval_ctx,
        )
    }

    fn end_action(
        &mut self,
        table: &Table,
        delete: bool,
        updated: &[usize],
    ) -> Result<(), ExecError> {
        let event = if delete {
            crate::trigger::DmlEvent::Delete
        } else {
            crate::trigger::DmlEvent::Update
        };
        let columns = updated
            .iter()
            .filter_map(|index| table.columns.get(*index))
            .map(|column| column.name.clone())
            .collect::<Vec<_>>();
        crate::trigger::fire_statement(
            self.write_ctx.catalog_kv,
            table,
            event,
            crabka_pgcatalog::trigger::TriggerTiming::After,
            &columns,
            self.write_ctx.eval_ctx,
        )
    }

    async fn modify_row(
        &mut self,
        request: crate::fk::FkCascadeRequest<'_>,
    ) -> Result<(crate::fk::FkCascadeOutcome, Vec<crabka_pgkv::WriteOp>), ExecError> {
        let crate::fk::FkCascadeRequest {
            table,
            rowid,
            change,
            constraint,
        } = request;
        // Split the borrows: the index cache and the statement's write
        // bookkeeping are both reached mutably from the same `&mut self`.
        let Self {
            write_ctx,
            writes,
            staged,
            indexes,
        } = self;
        let write_ctx = *write_ctx;
        let staged = *staged;
        let ctx = write_ctx.eval_ctx;
        let mut ops = Vec::new();
        let local_indexes = match indexes.entry(table.id) {
            std::collections::hash_map::Entry::Occupied(slot) => slot.into_mut(),
            std::collections::hash_map::Entry::Vacant(slot) => {
                slot.insert(writable_local_indexes(write_ctx.catalog_kv, table)?)
            }
        };
        write_ctx
            .lockmgr
            .acquire_as(
                table.id,
                rowid,
                crate::lockmgr::LockMode::Exclusive,
                write_ctx.lock_owner,
                write_ctx.lock_wait_cap,
            )
            .await
            .map_err(lock_acquire_error)?;
        let Some((cur_key_xid, cur_xmin, cur_row)) =
            eval_plan_qual(&write_ctx.staged_mutation(staged), table, rowid)?
        else {
            // Deleted by a concurrent committed transaction, or by this command's
            // own DML: nothing references the parent through this row any more.
            return Ok((crate::fk::FkCascadeOutcome::Skipped, ops));
        };
        // A row this constraint's own action already wrote. It runs before any
        // op is built, so a revisited row leaves the batch untouched as well as
        // unrecursed. A row the command's own DML — or another constraint's
        // action — modified passes, because the action is a command of its own.
        if !writes.claim_row_for_action(table.id, rowid, constraint) {
            return Ok((crate::fk::FkCascadeOutcome::Skipped, ops));
        }
        let (next, updated_columns) = match change {
            crate::fk::FkRowChange::Delete => (None, Vec::new()),
            crate::fk::FkRowChange::Assign(pairs) => {
                let mut next = cur_row.clone();
                let mut updated = Vec::new();
                for (ordinal, value) in pairs {
                    let ty = cascade_column(table, ordinal)?.ty;
                    next[ordinal] = coerce(value, ty, ctx)?;
                    updated.push(table.columns[ordinal].name.clone());
                }
                (Some(next), updated)
            }
            crate::fk::FkRowChange::AssignDefaults(ordinals) => {
                let mut next = cur_row.clone();
                let mut updated = Vec::new();
                for ordinal in ordinals {
                    next[ordinal] = default_value(cascade_column(table, ordinal)?, ctx)?;
                    updated.push(table.columns[ordinal].name.clone());
                }
                (Some(next), updated)
            }
        };
        let Some(next) = next else {
            if crate::trigger::fire_before_row(
                write_ctx.catalog_kv,
                crate::trigger::WriteTarget {
                    table,
                    check: &crate::rls::WriteChecks::exempt(
                        crate::rls::CheckExemption::ReferentialAction,
                    ),
                },
                crate::trigger::DmlEvent::Delete,
                &[],
                Some(&cur_row),
                None,
                ctx,
            )?
            .is_none()
            {
                return Ok((crate::fk::FkCascadeOutcome::Skipped, ops));
            }
            apply_locked_row_delete(
                write_ctx,
                table,
                local_indexes,
                &LockedRowDelete {
                    rowid,
                    cur_key_xid,
                    cur_xmin,
                    cur_row: &cur_row,
                },
                writes,
                &mut ops,
            )?;
            crate::trigger::fire_after_row(
                write_ctx.catalog_kv,
                table,
                crate::trigger::DmlEvent::Delete,
                &[],
                Some(&cur_row),
                None,
                ctx,
            )?;
            staged.stage(&ops);
            return Ok((crate::fk::FkCascadeOutcome::Applied { new_row: None }, ops));
        };
        let Some(next) = crate::trigger::fire_before_row(
            write_ctx.catalog_kv,
            crate::trigger::WriteTarget {
                table,
                check: &crate::rls::WriteChecks::exempt(
                    crate::rls::CheckExemption::ReferentialAction,
                ),
            },
            crate::trigger::DmlEvent::Update,
            &updated_columns,
            Some(&cur_row),
            Some(next),
            ctx,
        )?
        else {
            return Ok((crate::fk::FkCascadeOutcome::Skipped, ops));
        };
        // The follow-on checks a cascaded update owes are computed by the drain
        // from the row it returns, so this write queues none of its own.
        let no_hooks = crate::fk::StatementFkContext::default();
        apply_locked_row_update(
            write_ctx,
            table,
            local_indexes,
            &no_hooks,
            &LockedRowUpdate {
                rowid,
                cur_key_xid,
                cur_xmin,
                cur_row: &cur_row,
                next: &next,
            },
            writes,
            &mut ops,
        )
        .await?;
        crate::trigger::fire_after_row(
            write_ctx.catalog_kv,
            table,
            crate::trigger::DmlEvent::Update,
            &updated_columns,
            Some(&cur_row),
            Some(&next),
            ctx,
        )?;
        staged.stage(&ops);
        Ok((
            crate::fk::FkCascadeOutcome::Applied {
                new_row: Some(next),
            },
            ops,
        ))
    }
}

/// Run the referential checks a statement queued, once its whole `WITH` list and
/// body have staged their rows.
///
/// `PostgreSQL` fires its `AFTER ROW` trigger queue once for the whole command,
/// which is why nothing here happens inline: a `NOT DEFERRABLE` self-referencing
/// `INSERT INTO t (id, boss) VALUES (1, 1)` succeeds because the row is in place
/// by the time the check runs. A referential action re-enters the write path
/// through [`StatementCascade`], which shares this statement's
/// [`StatementWrites`]. So a cascade that comes back around to a row *an
/// action* already changed stops and does not recurse, while a row the
/// statement's own DML modified is still the action's to change.
async fn drain_statement_fk_checks(
    write_ctx: &WriteContext<'_>,
    writes: &mut StatementWrites,
    staged: &[crabka_pgkv::WriteOp],
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    if writes.fk_checks.is_empty() {
        return Ok(Vec::new());
    }
    let mut queue = std::mem::take(&mut writes.fk_checks);
    let staged_kv = StagedKv::new(write_ctx.kv, staged);
    let exec = write_ctx.fk_exec(&staged_kv);
    let mut cascade = StatementCascade {
        write_ctx,
        writes,
        staged: &staged_kv,
        indexes: HashMap::new(),
    };
    let mut deferred = write_ctx.take_deferred_fk();
    let drained = crate::fk::drain_statement_checks(
        &exec,
        write_ctx,
        &mut cascade,
        &mut queue,
        deferred.as_mut(),
    )
    .await;
    write_ctx.restore_deferred_fk(deferred);
    drained
}

/// Run the checks a transaction deferred, at `COMMIT` or at
/// `SET CONSTRAINTS … IMMEDIATE`.
///
/// Every earlier statement's rows are in the KV under this transaction's xid by
/// now, so the drain reads storage directly (an empty staged batch) and finds
/// a re-supplied key. This is what makes `DELETE; INSERT; COMMIT`
/// succeed under a deferred `NO ACTION`. A referential action re-enters the
/// write path through the same [`StatementCascade`] the statement drain uses,
/// over write bookkeeping of its own: the statements whose rows these checks
/// describe are finished, so there is none to share.
pub(crate) async fn drain_deferred_fk_checks(
    write_ctx: &WriteContext<'_>,
    checks: Vec<crate::fk::PendingCheck>,
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    if checks.is_empty() {
        return Ok(Vec::new());
    }
    let staged_kv = StagedKv::new(write_ctx.kv, &[]);
    let exec = write_ctx.fk_exec(&staged_kv);
    let mut writes = StatementWrites::default();
    let mut cascade = StatementCascade {
        write_ctx,
        writes: &mut writes,
        staged: &staged_kv,
        indexes: HashMap::new(),
    };
    crate::fk::drain_deferred_checks(&exec, write_ctx, &mut cascade, checks).await
}

/// The column a referential action names by ordinal. The ordinals come from the
/// same catalog relation the request carries, so a miss is catalog corruption.
fn cascade_column(table: &Table, ordinal: usize) -> Result<&Column, ExecError> {
    table
        .columns
        .get(ordinal)
        .ok_or_else(|| ExecError::UndefinedTableColumn {
            column: ordinal.to_string(),
            table: table.name.to_string(),
        })
}

/// What a data-modifying statement produced: the command tag, plus the relation
/// its `RETURNING` clause projected (absent when the statement had none).
pub(crate) struct WriteOutcome {
    tag: String,
    returning: Option<Relation>,
}

impl WriteOutcome {
    fn command(tag: String) -> Self {
        Self {
            tag,
            returning: None,
        }
    }

    fn into_result(self, ctx: &crate::clock::EvalCtx) -> QueryResult {
        match self.returning {
            None => QueryResult::Command { tag: self.tag },
            Some(rel) => {
                let fields = rel
                    .scope
                    .columns
                    .iter()
                    .map(|c| field(&c.name, c.ty))
                    .collect();
                rows_result_with_tag(fields, &rel.rows, ctx.output_style(), self.tag)
            }
        }
    }
}

/// Run the whole of one data-modifying statement: its `WITH` list, its body, and
/// then the referential checks all of those queued.
///
/// The drain is here rather than in each part because `PostgreSQL` treats the
/// `WITH`-list-plus-body as ONE command and fires its `AFTER ROW` trigger queue
/// once for it.
async fn execute_write_with_ctes(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    stmt: &Statement,
    writes: &mut StatementWrites,
) -> Result<(WriteOutcome, Vec<crabka_pgkv::WriteOp>), ExecError> {
    let mut statement_triggers = Vec::new();
    if let Some(with) = statement_with_clause(stmt) {
        for cte in &with.ctes {
            if let crabka_pgparser::ast::CteBody::Dml(dml) = &cte.body {
                statement_triggers.extend(statement_trigger_targets(write_ctx, dml)?);
            }
        }
    }
    statement_triggers.extend(statement_trigger_targets(write_ctx, stmt)?);
    for (table, event, updated) in &statement_triggers {
        crate::trigger::fire_statement(
            write_ctx.catalog_kv,
            table,
            *event,
            crabka_pgcatalog::trigger::TriggerTiming::Before,
            updated,
            write_ctx.eval_ctx,
        )?;
    }
    let (outcome, mut ops) = execute_write_parts(write_ctx, ctes, stmt, writes).await?;
    let fk_ops = drain_statement_fk_checks(write_ctx, writes, &ops).await?;
    ops.extend(fk_ops);
    for (table, event, updated) in statement_triggers.iter().rev() {
        crate::trigger::fire_statement(
            write_ctx.catalog_kv,
            table,
            *event,
            crabka_pgcatalog::trigger::TriggerTiming::After,
            updated,
            write_ctx.eval_ctx,
        )?;
    }
    Ok((outcome, ops))
}

/// Every relation a `TRUNCATE` empties, before `CASCADE` is consulted.
///
/// A target without `ONLY` stands for its whole inheritance tree, exactly as it
/// does for `UPDATE` and `DELETE`: `TRUNCATE parent` leaves an inheritance
/// child empty in `PostgreSQL`, and `TRUNCATE ONLY parent` is the spelling that
/// spares it. Both call sites read this list — the one that empties the
/// relations and the one that collects their statement triggers — so a child
/// pulled in here is both truncated and gets its `BEFORE TRUNCATE` trigger
/// fired, which is what `PostgreSQL` does.
///
/// Names are deduplicated: two targets in one list may share a descendant, and
/// so may the two routes to one relation in a multiple-inheritance DAG.
fn truncate_names(
    kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    targets: &[crabka_pgparser::ast::TruncateTarget],
) -> Result<Vec<crabka_pgparser::ast::RelationRef>, ExecError> {
    let mut out = Vec::with_capacity(targets.len());
    let mut seen = HashSet::new();
    for target in targets {
        let named = resolve_relation(kv, resolution, &target.name, SchemaDisposition::Utility)?;
        // The one member of the `ONLY` family that refuses rather than answers.
        // `SELECT`/`UPDATE`/`DELETE … ONLY` over a partitioned parent all read
        // or write its own — empty — row space and report nothing done, but
        // `TRUNCATE ONLY` is 42809 on 18.4, on the grounds that a partitioned
        // parent has no storage to truncate and the statement is therefore a
        // mistake rather than a no-op.
        if target.only && crate::partition::is_partitioned(kv, &named)? {
            return Err(ExecError::TruncateOnlyPartitioned);
        }
        let mut tree = vec![named.clone()];
        if !target.only {
            tree.extend(crate::inheritance::descendants(kv, &named)?);
        }
        for relation in tree {
            if seen.insert(relation.clone()) {
                out.push(crabka_pgparser::ast::RelationRef::qualified(
                    &relation.schema,
                    &relation.name,
                ));
            }
        }
    }
    Ok(out)
}

fn statement_trigger_targets(
    write_ctx: &WriteContext<'_>,
    stmt: &Statement,
) -> Result<Vec<(Table, crate::trigger::DmlEvent, Vec<String>)>, ExecError> {
    if let Statement::Truncate {
        targets, cascade, ..
    } = stmt
    {
        let written = truncate_names(
            write_ctx.catalog_kv,
            write_ctx.eval_ctx.resolution(),
            targets,
        )?;
        let names = resolve_relations(
            write_ctx.catalog_kv,
            write_ctx.eval_ctx.resolution(),
            &written,
            SchemaDisposition::Utility,
        )?;
        let tables = names
            .iter()
            .map(|name| {
                // This runs before the TRUNCATE arm itself, so a wrong-kind
                // target has to be refused here or it is reported as missing.
                match truncate_wrong_kind(write_ctx.catalog_kv, name) {
                    Some(error) => Err(error),
                    None => Ok(crabka_pgcatalog::get_table(write_ctx.catalog_kv, name)?),
                }
            })
            .collect::<Result<Vec<_>, ExecError>>()?;
        return Ok(
            crate::fk::expand_truncate_set(write_ctx.catalog_kv, &tables, *cascade)?
                .tables
                .into_iter()
                .map(|table| (table, crate::trigger::DmlEvent::Truncate, Vec::new()))
                .collect(),
        );
    }
    if let Statement::Insert {
        table,
        on_conflict:
            Some(crabka_pgparser::ast::OnConflict {
                action: crabka_pgparser::ast::OnConflictAction::DoUpdate { assignments, .. },
                ..
            }),
        ..
    } = stmt
    {
        let name = resolve_relation(
            write_ctx.catalog_kv,
            write_ctx.eval_ctx.resolution(),
            table,
            SchemaDisposition::Reference,
        )?;
        let table = crate::trigger::relation_trigger_table(write_ctx.catalog_kv, &name)?;
        return Ok(vec![
            (table.clone(), crate::trigger::DmlEvent::Insert, Vec::new()),
            (
                table,
                crate::trigger::DmlEvent::Update,
                assignments
                    .iter()
                    .map(|(column, _)| column.clone())
                    .collect(),
            ),
        ]);
    }
    if let Statement::Merge { table, clauses, .. } = stmt {
        let name = resolve_relation(
            write_ctx.catalog_kv,
            write_ctx.eval_ctx.resolution(),
            table,
            SchemaDisposition::Reference,
        )?;
        let table = crate::trigger::relation_trigger_table(write_ctx.catalog_kv, &name)?;
        let mut insert = false;
        let mut delete = false;
        let mut updated = Vec::new();
        for clause in clauses {
            match &clause.action {
                crabka_pgparser::ast::MergeAction::Insert { .. } => insert = true,
                crabka_pgparser::ast::MergeAction::Delete => delete = true,
                crabka_pgparser::ast::MergeAction::Update(assignments) => {
                    for column in assignments
                        .iter()
                        .flat_map(|assignment| assignment.targets.iter())
                    {
                        if !updated.contains(column) {
                            updated.push(column.clone());
                        }
                    }
                }
                crabka_pgparser::ast::MergeAction::DoNothing => {}
            }
        }
        let mut targets = Vec::new();
        if insert {
            targets.push((table.clone(), crate::trigger::DmlEvent::Insert, Vec::new()));
        }
        if !updated.is_empty() {
            targets.push((table.clone(), crate::trigger::DmlEvent::Update, updated));
        }
        if delete {
            targets.push((table, crate::trigger::DmlEvent::Delete, Vec::new()));
        }
        return Ok(targets);
    }
    let (reference, event, updated) = match stmt {
        Statement::Insert { table, .. } => (table, crate::trigger::DmlEvent::Insert, Vec::new()),
        Statement::Update {
            table, assignments, ..
        } => (
            table,
            crate::trigger::DmlEvent::Update,
            assignments
                .iter()
                .flat_map(|assignment| assignment.targets.iter().cloned())
                .collect(),
        ),
        Statement::Delete { table, .. } => (table, crate::trigger::DmlEvent::Delete, Vec::new()),
        _ => return Ok(Vec::new()),
    };
    let name = resolve_relation(
        write_ctx.catalog_kv,
        write_ctx.eval_ctx.resolution(),
        reference,
        SchemaDisposition::Reference,
    )?;
    let table = crate::trigger::relation_trigger_table(write_ctx.catalog_kv, &name)?;
    if crabka_pgcatalog::get_view(write_ctx.catalog_kv, &name).is_ok()
        && !crate::trigger::has_instead_row_trigger(
            write_ctx.catalog_kv,
            table.id,
            event,
            &updated,
        )?
    {
        return Ok(Vec::new());
    }
    Ok(vec![(table, event, updated)])
}

/// Evaluate the statement's `WITH` list, then the statement body against that
/// CTE scope.
///
/// The `WITH` list includes any data-modifying entries, which run exactly once
/// each whether or not the body references them. The referential checks they
/// queue are left for [`execute_write_with_ctes`] to drain once for all of
/// them.
///
/// Every entry sees the statement's own snapshot: a data-modifying CTE's rows
/// are staged as write ops and never written to the KV here, so neither a later
/// CTE nor the body can observe them, exactly as in `PostgreSQL`.
///
/// The parts run in `PostgreSQL`'s order, which is observable whenever two of
/// them touch the same row (whichever runs first is the one whose change
/// survives, because [`StatementWrites`] then holds the row against the other).
/// `PostgreSQL` runs a data-modifying item when something first demands its
/// rows, and runs the items nothing demands AFTER the main query, in reverse
/// list order, the order `ExecPostprocessPlan` walks `es_auxmodifytables`.
async fn execute_write_parts(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    stmt: &Statement,
    writes: &mut StatementWrites,
) -> Result<(WriteOutcome, Vec<crabka_pgkv::WriteOp>), ExecError> {
    let Some(with) = statement_with_clause(stmt) else {
        return execute_write_body(write_ctx, ctes, stmt, writes, Reach::of(stmt)).await;
    };
    let mut ops = Vec::new();
    let mut scope = ctes.child();
    // The body is stripped up front: the reference check below must see it
    // without the `WITH` list, whose own names would shadow the item.
    let body = statement_without_with(stmt);
    let mut deferred = Vec::new();
    for (index, cte) in with.ctes.iter().enumerate() {
        let rel = match &cte.body {
            crabka_pgparser::ast::CteBody::Query(_) => {
                let read = write_ctx.read_ctx(&scope);
                crate::cte::evaluate_cte_relation(&read, cte, with.recursive, &scope)?
            }
            crabka_pgparser::ast::CteBody::Dml(dml) => {
                if !cte_is_referenced(with, &body, index, &cte.name) {
                    // Nothing demands its rows, so it runs after the body.
                    deferred.push(dml);
                    continue;
                }
                let (outcome, cte_ops) = Box::pin(execute_write_body(
                    write_ctx,
                    &scope,
                    dml,
                    writes,
                    Reach::of(dml),
                ))
                .await?;
                ops.extend(cte_ops);
                let Some(rel) = outcome.returning else {
                    // Only a *reference* to a data-modifying item without a
                    // RETURNING clause is refused, and this item is referenced.
                    return Err(ExecError::Unsupported(format!(
                        "WITH query \"{}\" does not have a RETURNING clause",
                        cte.name
                    )));
                };
                // `evaluate_cte_relation` applies the aliases for a query item.
                crate::cte::apply_cte_column_aliases(rel, &cte.name, &cte.columns)?
            }
        };
        scope.insert(cte.name.clone(), rel);
    }
    let (outcome, body_ops) = Box::pin(execute_write_body(
        write_ctx,
        &scope,
        &body,
        writes,
        Reach::of(&body),
    ))
    .await?;
    ops.extend(body_ops);
    for dml in deferred.into_iter().rev() {
        let (_, cte_ops) = Box::pin(execute_write_body(
            write_ctx,
            &scope,
            dml,
            writes,
            Reach::of(dml),
        ))
        .await?;
        ops.extend(cte_ops);
    }
    Ok((outcome, ops))
}

/// Whether anything after `WITH` item `index` names it: a later item, or the
/// statement body.
fn cte_is_referenced(
    with: &crabka_pgparser::ast::WithClause,
    stmt: &Statement,
    index: usize,
    name: &str,
) -> bool {
    with.ctes[index + 1..]
        .iter()
        .any(|later| match &later.body {
            crabka_pgparser::ast::CteBody::Query(query) => {
                crate::cte::query_references(query, name)
            }
            crabka_pgparser::ast::CteBody::Dml(dml) => statement_references_relation(dml, name),
        })
        || statement_references_relation(stmt, name)
}

/// Whether a statement's relation positions name `name`.
fn statement_references_relation(stmt: &Statement, name: &str) -> bool {
    use crabka_pgparser::ast::{InsertSource, MergeSource};
    match stmt {
        Statement::Query(query) => crate::cte::query_references(query, name),
        Statement::CreateTableAs { query, .. } => crate::cte::query_references(query, name),
        Statement::Insert { source, .. } => match source {
            InsertSource::Query(query) => crate::cte::query_references(query, name),
            InsertSource::Values(_) | InsertSource::DefaultValues => false,
        },
        Statement::Update { from, .. } => from.iter().any(|item| table_expr_references(item, name)),
        Statement::Delete { using, .. } => {
            using.iter().any(|item| table_expr_references(item, name))
        }
        Statement::Merge { source, .. } => match source {
            MergeSource::Table { name: source, .. } => source.name == *name,
            MergeSource::Query { query, .. } => crate::cte::query_references(query, name),
        },
        _ => false,
    }
}

fn table_expr_references(item: &crabka_pgparser::ast::TableExpr, name: &str) -> bool {
    use crabka_pgparser::ast::TableExpr;
    match item {
        TableExpr::Table { name: source, .. } => source.name == *name,
        TableExpr::Derived { subquery, .. } => crate::cte::query_references(subquery, name),
        TableExpr::Join { left, right, .. } => {
            table_expr_references(left, name) || table_expr_references(right, name)
        }
        _ => false,
    }
}

/// The `WITH` list attached to a statement, when it has one.
pub(crate) fn statement_with_clause(stmt: &Statement) -> Option<&crabka_pgparser::ast::WithClause> {
    match stmt {
        Statement::Query(q) => q.with.as_ref(),
        Statement::CreateTableAs { query, .. } => query.with.as_ref(),
        Statement::Insert { with, .. }
        | Statement::Update { with, .. }
        | Statement::Delete { with, .. }
        | Statement::Merge { with, .. } => with.as_ref(),
        _ => None,
    }
}

/// The same statement with its `WITH` list removed. The CTE relations are
/// already materialized into the scope the body executes against.
fn statement_without_with(stmt: &Statement) -> Statement {
    let mut stmt = stmt.clone();
    match &mut stmt {
        Statement::Query(q) => q.with = None,
        Statement::CreateTableAs { query, .. } => query.with = None,
        Statement::Insert { with, .. }
        | Statement::Update { with, .. }
        | Statement::Delete { with, .. }
        | Statement::Merge { with, .. } => *with = None,
        _ => {}
    }
    stmt
}

/// Fold every uncorrelated subquery in a data-modifying statement's expression
/// clauses to a constant, under this statement's snapshot and CTE scope.
///
/// The write path's evaluator executes no subqueries of its own, so this is what
/// lets `UPDATE … WHERE k IN (SELECT …)` and a `MERGE` condition over a CTE work
/// at all. Each one is evaluated once for the statement, which is `PostgreSQL`'s
/// behavior for an uncorrelated subquery.
fn resolve_write_subqueries(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    stmt: &Statement,
) -> Result<Statement, ExecError> {
    use crabka_pgparser::ast::{AssignmentValue, InsertSource, MergeAction};

    let read = write_ctx.read_ctx(ctes);
    let resolve = |expr: &Expr| crate::subquery::resolve_expr(&read, expr);
    let resolve_opt = |expr: &Option<Expr>| -> Result<Option<Expr>, ExecError> {
        expr.as_ref().map(&resolve).transpose()
    };
    let resolve_assignments =
        |assignments: &mut Vec<crabka_pgparser::ast::Assignment>| -> Result<(), ExecError> {
            for assignment in assignments {
                match &mut assignment.value {
                    AssignmentValue::Expr(expr) => *expr = resolve(expr)?,
                    AssignmentValue::Row(items) => {
                        for item in items {
                            *item = resolve(item)?;
                        }
                    }
                    AssignmentValue::Subquery(_) => {}
                }
            }
            Ok(())
        };

    let mut stmt = stmt.clone();
    match &mut stmt {
        Statement::Insert {
            source: InsertSource::Values(rows),
            ..
        } => {
            for row in rows {
                for value in row {
                    *value = resolve(value)?;
                }
            }
        }
        Statement::Update {
            assignments,
            filter,
            ..
        } => {
            resolve_assignments(assignments)?;
            *filter = resolve_opt(filter)?;
        }
        Statement::Delete { filter, .. } => *filter = resolve_opt(filter)?,
        Statement::Merge { on, clauses, .. } => {
            *on = resolve(on)?;
            for clause in clauses {
                clause.condition = resolve_opt(&clause.condition)?;
                match &mut clause.action {
                    MergeAction::Update(assignments) => resolve_assignments(assignments)?,
                    MergeAction::Insert {
                        values: Some(values),
                        ..
                    } => {
                        for value in values {
                            *value = resolve(value)?;
                        }
                    }
                    MergeAction::Insert { .. } | MergeAction::Delete | MergeAction::DoNothing => {}
                }
            }
        }
        _ => {}
    }
    Ok(stmt)
}

/// `UPDATE`/`DELETE` over a partitioned parent: the same statement runs against
/// each leaf in turn and the affected-row counts are summed.
///
/// Divergence from `PostgreSQL`: an `UPDATE` that moves a row out of its own
/// partition's bound is 23514 here (`new row for relation … violates partition
/// constraint`), where `PostgreSQL` deletes the row from its old partition and
/// re-inserts it into the new one. A refusal is the correctness-preserving
/// choice. The alternative stores a row in a partition whose bound it does not
/// satisfy, and every later read would answer that wrongly.
async fn partitioned_dml(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    stmt: &Statement,
    writes: &mut StatementWrites,
) -> Result<(WriteOutcome, Vec<crabka_pgkv::WriteOp>), ExecError> {
    let resolution = write_ctx.eval_ctx.resolution();
    let (parent, verb, returning) = match stmt {
        Statement::Update {
            table, returning, ..
        } => (table, "UPDATE", returning),
        Statement::Delete {
            table, returning, ..
        } => (table, "DELETE", returning),
        _ => unreachable!("the caller matched an UPDATE or a DELETE"),
    };
    let parent = resolve_relation(
        write_ctx.catalog_kv,
        resolution,
        parent,
        SchemaDisposition::Reference,
    )?;
    let mut ops = Vec::new();
    let mut affected: u64 = 0;
    let mut returned: Option<Relation> = None;
    let parent_table = crabka_pgcatalog::get_table(write_ctx.catalog_kv, &parent)?;
    for leaf in crate::partition::leaves_of(write_ctx.catalog_kv, &parent)? {
        // The per-leaf body resolves `RETURNING` against the leaf's own column
        // order, so a leaf whose columns are ordered differently would
        // contribute rows in a different shape. That only arises for a leaf
        // attached from a table declared out of order, and it is refused rather
        // than answered with mismatched columns. Without `RETURNING` no row
        // shape escapes the statement, so the mismatch cannot be observed and
        // the write proceeds -- which is what lets `TRUNCATE` reach such a
        // partition, since it runs as an unqualified `DELETE`.
        let leaf_table = crabka_pgcatalog::get_table(write_ctx.catalog_kv, &leaf)?;
        if returning.is_some()
            && column_mapping(&parent_table, &leaf_table)?
                .iter()
                .enumerate()
                .any(|(expected, actual)| expected != *actual)
        {
            return Err(ExecError::Unsupported(format!(
                "{verb} over a partitioned table is not supported when a partition declares its \
                 columns in a different order than its parent: partition \"{leaf}\" does"
            )));
        }
        let per_leaf = retarget_tree_dml(stmt, &leaf, &parent);
        // The partitioned parent owns no rows, but it is the relation the
        // statement named, so it is the one whose ACL and policies decide the
        // write. See [`WriteContext::governing`].
        let leaf_ctx = WriteContext {
            governing: Some(write_ctx.governing.unwrap_or(&parent_table)),
            ..*write_ctx
        };
        let (outcome, leaf_ops) = Box::pin(execute_write_body(
            &leaf_ctx,
            ctes,
            &per_leaf,
            writes,
            Reach::Storage,
        ))
        .await?;
        ops.extend(leaf_ops);
        // The per-leaf body already rendered its own count into the tag; the
        // parent's tag is their sum.
        affected += affected_from_tag(&outcome.tag);
        if let Some(rows) = outcome.returning {
            match &mut returned {
                Some(accumulated) => accumulated.rows.extend(rows.rows),
                None => returned = Some(rows),
            }
        }
    }
    Ok((
        WriteOutcome {
            tag: format!("{verb} {affected}"),
            returning: returned,
        },
        ops,
    ))
}

/// The row count a completed write rendered into its command tag.
fn affected_from_tag(tag: &str) -> u64 {
    tag.rsplit(' ')
        .next()
        .and_then(|count| count.parse::<u64>().ok())
        .unwrap_or_default()
}

/// Point one relation's `UPDATE`/`DELETE` at a single relation below it.
///
/// Two things travel with the target beyond its name.
///
/// `only` is set because the caller has already enumerated the whole tree:
/// without it a child with children of its own would expand again and write
/// every grandchild once per path to it. It says that and nothing more — the
/// caller passes [`Reach::Storage`] alongside, and that, not this flag, is what
/// decides whether a partitioned target still expands into its leaves. The two
/// questions used to share this one boolean, which is how `ONLY` came to be
/// ignored on a partitioned parent; see [`Reach`]. The flag survives because
/// the sharded-write gate reads it for the inheritance question alone.
///
/// The alias is the subtle one. Every expression in the statement resolves
/// against [`table_qualifier`], which falls back to the *table's own name* when
/// no alias is given — so simply renaming the target silently moves the
/// qualifier from `parent` to `child`, and `UPDATE parent SET … WHERE
/// parent.x = 1` stops resolving with "missing FROM-clause entry for table
/// parent". Pinning the alias to the name the statement was written against
/// keeps every qualified reference — in the filter, in a `SET` right-hand side
/// and in `RETURNING` — resolving to the same thing it did before the rewrite.
fn retarget_tree_dml(
    stmt: &Statement,
    target: &crabka_pgcatalog::RelationName,
    named: &crabka_pgcatalog::RelationName,
) -> Statement {
    let mut per_relation = stmt.clone();
    match &mut per_relation {
        Statement::Update {
            table, only, alias, ..
        }
        | Statement::Delete {
            table, only, alias, ..
        } => {
            *table = crabka_pgparser::ast::RelationRef::qualified(&target.schema, &target.name);
            *only = true;
            if alias.is_none() {
                *alias = Some(named.name.clone());
            }
        }
        _ => unreachable!("the caller matched an UPDATE or a DELETE"),
    }
    per_relation
}

/// `UPDATE parent` / `DELETE FROM parent` over a table-inheritance tree, which
/// `PostgreSQL` applies to the parent *and* every relation below it unless the
/// statement said `ONLY`.
///
/// This mirrors [`inherited_scan`] on the read side, and has to: leaving it out
/// is not a missing feature but a wrong answer, because `SELECT count(*) FROM
/// parent` already counts the child rows that `DELETE FROM parent` then walks
/// past. The tree is a DAG rather than a chain — `d INHERITS (b, c)` under
/// `b, c INHERITS a` is reachable from `a` twice — so the relation list comes
/// from [`crate::inheritance::descendants`], which names each one once, and in
/// the same order the read side appends them.
///
/// Unlike a partitioned write, this never moves a row: `PostgreSQL` updates an
/// inheritance child's row in place even when the new value would have suited
/// the parent, so each relation's rows are simply written where they already
/// live.
async fn inherited_dml(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    stmt: &Statement,
    writes: &mut StatementWrites,
) -> Result<(WriteOutcome, Vec<crabka_pgkv::WriteOp>), ExecError> {
    let resolution = write_ctx.eval_ctx.resolution();
    let (named, verb) = match stmt {
        Statement::Update { table, .. } => (table, "UPDATE"),
        Statement::Delete { table, .. } => (table, "DELETE"),
        _ => unreachable!("the caller matched an UPDATE or a DELETE"),
    };
    let named = resolve_relation(
        write_ctx.catalog_kv,
        resolution,
        named,
        SchemaDisposition::Reference,
    )?;
    let parent = crabka_pgcatalog::get_table(write_ctx.catalog_kv, &named)?;
    let mut relations = vec![named.clone()];
    relations.extend(crate::inheritance::descendants(
        write_ctx.catalog_kv,
        &named,
    )?);
    let stmt = &reshape_returning_for_tree(write_ctx, stmt, &parent, &relations)?;
    let mut ops = Vec::new();
    let mut affected: u64 = 0;
    let mut returned: Option<Relation> = None;
    for relation in relations {
        let per_relation = retarget_tree_dml(stmt, &relation, &named);
        // Every relation in the tree is written under the named parent's ACL
        // and policies. See [`WriteContext::governing`].
        let child_ctx = WriteContext {
            governing: Some(write_ctx.governing.unwrap_or(&parent)),
            ..*write_ctx
        };
        let (outcome, child_ops) = Box::pin(execute_write_body(
            &child_ctx,
            ctes,
            &per_relation,
            writes,
            Reach::Storage,
        ))
        .await?;
        ops.extend(child_ops);
        affected += affected_from_tag(&outcome.tag);
        if let Some(rows) = outcome.returning {
            match &mut returned {
                Some(accumulated) => accumulated.rows.extend(rows.rows),
                None => returned = Some(rows),
            }
        }
    }
    Ok((
        WriteOutcome {
            tag: format!("{verb} {affected}"),
            returning: returned,
        },
        ops,
    ))
}

/// Pin a tree write's `RETURNING *` to the parent's column list.
///
/// A `*` is expanded per relation against whatever that relation stores, so a
/// child declared `(b, a)` would contribute its rows in the wrong order and a
/// child with an extra column would contribute an extra field —
/// `PostgreSQL` reports every row of the hierarchy in the *parent's* shape.
/// Naming the parent's columns explicitly, once, makes each relation produce
/// that shape; they resolve in every child because inheritance guarantees the
/// name is there, whatever ordinal it sits at.
///
/// The rewrite is skipped when no relation below the parent departs from its
/// column list, which is the overwhelmingly common case (`CREATE TABLE c ()
/// INHERITS (p)`) — there `*` already expands identically everywhere, and the
/// statement is passed through untouched.
fn reshape_returning_for_tree(
    write_ctx: &WriteContext<'_>,
    stmt: &Statement,
    parent: &Table,
    relations: &[crabka_pgcatalog::RelationName],
) -> Result<Statement, ExecError> {
    let (returning, from, alias) = match stmt {
        Statement::Update {
            returning,
            from,
            alias,
            ..
        } => (returning, from.as_slice(), alias),
        Statement::Delete {
            returning,
            using,
            alias,
            ..
        } => (returning, using.as_slice(), alias),
        _ => unreachable!("the caller matched an UPDATE or a DELETE"),
    };
    let qualifier = alias.clone().unwrap_or_else(|| parent.name.name.clone());
    let Some(returning) = returning else {
        return Ok(stmt.clone());
    };
    let spans_target = |item: &SelectItem| match item {
        SelectItem::Wildcard => true,
        SelectItem::QualifiedWildcard(q) => *q == qualifier,
        SelectItem::Expr { .. } => false,
    };
    if !returning.items.iter().any(spans_target) {
        return Ok(stmt.clone());
    }
    let mut uniform = true;
    for relation in relations {
        let child = crabka_pgcatalog::get_table(write_ctx.catalog_kv, relation)?;
        uniform &= child.columns.len() == parent.columns.len()
            && column_mapping(parent, &child)?
                .iter()
                .enumerate()
                .all(|(expected, actual)| expected == *actual);
    }
    if uniform {
        return Ok(stmt.clone());
    }
    // A bare `*` also spans the FROM/USING relations, and their columns cannot
    // be named here without resolving each source item's own shape. Refusing is
    // the honest answer: silently dropping them would report the wrong row.
    if !from.is_empty() && returning.items.contains(&SelectItem::Wildcard) {
        return Err(ExecError::Unsupported(format!(
            "RETURNING * over an inheritance tree is not supported alongside FROM/USING when a \
             relation below \"{}\" declares the parent's columns differently; name the columns \
             explicitly",
            parent.name
        )));
    }
    let target_columns: Vec<SelectItem> = parent
        .columns
        .iter()
        .map(|column| SelectItem::Expr {
            expr: Expr::Column {
                table: Some(qualifier.clone()),
                name: column.name.clone(),
            },
            alias: Some(column.name.clone()),
        })
        .collect();
    let items = returning
        .items
        .iter()
        .flat_map(|item| {
            if spans_target(item) {
                target_columns.clone()
            } else {
                vec![item.clone()]
            }
        })
        .collect();
    let reshaped = crabka_pgparser::ast::Returning {
        items,
        ..returning.clone()
    };
    let mut out = stmt.clone();
    match &mut out {
        Statement::Update { returning, .. } | Statement::Delete { returning, .. } => {
            *returning = Some(reshaped);
        }
        _ => unreachable!("the caller matched an UPDATE or a DELETE"),
    }
    Ok(out)
}

/// Describe a rejected row for this write's caller, or answer `None` when that
/// caller may not be shown it. A forwarder to the one gate,
/// [`crate::rls::describe_row`], which is where the rule lives.
fn describe_row(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    row: &[Datum],
    modified: &[String],
) -> Option<String> {
    let describer = write_ctx.describer();
    crate::rls::describe_row(
        &describer.privileges(write_ctx.catalog_kv),
        &describer.security(write_ctx.catalog_kv),
        table,
        row,
        modified,
        write_ctx.eval_ctx,
    )
}

/// The same decision for a description that names only the partition key —
/// `PostgreSQL`'s `ExecBuildSlotPartitionKeyDescription`, which is a separate
/// function upstream with a separate rule.
///
/// It has no `modifiedCols` fallback: a caller without table-level `SELECT`
/// must hold it on *every* key column or be told nothing, and there is no
/// trimmed middle form. With no column-level grants in this engine that
/// collapses to the table-level test.
fn may_describe_key(write_ctx: &WriteContext<'_>, table: &Table) -> bool {
    let describer = write_ctx.describer();
    let kv = write_ctx.catalog_kv;
    matches!(
        crate::rls::decide(
            &describer.security(kv),
            table,
            crabka_pgcatalog::policy::PolicyCommand::Select,
        ),
        Ok(crate::rls::RowSecurity::Open)
    ) && matches!(
        crate::privilege::holds(
            &describer.privileges(kv),
            &table.name,
            &table.owner,
            crate::privilege::Privilege::Select,
        ),
        Ok(true)
    )
}

/// A row written straight into a leaf partition must still satisfy the bound of
/// that leaf *and of every ancestor above it*, `PostgreSQL`'s implicit
/// per-partition `CHECK`, reported as 23514.
///
/// The whole chain, not the immediate parent alone: `PostgreSQL` builds the
/// constraint with `RelationGetPartitionQual`, which walks up to the root, so a
/// row that falls inside a leaf's own bound and outside its grandparent's is
/// still refused. Checking one level would store a row that no routed `INSERT`
/// could ever have put there, and that the parent would then never return.
///
/// Whichever level declines it, the error names the relation the statement
/// wrote and quotes that relation's row, because that is the row the caller
/// offered.
fn check_partition_constraint(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    row: &[Datum],
    modified: &[String],
) -> Result<(), ExecError> {
    let kv = write_ctx.catalog_kv;
    let mut current = table.clone();
    let mut current_row = row.to_vec();
    while let Some((parent, bound)) = crate::partition::parent_of(kv, &current.name)? {
        let parent_table = crabka_pgcatalog::get_table(kv, &parent)?;
        let Some(scheme) = crate::partition::scheme_of(kv, &parent)? else {
            return Ok(());
        };
        let ordinals = column_mapping(&parent_table, &current)?;
        let parent_row = ordinals
            .iter()
            .map(|ordinal| current_row.get(*ordinal).cloned().unwrap_or(Datum::Null))
            .collect::<Vec<_>>();
        let siblings = crate::partition::partitions_of(kv, &parent)?;
        if !crate::partition::satisfies(&scheme, &bound, &siblings, &parent_row)? {
            return Err(ExecError::PartitionConstraintViolation {
                relation: table.name.to_string(),
                row: describe_row(write_ctx, table, row, modified),
            });
        }
        current = parent_table;
        current_row = parent_row;
    }
    Ok(())
}

/// `INSERT` into a partitioned parent: every proposed row is routed to the leaf
/// its partition key selects and written there.
///
/// The rows are built against the *parent's* column list, so defaults, coercion
/// and `NOT NULL` all come from the parent. They are then permuted into the
/// chosen leaf's own column order on the way out, so a leaf attached with its
/// columns in a different order still stores them correctly.
async fn partitioned_insert(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    stmt: &Statement,
    writes: &mut StatementWrites,
) -> Result<(WriteOutcome, Vec<crabka_pgkv::WriteOp>), ExecError> {
    let resolution = write_ctx.eval_ctx.resolution();
    let Statement::Insert {
        table,
        columns,
        source,
        on_conflict,
        returning,
        ..
    } = stmt
    else {
        unreachable!("the caller matched an INSERT")
    };
    let catalog_kv = write_ctx.catalog_kv;
    let ctx = write_ctx.eval_ctx;
    if on_conflict.is_some() {
        return Err(ExecError::Unsupported(
            "INSERT … ON CONFLICT into a partitioned table is not supported: conflict arbitration \
             would have to span every partition's indexes, which are enforced per partition here"
                .into(),
        ));
    }
    let parent = crabka_pgcatalog::get_table(
        catalog_kv,
        &resolve_relation(catalog_kv, resolution, table, SchemaDisposition::Reference)?,
    )?;
    let (target_idx, rows) = insert_source_rows(write_ctx, ctes, &parent, columns, source)?;
    let mut ops: Vec<crabka_pgkv::WriteOp> = Vec::new();
    if rows.is_empty() {
        return Ok((WriteOutcome::command("INSERT 0 0".into()), ops));
    }
    let mut returned_rows = returning
        .as_ref()
        .map(|_| Vec::with_capacity(rows.len()))
        .unwrap_or_default();
    let mut inserted: u64 = 0;
    // Resolved once per leaf rather than once per row: a relation in no foreign
    // key must pay one boolean test per write, not a catalog read.
    let mut leaf_fk: HashMap<TableId, crate::fk::StatementFkContext> = HashMap::new();
    // PostgreSQL judges a routed row by the policies of the relation the
    // statement named, never the leaf's own — the same rule the read gate
    // applies to a partition tree.
    let supplied = WriteContext::modified_columns(&parent, &target_idx);
    let check = write_ctx.row_check(
        &parent,
        crabka_pgcatalog::policy::PolicyCommand::Insert,
        &supplied,
    )?;
    for row_exprs in &rows {
        let full = build_insert_row(&parent, &target_idx, row_exprs, ctx)?;
        let (leaf, leaf_row) = route_row_to_leaf(write_ctx, &parent, &full)?;
        let Some(leaf_row) = crate::trigger::fire_before_row(
            catalog_kv,
            crate::trigger::WriteTarget {
                table: &leaf,
                check: &check,
            },
            crate::trigger::DmlEvent::Insert,
            &[],
            None,
            Some(leaf_row),
            ctx,
        )?
        else {
            continue;
        };
        check_partition_constraint(write_ctx, &leaf, &leaf_row, &supplied)?;
        let local_indexes = writable_local_indexes(catalog_kv, &leaf)?;
        let fk_ctx = match leaf_fk.entry(leaf.id) {
            std::collections::hash_map::Entry::Occupied(slot) => slot.into_mut(),
            std::collections::hash_map::Entry::Vacant(slot) => {
                slot.insert(crate::fk::StatementFkContext::resolve(catalog_kv, &leaf)?)
            }
        };
        // One rowid per row rather than one block per statement: rows of the
        // same statement can land in different leaves, and each leaf has its
        // own rowid space.
        let (rowid, seq_op) = write_ctx.seq.alloc(write_ctx.kv, leaf.id, 1)?;
        ops.extend(seq_op);
        enforce_unique_local_indexes(write_ctx, &leaf, &local_indexes, rowid, &leaf_row, writes)
            .await?;
        if !fk_ctx.is_empty() {
            writes.fk_checks.after_insert(fk_ctx, rowid, &leaf_row)?;
        }
        if returning.is_some() {
            let ordinals = column_mapping(&parent, &leaf)?;
            let returned = ordinals
                .iter()
                .map(|ordinal| leaf_row[*ordinal].clone())
                .collect();
            returned_rows.push(ReturnedRow {
                new: Some(returned),
                old: None,
                source: Vec::new(),
                action: None,
            });
        }
        ops.push(crabka_pgkv::WriteOp::Put {
            key: crabka_pgmvcc::version::version_key_xid(leaf.id, rowid, write_ctx.xid),
            value: encode_table_tuple(
                &leaf,
                write_ctx.xid,
                crabka_pgmvcc::xid::INVALID_XID,
                &leaf_row,
            ),
        });
        ops.extend(local_index_entry_ops(
            &leaf,
            &local_indexes,
            rowid,
            &leaf_row,
        )?);
        crate::trigger::fire_after_row(
            catalog_kv,
            &leaf,
            crate::trigger::DmlEvent::Insert,
            &[],
            None,
            Some(&leaf_row),
            ctx,
        )?;
        inserted += 1;
    }
    let spec = ReturningSpec::new(&parent, &parent.name.name, returning.as_ref(), None, false)?;
    Ok((
        spec.outcome(format!("INSERT 0 {inserted}"), returned_rows, ctx)?,
        ops,
    ))
}

/// The catalog's spelling of a parsed check-option level.
///
/// The two enums are deliberately separate: `crabka_pgcatalog` is the durable
/// catalog and depends on no SQL grammar, so the executor is where the syntax
/// becomes storage.
const fn catalog_check_option(
    level: crabka_pgparser::ast::ViewCheckOption,
) -> crabka_pgcatalog::ViewCheckOption {
    match level {
        crabka_pgparser::ast::ViewCheckOption::Local => crabka_pgcatalog::ViewCheckOption::Local,
        crabka_pgparser::ast::ViewCheckOption::Cascaded => {
            crabka_pgcatalog::ViewCheckOption::Cascaded
        }
    }
}

fn is_view_ref(
    kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    reference: &crabka_pgparser::ast::RelationRef,
) -> Result<bool, ExecError> {
    let name = resolve_relation(kv, resolution, reference, SchemaDisposition::Reference)?;
    match crabka_pgcatalog::get_view(kv, &name) {
        Ok(_) => Ok(true),
        Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) => Ok(false),
        Err(error) => Err(error.into()),
    }
}

/// A write statement rewritten onto the relation underneath a chain of views.
struct RewrittenViewWrite {
    stmt: Statement,
    /// The role the rewritten write is decided under — the innermost view's
    /// owner, unless a `security_invoker` view keeps the caller's identity.
    role: String,
    /// The check options collected on the way down, ready for the row that
    /// reaches storage.
    checks: Vec<crate::viewwrite::ViewCheck>,
}

/// Enforce the check options this statement was rewritten through against a row
/// an `INSTEAD OF` trigger produced.
///
/// The rewritten path gets this for free through
/// [`crate::rls::WriteChecks`], which only the table write path reaches. A chain
/// that bottoms out at a trigger-bearing view needs the same judgement made
/// here, on the view's own rowtype, which is the row `PostgreSQL` judges too.
fn permit_view_checks(
    write_ctx: &WriteContext<'_>,
    view: &Table,
    row: &[Datum],
    modified: &[String],
) -> Result<(), ExecError> {
    let ctx = write_ctx.eval_ctx;
    let scope = Scope::single(view, &view.name.name);
    for check in write_ctx.view_checks {
        if !row_matches(Some(&check.qual), &scope, row, ctx)? {
            return Err(ExecError::ViewCheckOptionViolation {
                view: check.view.clone(),
                row: describe_row(write_ctx, view, row, modified),
            });
        }
    }
    Ok(())
}

/// Rewrite `stmt` from the view it names onto the relation underneath.
fn rewrite_view_write(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    stmt: &Statement,
    name: &crabka_pgcatalog::RelationName,
) -> Result<RewrittenViewWrite, ExecError> {
    use crabka_pgparser::ast::{InsertSource, SelectItem};

    let catalog_kv = write_ctx.catalog_kv;
    let resolution = write_ctx.eval_ctx.resolution();
    let stored = crabka_pgcatalog::get_view(catalog_kv, name)?;
    let (write, alias) = match stmt {
        Statement::Insert { .. } => (crate::viewwrite::ViewWrite::Insert, None),
        Statement::Update { alias, .. } => (crate::viewwrite::ViewWrite::Update, alias.as_deref()),
        Statement::Delete { alias, .. } => (crate::viewwrite::ViewWrite::Delete, alias.as_deref()),
        _ => unreachable!("view DML only accepts INSERT, UPDATE, or DELETE"),
    };
    let qualifier = view_write_qualifier(name, alias).to_string();
    let privileges = write_ctx.privileges();
    let permit = |view: &crabka_pgcatalog::View, role: &str| {
        crate::privilege::require(
            &crate::privilege::PrivilegeCtx::new(catalog_kv, role),
            &view.name,
            &view.owner,
            crate::privilege::RelationKind::View,
            match write {
                crate::viewwrite::ViewWrite::Insert => crate::privilege::Privilege::Insert,
                crate::viewwrite::ViewWrite::Update => crate::privilege::Privilege::Update,
                crate::viewwrite::ViewWrite::Delete => crate::privilege::Privilege::Delete,
            },
        )
    };
    let instead = |relation: &crabka_pgcatalog::RelationName| {
        let id = crate::catalog_rel::view_oids(catalog_kv)?
            .get(relation)
            .copied()
            .and_then(|oid| u32::try_from(oid).ok())
            .unwrap_or(0);
        crate::trigger::has_instead_row_trigger(
            catalog_kv,
            id,
            crate::trigger::DmlEvent::Insert,
            &[],
        )
        .and_then(|insert| {
            Ok(insert
                || crate::trigger::has_instead_row_trigger(
                    catalog_kv,
                    id,
                    crate::trigger::DmlEvent::Update,
                    &[],
                )?
                || crate::trigger::has_instead_row_trigger(
                    catalog_kv,
                    id,
                    crate::trigger::DmlEvent::Delete,
                    &[],
                )?)
        })
    };
    let view_ctx = crate::viewwrite::ViewWriteCtx {
        kv: catalog_kv,
        resolution,
        instead_trigger: &instead,
        permit: &permit,
    };
    let _ = &privileges;
    let rewrite = crate::viewwrite::resolve(
        &view_ctx,
        &stored,
        write,
        &qualifier,
        write_ctx.fctx.effective_role(),
    )?;
    let target = relation_ref_of(&rewrite.target);
    let sub = |expr: &Expr| rewrite.rewrite_statement_expr(expr, &qualifier);
    // Every column a statement names has to be one of the view's, exactly as
    // PostgreSQL resolves it against the view's rowtype before rewriting. Left
    // unchecked, a name the view does not project would resolve against the
    // base relation the rewrite substitutes in, and a write would silently read
    // a column the view hides.
    let check_names = |exprs: &[&Expr], strict: bool| -> Result<(), ExecError> {
        for expr in exprs {
            rewrite.reject_foreign_columns(expr, &qualifier, strict)?;
        }
        Ok(())
    };
    let returning_items = |returning: &Option<crabka_pgparser::ast::Returning>| {
        returning.as_ref().map(|returning| {
            let items = returning
                .items
                .iter()
                .flat_map(|item| match item {
                    SelectItem::Wildcard => rewrite.wildcard_items(),
                    SelectItem::QualifiedWildcard(written) if *written == qualifier => {
                        rewrite.wildcard_items()
                    }
                    other => vec![other.clone()],
                })
                .map(|item| match item {
                    // The output column keeps the name the *view* gave it.
                    // Substitution replaces a bare `aa` with the base column it
                    // was selected from, and a column reference names itself —
                    // so without an explicit alias the rewrite would rename the
                    // user's RETURNING column out from under them.
                    SelectItem::Expr { expr, alias } => SelectItem::Expr {
                        alias: alias.or_else(|| match &expr {
                            Expr::Column { name, .. } => Some(name.clone()),
                            _ => None,
                        }),
                        expr: sub(&expr),
                    },
                    other => other,
                })
                .collect();
            crabka_pgparser::ast::Returning {
                old_alias: returning.old_alias.clone(),
                new_alias: returning.new_alias.clone(),
                items,
            }
        })
    };

    let stmt = match stmt {
        Statement::Insert {
            columns,
            source,
            on_conflict,
            returning,
            ..
        } => {
            // With no column list the implicit target list is the view's
            // leading columns, truncated to what the source supplies — the same
            // rule `resolve_insert_targets` applies to a table, applied one
            // level up so the truncation counts *view* columns.
            let named: Vec<String> = match columns {
                Some(written) => written.clone(),
                None => {
                    let width = match source {
                        InsertSource::Values(rows) => rows.first().map_or(0, Vec::len),
                        InsertSource::DefaultValues => 0,
                        InsertSource::Query(query) => crate::query::describe_query_expr_with_ctes(
                            catalog_kv, resolution, query, ctes,
                        )?
                        .len(),
                    };
                    rewrite
                        .columns
                        .iter()
                        .take(width)
                        .map(|column| column.name.clone())
                        .collect()
                }
            };
            let mapped = named
                .iter()
                .map(|column| rewrite.assignable(column, &name.name, write))
                .collect::<Result<Vec<_>, _>>()?;
            // Two of the view's columns may select the same base column
            // (`SELECT a, b, a AS aa`), and an INSERT that names both would
            // assign it twice. PostgreSQL reports that against the *base*
            // column, and reports it here rather than letting the second value
            // quietly win.
            let mut assigned = std::collections::HashSet::new();
            if let Some(repeated) = mapped.iter().find(|column| !assigned.insert(*column)) {
                return Err(ExecError::Syntax(format!(
                    "multiple assignments to same column \"{repeated}\""
                )));
            }
            // An INSERT carries no alias, so its RETURNING has to name the
            // relation underneath rather than the view the user wrote.
            let returning =
                returning_items(returning).map(|returning| crabka_pgparser::ast::Returning {
                    items: returning
                        .items
                        .iter()
                        .map(|item| match item {
                            SelectItem::Expr { expr, alias } => SelectItem::Expr {
                                expr: crate::viewwrite::ViewRewrite::unqualify_expr(
                                    expr, &qualifier,
                                ),
                                alias: alias.clone(),
                            },
                            other => other.clone(),
                        })
                        .collect(),
                    ..returning
                });
            let on_conflict = on_conflict
                .as_ref()
                .map(|clause| rewrite_view_conflict(clause, &rewrite, &qualifier, &name.name))
                .transpose()?;
            Statement::Insert {
                table: target,
                columns: Some(mapped),
                source: source.clone(),
                with: None,
                on_conflict,
                returning,
            }
        }
        Statement::Update {
            assignments,
            from,
            filter,
            returning,
            ..
        } => {
            check_names(&filter.iter().collect::<Vec<_>>(), from.is_empty())?;
            let assignments = assignments
                .iter()
                .map(|assignment| {
                    Ok(crabka_pgparser::ast::Assignment {
                        targets: assignment
                            .targets
                            .iter()
                            .map(|column| rewrite.assignable(column, &name.name, write))
                            .collect::<Result<Vec<_>, ExecError>>()?,
                        subscripts: assignment.subscripts.clone(),
                        value: rewrite_assignment_value(&assignment.value, &sub),
                    })
                })
                .collect::<Result<Vec<_>, ExecError>>()?;
            Statement::Update {
                table: target,
                only: true,
                with: None,
                alias: Some(qualifier.clone()),
                assignments,
                from: from.clone(),
                filter: rewrite.restrict(filter.as_ref().map(&sub)),
                returning: returning_items(returning),
            }
        }
        Statement::Delete {
            using,
            filter,
            returning,
            ..
        } => {
            check_names(&filter.iter().collect::<Vec<_>>(), using.is_empty())?;
            Statement::Delete {
                table: target,
                only: true,
                with: None,
                alias: Some(qualifier.clone()),
                using: using.clone(),
                filter: rewrite.restrict(filter.as_ref().map(&sub)),
                returning: returning_items(returning),
            }
        }
        _ => unreachable!("view DML only accepts INSERT, UPDATE, or DELETE"),
    };
    Ok(RewrittenViewWrite {
        stmt,
        role: rewrite.run_as.clone(),
        checks: rewrite.row_checks(&qualifier),
    })
}

/// Rewrite an `ON CONFLICT` clause from the view's columns onto the relation
/// underneath.
///
/// The arbiter's inference columns and the `DO UPDATE SET` targets are
/// assignments and take the same refusal an ordinary target column does; the
/// expressions go through the `excluded`-aware rewrite.
fn rewrite_view_conflict(
    clause: &crabka_pgparser::ast::OnConflict,
    rewrite: &crate::viewwrite::ViewRewrite,
    qualifier: &str,
    view: &str,
) -> Result<crabka_pgparser::ast::OnConflict, ExecError> {
    use crabka_pgparser::ast::{OnConflict, OnConflictAction, OnConflictTarget};

    let write = crate::viewwrite::ViewWrite::Insert;
    // An INSERT has no alias to hang the statement's qualifier on, so a
    // reference to the *stored* row moves onto the target's bare relation name;
    // `excluded` keeps its own qualifier, which is not the statement's.
    let target_name = rewrite.target.name.clone();
    let sub = |expr: &Expr| {
        crate::viewwrite::ViewRewrite::requalify_expr(
            &rewrite.rewrite_conflict_expr(expr, qualifier),
            qualifier,
            &target_name,
        )
    };
    let target = match &clause.target {
        OnConflictTarget::Columns {
            columns,
            index_predicate,
        } => OnConflictTarget::Columns {
            columns: columns
                .iter()
                .map(|column| rewrite.assignable(column, view, write))
                .collect::<Result<Vec<_>, ExecError>>()?,
            index_predicate: index_predicate.as_ref().map(&sub),
        },
        other => other.clone(),
    };
    let action = match &clause.action {
        OnConflictAction::DoNothing => OnConflictAction::DoNothing,
        OnConflictAction::DoUpdate {
            assignments,
            filter,
        } => OnConflictAction::DoUpdate {
            assignments: assignments
                .iter()
                .map(|(column, expr)| Ok((rewrite.assignable(column, view, write)?, sub(expr))))
                .collect::<Result<Vec<_>, ExecError>>()?,
            filter: filter.as_ref().map(&sub),
        },
    };
    Ok(OnConflict { target, action })
}

/// Apply a rewrite to an assignment's right-hand side, whichever spelling it
/// has.
fn rewrite_assignment_value(
    value: &crabka_pgparser::ast::AssignmentValue,
    sub: &impl Fn(&Expr) -> Expr,
) -> crabka_pgparser::ast::AssignmentValue {
    use crabka_pgparser::ast::AssignmentValue;
    match value {
        AssignmentValue::Expr(expr) => AssignmentValue::Expr(sub(expr)),
        AssignmentValue::Row(exprs) => AssignmentValue::Row(exprs.iter().map(sub).collect()),
        AssignmentValue::Subquery(query) => AssignmentValue::Subquery(query.clone()),
    }
}

/// A `RelationRef` naming a resolved relation, for a statement this executor
/// builds rather than parses.
fn relation_ref_of(name: &crabka_pgcatalog::RelationName) -> crabka_pgparser::ast::RelationRef {
    crabka_pgparser::ast::RelationRef {
        schema: Some(name.schema.clone()),
        name: name.name.clone(),
    }
}

/// The statement's own qualifier for the view it names — its alias when it has
/// one, otherwise the view's bare name. Every rewritten reference to the
/// relation the write lands on carries this, and the rewritten statement aliases
/// that relation with it, so a qualified reference the user wrote still
/// resolves.
fn view_write_qualifier<'a>(
    name: &'a crabka_pgcatalog::RelationName,
    alias: Option<&'a str>,
) -> &'a str {
    alias.unwrap_or(&name.name)
}

/// Dispatch a write that named a view.
///
/// Two paths, and which one applies is decided by whether the view carries an
/// `INSTEAD OF` row trigger for this event: the trigger performs the write
/// itself, or — when there is none — the statement is rewritten onto the
/// relation underneath and handed back to [`execute_write_body`].
async fn execute_view_dml(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    stmt: &Statement,
    writes: &mut StatementWrites,
) -> Result<(WriteOutcome, Vec<crabka_pgkv::WriteOp>), ExecError> {
    let reference = match stmt {
        Statement::Insert { table, .. }
        | Statement::Update { table, .. }
        | Statement::Delete { table, .. } => table,
        _ => unreachable!("view DML only accepts INSERT, UPDATE, or DELETE"),
    };
    let name = resolve_relation(
        write_ctx.catalog_kv,
        write_ctx.eval_ctx.resolution(),
        reference,
        SchemaDisposition::Reference,
    )?;
    let view = crate::trigger::relation_trigger_table(write_ctx.catalog_kv, &name)?;
    let ctx = write_ctx.eval_ctx;
    let (event, updated) = match stmt {
        Statement::Insert { .. } => (crate::trigger::DmlEvent::Insert, Vec::new()),
        Statement::Update { assignments, .. } => (
            crate::trigger::DmlEvent::Update,
            assignments
                .iter()
                .flat_map(|assignment| assignment.targets.iter().cloned())
                .collect(),
        ),
        _ => (crate::trigger::DmlEvent::Delete, Vec::new()),
    };
    if !crate::trigger::has_instead_row_trigger(write_ctx.catalog_kv, view.id, event, &updated)? {
        let rewritten = rewrite_view_write(write_ctx, ctes, stmt, &name)?;
        let inner = WriteContext {
            fctx: ForeignCtx {
                current_user: &rewritten.role,
                ..write_ctx.fctx
            },
            view_checks: &rewritten.checks,
            ..*write_ctx
        };
        return Box::pin(execute_write_body(
            &inner,
            ctes,
            &rewritten.stmt,
            writes,
            Reach::Storage,
        ))
        .await;
    }

    match stmt {
        Statement::Insert {
            columns,
            source,
            on_conflict,
            returning,
            ..
        } => {
            if on_conflict.is_some() {
                return Err(ExecError::Unsupported(
                    "INSERT ... ON CONFLICT is not supported on views".into(),
                ));
            }
            let (targets, rows) = insert_source_rows(write_ctx, ctes, &view, columns, source)?;
            let spec = ReturningSpec::new(&view, &view.name.name, returning.as_ref(), None, false)?;
            let mut returned = Vec::new();
            let mut count = 0_u64;
            for row in rows {
                let proposed = build_insert_row(&view, &targets, &row, ctx)?;
                let Some(result) = crate::trigger::fire_instead_row(
                    write_ctx.catalog_kv,
                    &view,
                    crate::trigger::DmlEvent::Insert,
                    &[],
                    None,
                    Some(proposed),
                    ctx,
                )?
                else {
                    continue;
                };
                permit_view_checks(
                    write_ctx,
                    &view,
                    &result,
                    &WriteContext::modified_columns(&view, &targets),
                )?;
                count += 1;
                if returning.is_some() {
                    returned.push(ReturnedRow {
                        new: Some(result),
                        old: None,
                        source: Vec::new(),
                        action: None,
                    });
                }
            }
            Ok((
                spec.outcome(format!("INSERT 0 {count}"), returned, ctx)?,
                Vec::new(),
            ))
        }
        Statement::Update {
            alias,
            assignments,
            from,
            filter,
            returning,
            ..
        } => {
            let qualifier = table_qualifier(&view, alias);
            let read = write_ctx.read_ctx(ctes);
            let target_expr = crabka_pgparser::ast::TableExpr::Table {
                name: reference.clone(),
                // Pinned to `true` whatever the statement wrote. UPDATE and
                // DELETE do not descend into inheritance children yet, so
                // scanning them here would collect rows the write path has no
                // way to address. `Statement::{Update,Delete}::only` carries
                // what was written; this is the line that starts reading it the
                // day DML recursion lands.
                only: true,
                alias: alias.clone(),
                columns: None,
                sample: None,
            };
            let target_rows =
                build_from(&read, std::slice::from_ref(&target_expr), None, None, None)?.rows;
            let source = DmlSource::build(write_ctx, ctes, &view, qualifier, from)?;
            let bound_filter = source.bind_filter(filter.as_ref())?;
            let targets = resolve_assignments(write_ctx, ctes, &view, assignments)?;
            let spec = ReturningSpec::new(
                &view,
                qualifier,
                returning.as_ref(),
                Some(&source.scope),
                false,
            )?;
            let updated: Vec<String> = assignments
                .iter()
                .flat_map(|assignment| assignment.targets.iter().cloned())
                .collect();
            let mut returned = Vec::new();
            let mut count = 0_u64;
            for old in target_rows {
                let Some(joined) = source.first_match(bound_filter.as_ref(), &old, ctx)? else {
                    continue;
                };
                let proposed = apply_assignments(&view, &targets, &source.scope, &joined, ctx)?;
                let Some(result) = crate::trigger::fire_instead_row(
                    write_ctx.catalog_kv,
                    &view,
                    crate::trigger::DmlEvent::Update,
                    &updated,
                    Some(&old),
                    Some(proposed),
                    ctx,
                )?
                else {
                    continue;
                };
                permit_view_checks(write_ctx, &view, &result, &updated)?;
                count += 1;
                if returning.is_some() {
                    returned.push(ReturnedRow::updated(
                        result,
                        old,
                        joined[view.columns.len()..].to_vec(),
                    ));
                }
            }
            Ok((
                spec.outcome(format!("UPDATE {count}"), returned, ctx)?,
                Vec::new(),
            ))
        }
        Statement::Delete {
            alias,
            using,
            filter,
            returning,
            ..
        } => {
            let qualifier = table_qualifier(&view, alias);
            let read = write_ctx.read_ctx(ctes);
            let target_expr = crabka_pgparser::ast::TableExpr::Table {
                name: reference.clone(),
                // Pinned to `true` whatever the statement wrote. UPDATE and
                // DELETE do not descend into inheritance children yet, so
                // scanning them here would collect rows the write path has no
                // way to address. `Statement::{Update,Delete}::only` carries
                // what was written; this is the line that starts reading it the
                // day DML recursion lands.
                only: true,
                alias: alias.clone(),
                columns: None,
                sample: None,
            };
            let target_rows =
                build_from(&read, std::slice::from_ref(&target_expr), None, None, None)?.rows;
            let source = DmlSource::build(write_ctx, ctes, &view, qualifier, using)?;
            let bound_filter = source.bind_filter(filter.as_ref())?;
            let spec = ReturningSpec::new(
                &view,
                qualifier,
                returning.as_ref(),
                Some(&source.scope),
                false,
            )?;
            let mut returned = Vec::new();
            let mut count = 0_u64;
            for old in target_rows {
                let Some(joined) = source.first_match(bound_filter.as_ref(), &old, ctx)? else {
                    continue;
                };
                let Some(result) = crate::trigger::fire_instead_row(
                    write_ctx.catalog_kv,
                    &view,
                    crate::trigger::DmlEvent::Delete,
                    &[],
                    Some(&old),
                    None,
                    ctx,
                )?
                else {
                    continue;
                };
                count += 1;
                if returning.is_some() {
                    returned.push(ReturnedRow {
                        new: None,
                        old: Some(result),
                        source: joined[view.columns.len()..].to_vec(),
                        action: None,
                    });
                }
            }
            Ok((
                spec.outcome(format!("DELETE {count}"), returned, ctx)?,
                Vec::new(),
            ))
        }
        _ => unreachable!(),
    }
}

/// Run one write statement.
///
/// `reach` says how far below its target the statement may go. A statement the
/// session submitted carries its own answer in `ONLY`, and passes
/// [`Reach::of`]. The engine's own desugarings — the per-relation pieces of a
/// tree write, a view rewrite, the unfiltered `DELETE`s a `TRUNCATE` becomes —
/// pass [`Reach::Storage`], because they have already walked the inheritance
/// tree themselves but still need a partitioned target to expand. That
/// distinction cannot be spelled in the AST's one boolean; see [`Reach`].
async fn execute_write_body(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    stmt: &Statement,
    writes: &mut StatementWrites,
    reach: Reach,
) -> Result<(WriteOutcome, Vec<crabka_pgkv::WriteOp>), ExecError> {
    let resolved = resolve_write_subqueries(write_ctx, ctes, stmt)?;
    let stmt = &resolved;
    let resolution = write_ctx.eval_ctx.resolution();
    let catalog_kv = write_ctx.catalog_kv;
    let kv = write_ctx.kv;
    let lockmgr = write_ctx.lockmgr;
    let seq = write_ctx.seq;
    let xid = write_ctx.xid;
    let lock_owner = write_ctx.lock_owner;
    let ctx = write_ctx.eval_ctx;
    let mut ops: Vec<crabka_pgkv::WriteOp> = Vec::new();
    match stmt {
        // The read body of a statement whose `WITH` list modified data. The CTE
        // relations are already in `ctes`; the query itself runs read-only.
        Statement::Query(q) => {
            let read = write_ctx.read_ctx(ctes);
            let rel = crate::query::query_to_relation(&read, q)?;
            let tag = format!("SELECT {}", rel.rows.len());
            Ok((
                WriteOutcome {
                    tag,
                    returning: Some(rel),
                },
                ops,
            ))
        }
        Statement::Insert { table, .. }
        | Statement::Update { table, .. }
        | Statement::Delete { table, .. }
            if is_view_ref(catalog_kv, resolution, table)? =>
        {
            Box::pin(execute_view_dml(write_ctx, ctes, stmt, writes)).await
        }
        Statement::Insert { table, .. } if is_partitioned_ref(catalog_kv, resolution, table)? => {
            partitioned_insert(write_ctx, ctes, stmt, writes).await
        }
        // `reach`, not the statement's own `ONLY`: a `TRUNCATE` desugars to an
        // unfiltered `DELETE` that says `ONLY` to stop the inheritance walk it
        // has already done, and reading that as the user's `ONLY` would leave a
        // partitioned parent full. Under a real `ONLY` this arm is skipped and
        // the plain path writes the parent's own — empty — row space, so
        // `DELETE FROM ONLY parted` reports `DELETE 0` and touches no leaf.
        Statement::Update { table, .. } | Statement::Delete { table, .. }
            if reach.spans_partitions() && is_partitioned_ref(catalog_kv, resolution, table)? =>
        {
            Box::pin(partitioned_dml(write_ctx, ctes, stmt, writes)).await
        }
        // After the partitioned guard, so a target that is both a partitioned
        // parent and an inheritance parent routes by partition first. `ONLY`
        // asks for exactly the un-expanded write, and a childless target has
        // nothing to expand into, so both fall through to the plain arms and
        // pay one children-index probe.
        Statement::Update { table, .. } | Statement::Delete { table, .. }
            if reach == Reach::Tree && has_inheritance_children(catalog_kv, resolution, table)? =>
        {
            Box::pin(inherited_dml(write_ctx, ctes, stmt, writes)).await
        }
        Statement::Merge { table, .. } if is_partitioned_ref(catalog_kv, resolution, table)? => {
            Err(ExecError::Unsupported(
                "MERGE into a partitioned table is not supported: a source row that matches no \
                 target row would have to be routed, and the matched/not-matched decision spans \
                 every partition at once"
                    .into(),
            ))
        }
        Statement::Insert {
            table,
            columns,
            source,
            on_conflict,
            returning,
            ..
        } => {
            let table =
                &resolve_relation(catalog_kv, resolution, table, SchemaDisposition::Reference)?;
            let t = crabka_pgcatalog::get_table(catalog_kv, table)?;
            let (target_idx, rows) = insert_source_rows(write_ctx, ctes, &t, columns, source)?;
            let rows = &rows;
            if rows.is_empty() {
                return Ok((WriteOutcome::command("INSERT 0 0".into()), ops));
            }
            let local_indexes = writable_local_indexes(catalog_kv, &t)?;
            let fk_ctx = crate::fk::StatementFkContext::resolve(catalog_kv, &t)?;
            let supplied = WriteContext::modified_columns(&t, &target_idx);
            let insert_check = write_ctx.row_check(
                &t,
                crabka_pgcatalog::policy::PolicyCommand::Insert,
                &supplied,
            )?;
            // Arbiter resolution is statement-level: a bad conflict target is an
            // error even when no row would have conflicted.
            let arbiters = match on_conflict {
                Some(on_conflict) => {
                    resolve_arbiter_indexes(&t, &local_indexes, &on_conflict.target)?
                }
                None => Vec::new(),
            };
            // The command tag's N: inserted rows plus rows updated by DO UPDATE.
            // Rows skipped by DO NOTHING or by a false DO UPDATE … WHERE do not
            // count. Without an ON CONFLICT clause this always ends at rows.len().
            let mut inserted_or_updated: u64 = 0;
            // Reserve a contiguous block of rowids atomically. In Durable mode the
            // SequenceManager persists the new next-rowid itself (seq_op is None).
            // In Replicated mode it returns the seq Put for us to fold into this
            // same commit batch (max-merged by the replicated state machine).
            // Rows that end up skipped or updated leave their reserved rowid
            // unused, exactly as PostgreSQL burns a sequence value per proposed row.
            let n_rows = rows.len() as u64;
            let (start, seq_op) = seq.alloc(kv, t.id, n_rows)?;
            if let Some(op) = seq_op {
                ops.push(op);
            }
            let mut returned_rows = returning
                .as_ref()
                .map(|_| Vec::with_capacity(rows.len()))
                .unwrap_or_default();
            for (rowid, row_exprs) in (start..).zip(rows.iter()) {
                // `insert_source_rows` already sized the target list to the
                // source's width, so every row fills exactly `target_idx`.
                // Defaults, coercion and NOT NULL apply to the proposed row even
                // when ON CONFLICT would go on to skip it — PostgreSQL raises
                // 23502 on a DO NOTHING row too.
                let full = build_insert_row(&t, &target_idx, row_exprs, ctx)?;
                let Some(full) = crate::trigger::fire_before_row(
                    catalog_kv,
                    crate::trigger::WriteTarget {
                        table: &t,
                        check: &insert_check,
                    },
                    crate::trigger::DmlEvent::Insert,
                    &[],
                    None,
                    Some(full),
                    ctx,
                )?
                else {
                    continue;
                };
                check_partition_constraint(write_ctx, &t, &full, &supplied)?;
                if let Some(on_conflict) = on_conflict {
                    let plan =
                        arbitrate_insert_row(write_ctx, &t, &arbiters, on_conflict, &full, writes)
                            .await?;
                    match plan {
                        InsertRowPlan::Insert => {}
                        // The arbiter key lock stays held to COMMIT/ROLLBACK, as
                        // it does for every other unique-key decision.
                        InsertRowPlan::Skip => continue,
                        // NB: the conflicting row's rowid, not this VALUES row's
                        // reserved one — that reservation goes unused.
                        InsertRowPlan::Update {
                            rowid: holder_rowid,
                            cur_key_xid,
                            cur_xmin,
                            cur_row,
                        } => {
                            let crabka_pgparser::ast::OnConflictAction::DoUpdate {
                                assignments,
                                filter,
                            } = &on_conflict.action
                            else {
                                unreachable!("only DO UPDATE plans a row update")
                            };
                            let updated = apply_insert_conflict_update(
                                write_ctx,
                                &t,
                                &local_indexes,
                                &fk_ctx,
                                &ConflictUpdate {
                                    assignments,
                                    filter: filter.as_ref(),
                                    rowid: holder_rowid,
                                    cur_key_xid,
                                    cur_xmin,
                                    cur_row: &cur_row,
                                    proposed: &full,
                                },
                                writes,
                                &mut ops,
                            )
                            .await?;
                            // A DO UPDATE … WHERE that is not true leaves the row
                            // neither inserted nor updated, with no RETURNING row.
                            let Some(next) = updated else { continue };
                            writes.claim_row(t.id, holder_rowid);
                            if returning.is_some() {
                                returned_rows.push(ReturnedRow::updated(next, cur_row, Vec::new()));
                            }
                            inserted_or_updated += 1;
                            continue;
                        }
                    }
                }
                // No conflict (or no ON CONFLICT clause): the plain insert path.
                // Re-locking the arbiter keys here is idempotent, and this also
                // enforces 23505 on the unique indexes that do NOT arbitrate —
                // PostgreSQL's ordering.
                enforce_unique_local_indexes(write_ctx, &t, &local_indexes, rowid, &full, writes)
                    .await?;
                // Append only, never probe: the check runs once the statement's
                // rows exist, which is what makes a self-referencing
                // `INSERT INTO t (id, boss) VALUES (1, 1)` succeed under a
                // NOT DEFERRABLE constraint, exactly as it does in PostgreSQL.
                if !fk_ctx.is_empty() {
                    writes.fk_checks.after_insert(&fk_ctx, rowid, &full)?;
                }
                if returning.is_some() {
                    returned_rows.push(ReturnedRow {
                        new: Some(full.clone()),
                        old: None,
                        source: Vec::new(),
                        action: None,
                    });
                }
                ops.push(crabka_pgkv::WriteOp::Put {
                    key: crabka_pgmvcc::version::version_key_xid(t.id, rowid, xid),
                    value: encode_table_tuple(&t, xid, crabka_pgmvcc::xid::INVALID_XID, &full),
                });
                ops.extend(local_index_entry_ops(&t, &local_indexes, rowid, &full)?);
                crate::trigger::fire_after_row(
                    catalog_kv,
                    &t,
                    crate::trigger::DmlEvent::Insert,
                    &[],
                    None,
                    Some(&full),
                    ctx,
                )?;
                inserted_or_updated += 1;
            }
            let tag = format!("INSERT 0 {inserted_or_updated}");
            let spec = ReturningSpec::new(&t, &t.name.name, returning.as_ref(), None, false)?;
            Ok((spec.outcome(tag, returned_rows, ctx)?, ops))
        }
        Statement::Update {
            table,
            alias,
            assignments,
            from,
            filter,
            returning,
            ..
        } => {
            let table =
                &resolve_relation(catalog_kv, resolution, table, SchemaDisposition::Reference)?;
            let t = crabka_pgcatalog::get_table(catalog_kv, table)?;
            let local_indexes = writable_local_indexes(catalog_kv, &t)?;
            let fk_ctx = crate::fk::StatementFkContext::resolve(catalog_kv, &t)?;
            let qualifier = table_qualifier(&t, alias);
            let source = DmlSource::build(write_ctx, ctes, &t, qualifier, from)?;
            let bound_filter = source.bind_filter(filter.as_ref())?;
            let targets = resolve_assignments(write_ctx, ctes, &t, assignments)?;
            let spec = ReturningSpec::new(
                &t,
                qualifier,
                returning.as_ref(),
                Some(&source.scope),
                false,
            )?;
            let mut n: u64 = 0;
            let mut returned_rows = returning.as_ref().map(|_| Vec::new()).unwrap_or_default();
            // The `SET` list, which is both what the triggers are told changed
            // and the set a rejected row may be described by.
            let updated_columns: Vec<String> = assignments
                .iter()
                .flat_map(|assignment| assignment.targets.iter().cloned())
                .collect();
            let update_check = write_ctx.row_check(
                &t,
                crabka_pgcatalog::policy::PolicyCommand::Update,
                &updated_columns,
            )?;
            for (rowid, _xmin, scanned_row) in write_candidate_rows(
                write_ctx,
                &t,
                crate::privilege::WriteAction::Update,
                source.probe_filter(filter.as_ref()),
                crate::privilege::dml_reads_target(
                    &t,
                    qualifier,
                    filter.as_ref(),
                    returning.as_ref(),
                    assignments,
                ),
            )? {
                // 1. Filter on the snapshot-visible row FIRST — do not lock rows
                //    that don't match the WHERE clause (avoids over-locking and
                //    restores row-level write concurrency for different rows).
                if source
                    .first_match(bound_filter.as_ref(), &scanned_row, ctx)?
                    .is_none()
                {
                    continue;
                }
                // 2. Lock only matching candidates.
                lockmgr
                    .acquire_as(
                        t.id,
                        rowid,
                        crate::lockmgr::LockMode::Exclusive,
                        lock_owner,
                        write_ctx.lock_wait_cap,
                    )
                    .await
                    .map_err(lock_acquire_error)?;
                // 3. EvalPlanQual: re-read this row under the lock and decide what to
                //    operate on (40001 under RR if changed since our snapshot).
                let Some((cur_key_xid, cur_xmin, cur_row)) =
                    eval_plan_qual(&write_ctx.mutation(), &t, rowid)?
                else {
                    continue; // deleted by a concurrent committed txn — skip
                };
                // 4. Re-check the filter on the (possibly re-found) current row —
                //    under READ COMMITTED the row may have changed since the scan.
                //    A joined UPDATE updates each target row once, using the first
                //    source row it matches (PostgreSQL leaves the choice
                //    unspecified when several match).
                let Some(joined) = source.first_match(bound_filter.as_ref(), &cur_row, ctx)? else {
                    continue; // no longer matches the WHERE clause
                };
                // 5. PostgreSQL modifies a given row at most once per command, so
                //    a row another part of this statement already updated or
                //    deleted is left alone rather than updated again.
                if !writes.claim_row(t.id, rowid) {
                    continue;
                }
                let next = apply_assignments(&t, &targets, &source.scope, &joined, ctx)?;
                let Some(next) = crate::trigger::fire_before_row(
                    catalog_kv,
                    crate::trigger::WriteTarget {
                        table: &t,
                        check: &update_check,
                    },
                    crate::trigger::DmlEvent::Update,
                    &updated_columns,
                    Some(&cur_row),
                    Some(next),
                    ctx,
                )?
                else {
                    continue;
                };
                check_partition_constraint(write_ctx, &t, &next, &updated_columns)?;
                apply_locked_row_update(
                    write_ctx,
                    &t,
                    &local_indexes,
                    &fk_ctx,
                    &LockedRowUpdate {
                        rowid,
                        cur_key_xid,
                        cur_xmin,
                        cur_row: &cur_row,
                        next: &next,
                    },
                    writes,
                    &mut ops,
                )
                .await?;
                crate::trigger::fire_after_row(
                    catalog_kv,
                    &t,
                    crate::trigger::DmlEvent::Update,
                    &updated_columns,
                    Some(&cur_row),
                    Some(&next),
                    ctx,
                )?;
                if returning.is_some() {
                    returned_rows.push(ReturnedRow::updated(
                        next,
                        cur_row,
                        joined[t.columns.len()..].to_vec(),
                    ));
                }
                n += 1;
            }
            let tag = format!("UPDATE {n}");
            Ok((spec.outcome(tag, returned_rows, ctx)?, ops))
        }
        Statement::Delete {
            table,
            alias,
            using,
            filter,
            returning,
            ..
        } => {
            let table =
                &resolve_relation(catalog_kv, resolution, table, SchemaDisposition::Reference)?;
            let t = crabka_pgcatalog::get_table(catalog_kv, table)?;
            let local_indexes = writable_local_indexes(catalog_kv, &t)?;
            // A `TRUNCATE` desugars to one of these per relation; the truncate
            // set suppresses exactly the parent-side keys whose child is being
            // emptied in the same statement, so no referential action fires.
            let fk_ctx = crate::fk::StatementFkContext::resolve_for_truncate(
                catalog_kv,
                &t,
                &writes.truncate_set,
            )?;
            let is_truncate = writes.truncate_set.contains(&t.id);
            let qualifier = table_qualifier(&t, alias);
            let source = DmlSource::build(write_ctx, ctes, &t, qualifier, using)?;
            let bound_filter = source.bind_filter(filter.as_ref())?;
            let spec = ReturningSpec::new(
                &t,
                qualifier,
                returning.as_ref(),
                Some(&source.scope),
                false,
            )?;
            let mut n: u64 = 0;
            let mut returned_rows = returning.as_ref().map(|_| Vec::new()).unwrap_or_default();
            for (rowid, _xmin, scanned_row) in write_candidate_rows(
                write_ctx,
                &t,
                // A `TRUNCATE` desugars to one of these, and PostgreSQL
                // authorizes it with the TRUNCATE privilege rather than DELETE.
                // The truncate set is the statement's own record of which
                // relations it is emptying, so it is also the honest answer to
                // "which privilege authorized this delete".
                if is_truncate {
                    crate::privilege::WriteAction::Truncate
                } else {
                    crate::privilege::WriteAction::Delete
                },
                source.probe_filter(filter.as_ref()),
                crate::privilege::dml_reads_target(
                    &t,
                    qualifier,
                    filter.as_ref(),
                    returning.as_ref(),
                    &[],
                ),
            )? {
                // 1. Filter on the snapshot-visible row FIRST — do not lock rows
                //    that don't match the WHERE clause.
                if source
                    .first_match(bound_filter.as_ref(), &scanned_row, ctx)?
                    .is_none()
                {
                    continue;
                }
                // 2. Lock only matching candidates.
                lockmgr
                    .acquire_as(
                        t.id,
                        rowid,
                        crate::lockmgr::LockMode::Exclusive,
                        lock_owner,
                        write_ctx.lock_wait_cap,
                    )
                    .await
                    .map_err(lock_acquire_error)?;
                // 3. EvalPlanQual: re-read this row under the lock.
                let Some((cur_key_xid, cur_xmin, cur_row)) =
                    eval_plan_qual(&write_ctx.mutation(), &t, rowid)?
                else {
                    continue; // already deleted by a concurrent committed txn
                };
                // 4. Re-check filter on the (possibly re-found) current row.
                let Some(joined) = source.first_match(bound_filter.as_ref(), &cur_row, ctx)? else {
                    continue; // no longer matches the WHERE clause
                };
                // 5. A row another part of this statement already updated or
                //    deleted is left alone: PostgreSQL modifies a given row at
                //    most once per command, so it is neither deleted again nor
                //    RETURNed a second time.
                if !writes.claim_row(t.id, rowid) {
                    continue;
                }
                if !is_truncate
                    && crate::trigger::fire_before_row(
                        catalog_kv,
                        crate::trigger::WriteTarget {
                            table: &t,
                            check: &crate::rls::WriteChecks::exempt(
                                crate::rls::CheckExemption::RemovesRows,
                            ),
                        },
                        crate::trigger::DmlEvent::Delete,
                        &[],
                        Some(&cur_row),
                        None,
                        ctx,
                    )?
                    .is_none()
                {
                    continue;
                }
                // Append only: the parent-side probe needs the KV and the lock
                // manager, and the row's tombstone is only staged, so the check
                // waits for the end of the statement.
                if !fk_ctx.is_empty() {
                    writes.fk_checks.after_delete(&fk_ctx, rowid, &cur_row)?;
                }
                if returning.is_some() {
                    returned_rows.push(ReturnedRow {
                        new: None,
                        old: Some(cur_row.clone()),
                        source: joined[t.columns.len()..].to_vec(),
                        action: None,
                    });
                }
                apply_locked_row_delete(
                    write_ctx,
                    &t,
                    &local_indexes,
                    &LockedRowDelete {
                        rowid,
                        cur_key_xid,
                        cur_xmin,
                        cur_row: &cur_row,
                    },
                    writes,
                    &mut ops,
                )?;
                if !is_truncate {
                    crate::trigger::fire_after_row(
                        catalog_kv,
                        &t,
                        crate::trigger::DmlEvent::Delete,
                        &[],
                        Some(&cur_row),
                        None,
                        ctx,
                    )?;
                }
                n += 1;
            }
            let tag = format!("DELETE {n}");
            Ok((spec.outcome(tag, returned_rows, ctx)?, ops))
        }
        Statement::Merge { .. } => Box::pin(execute_merge(write_ctx, ctes, stmt, writes)).await,
        Statement::Cluster(target) => {
            execute_cluster(write_ctx, target.as_ref(), writes, &mut ops).await?;
            Ok((WriteOutcome::command("CLUSTER".into()), ops))
        }
        Statement::Truncate {
            targets,
            restart_identity,
            cascade,
        } => {
            if *restart_identity {
                return Err(ExecError::Unsupported(
                    "TRUNCATE RESTART IDENTITY is not supported: SERIAL sequence ownership is not tracked".into(),
                ));
            }
            // Validate every name (and refuse sharded targets) before touching
            // any table: the statement is all-or-nothing across the list.
            //
            // A target without `ONLY` stands for its whole inheritance tree, so
            // this list is already wider than the one written down; `CASCADE`
            // widens it further below.
            let written = truncate_names(catalog_kv, resolution, targets)?;
            let mut named = Vec::with_capacity(written.len());
            for name in
                resolve_relations(catalog_kv, resolution, &written, SchemaDisposition::Utility)?
            {
                if let Some(error) = truncate_wrong_kind(catalog_kv, &name) {
                    return Err(error);
                }
                let t = crabka_pgcatalog::get_table(catalog_kv, &name)?;
                if table_uses_global_visibility(&t) {
                    return Err(ExecError::Unsupported(
                        "TRUNCATE on sharded tables is not supported".into(),
                    ));
                }
                named.push(t);
            }
            // `TRUNCATE` does not fire `ON DELETE CASCADE`: it refuses when a
            // relation outside the set references one inside it, and `CASCADE`
            // widens the *set* instead. Divergence: PostgreSQL also emits a
            // `NOTICE: truncate cascades to table "…"` per relation `CASCADE`
            // pulls in, which this engine has no NoticeResponse path for, so
            // `TruncateSet::cascaded` is computed and left unemitted.
            let set = crate::fk::expand_truncate_set(catalog_kv, &named, *cascade)?;
            // Every relation the statement will empty, including the ones
            // CASCADE pulled in, before the first row of the first one is
            // touched: TRUNCATE is all-or-nothing, so a denial has to arrive
            // before any work is done. The desugared DELETEs below carry
            // `WriteAction::Truncate` and are authorized by this, not by the
            // DELETE privilege.
            for table in &set.tables {
                crate::privilege::require(
                    &write_ctx.privileges(),
                    &table.name,
                    &table.owner,
                    crate::privilege::RelationKind::Table,
                    crate::privilege::Privilege::Truncate,
                )?;
            }
            // Carried on the statement's write state so each desugared DELETE
            // suppresses exactly the parent-side keys whose child is in the set
            // — by construction every one of them, so no action ever fires.
            writes.truncate_set = set.ids();
            // Desugar to an unfiltered DELETE per table: TRUNCATE shares the
            // MVCC write path (row locks, xmax stamping, rollback) rather
            // than clearing storage, so it is transactional like PostgreSQL's.
            for table in &set.tables {
                let delete = Statement::Delete {
                    table: crabka_pgparser::ast::RelationRef {
                        schema: Some(table.name.schema.clone()),
                        name: table.name.name.clone(),
                    },
                    only: true,
                    alias: None,
                    filter: None,
                    using: Vec::new(),
                    returning: None,
                    with: None,
                };
                let (_, delete_ops) = Box::pin(execute_write_body(
                    write_ctx,
                    ctes,
                    &delete,
                    writes,
                    Reach::Storage,
                ))
                .await?;
                ops.extend(delete_ops);
            }
            Ok((WriteOutcome::command("TRUNCATE TABLE".into()), ops))
        }
        _ => Err(ExecError::Unsupported("not a write statement".into())),
    }
}

/// The name every expression in a DML statement resolves the target's columns
/// under: its alias when it has one, else the table name. `PostgreSQL` hides
/// the real name once an alias is given.
fn table_qualifier<'a>(table: &'a Table, alias: &'a Option<String>) -> &'a str {
    alias.as_deref().unwrap_or(&table.name.name)
}

/// The `FROM`/`USING` relation joined to a DML target, materialized once for the
/// whole statement. The plain (unjoined) form is the degenerate case with one
/// empty source row, so both share one code path.
struct DmlSource {
    /// Target columns first, then the source relation's columns.
    scope: Scope,
    rows: Vec<Vec<Datum>>,
    joined: bool,
}

impl DmlSource {
    fn build(
        write_ctx: &WriteContext<'_>,
        ctes: &crate::cte::CteContext,
        table: &Table,
        qualifier: &str,
        from: &[crabka_pgparser::ast::TableExpr],
    ) -> Result<Self, ExecError> {
        let mut scope = Scope::single(table, qualifier);
        if from.is_empty() {
            return Ok(Self {
                scope,
                rows: vec![Vec::new()],
                joined: false,
            });
        }
        let read = write_ctx.read_ctx(ctes);
        // The target relation is not in the FROM/USING items' scope — SQL puts
        // it out of their reach, and `LATERAL` cannot bring it back — so a name
        // only the target supplies is that prohibition, not a missing entry.
        let kind = if from.iter().any(item_is_lateral) {
            OuterReference::LateralTarget
        } else {
            OuterReference::Target
        };
        let rel = build_from(&read, from, None, None, None)
            .map_err(|error| explain_outer_reference(error, &scope, kind))?;
        scope.columns.extend(rel.scope.columns);
        Ok(Self {
            scope,
            rows: rel.rows,
            joined: true,
        })
    }

    /// The predicate the index-probe planner may use to narrow the target scan.
    /// A joined statement's `WHERE` mentions source columns the probe cannot
    /// resolve, so it falls back to a full scan.
    fn probe_filter<'f>(&self, filter: Option<&'f Expr>) -> Option<&'f Expr> {
        if self.joined { None } else { filter }
    }

    /// Bind the statement's `WHERE` against the combined scope, once, before
    /// the candidate loop. The index probe keeps the source spelling — it reads
    /// column NAMES to match an index — so only [`Self::first_match`] takes the
    /// bound form.
    fn bind_filter(
        &self,
        filter: Option<&Expr>,
    ) -> Result<Option<crate::bind::BoundExpr>, ExecError> {
        crate::bind::bind_optional(filter, &self.scope)
    }

    /// The first source row that satisfies `filter` for this target row, as the
    /// combined row expressions resolve against. `None` means the target row is
    /// not affected by the statement.
    fn first_match(
        &self,
        filter: Option<&crate::bind::BoundExpr>,
        target_row: &[Datum],
        ctx: &crate::clock::EvalCtx,
    ) -> Result<Option<Vec<Datum>>, ExecError> {
        let filter = filter.map(crate::bind::BoundExpr::expr);
        for source_row in &self.rows {
            let mut combined = target_row.to_vec();
            combined.extend_from_slice(source_row);
            if row_matches(filter, &self.scope, &combined, ctx)? {
                return Ok(Some(combined));
            }
        }
        Ok(None)
    }
}

/// One `SET` target after analysis: the column slot plus how its new value is
/// produced.
enum AssignedValue<'a> {
    /// Evaluated against the joined row, per affected row.
    Expr(&'a Expr),
    /// Already computed: a multi-column `= (SELECT …)`, which `PostgreSQL`
    /// evaluates once when the sub-select does not reference the target.
    Value(Datum),
    /// `SET j['a'][0] = e`: the write puts the new value *into* the column's
    /// current jsonb value at the subscripted path.
    Subscripted {
        subscripts: &'a [ArraySubscript],
        value: &'a Expr,
    },
}

/// Resolve every `SET` entry to a column slot and a value source, raising
/// `PostgreSQL`'s analysis errors up front: 42703 for an unknown column, 42701
/// for a column assigned twice, and 42601 for an arity mismatch on the
/// multi-column forms.
fn resolve_assignments<'a>(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    table: &Table,
    assignments: &'a [crabka_pgparser::ast::Assignment],
) -> Result<Vec<(usize, AssignedValue<'a>)>, ExecError> {
    use crabka_pgparser::ast::AssignmentValue;

    let mut out: Vec<(usize, AssignedValue<'a>)> = Vec::new();
    for assignment in assignments {
        let slots = assignment
            .targets
            .iter()
            .map(|column| {
                table
                    .column_index(column)
                    .ok_or_else(|| ExecError::UndefinedColumn(column.clone()))
            })
            .collect::<Result<Vec<_>, _>>()?;
        match &assignment.value {
            AssignmentValue::Expr(expr) if !assignment.subscripts.is_empty() => {
                debug_assert_eq!(slots.len(), 1, "single-target assignment");
                out.push((
                    slots[0],
                    AssignedValue::Subscripted {
                        subscripts: &assignment.subscripts,
                        value: expr,
                    },
                ));
            }
            AssignmentValue::Expr(expr) => {
                debug_assert_eq!(slots.len(), 1, "single-target assignment");
                out.push((slots[0], AssignedValue::Expr(expr)));
            }
            AssignmentValue::Row(items) => {
                if items.len() != slots.len() {
                    return Err(assignment_arity_error(slots.len(), items.len()));
                }
                for (slot, expr) in slots.iter().zip(items) {
                    out.push((*slot, AssignedValue::Expr(expr)));
                }
            }
            AssignmentValue::Subquery(query) => {
                let read = write_ctx.read_ctx(ctes);
                let rel = crate::query::query_to_relation(&read, query)?;
                if rel.scope.width() != slots.len() {
                    return Err(assignment_arity_error(slots.len(), rel.scope.width()));
                }
                if rel.rows.len() > 1 {
                    return Err(ExecError::CardinalityViolation);
                }
                // A sub-select that returns no row assigns NULL to every target,
                // exactly as a zero-row scalar subquery evaluates to NULL.
                for (offset, slot) in slots.iter().enumerate() {
                    let value = rel
                        .rows
                        .first()
                        .map_or(Datum::Null, |row| row[offset].clone());
                    out.push((*slot, AssignedValue::Value(value)));
                }
            }
        }
    }
    let mut seen = HashSet::new();
    for (slot, value) in &out {
        // Subscripted entries update the column in place rather than replacing
        // it, so `SET j['a'] = …, j['b'] = …` is legal in PostgreSQL and each
        // one sees the previous one's result.
        if matches!(value, AssignedValue::Subscripted { .. }) {
            continue;
        }
        if !seen.insert(*slot) {
            // PostgreSQL reports a repeated assignment target as a syntax
            // error (42601), not as a duplicate-object error.
            return Err(ExecError::Syntax(format!(
                "multiple assignments to same column \"{}\"",
                table.columns[*slot].name
            )));
        }
    }
    Ok(out)
}

fn assignment_arity_error(targets: usize, values: usize) -> ExecError {
    ExecError::Syntax(format!(
        "number of columns ({targets}) does not match number of values ({values})"
    ))
}

/// Apply the resolved assignments to a copy of the target row.
fn apply_assignments(
    table: &Table,
    targets: &[(usize, AssignedValue<'_>)],
    scope: &Scope,
    joined_row: &[Datum],
    ctx: &crate::clock::EvalCtx,
) -> Result<Vec<Datum>, ExecError> {
    let mut next = joined_row[..table.columns.len()].to_vec();
    for (idx, value) in targets {
        // As on the INSERT side, `DEFAULT` is the only value an `UPDATE` may
        // name for a generated column.
        if table.columns[*idx].generated.is_some()
            && !matches!(value, AssignedValue::Expr(Expr::Default))
        {
            return Err(ExecError::GeneratedColumnWrite {
                message: format!(
                    "column \"{}\" can only be updated to DEFAULT",
                    table.columns[*idx].name
                ),
                column: table.columns[*idx].name.clone(),
            });
        }
        let raw = match value {
            AssignedValue::Value(value) => value.clone(),
            AssignedValue::Expr(Expr::Default) => default_value(&table.columns[*idx], ctx)?,
            AssignedValue::Expr(expr) => {
                eval_assignment_value(expr, table.columns[*idx].ty, scope, joined_row, ctx)?
            }
            // The subscripted form reads the column's *current* value, so a
            // second entry for the same column sees the first one's result.
            AssignedValue::Subscripted { subscripts, value } => {
                let args =
                    crate::eval::eval_assignment_subscripts(subscripts, scope, joined_row, ctx)?;
                let new_value = crate::eval::eval(value, scope, joined_row, ctx)?;
                // An array column writes into the array; anything else is the
                // jsonb path, which has no slice form.
                match table.columns[*idx].ty.array_element() {
                    Some(elem) => {
                        crate::array_fn::array_assign(&next[*idx], &args, &new_value, elem, ctx)?
                    }
                    None => {
                        let indexes = args
                            .iter()
                            .map(|arg| match arg {
                                crate::array_fn::SubscriptArg::Index(value) => Ok(value.clone()),
                                crate::array_fn::SubscriptArg::Slice { .. } => {
                                    Err(ExecError::TypeMismatch(
                                        "jsonb subscript does not support slices".into(),
                                    ))
                                }
                            })
                            .collect::<Result<Vec<_>, ExecError>>()?;
                        crate::json_fn::jsonb_subscript_assign(&next[*idx], &indexes, &new_value)?
                    }
                }
            }
        };
        next[*idx] = coerce(raw, table.columns[*idx].ty, ctx)?;
    }
    finish_written_row(table, &mut next, ctx)?;
    Ok(next)
}

/// One row a `RETURNING` clause will project: the post-image (absent for
/// `DELETE`), the pre-image (absent for a plain `INSERT`), and the joined
/// source columns the clause may also reference.
struct ReturnedRow {
    new: Option<Vec<Datum>>,
    old: Option<Vec<Datum>>,
    source: Vec<Datum>,
    /// What `merge_action()` reports for this row; `None` outside `MERGE`.
    action: Option<&'static str>,
}

impl ReturnedRow {
    fn updated(new: Vec<Datum>, old: Vec<Datum>, source: Vec<Datum>) -> Self {
        Self {
            new: Some(new),
            old: Some(old),
            source,
            action: None,
        }
    }
}

/// The prefix that makes an `OLD`/`NEW` image binding unreachable by a bare
/// column reference.
///
/// It cannot occur in any identifier the lexer produces, not even a quoted one,
/// which cannot contain a control character. So `RETURNING v` still resolves to
/// the one target column named `v`, as it does in `PostgreSQL`.
const IMAGE_BINDING_PREFIX: char = '\u{1}';

/// An analyzed `RETURNING` clause: the scope its expressions resolve against and
/// the projection rewritten so `OLD`/`NEW` references reach the image bindings.
struct ReturningSpec {
    scope: Scope,
    items: Vec<SelectItem>,
    /// Where the pre-image columns start in the combined row.
    old_offset: usize,
    /// Where the post-image columns start in the combined row.
    new_offset: usize,
    /// `MERGE` appends one `merge_action()` column after the image blocks.
    merge: bool,
    /// The target relation, kept only when it has a `VIRTUAL` generated column.
    /// The post-image a write hands back carries the NULL placeholder that goes
    /// to storage, so `RETURNING` has to produce the value the next reader would
    /// see rather than print the placeholder.
    target: Option<Box<Table>>,
    active: bool,
}

/// The name of the synthetic binding `merge_action()` is rewritten to. Like the
/// `OLD`/`NEW` image bindings it is unreachable by an ordinary column reference.
const MERGE_ACTION_BINDING: &str = "\u{1}merge_action";

impl ReturningSpec {
    fn new(
        table: &Table,
        qualifier: &str,
        returning: Option<&crabka_pgparser::ast::Returning>,
        source: Option<&Scope>,
        merge: bool,
    ) -> Result<Self, ExecError> {
        // `MERGE` lists its source relation before its target, so `RETURNING *`
        // expands source-first there and target-first everywhere else.
        let target_width = table.columns.len();
        let Some(returning) = returning else {
            return Ok(Self {
                scope: Scope::empty(),
                items: Vec::new(),
                old_offset: 0,
                new_offset: 0,
                merge,
                target: None,
                active: false,
            });
        };
        // The visible relations: the target, then any FROM/USING/MERGE source.
        let mut scope = match source {
            Some(source) => source.clone(),
            None => Scope::single(table, qualifier),
        };
        let visible_width = scope.width();
        // PostgreSQL 18's default `old`/`new` spellings are suppressed when a
        // relation of that name is already in scope.
        let taken = |name: &str| {
            scope
                .columns
                .iter()
                .any(|c| c.qualifier.as_deref() == Some(name))
        };
        // An explicit image alias is a relation name like any other: colliding
        // with a relation in scope, or with the other image's alias, is 42712.
        for alias in [&returning.old_alias, &returning.new_alias]
            .into_iter()
            .flatten()
        {
            if taken(alias) {
                return Err(ExecError::DuplicateAlias(alias.clone()));
            }
        }
        if let (Some(old), Some(new)) = (&returning.old_alias, &returning.new_alias)
            && old == new
        {
            return Err(ExecError::DuplicateAlias(old.clone()));
        }
        // An explicit alias also suppresses the OTHER image's default spelling,
        // so `RETURNING WITH (NEW AS old) old.v` reads the post-image.
        let old_alias = returning.old_alias.clone().or_else(|| {
            (!taken("old") && returning.new_alias.as_deref() != Some("old"))
                .then(|| "old".to_string())
        });
        let new_alias = returning.new_alias.clone().or_else(|| {
            (!taken("new") && returning.old_alias.as_deref() != Some("new"))
                .then(|| "new".to_string())
        });
        let old_offset = scope.width();
        scope.columns.extend(image_bindings(table, "old"));
        let new_offset = scope.width();
        scope.columns.extend(image_bindings(table, "new"));
        if merge {
            scope.columns.push(ColumnBinding {
                exposure: Exposure::Output,
                qualifier: None,
                name: MERGE_ACTION_BINDING.to_string(),
                ty: ColumnType::Text,
            });
        }
        let mut items = Vec::new();
        for item in &returning.items {
            match item {
                // `*` spans the visible relations only — never the image aliases.
                SelectItem::Wildcard => {
                    let order: Vec<usize> = if merge {
                        (target_width..visible_width)
                            .chain(0..target_width)
                            .collect()
                    } else {
                        (0..visible_width).collect()
                    };
                    // This expands by index range rather than through
                    // `resolve_projection`, so it has to skip a USING/NATURAL
                    // join's retained input columns itself: `UPDATE … FROM a
                    // JOIN b USING (x) RETURNING *` must not return `x` thrice.
                    items.extend(
                        order
                            .into_iter()
                            .filter(|i| !scope.columns[*i].is_join_input())
                            .map(|i| {
                                let c = &scope.columns[i];
                                SelectItem::Expr {
                                    expr: Expr::Column {
                                        table: c.qualifier.clone(),
                                        name: c.name.clone(),
                                    },
                                    alias: Some(c.name.clone()),
                                }
                            }),
                    );
                }
                SelectItem::QualifiedWildcard(q) if Some(q) == old_alias.as_ref() => {
                    items.extend(image_wildcard(table, "old"));
                }
                SelectItem::QualifiedWildcard(q) if Some(q) == new_alias.as_ref() => {
                    items.extend(image_wildcard(table, "new"));
                }
                SelectItem::QualifiedWildcard(_) => items.push(item.clone()),
                SelectItem::Expr { expr, alias } => {
                    let rewritten = rewrite_image_refs(
                        expr,
                        &ImageAliases {
                            table,
                            old: old_alias.as_deref(),
                            new: new_alias.as_deref(),
                            merge,
                        },
                    );
                    // Rewriting hides the output name a bare `old.v` or
                    // `merge_action()` would otherwise derive, so it is pinned
                    // from the spelling the user wrote.
                    let alias = alias.clone().or_else(|| match expr {
                        Expr::Func(fc) if merge && fc.name == "merge_action" => {
                            Some("merge_action".to_string())
                        }
                        Expr::Column {
                            table: Some(q),
                            name,
                        } if Some(q.as_str()) == old_alias.as_deref()
                            || Some(q.as_str()) == new_alias.as_deref() =>
                        {
                            Some(name.clone())
                        }
                        _ => None,
                    });
                    items.push(SelectItem::Expr {
                        expr: rewritten,
                        alias,
                    });
                }
            }
        }
        Ok(Self {
            scope,
            items,
            old_offset,
            new_offset,
            merge,
            target: has_virtual_generated(table).then(|| Box::new(table.clone())),
            active: true,
        })
    }

    fn outcome(
        &self,
        tag: String,
        rows: Vec<ReturnedRow>,
        ctx: &crate::clock::EvalCtx,
    ) -> Result<WriteOutcome, ExecError> {
        if !self.active {
            return Ok(WriteOutcome::command(tag));
        }
        let width = self.new_offset - self.old_offset;
        let combined: Vec<Vec<Datum>> = rows
            .into_iter()
            .map(|mut row| {
                if let Some(target) = &self.target {
                    for image in [&mut row.old, &mut row.new].into_iter().flatten() {
                        expand_virtual_generated_row(target, image, ctx)?;
                    }
                }
                let nulls = vec![Datum::Null; width];
                // The visible target columns show the post-image, or the
                // pre-image for a DELETE, which is what PostgreSQL projects.
                let mut out = row
                    .new
                    .clone()
                    .or_else(|| row.old.clone())
                    .unwrap_or_else(|| nulls.clone());
                out.extend(row.source);
                out.extend(row.old.unwrap_or_else(|| nulls.clone()));
                out.extend(row.new.unwrap_or(nulls));
                if self.merge {
                    out.push(row.action.map_or(Datum::Null, |a| Datum::Text(a.into())));
                }
                Ok(out)
            })
            .collect::<Result<_, ExecError>>()?;
        let (fields, out_exprs, tys) = resolve_projection(&self.items, &self.scope)?;
        let projected = project_rows(&out_exprs, &self.scope, &combined, ctx)?;
        let scope = Scope {
            columns: fields
                .iter()
                .zip(&tys)
                .map(|(f, ty)| ColumnBinding {
                    exposure: Exposure::Output,
                    qualifier: None,
                    name: f.name.clone(),
                    ty: *ty,
                })
                .collect(),
        };
        Ok(WriteOutcome {
            tag,
            returning: Some(Relation {
                scope,
                rows: projected,
            }),
        })
    }
}

fn image_binding_name(image: &str, column: &str) -> String {
    format!("{IMAGE_BINDING_PREFIX}{image}.{column}")
}

fn image_bindings(table: &Table, image: &str) -> Vec<ColumnBinding> {
    table
        .columns
        .iter()
        .map(|c| ColumnBinding {
            exposure: Exposure::Output,
            qualifier: None,
            name: image_binding_name(image, &c.name),
            ty: c.ty,
        })
        .collect()
}

fn image_wildcard(table: &Table, image: &str) -> Vec<SelectItem> {
    table
        .columns
        .iter()
        .map(|c| SelectItem::Expr {
            expr: Expr::Column {
                table: None,
                name: image_binding_name(image, &c.name),
            },
            alias: Some(c.name.clone()),
        })
        .collect()
}

/// Point every `old.col` / `new.col` reference at its image binding.
///
/// This leaves alone the nodes that cannot contain a row reference reachable
/// from `RETURNING`: literals, parameters, and the subquery forms, which have
/// their own scope.
struct ImageAliases<'a> {
    table: &'a Table,
    old: Option<&'a str>,
    new: Option<&'a str>,
    merge: bool,
}

fn rewrite_image_refs(expr: &Expr, aliases: &ImageAliases<'_>) -> Expr {
    let recurse = |e: &Expr| Box::new(rewrite_image_refs(e, aliases));
    let recurse_all = |items: &[Expr]| -> Vec<Expr> { items.iter().map(|e| *recurse(e)).collect() };
    match expr {
        // `merge_action()` is not an ordinary function: it reports which WHEN
        // clause produced the row, so it reads a per-row binding.
        Expr::Func(fc)
            if aliases.merge
                && fc.name == "merge_action"
                && matches!(&fc.args, crabka_pgparser::ast::FuncArgs::Exprs(a) if a.is_empty()) =>
        {
            Expr::Column {
                table: None,
                name: MERGE_ACTION_BINDING.to_string(),
            }
        }
        Expr::Column {
            table: Some(qualifier),
            name,
        } => {
            let image = if Some(qualifier.as_str()) == aliases.old {
                Some("old")
            } else if Some(qualifier.as_str()) == aliases.new {
                Some("new")
            } else {
                None
            };
            match image {
                // An image reference to a column the target does not have keeps
                // its readable spelling, so resolution reports 42703 against
                // `old.nope` rather than the internal binding name.
                Some(image) if aliases.table.column_index(name).is_some() => Expr::Column {
                    table: None,
                    name: image_binding_name(image, name),
                },
                Some(_) => Expr::Column {
                    table: None,
                    name: format!("{qualifier}.{name}"),
                },
                None => expr.clone(),
            }
        }
        Expr::Unary { op, expr } => Expr::Unary {
            op: *op,
            expr: recurse(expr),
        },
        Expr::Binary { op, left, right } => Expr::Binary {
            op: *op,
            left: recurse(left),
            right: recurse(right),
        },
        Expr::Func(fc) => Expr::Func(crabka_pgparser::ast::FuncCall {
            name: fc.name.clone(),
            distinct: fc.distinct,
            args: match &fc.args {
                crabka_pgparser::ast::FuncArgs::Star => crabka_pgparser::ast::FuncArgs::Star,
                crabka_pgparser::ast::FuncArgs::Exprs(args) => {
                    crabka_pgparser::ast::FuncArgs::Exprs(recurse_all(args))
                }
            },
            // An aggregate's own sort keys are ordinary expressions over the
            // same rows, so they are rewritten exactly like its arguments.
            order_by: fc
                .order_by
                .iter()
                .map(|item| crabka_pgparser::ast::OrderItem {
                    expr: *recurse(&item.expr),
                    asc: item.asc,
                    nulls_first: item.nulls_first,
                })
                .collect(),
            // The FILTER predicate is rewritten like an argument; dropping it
            // would turn a filtered aggregate into an unfiltered one.
            filter: fc.filter.as_deref().map(recurse),
        }),
        Expr::IsNull { expr, negated } => Expr::IsNull {
            expr: recurse(expr),
            negated: *negated,
        },
        Expr::InList {
            expr,
            list,
            negated,
        } => Expr::InList {
            expr: recurse(expr),
            list: recurse_all(list),
            negated: *negated,
        },
        Expr::Between {
            expr,
            low,
            high,
            negated,
        } => Expr::Between {
            expr: recurse(expr),
            low: recurse(low),
            high: recurse(high),
            negated: *negated,
        },
        Expr::Like {
            expr,
            pattern,
            negated,
            kind,
            escape,
        } => Expr::Like {
            expr: recurse(expr),
            pattern: recurse(pattern),
            negated: *negated,
            kind: *kind,
            escape: escape.as_ref().map(|e| recurse(e)),
        },
        Expr::Case {
            operand,
            whens,
            else_result,
        } => Expr::Case {
            operand: operand.as_ref().map(|e| recurse(e)),
            whens: whens
                .iter()
                .map(|(c, r)| (*recurse(c), *recurse(r)))
                .collect(),
            else_result: else_result.as_ref().map(|e| recurse(e)),
        },
        Expr::Cast { expr, ty } => Expr::Cast {
            expr: recurse(expr),
            ty: *ty,
        },
        Expr::ArrayLiteral(items) => Expr::ArrayLiteral(recurse_all(items)),
        Expr::Row(items) => Expr::Row(recurse_all(items)),
        Expr::Subscript { base, index } => Expr::Subscript {
            base: recurse(base),
            index: recurse(index),
        },
        other => other.clone(),
    }
}

/// `MERGE INTO target USING source ON cond WHEN …`.
///
/// The source relation and the target's visible rows are both materialized
/// against the statement snapshot, then joined on `ON`. Source rows drive the
/// `MATCHED` and `NOT MATCHED [BY TARGET]` clauses; a second pass over the
/// target rows no source row joined drives `NOT MATCHED BY SOURCE`. A target
/// row that two clauses would touch is `PostgreSQL`'s 21000.
async fn execute_merge(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    stmt: &Statement,
    writes: &mut StatementWrites,
) -> Result<(WriteOutcome, Vec<crabka_pgkv::WriteOp>), ExecError> {
    use crabka_pgparser::ast::{MergeAction, MergeMatchKind, MergeSource};

    let resolution = write_ctx.eval_ctx.resolution();
    let Statement::Merge {
        table,
        alias,
        source,
        on,
        clauses,
        returning,
        ..
    } = stmt
    else {
        return Err(ExecError::Unsupported("not a MERGE statement".into()));
    };
    let ctx = write_ctx.eval_ctx;
    let table = &resolve_relation(
        write_ctx.catalog_kv,
        resolution,
        table,
        SchemaDisposition::Reference,
    )?;
    let t = crabka_pgcatalog::get_table(write_ctx.catalog_kv, table)?;
    let local_indexes = writable_local_indexes(write_ctx.catalog_kv, &t)?;
    let fk_ctx = crate::fk::StatementFkContext::resolve(write_ctx.catalog_kv, &t)?;
    let qualifier = table_qualifier(&t, alias);
    let mut ops: Vec<crabka_pgkv::WriteOp> = Vec::new();

    let read = write_ctx.read_ctx(ctes);
    let source_rel = match source {
        MergeSource::Table { name, alias } => {
            let te = crabka_pgparser::ast::TableExpr::Table {
                name: name.clone(),
                only: false,
                alias: alias.clone(),
                columns: None,
                sample: None,
            };
            build_from(&read, std::slice::from_ref(&te), None, None, None)?
        }
        MergeSource::Query {
            query,
            alias,
            columns,
        } => {
            let rel = crate::query::query_to_relation(&read, query)?;
            crate::values::requalify_derived(rel, alias, columns)?
        }
    };
    let source_width = source_rel.scope.width();
    let mut scope = Scope::single(&t, qualifier);
    let target_width = scope.width();
    scope.columns.extend(source_rel.scope.columns.clone());
    let spec = ReturningSpec::new(&t, qualifier, returning.as_ref(), Some(&scope), true)?;

    // MERGE reaches rows through its own join, so `SELECT` policies decide
    // which rows it sees and the clauses it was written with decide which
    // privileges it needs. Both are settled here, before the first row is read:
    // `PostgreSQL` checks a MERGE's privileges at statement start whether or
    // not a particular `WHEN` clause ever fires.
    let target_rows = write_candidate_rows(
        write_ctx,
        &t,
        crate::privilege::WriteAction::Merge(crate::privilege::MergeClauses::of(clauses)),
        None,
        true,
    )?;
    // The `UPDATE` and `DELETE` policies then judge each row an action reaches,
    // one row at a time, and raise rather than skip — see `MergeRowSecurity`.
    let row_security = MergeRowSecurity::compile(write_ctx, &t)?;
    let mut matched: HashSet<u64> = HashSet::new();
    let mut returned_rows = Vec::new();
    let mut n: u64 = 0;

    // Every (source, target) pair evaluates the same ON condition, so its
    // column references are resolved once against the joined scope.
    let on_bound = crate::bind::BoundExpr::new(on, &scope)?;
    for source_row in &source_rel.rows {
        let mut any_match = false;
        for (rowid, _xmin, target_row) in &target_rows {
            let mut joined = target_row.clone();
            joined.extend_from_slice(source_row);
            if !row_matches(Some(on_bound.expr()), &scope, &joined, ctx)? {
                continue;
            }
            any_match = true;
            matched.insert(*rowid);
            let Some(when) =
                pick_merge_clause(clauses, MergeMatchKind::Matched, &scope, &joined, ctx)?
            else {
                continue;
            };
            if matches!(when.action, MergeAction::DoNothing) {
                continue;
            }
            // A row any part of this statement already modified — an earlier
            // WHEN clause, or a data-modifying WITH item — is PostgreSQL's 21000.
            if !writes.claim_row(t.id, *rowid) {
                return Err(ExecError::Remote(crabka_pgwire::error::PgError::error(
                    "21000",
                    "MERGE command cannot affect row a second time",
                )));
            }
            let applied = Box::pin(apply_merge_row_action(
                write_ctx,
                &MergeRowAction {
                    table: &t,
                    local_indexes: &local_indexes,
                    fk: &fk_ctx,
                    ctes,
                    scope: &scope,
                    rowid: *rowid,
                    joined: &joined,
                    action: &when.action,
                    security: &row_security,
                },
                writes,
                &mut ops,
            ))
            .await?;
            if let Some(row) = applied {
                n += 1;
                if spec.active {
                    returned_rows.push(row);
                }
            }
        }
        if any_match {
            continue;
        }
        let mut joined = vec![Datum::Null; target_width];
        joined.extend_from_slice(source_row);
        let Some(when) = pick_merge_clause(
            clauses,
            MergeMatchKind::NotMatchedByTarget,
            &scope,
            &joined,
            ctx,
        )?
        else {
            continue;
        };
        let MergeAction::Insert { columns, values } = &when.action else {
            continue; // DO NOTHING
        };
        let exprs: Vec<Expr> = values.clone().unwrap_or_default();
        // `INSERT DEFAULT VALUES` has no target list at all; otherwise a MERGE
        // insert action obeys the same arity rule as a plain INSERT, and reports
        // it with the same two messages.
        let target_idx = if values.is_none() {
            Vec::new()
        } else {
            resolve_insert_targets(&t, columns, exprs.len())?
        };
        // The VALUES may reference the source row, so they are evaluated against
        // the joined scope before the row is assembled.
        // A literal keeps its unresolved form so `build_insert_row` applies the
        // same `unknown`-literal typing a plain INSERT would; everything else is
        // folded against the joined row, which the source columns live in.
        let evaluated = exprs
            .iter()
            .zip(&target_idx)
            .map(|(expr, slot)| match expr {
                Expr::Default | Expr::StringLiteral(_) | Expr::BitStringLiteral(_) => {
                    Ok(expr.clone())
                }
                _ => crate::eval::eval(expr, &scope, &joined, ctx).map(|value| Expr::Const {
                    value,
                    ty: t.columns[*slot].ty,
                }),
            })
            .collect::<Result<Vec<_>, ExecError>>()?;
        let full = build_insert_row(&t, &target_idx, &evaluated, ctx)?;
        let merge_insert_check = write_ctx.row_check(
            &t,
            crabka_pgcatalog::policy::PolicyCommand::Insert,
            &WriteContext::modified_columns(&t, &target_idx),
        )?;
        let Some(full) = crate::trigger::fire_before_row(
            write_ctx.catalog_kv,
            crate::trigger::WriteTarget {
                table: &t,
                check: &merge_insert_check,
            },
            crate::trigger::DmlEvent::Insert,
            &[],
            None,
            Some(full),
            ctx,
        )?
        else {
            continue;
        };
        let (rowid, seq_op) = write_ctx.seq.alloc(write_ctx.kv, t.id, 1)?;
        if let Some(op) = seq_op {
            ops.push(op);
        }
        enforce_unique_local_indexes(write_ctx, &t, &local_indexes, rowid, &full, writes).await?;
        if !fk_ctx.is_empty() {
            writes.fk_checks.after_insert(&fk_ctx, rowid, &full)?;
        }
        ops.push(crabka_pgkv::WriteOp::Put {
            key: crabka_pgmvcc::version::version_key_xid(t.id, rowid, write_ctx.xid),
            value: encode_table_tuple(&t, write_ctx.xid, crabka_pgmvcc::xid::INVALID_XID, &full),
        });
        ops.extend(local_index_entry_ops(&t, &local_indexes, rowid, &full)?);
        crate::trigger::fire_after_row(
            write_ctx.catalog_kv,
            &t,
            crate::trigger::DmlEvent::Insert,
            &[],
            None,
            Some(&full),
            ctx,
        )?;
        n += 1;
        if spec.active {
            returned_rows.push(ReturnedRow {
                new: Some(full),
                old: None,
                source: source_row.clone(),
                action: Some("INSERT"),
            });
        }
    }

    for (rowid, _xmin, target_row) in &target_rows {
        if matched.contains(rowid) {
            continue;
        }
        let mut joined = target_row.clone();
        joined.extend(std::iter::repeat_n(Datum::Null, source_width));
        let Some(when) = pick_merge_clause(
            clauses,
            MergeMatchKind::NotMatchedBySource,
            &scope,
            &joined,
            ctx,
        )?
        else {
            continue;
        };
        if matches!(when.action, MergeAction::DoNothing) {
            continue;
        }
        if !writes.claim_row(t.id, *rowid) {
            return Err(ExecError::Remote(crabka_pgwire::error::PgError::error(
                "21000",
                "MERGE command cannot affect row a second time",
            )));
        }
        let applied = Box::pin(apply_merge_row_action(
            write_ctx,
            &MergeRowAction {
                table: &t,
                local_indexes: &local_indexes,
                fk: &fk_ctx,
                ctes,
                scope: &scope,
                rowid: *rowid,
                joined: &joined,
                action: &when.action,
                security: &row_security,
            },
            writes,
            &mut ops,
        ))
        .await?;
        if let Some(row) = applied {
            n += 1;
            if spec.active {
                returned_rows.push(row);
            }
        }
    }

    Ok((spec.outcome(format!("MERGE {n}"), returned_rows, ctx)?, ops))
}

/// The first `WHEN` clause of `kind` whose `AND` condition holds for this row.
fn pick_merge_clause<'a>(
    clauses: &'a [crabka_pgparser::ast::MergeWhen],
    kind: crabka_pgparser::ast::MergeMatchKind,
    scope: &Scope,
    row: &[Datum],
    ctx: &crate::clock::EvalCtx,
) -> Result<Option<&'a crabka_pgparser::ast::MergeWhen>, ExecError> {
    for clause in clauses.iter().filter(|c| c.kind == kind) {
        if row_matches(clause.condition.as_ref(), scope, row, ctx)? {
            return Ok(Some(clause));
        }
    }
    Ok(None)
}

struct MergeRowAction<'a> {
    table: &'a Table,
    local_indexes: &'a [crabka_pgcatalog::Index],
    fk: &'a crate::fk::StatementFkContext,
    ctes: &'a crate::cte::CteContext,
    scope: &'a Scope,
    rowid: u64,
    joined: &'a [Datum],
    action: &'a crabka_pgparser::ast::MergeAction,
    security: &'a MergeRowSecurity,
}

/// The `USING` qual each `MERGE` action judges an already-matched target row
/// against.
///
/// A plain `UPDATE` or `DELETE` applies its command's `USING` qual as a filter:
/// a row that fails it was never a candidate, and the statement reports a lower
/// count. A `MERGE` cannot do that. It found the row through its own join,
/// under the `SELECT` policies, and it has already decided which `WHEN` clause
/// the row meets — so dropping the row now would silently turn a matched row
/// into a row that matched nothing. `PostgreSQL` raises instead:
///
/// ```text
/// ERROR:  42501: target row violates row-level security policy (USING expression) for table "t"
/// ```
///
/// which is exactly [`crate::rls::CheckSubject::TargetRow`], the same shape
/// `INSERT … ON CONFLICT DO UPDATE` uses for the row it found and is about to
/// change.
///
/// Both quals are compiled once per statement rather than once per row. A
/// relation without row security costs nothing to compile: the decision
/// short-circuits on the relation's own flag before it reads a policy.
struct MergeRowSecurity {
    update: crate::rls::RowSecurityCheck,
    delete: crate::rls::RowSecurityCheck,
}

impl MergeRowSecurity {
    fn compile(write_ctx: &WriteContext<'_>, table: &Table) -> Result<Self, ExecError> {
        use crabka_pgcatalog::policy::PolicyCommand;
        let governor = write_ctx.governor(table);
        let compile = |command| {
            crate::rls::RowSecurityCheck::compile(
                &write_ctx.rls(),
                governor,
                command,
                crate::rls::CheckSubject::TargetRow,
            )
        };
        Ok(Self {
            update: compile(PolicyCommand::Update)?,
            delete: compile(PolicyCommand::Delete)?,
        })
    }
}

/// Apply an `UPDATE`/`DELETE` merge action to one already-matched target row,
/// under the same lock + `EvalPlanQual` recheck the ordinary write path uses.
async fn apply_merge_row_action(
    write_ctx: &WriteContext<'_>,
    request: &MergeRowAction<'_>,
    writes: &mut StatementWrites,
    ops: &mut Vec<crabka_pgkv::WriteOp>,
) -> Result<Option<ReturnedRow>, ExecError> {
    use crabka_pgparser::ast::MergeAction;

    let t = request.table;
    let ctx = write_ctx.eval_ctx;
    write_ctx
        .lockmgr
        .acquire_as(
            t.id,
            request.rowid,
            crate::lockmgr::LockMode::Exclusive,
            write_ctx.lock_owner,
            write_ctx.lock_wait_cap,
        )
        .await
        .map_err(lock_acquire_error)?;
    let Some((cur_key_xid, cur_xmin, cur_row)) =
        eval_plan_qual(&write_ctx.mutation(), t, request.rowid)?
    else {
        return Ok(None); // deleted by a concurrent committed transaction
    };
    let source = request.joined[t.columns.len()..].to_vec();
    match request.action {
        MergeAction::Update(assignments) => {
            request.security.update.permit_row(t, &cur_row, ctx)?;
            let targets = resolve_assignments(write_ctx, request.ctes, t, assignments)?;
            let mut joined = cur_row.clone();
            joined.extend_from_slice(&source);
            let next = apply_assignments(t, &targets, request.scope, &joined, ctx)?;
            let updated_columns = assignments
                .iter()
                .flat_map(|assignment| assignment.targets.iter().cloned())
                .collect::<Vec<_>>();
            let Some(next) = crate::trigger::fire_before_row(
                write_ctx.catalog_kv,
                crate::trigger::WriteTarget {
                    table: t,
                    check: &write_ctx.row_check(
                        t,
                        crabka_pgcatalog::policy::PolicyCommand::Update,
                        &updated_columns,
                    )?,
                },
                crate::trigger::DmlEvent::Update,
                &updated_columns,
                Some(&cur_row),
                Some(next),
                ctx,
            )?
            else {
                return Ok(None);
            };
            apply_locked_row_update(
                write_ctx,
                t,
                request.local_indexes,
                request.fk,
                &LockedRowUpdate {
                    rowid: request.rowid,
                    cur_key_xid,
                    cur_xmin,
                    cur_row: &cur_row,
                    next: &next,
                },
                writes,
                ops,
            )
            .await?;
            crate::trigger::fire_after_row(
                write_ctx.catalog_kv,
                t,
                crate::trigger::DmlEvent::Update,
                &updated_columns,
                Some(&cur_row),
                Some(&next),
                ctx,
            )?;
            Ok(Some(ReturnedRow {
                new: Some(next),
                old: Some(cur_row),
                source,
                action: Some("UPDATE"),
            }))
        }
        MergeAction::Delete => {
            request.security.delete.permit_row(t, &cur_row, ctx)?;
            if crate::trigger::fire_before_row(
                write_ctx.catalog_kv,
                crate::trigger::WriteTarget {
                    table: t,
                    check: &crate::rls::WriteChecks::exempt(
                        crate::rls::CheckExemption::RemovesRows,
                    ),
                },
                crate::trigger::DmlEvent::Delete,
                &[],
                Some(&cur_row),
                None,
                ctx,
            )?
            .is_none()
            {
                return Ok(None);
            }
            // The deleted row's unique keys are free for a later part of this
            // statement, exactly as on the plain DELETE path.
            writes.release_row_keys(t, request.local_indexes, request.rowid, &cur_row, None)?;
            if !request.fk.is_empty() {
                writes
                    .fk_checks
                    .after_delete(request.fk, request.rowid, &cur_row)?;
            }
            if cur_xmin == write_ctx.xid {
                ops.push(crabka_pgkv::WriteOp::Put {
                    key: crabka_pgmvcc::version::version_key_xid(
                        t.id,
                        request.rowid,
                        write_ctx.xid,
                    ),
                    value: encode_table_tuple(t, write_ctx.xid, write_ctx.xid, &cur_row),
                });
            } else {
                ops.push(crabka_pgkv::WriteOp::Put {
                    key: crabka_pgmvcc::version::version_key_xid(t.id, request.rowid, cur_key_xid),
                    value: encode_table_tuple(t, cur_xmin, write_ctx.xid, &cur_row),
                });
            }
            crate::trigger::fire_after_row(
                write_ctx.catalog_kv,
                t,
                crate::trigger::DmlEvent::Delete,
                &[],
                Some(&cur_row),
                None,
                ctx,
            )?;
            Ok(Some(ReturnedRow {
                new: None,
                old: Some(cur_row),
                source,
                action: Some("DELETE"),
            }))
        }
        MergeAction::DoNothing | MergeAction::Insert { .. } => Ok(None),
    }
}

/// The rows an `INSERT` supplies, plus the target column slots they fill.
///
/// A feeding query is materialized before any row is written, so an
/// `INSERT … SELECT` that reads the target table sees the pre-insert snapshot
/// as `PostgreSQL` does.
fn insert_source_rows(
    write_ctx: &WriteContext<'_>,
    ctes: &crate::cte::CteContext,
    table: &Table,
    columns: &Option<Vec<String>>,
    source: &crabka_pgparser::ast::InsertSource,
) -> Result<(Vec<usize>, Vec<Vec<Expr>>), ExecError> {
    use crabka_pgparser::ast::InsertSource;
    match source {
        InsertSource::Values(rows) => {
            // Rows of differing width are PostgreSQL's own 42601, raised before
            // the arity of the target list is even considered.
            let width = rows.first().map_or(0, Vec::len);
            if rows.iter().any(|row| row.len() != width) {
                return Err(ExecError::ValuesColumnCount);
            }
            Ok((resolve_insert_targets(table, columns, width)?, rows.clone()))
        }
        // Every column takes its default; an explicit column list is a syntax
        // error in PostgreSQL, so none can be present here.
        InsertSource::DefaultValues => Ok((Vec::new(), vec![Vec::new()])),
        InsertSource::Query(query) => {
            // Resolve the names first so an unknown column is 42703 before the
            // feeding query runs, as it is in PostgreSQL's parse analysis.
            resolve_targets(table, columns)?;
            let read = write_ctx.read_ctx(ctes);
            let Relation { scope, rows } = crate::query::query_to_relation(&read, query)?;
            let target_idx = resolve_insert_targets(table, columns, scope.width())?;
            // A column the feeding query left `unknown` goes back to being the
            // literal it was written as, so `build_insert_row` types it against
            // the target column exactly as it types a VALUES row. The flags are
            // positional over the row, so they are used only when they span it:
            // a relation of another width is one this walk cannot index, and
            // typing the wrong column would be worse than typing none.
            let unknown = unknown_literal_columns(query);
            let unknown: &[bool] = if unknown.len() == scope.width() {
                &unknown
            } else {
                &[]
            };
            let rows = rows
                .into_iter()
                .map(|row| {
                    row.into_iter()
                        .zip(&scope.columns)
                        .enumerate()
                        .map(|(index, (value, column))| match value {
                            // Only a value the literal itself produced may go
                            // back to being one, which is why the datum is
                            // matched and not merely re-rendered.
                            Datum::Text(text) if unknown.get(index).copied().unwrap_or(false) => {
                                Expr::StringLiteral(text)
                            }
                            value => Expr::Const {
                                value,
                                ty: column.ty,
                            },
                        })
                        .collect()
                })
                .collect();
            Ok((target_idx, rows))
        }
    }
}

/// The output columns a query hands to an `INSERT` as PostgreSQL's `unknown`,
/// one flag per column of the query's own target list.
///
/// An `INSERT … SELECT` is the one place `PostgreSQL` declines to resolve a
/// query's unknown outputs to `text`. It analyses the feeding query with that
/// resolution switched off, and then takes every target entry that is still an
/// unknown constant *as the constant*, rather than as a reference to the
/// query's column. The literal therefore arrives at the target list untyped and
/// takes the target column's type, which is what makes `INSERT INTO point_tbl
/// SELECT '(0,0)'` a point where `SELECT '(0,0)'` on its own is text. Without
/// it, the two `INSERT` spellings of one row disagree: the `VALUES` form
/// resolves the literal and the `SELECT` form is 42804.
///
/// What is left out is left out because `PostgreSQL` has already had to choose
/// the column's type there, so nothing unknown survives to be re-typed:
///
/// * a set operation, whose column type is the common type of its branches and
///   is `text` when every branch is unknown — `… SELECT '(0,0)' UNION ALL
///   SELECT '(1,1)'` really is 42804;
/// * a sub-select, a derived table or a `VALUES` relation, each of which has
///   resolved its own unknown outputs to `text` at the boundary since
///   `PostgreSQL` 10 — so `… SELECT * FROM (VALUES ('(0,0)')) v` is 42804 too;
/// * anything that is not the bare literal: a cast, a function call, a column
///   reference or a `CASE` all carry a type of their own.
///
/// `ORDER BY`, `LIMIT`, `OFFSET` and a `WITH` prefix wrap a select list without
/// retyping it, so they are transparent and the list underneath still counts.
///
/// A `NULL` literal is unknown in `PostgreSQL` as well, and is deliberately not
/// reported here: [`coerce`] already stores a `Datum::Null` into a column of
/// any type, and sending it through [`resolve_unknown_literal`] instead would
/// hand the target's input function an empty string to parse.
///
/// The vector is empty when no column qualifies, which includes every select
/// list holding a `*`: a wildcard stands for as many columns as the relation
/// beneath it has, and no walk of the list alone can count them. A wildcard is
/// never unknown, so declining the whole list there costs nothing.
fn unknown_literal_columns(query: &crabka_pgparser::ast::QueryExpr) -> Vec<bool> {
    use crabka_pgparser::ast::{QueryBody, SelectItem, SetExpr};
    let SetExpr::Query(body) = &query.body else {
        return Vec::new();
    };
    match body {
        QueryBody::Nested(nested) => unknown_literal_columns(nested),
        QueryBody::Values(_) => Vec::new(),
        QueryBody::Select(select) => select
            .projection
            .iter()
            .map(|item| match item {
                SelectItem::Expr { expr, .. } => Some(matches!(expr, Expr::StringLiteral(_))),
                SelectItem::Wildcard | SelectItem::QualifiedWildcard(_) => None,
            })
            .collect::<Option<Vec<bool>>>()
            .filter(|columns| columns.contains(&true))
            .unwrap_or_default(),
    }
}

/// The relation a `COPY … FROM` loads into, and the column list it fills.
///
/// `PostgreSQL`'s grammar has no `COPY ( <query> ) FROM` spelling, so the target
/// of a load is always a relation; carrying just those two fields keeps the
/// write paths free of the statement's framing options, which are already
/// resolved by the time rows reach them.
#[derive(Debug, Clone, Copy)]
pub(crate) struct CopyIntoTarget<'a> {
    pub(crate) name: &'a crabka_pgparser::ast::RelationRef,
    pub(crate) columns: &'a Option<Vec<String>>,
}

pub(crate) async fn execute_copy_write(
    write_ctx: &WriteContext<'_>,
    target: CopyIntoTarget<'_>,
    rows: &[crate::copyfmt::CopyRow<'_>],
) -> Result<(QueryResult, Vec<crabka_pgkv::WriteOp>), ExecError> {
    let catalog_kv = write_ctx.catalog_kv;
    let kv = write_ctx.kv;
    let seq = write_ctx.seq;
    let snapshot_xid = write_ctx.xid;
    let ctx = write_ctx.eval_ctx;
    let resolution = ctx.resolution();
    let mut ops = Vec::new();
    let table = crabka_pgcatalog::get_table(
        catalog_kv,
        &resolve_relation(
            catalog_kv,
            resolution,
            target.name,
            SchemaDisposition::Utility,
        )?,
    )?;
    // Hoisted out of the row loop: the target's index set is the same for every
    // row, so reading it per row was a catalog round trip per row. A row that
    // routes to a partition leaf belongs to a different relation, so that case
    // — and only that case — reads again below.
    let parent_indexes = writable_local_indexes(catalog_kv, &table)?;
    // The relation the COPY named governs every routed row, exactly as it does
    // for a partitioned INSERT. `COPY … FROM` into a relation under row
    // security is refused before the statement runs (see the session's copy-in
    // start), so this check is the second line rather than the first.
    // Hoisted for the same reason as the index set, and cached per routed leaf
    // below: one resolution per relation, never one per row.
    let parent_fk = crate::fk::StatementFkContext::resolve(catalog_kv, &table)?;
    let mut leaf_fk: HashMap<TableId, crate::fk::StatementFkContext> = HashMap::new();
    let mut writes = StatementWrites::default();
    let target_idx = resolve_targets(&table, target.columns)?;
    let copied_columns = WriteContext::modified_columns(&table, &target_idx);
    let copy_check = write_ctx.row_check(
        &table,
        crabka_pgcatalog::policy::PolicyCommand::Insert,
        &copied_columns,
    )?;
    let n_rows = rows.len() as u64;
    crate::trigger::fire_statement(
        catalog_kv,
        &table,
        crate::trigger::DmlEvent::Insert,
        crabka_pgcatalog::trigger::TriggerTiming::Before,
        &[],
        ctx,
    )?;
    if n_rows == 0 {
        crate::trigger::fire_statement(
            catalog_kv,
            &table,
            crate::trigger::DmlEvent::Insert,
            crabka_pgcatalog::trigger::TriggerTiming::After,
            &[],
            ctx,
        )?;
        return Ok((command("COPY 0"), ops));
    }
    let (start, seq_op) = seq.alloc(kv, table.id, n_rows)?;
    if let Some(op) = seq_op {
        ops.push(op);
    }
    let partitioned = crate::partition::is_partitioned(catalog_kv, &table.name)?;
    let mut copied = 0_u64;
    // The relation every `CONTEXT` line names, which is the one the statement
    // copied into even for a row that routes to a partition leaf.
    let copied_into = table.name.name.clone();
    // Each of these borrows nothing, so it is one branch and one clone of a
    // short name per *failing* row and nothing at all per successful one.
    let at_line = |error, row: &crate::copyfmt::CopyRow<'_>| {
        copy_row_context(
            error,
            &copied_into,
            row,
            crate::copyfmt::CopyContext::Line { raw: row.raw },
        )
    };
    let at_line_number = |error, row: &crate::copyfmt::CopyRow<'_>| {
        copy_row_context(
            error,
            &copied_into,
            row,
            crate::copyfmt::CopyContext::LineNumber,
        )
    };
    for (rowid, row) in (start..).zip(rows.iter()) {
        copy_row_width(&table, &target_idx, row)?;
        let full = build_copy_row(&table, &target_idx, row, ctx)?;
        // COPY into a partitioned parent routes each row exactly as INSERT
        // does; the reserved rowid block belongs to the parent, so a routed row
        // takes one from its own leaf instead.
        let (table, rowid, full, routed) = if partitioned {
            let (leaf, leaf_row) =
                route_row_to_leaf(write_ctx, &table, &full).map_err(|error| at_line(error, row))?;
            let (leaf_rowid, seq_op) = seq.alloc(kv, leaf.id, 1)?;
            ops.extend(seq_op);
            (leaf, leaf_rowid, leaf_row, true)
        } else {
            check_partition_constraint(write_ctx, &table, &full, &copied_columns)
                .map_err(|error| at_line(error, row))?;
            (table.clone(), rowid, full, false)
        };
        let Some(full) = crate::trigger::fire_before_row(
            catalog_kv,
            crate::trigger::WriteTarget {
                table: &table,
                check: &copy_check,
            },
            crate::trigger::DmlEvent::Insert,
            &[],
            None,
            Some(full),
            ctx,
        )
        .map_err(|error| at_line(error, row))?
        else {
            continue;
        };
        let routed_indexes = if routed {
            Some(writable_local_indexes(catalog_kv, &table)?)
        } else {
            None
        };
        let local_indexes = routed_indexes.as_deref().unwrap_or(&parent_indexes);
        let fk_ctx = if routed {
            match leaf_fk.entry(table.id) {
                std::collections::hash_map::Entry::Occupied(slot) => slot.into_mut(),
                std::collections::hash_map::Entry::Vacant(slot) => {
                    slot.insert(crate::fk::StatementFkContext::resolve(catalog_kv, &table)?)
                }
            }
        } else {
            &parent_fk
        };
        // A duplicate key is raised where PostgreSQL raises it — at the point
        // the row reaches the index — and by then its line buffer has been
        // flushed, so the context is the line *number* with no line quoted.
        enforce_unique_local_indexes(write_ctx, &table, local_indexes, rowid, &full, &mut writes)
            .await
            .map_err(|error| at_line_number(error, row))?;
        if !fk_ctx.is_empty() {
            writes.fk_checks.after_insert(fk_ctx, rowid, &full)?;
        }
        ops.push(crabka_pgkv::WriteOp::Put {
            key: crabka_pgmvcc::version::version_key_xid(table.id, rowid, snapshot_xid),
            value: encode_table_tuple(&table, snapshot_xid, crabka_pgmvcc::xid::INVALID_XID, &full),
        });
        ops.extend(local_index_entry_ops(&table, local_indexes, rowid, &full)?);
        crate::trigger::fire_after_row(
            catalog_kv,
            &table,
            crate::trigger::DmlEvent::Insert,
            &[],
            None,
            Some(&full),
            ctx,
        )?;
        copied += 1;
    }
    // `COPY` is one command, so its referential checks fire once, after every
    // row is staged — the same timing an `INSERT` of the same rows would give.
    let fk_ops = drain_statement_fk_checks(write_ctx, &mut writes, &ops).await?;
    ops.extend(fk_ops);
    crate::trigger::fire_statement(
        catalog_kv,
        &table,
        crate::trigger::DmlEvent::Insert,
        crabka_pgcatalog::trigger::TriggerTiming::After,
        &[],
        ctx,
    )?;
    Ok((command(&format!("COPY {copied}")), ops))
}

pub(crate) fn execute_timestamp_copy_write(
    catalog_kv: &dyn Kv,
    kv: &dyn Kv,
    seq: &crate::seq::SequenceManager,
    target: CopyIntoTarget<'_>,
    rows: &[crate::copyfmt::CopyRow<'_>],
    ctx: &crate::clock::EvalCtx,
) -> Result<TimestampWritePlan, ExecError> {
    let resolution = ctx.resolution();
    let table = crabka_pgcatalog::get_table(
        catalog_kv,
        &resolve_relation(
            catalog_kv,
            resolution,
            target.name,
            SchemaDisposition::Utility,
        )?,
    )?;
    if !table_uses_global_visibility(&table) {
        return Err(ExecError::Unsupported(
            "timestamp COPY requires a sharded table".into(),
        ));
    }
    let indexes = crabka_pgcatalog::list_table_indexes(catalog_kv, &table.name)?;
    if indexes.iter().any(|index| {
        index.placement == crabka_pgcatalog::IndexPlacement::Local
            || (index.placement == crabka_pgcatalog::IndexPlacement::Global && index.unique)
    }) {
        return Err(ExecError::Unsupported(
            "COPY index maintenance for sharded tables is not supported".into(),
        ));
    }
    let global_indexes = indexes
        .iter()
        .filter(|index| index.placement == crabka_pgcatalog::IndexPlacement::Global)
        .collect::<Vec<_>>();
    let target_idx = resolve_targets(&table, target.columns)?;
    let n_rows = rows.len() as u64;
    if n_rows == 0 {
        return Ok(TimestampWritePlan {
            result: command("COPY 0"),
            writes: Vec::new(),
            commit_ops: Vec::new(),
        });
    }
    let (start, seq_op) = seq.alloc(kv, table.id, n_rows)?;
    let mut writes = Vec::with_capacity(rows.len());
    for (rowid, copied) in (start..).zip(rows.iter()) {
        copy_row_width(&table, &target_idx, copied)?;
        let row = build_copy_row(&table, &target_idx, copied, ctx)?;
        writes.push(TimestampWrite {
            table_id: table.id,
            bucket: hash_bucket_for_row(&table, &row)?,
            rowid,
            global_index_intents: global_index_intents_for_row(
                &table,
                &global_indexes,
                rowid,
                &row,
            )?,
            row,
            delete: false,
        });
    }
    Ok(TimestampWritePlan {
        result: command(&format!("COPY {n_rows}")),
        writes,
        commit_ops: seq_op.into_iter().collect(),
    })
}

fn writable_local_indexes(
    catalog_kv: &dyn Kv,
    table: &Table,
) -> Result<Vec<crabka_pgcatalog::Index>, ExecError> {
    let indexes = crabka_pgcatalog::list_table_indexes(catalog_kv, &table.name)?;
    if indexes.is_empty() {
        return Ok(Vec::new());
    }
    let mut local_indexes = Vec::new();
    for index in indexes {
        if index.placement != crabka_pgcatalog::IndexPlacement::Local {
            if index.unique {
                return Err(ExecError::Unsupported(
                    "unique global indexes are not supported until global enforcement exists"
                        .into(),
                ));
            }
            continue;
        }
        reject_unwritable_local_index(table)?;
        local_indexes.push(index);
    }
    Ok(local_indexes)
}

/// One relation `CLUSTER` will reorder, paired with the index whose order it
/// takes. A partitioned parent expands into one unit per leaf.
struct ClusterUnit {
    table: Table,
    index: crabka_pgcatalog::Index,
}

/// `there is no previously clustered index for table "…"` (42704) — what
/// `PostgreSQL` raises for `CLUSTER <table>` with no `USING` and no recorded
/// index.
fn no_clustered_index(name: &crabka_pgcatalog::RelationName) -> ExecError {
    ExecError::UndefinedObject(format!(
        "there is no previously clustered index for table \"{}\"",
        name.name
    ))
}

/// `CLUSTER [ <table> [ USING <index> ] ]`.
///
/// `PostgreSQL` rewrites the heap so that a sequential scan returns the rows in
/// the index's order. Gres stores a row at `/<table_id>/1/<rowid>` and every
/// scan hands rows back in rowid order — that is [`crate::scanner::RangeScanner`]'s
/// documented contract, not an accident of the map — so the same effect is a
/// *renumbering*: read the live rows, sort them by the index key, and rewrite
/// them over a fresh ascending block of rowids.
///
/// The renumbering stays inside the rowid contract because the new block comes
/// from [`crate::seq::SequenceManager::alloc`], whose invariant is that the
/// persisted counter is at or above every rowid ever handed out. The rows move
/// strictly *upward* into rowids that were never used; the vacated ones are
/// abandoned, never recycled. Nothing is minted by hand.
///
/// The rewrite is an ordinary MVCC delete-and-reinsert under each row's
/// exclusive lock, not a physical move: the old version is tombstoned with this
/// transaction's `xmax` and the new one written with its `xmin`, so a snapshot
/// that cannot see this transaction still reads the table exactly as it was,
/// and `ROLLBACK` leaves the heap untouched. That is also why the secondary
/// indexes need no special handling — the entries for the old rowids stay valid
/// for as long as the old versions are visible to somebody, and the ordinary
/// chain prune reclaims them afterwards.
///
/// Sharded relations are refused, as `TRUNCATE` refuses them: their hidden
/// rowids are timestamps drawn from a lease rather than a per-table counter, so
/// there is no ascending block to move rows into.
async fn execute_cluster(
    write_ctx: &WriteContext<'_>,
    target: Option<&crabka_pgparser::ast::ClusterTarget>,
    writes: &mut StatementWrites,
    ops: &mut Vec<crabka_pgkv::WriteOp>,
) -> Result<(), ExecError> {
    let units = match target {
        Some(target) => cluster_units_for_target(write_ctx, target)?,
        None => cluster_units_for_role(write_ctx)?,
    };
    for unit in &units {
        cluster_one_relation(write_ctx, unit, writes, ops).await?;
    }
    Ok(())
}

/// The catalog writes `CLUSTER <table> USING <index>` makes: the relation's
/// `pg_index.indisclustered` moves to the named index.
///
/// Raised separately from the reordering because a catalog record carries no
/// MVCC header — it has to go through the session's catalog seam, which records
/// the before-images `ROLLBACK` undoes it with, rather than riding the row
/// batch, whose undo is the aborted xid on each tuple.
///
/// Empty for `CLUSTER <table>` (which reuses the recorded index rather than
/// choosing one) and for a partitioned parent, whose indexes `PostgreSQL` never
/// marks.
pub(crate) fn cluster_mark_ops(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    target: &crabka_pgparser::ast::ClusterTarget,
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    let Some(index_name) = target.index.as_deref() else {
        return Ok(Vec::new());
    };
    let name = crate::relname::resolve_relation(
        catalog_kv,
        resolution,
        &target.table,
        crate::relname::SchemaDisposition::Utility,
    )?;
    if crate::partition::is_partitioned(catalog_kv, &name)? {
        return Ok(Vec::new());
    }
    let table = crabka_pgcatalog::get_table(catalog_kv, &name)?;
    let index = cluster_index_named(catalog_kv, &table, index_name)?;
    record_clustered_index_ops(catalog_kv, &table, Some(&index.name))
}

/// Mark `index` as `table`'s clustered index, clearing the flag from every other
/// index on the relation. `None` clears all of them (`SET WITHOUT CLUSTER`).
///
/// Only the records whose flag actually moves are rewritten, so the batch is
/// empty — and the statement writes nothing — when the mark is already where it
/// is being asked to go.
fn record_clustered_index_ops(
    catalog_kv: &dyn Kv,
    table: &Table,
    index: Option<&str>,
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    let mut ops = Vec::new();
    for mut candidate in crabka_pgcatalog::list_table_indexes(catalog_kv, &table.name)? {
        let wanted = index.is_some_and(|name| name == candidate.name);
        if candidate.clustered == wanted {
            continue;
        }
        candidate.clustered = wanted;
        ops.extend(crabka_pgcatalog::put_index_ops(&candidate));
    }
    Ok(ops)
}

/// Resolve, authorize and expand the relation one `CLUSTER <table> …` names.
fn cluster_units_for_target(
    write_ctx: &WriteContext<'_>,
    target: &crabka_pgparser::ast::ClusterTarget,
) -> Result<Vec<ClusterUnit>, ExecError> {
    let catalog_kv = write_ctx.catalog_kv;
    let name = crate::relname::resolve_relation(
        catalog_kv,
        write_ctx.eval_ctx.resolution(),
        &target.table,
        crate::relname::SchemaDisposition::Utility,
    )?;
    let table = crabka_pgcatalog::get_table(catalog_kv, &name)?;
    require_cluster_privilege(write_ctx, &table)?;
    if crate::partition::is_partitioned(catalog_kv, &name)? {
        // A partitioned parent holds no rows: `PostgreSQL` reorders each leaf by
        // the leaf's own copy of the index and leaves every partitioned index
        // unmarked, which is why `CLUSTER <partitioned parent>` with no `USING`
        // still reports that there is no previously clustered index.
        let Some(index_name) = target.index.as_deref() else {
            return Err(no_clustered_index(&name));
        };
        let parent_index = cluster_index_named(catalog_kv, &table, index_name)?;
        let mut units = Vec::new();
        for leaf in crate::partition::leaves_of(catalog_kv, &name)? {
            let leaf_table = crabka_pgcatalog::get_table(catalog_kv, &leaf)?;
            // The leaf's copy is matched by key, not by name: a partition's
            // index carries its own generated name.
            let Some(index) = crabka_pgcatalog::list_table_indexes(catalog_kv, &leaf)?
                .into_iter()
                .find(|index| index.columns == parent_index.columns)
            else {
                continue;
            };
            units.push(ClusterUnit {
                table: leaf_table,
                index,
            });
        }
        return Ok(units);
    }
    let index = match target.index.as_deref() {
        Some(index_name) => cluster_index_named(catalog_kv, &table, index_name)?,
        None => crabka_pgcatalog::list_table_indexes(catalog_kv, &name)?
            .into_iter()
            .find(|index| index.clustered)
            .ok_or_else(|| no_clustered_index(&name))?,
    };
    Ok(vec![ClusterUnit { table, index }])
}

/// Every relation the bare `CLUSTER` reorders: the ones that already record a
/// clustered index and that the current role may cluster.
///
/// `PostgreSQL` warns about, and then skips, a relation the role cannot
/// cluster; Gres has no `NoticeResponse` path from here, so the skip happens
/// silently. The regression suite runs this statement under
/// `client_min_messages = ERROR` for exactly that reason.
fn cluster_units_for_role(write_ctx: &WriteContext<'_>) -> Result<Vec<ClusterUnit>, ExecError> {
    let catalog_kv = write_ctx.catalog_kv;
    let mut units = Vec::new();
    for index in marked_clustered_indexes(catalog_kv)? {
        let table = crabka_pgcatalog::get_table(catalog_kv, &index.table)?;
        if require_cluster_privilege(write_ctx, &table).is_err() {
            continue;
        }
        units.push(ClusterUnit { table, index });
    }
    Ok(units)
}

/// Every index carrying `pg_index.indisclustered`, in catalog order.
///
/// The session reads this to know which relations a bare `CLUSTER` will reach,
/// so it can lock them before the executor starts moving their rows — the
/// executor's own view of the set has to agree with the one that was locked,
/// which is why both come from here.
pub(crate) fn marked_clustered_indexes(
    catalog_kv: &dyn Kv,
) -> Result<Vec<crabka_pgcatalog::Index>, ExecError> {
    Ok(crabka_pgcatalog::list_indexes(catalog_kv)?
        .into_iter()
        .filter(|index| index.clustered)
        .collect())
}

/// `PostgreSQL` authorizes `CLUSTER` with the relation's `MAINTAIN` privilege,
/// which only the owner (and the superuser) holds here, and reports the refusal
/// as `permission denied for table <name>` rather than `must be owner of`.
fn require_cluster_privilege(write_ctx: &WriteContext<'_>, table: &Table) -> Result<(), ExecError> {
    let role = write_ctx.fctx.effective_role();
    if crabka_pgcatalog::role_has_privs_of(write_ctx.catalog_kv, role, &table.owner)?
        || crate::rls::role_is_superuser(write_ctx.catalog_kv, role)?
    {
        return Ok(());
    }
    Err(ExecError::PermissionDenied {
        kind: "table",
        relation: table.name.name.clone(),
    })
}

/// Look up the index a `CLUSTER … USING <name>` (or `CLUSTER <name> ON …`)
/// asked for, and refuse the ones whose order cannot drive a heap rewrite.
fn cluster_index_named(
    catalog_kv: &dyn Kv,
    table: &Table,
    index_name: &str,
) -> Result<crabka_pgcatalog::Index, ExecError> {
    let index = crabka_pgcatalog::list_table_indexes(catalog_kv, &table.name)?
        .into_iter()
        .find(|index| index.name == index_name)
        .ok_or_else(|| {
            ExecError::UndefinedObject(format!(
                "index \"{index_name}\" for table \"{}\" does not exist",
                table.name.name
            ))
        })?;
    if index.method != crabka_pgcatalog::IndexMethod::Btree {
        return Err(ExecError::Unsupported(format!(
            "cannot cluster on index \"{index_name}\" because access method does not support \
             clustering"
        )));
    }
    Ok(index)
}

/// Reorder one relation's live rows into `unit.index`'s order.
async fn cluster_one_relation(
    write_ctx: &WriteContext<'_>,
    unit: &ClusterUnit,
    writes: &mut StatementWrites,
    ops: &mut Vec<crabka_pgkv::WriteOp>,
) -> Result<(), ExecError> {
    let table = &unit.table;
    if table_uses_global_visibility(table) {
        return Err(ExecError::Unsupported(
            "CLUSTER on sharded tables is not supported: a hidden rowid there is a leased \
             timestamp, not a position in a per-table sequence"
                .into(),
        ));
    }
    reject_cluster_with_pending_checks(write_ctx, table)?;
    let scanned = scan_live(
        write_ctx.kv,
        write_ctx.global,
        write_ctx.global_snapshot,
        write_ctx.snapshot,
        Some(write_ctx.xid),
        table,
    )?;
    // Reclustering an already-clustered relation is the common case — the bare
    // `CLUSTER` reruns every marked relation — and it moves nothing. Decide that
    // from the snapshot rows, before taking a single row lock: the alternative
    // is to lock and re-read the whole table to discover there is no work, which
    // measured three times the cost of the rewrite it was avoiding.
    if cluster_scan_is_ordered(table, &unit.index, &scanned, write_ctx.eval_ctx)? {
        return Ok(());
    }
    // Lock in ascending rowid order — the order every other statement takes
    // this table's row locks in — then re-read each row under its lock, exactly
    // as `DELETE` does, so a concurrent writer is serialized against rather
    // than read around.
    let mut locked = Vec::with_capacity(scanned.len());
    for (rowid, _, _) in &scanned {
        write_ctx
            .lockmgr
            .acquire_as(
                table.id,
                *rowid,
                crate::lockmgr::LockMode::Exclusive,
                write_ctx.lock_owner,
                write_ctx.lock_wait_cap,
            )
            .await
            .map_err(lock_acquire_error)?;
        let Some((cur_key_xid, cur_xmin, cur_row)) =
            eval_plan_qual(&write_ctx.mutation(), table, *rowid)?
        else {
            continue; // already deleted by a concurrent committed transaction
        };
        let key = cluster_sort_key(table, &unit.index, &cur_row, write_ctx.eval_ctx)?;
        locked.push((key, *rowid, cur_key_xid, cur_xmin, cur_row));
    }
    // Stable, so rows sharing an index key keep the order they already have —
    // the only deterministic tie-break available, and the one that makes
    // reclustering idempotent.
    locked.sort_by(|a, b| compare_cluster_key(&a.0, &b.0));
    if locked.windows(2).all(|pair| pair[0].1 < pair[1].1) {
        // The pre-check said the same thing about the snapshot rows, but under
        // READ COMMITTED the versions re-read under the locks can be newer.
        // Confirming it here is what keeps `CLUSTER` from burning a block of
        // rowids to rewrite a heap into the order it is already in.
        return Ok(());
    }
    let local_indexes = writable_local_indexes(write_ctx.catalog_kv, table)?;
    let (start, seq_op) = write_ctx.seq.alloc(
        write_ctx.kv,
        table.id,
        u64::try_from(locked.len()).map_err(|_| {
            ExecError::Unsupported("CLUSTER row count exceeds the rowid domain".into())
        })?,
    )?;
    ops.extend(seq_op);
    // `(start..)` walks the reserved block, the way the INSERT path walks the
    // block it reserved: the rows land at consecutive ascending rowids in the
    // order they were just sorted into, which is what makes the next scan read
    // them back in index order.
    for (new_rowid, (_, rowid, cur_key_xid, cur_xmin, cur_row)) in (start..).zip(locked.iter()) {
        apply_locked_row_delete(
            write_ctx,
            table,
            &local_indexes,
            &LockedRowDelete {
                rowid: *rowid,
                cur_key_xid: *cur_key_xid,
                cur_xmin: *cur_xmin,
                cur_row,
            },
            writes,
            ops,
        )?;
        ops.push(crabka_pgkv::WriteOp::Put {
            key: crabka_pgmvcc::version::version_key_xid(table.id, new_rowid, write_ctx.xid),
            value: encode_table_tuple(
                table,
                write_ctx.xid,
                crabka_pgmvcc::xid::INVALID_XID,
                cur_row,
            ),
        });
        ops.extend(local_index_entry_ops(
            table,
            &local_indexes,
            new_rowid,
            cur_row,
        )?);
    }
    Ok(())
}

/// Refuse to reorder a relation the open transaction still owes a deferred
/// referential check on, as `PostgreSQL` does (55006).
///
/// A deferred check identifies its row by rowid and re-derives the key from
/// whatever version that rowid holds at `COMMIT`. Reordering moves the row to a
/// different rowid and tombstones the old one, so the check would read no
/// version at all, conclude the row is gone, and pass — committing the
/// violation it existed to catch. `PostgreSQL` reaches the same conclusion from
/// its own direction and reports it as pending trigger events, which is what a
/// deferred check is there.
fn reject_cluster_with_pending_checks(
    write_ctx: &WriteContext<'_>,
    table: &Table,
) -> Result<(), ExecError> {
    let owed = write_ctx
        .deferred_fk
        .is_some_and(|slot| slot.lock().expect("deferred fk").touches_table(table.id));
    if owed {
        return Err(ExecError::ObjectInUse(format!(
            "cannot CLUSTER \"{}\" because it has pending trigger events",
            table.name.name
        )));
    }
    Ok(())
}

/// Whether `scanned` — which arrives in rowid order, so in the order an
/// unqualified scan reads the heap — is already in `index`'s order.
fn cluster_scan_is_ordered(
    table: &Table,
    index: &crabka_pgcatalog::Index,
    scanned: &[(u64, u64, Vec<Datum>)],
    ctx: &crate::clock::EvalCtx,
) -> Result<bool, ExecError> {
    let mut previous: Option<Vec<Datum>> = None;
    for (_, _, row) in scanned {
        let key = cluster_sort_key(table, index, row, ctx)?;
        if let Some(previous) = &previous
            && compare_cluster_key(previous, &key) == std::cmp::Ordering::Greater
        {
            return Ok(false);
        }
        previous = Some(key);
    }
    Ok(true)
}

/// The values one row sorts by under `index`.
///
/// An expression key is evaluated against the row the way a generated column's
/// expression is; a plain key is the stored column value.
fn cluster_sort_key(
    table: &Table,
    index: &crabka_pgcatalog::Index,
    row: &[Datum],
    ctx: &crate::clock::EvalCtx,
) -> Result<Vec<Datum>, ExecError> {
    let mut key = Vec::with_capacity(index.columns.len());
    for column in &index.columns {
        if let Some(source) = crabka_pgcatalog::index_key_expression(column) {
            let expr = crabka_pgparser::parser::parse_expression(source)?;
            let scope = Scope::single(table, &table.name.name);
            key.push(crate::eval::eval(&expr, &scope, row, ctx)?);
            continue;
        }
        let ordinal = table
            .column_index(column)
            .ok_or_else(|| ExecError::UndefinedColumn(column.clone()))?;
        key.push(row[ordinal].clone());
    }
    Ok(key)
}

/// Compare two index keys the way a btree orders them: ascending, NULLs last.
///
/// Gres's catalog records an index's key columns as names without a per-column
/// `ASC`/`DESC` or `NULLS` clause, so there is exactly one order an index can
/// have and it is `PostgreSQL`'s default one.
fn compare_cluster_key(a: &[Datum], b: &[Datum]) -> std::cmp::Ordering {
    use std::cmp::Ordering;
    for (x, y) in a.iter().zip(b.iter()) {
        let ord = match (x.is_null(), y.is_null()) {
            (true, true) => Ordering::Equal,
            (true, false) => Ordering::Greater,
            (false, true) => Ordering::Less,
            (false, false) => crabka_pgtypes::ops::compare(x, y)
                .ok()
                .flatten()
                .unwrap_or(Ordering::Equal),
        };
        if ord != Ordering::Equal {
            return ord;
        }
    }
    Ordering::Equal
}

/// The relation whose unique-index gate a DML statement must hold SHARED for
/// its duration (until COMMIT/ROLLBACK in an explicit transaction). Unique-index
/// DDL takes that relation's gate EXCLUSIVELY while it backfills. Same-key DML
/// conflicts serialize through per-key locks in the `RowLockManager` instead.
pub(crate) enum UniqueLocalSerialization {
    None,
    Shared(crabka_pgcatalog::TableId),
}

pub(crate) fn write_requires_unique_local_serialization(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    stmt: &Statement,
) -> Result<UniqueLocalSerialization, ExecError> {
    let table_name = match stmt {
        Statement::Insert { table, .. }
        | Statement::Update { table, .. }
        | Statement::Delete { table, .. }
        | Statement::Merge { table, .. } => table,
        // `CLUSTER` moves rows to new rowids and re-emits every local index
        // entry for them, which is exactly what a concurrent unique-index
        // backfill must not run alongside.
        Statement::Cluster(Some(target)) => &target.table,
        _ => return Ok(UniqueLocalSerialization::None),
    };
    let table_name = resolve_relation(
        catalog_kv,
        resolution,
        table_name,
        SchemaDisposition::Reference,
    )?;
    table_requires_unique_local_serialization(catalog_kv, &table_name)
}

pub(crate) fn copy_requires_unique_local_serialization(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    target: CopyIntoTarget<'_>,
) -> Result<UniqueLocalSerialization, ExecError> {
    table_requires_unique_local_serialization(
        catalog_kv,
        &resolve_relation(
            catalog_kv,
            resolution,
            target.name,
            SchemaDisposition::Utility,
        )?,
    )
}

/// The op recording a temporary namespace, when it is not recorded already.
///
/// The engine creates a temporary namespace on behalf of a session that first
/// puts something in it, never a statement that names it. `CREATE SCHEMA`
/// refuses every `pg_`-prefixed name, as `PostgreSQL` does.
fn ensure_schema_ops(kv: &dyn Kv, schema: &str) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    if crabka_pgcatalog::schema_exists(kv, schema)? {
        return Ok(Vec::new());
    }
    Ok(vec![crabka_pgcatalog::create_temp_schema_op(schema)])
}

/// The batch that removes every relation and user type `schema` holds, whatever
/// kind each is, together with everything outside the schema that depends on
/// one of them:
/// dropping a table here is [the same drop](drop_table_and_dependents_ops) a
/// `DROP TABLE … CASCADE` performs, so a foreign key or view in another schema
/// goes with its referent rather than outliving it, and a partition stored
/// elsewhere goes with its parent.
///
/// `DROP SCHEMA … CASCADE` is one caller; the others are the three points a
/// temporary namespace is emptied: `DISCARD TEMP`, the end of a session, and
/// the purge a session runs over its own namespace before it first uses it, in
/// case a crashed backend of the same id left rows behind.
///
/// # Errors
///
/// Returns storage/corruption errors from the catalog KV seam.
pub(crate) fn drop_schema_contents_ops(
    kv: &dyn Kv,
    schema: &str,
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    let contents = crabka_pgcatalog::schema_contents(kv, schema)?;
    // The partitions of a table in `schema` go with their parent even when they
    // live outside it, so they are part of the batch and have to be known before
    // any of it is emitted: a foreign key whose child is in that set neither
    // blocks the drop nor needs an op of its own.
    let mut partitions = HashSet::new();
    for relation in &contents {
        if crabka_pgcatalog::get_table(kv, relation).is_ok() {
            partitions.extend(crate::partition::descendants(kv, relation)?);
        }
    }
    let dropping: HashSet<_> = contents.iter().chain(partitions.iter()).cloned().collect();
    let mut ops = Vec::new();
    let mut handled: HashSet<crabka_pgcatalog::RelationName> = HashSet::new();
    // Parents first, striking off each partition they carry. Whatever still
    // stands afterwards is emitted on its own account — a partition whose parent
    // is in another schema, or a cycle in the partition metadata that leaves the
    // batch rootless — so no relation in the schema is left behind.
    for parents_first in [true, false] {
        for relation in &contents {
            if handled.contains(relation) || (parents_first && partitions.contains(relation)) {
                continue;
            }
            handled.insert(relation.clone());
            if crabka_pgcatalog::get_view(kv, relation).is_ok() {
                ops.extend(drop_view_with_triggers_ops(kv, relation)?);
            } else if let Ok(table) = crabka_pgcatalog::get_table(kv, relation) {
                handled.extend(crate::partition::descendants(kv, relation)?);
                ops.extend(drop_table_and_dependents_ops(kv, &table, &dropping, true)?);
            } else {
                ops.extend(crabka_pgcatalog::drop_sequence_ops(kv, relation)?);
            }
        }
    }
    ops.extend(crate::inheritance::drop_metadata_ops(kv, &dropping)?);
    ops.extend(crate::usertype::drop_schema_types_ops(kv, schema)?);
    Ok(ops)
}

/// The batch that drops one table with everything that depends on it: the stored
/// views over it, the foreign keys that reference it, and the partitions that
/// hang off it, wherever those live, because a dependency in another schema is
/// still a dependency.
///
/// `dropping` names the relations the same statement already removes. A
/// dependency inside that set neither blocks the drop nor needs an op of its own,
/// since it goes away with its own relation; that is what lets `DROP TABLE p, c`,
/// a mutually referencing pair, and `DROP SCHEMA … CASCADE` succeed.
///
/// Without `cascade` a dependency outside that set is a 2BP01 refusal. With it,
/// `PostgreSQL` splits the two kinds: a referencing *constraint* is dropped and
/// its child table survives, while a dependent view is dropped outright. A
/// partition is neither. It has no independent existence, so it goes with its
/// parent whether or not `CASCADE` was written.
///
/// Inheritance links are *not* settled here. A child's parent list has to be
/// rewritten against the whole statement's removal set rather than against one
/// name out of it, so [`crate::inheritance::drop_metadata_ops`] is called once,
/// by the caller, over every relation the statement takes away: its targets and
/// the partitions hanging off them. That function says what a per-relation
/// rewrite corrupted.
///
/// # Errors
///
/// Returns undefined-relation, dependent-object, and storage/corruption errors
/// from the catalog KV seam.
fn drop_table_and_dependents_ops(
    kv: &dyn Kv,
    table: &Table,
    dropping: &HashSet<crabka_pgcatalog::RelationName>,
    cascade: bool,
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    let name = &table.name;
    let table_ops = crabka_pgcatalog::drop_table_ops(kv, name)?;
    let mut ops = Vec::new();
    let dependents: Vec<_> = dependent_view_chain(kv, name, None)?
        .into_iter()
        .filter(|(view, _)| !dropping.contains(view))
        .collect();
    if !dependents.is_empty() {
        if !cascade {
            return Err(dependent_objects_error(
                kv,
                &format!(
                    "cannot drop {} {name} because other objects depend on it",
                    stored_relation_kind(table)
                ),
                &dependents,
            ));
        }
        for (view, _) in &dependents {
            ops.extend(drop_dependent_relation_ops(kv, view)?);
        }
    }
    ops.extend(drop_blocking_foreign_keys(kv, table, dropping, cascade)?);
    for descendant in crate::partition::descendants(kv, name)? {
        if let Ok(descendant_table) = crabka_pgcatalog::get_table(kv, &descendant) {
            ops.extend(crabka_pgcatalog::trigger::drop_triggers_for_table_ops(
                kv,
                descendant_table.id,
            )?);
        }
        ops.extend(crabka_pgcatalog::drop_table_ops(kv, &descendant)?);
        ops.extend(crate::partition::drop_metadata_ops(kv, &descendant)?);
        // Only the departing relation's own statistics go. A parent losing its
        // last child keeps its `relhassubclass` latch, which is the stale
        // window `ANALYZE` is what closes.
        ops.extend(crate::relstats::drop_metadata_ops(&descendant));
    }
    ops.extend(crate::partition::drop_metadata_ops(kv, name)?);
    ops.extend(crate::relstats::drop_metadata_ops(name));
    ops.extend(crabka_pgcatalog::trigger::drop_triggers_for_table_ops(
        kv, table.id,
    )?);
    ops.extend(table_ops);
    Ok(ops)
}

/// A materialized view seen as the [`crabka_pgcatalog::View`] the dependency
/// machinery understands, or `None` for any other stored relation.
///
/// The synthesized record is not stored and is never written back — it exists so
/// one walker can answer "what does this relation's query read" for both kinds.
fn materialized_as_view(table: crabka_pgcatalog::Table) -> Option<crabka_pgcatalog::View> {
    let matview = table.materialized?;
    Some(crabka_pgcatalog::View {
        name: table.name,
        definition: matview.definition,
        owner: table.owner,
        columns: table.columns,
        options: crabka_pgcatalog::ViewOptions::default(),
    })
}

/// Drop one relation that a `CASCADE` reached because its query reads the
/// relation being dropped.
///
/// A dependent is a view or a materialized view, and the two go away by
/// different batteries: a view is a catalog record, a materialized view is a
/// stored relation with a heap and indexes. Dispatching here rather than at each
/// call site is what keeps `DROP TABLE … CASCADE` and `DROP VIEW … CASCADE` from
/// each having to know.
fn drop_dependent_relation_ops(
    kv: &dyn Kv,
    name: &crabka_pgcatalog::RelationName,
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    if let Ok(table) = crabka_pgcatalog::get_table(kv, name)
        && table.materialized.is_some()
    {
        let mut ops = crabka_pgcatalog::trigger::drop_triggers_for_table_ops(kv, table.id)?;
        ops.extend(crabka_pgcatalog::drop_table_ops(kv, name)?);
        return Ok(ops);
    }
    drop_view_with_triggers_ops(kv, name)
}

fn drop_view_with_triggers_ops(
    kv: &dyn Kv,
    name: &crabka_pgcatalog::RelationName,
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    let view_id = crate::catalog_rel::view_oids(kv)?
        .get(name)
        .copied()
        .and_then(|oid| u32::try_from(oid).ok());
    let mut ops = crabka_pgcatalog::drop_view_ops(kv, name)?;
    if let Some(view_id) = view_id {
        ops.extend(crabka_pgcatalog::trigger::drop_triggers_for_table_ops(
            kv, view_id,
        )?);
    }
    Ok(ops)
}

/// How many table ids a DDL statement will allocate.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum TableIdDemand {
    /// The statement creates no relation of its own.
    None,
    /// The statement creates exactly this many relations.
    Fixed(usize),
    /// The count is not knowable before the statement runs.
    Unbounded,
}

/// True when `stmt` writes the `TEMPORARY` (or `TEMP`) keyword.
pub(crate) fn ddl_requests_temporary(stmt: &Statement) -> bool {
    matches!(
        stmt,
        Statement::CreateTable {
            temporary: true,
            ..
        } | Statement::CreateView {
            temporary: true,
            ..
        }
    )
}

/// The schema qualifier a relation-creating statement wrote, if it wrote one.
pub(crate) fn ddl_created_qualifier(stmt: &Statement) -> Option<&str> {
    let reference = match stmt {
        Statement::CreateTable { name, .. }
        | Statement::CreateForeignTable { name, .. }
        | Statement::CreateView { name, .. } => name,
        Statement::ImportForeignSchema { into_schema, .. } => return Some(into_schema),
        _ => return None,
    };
    reference.schema.as_deref()
}

/// The table ids `stmt` will allocate, so the session can claim them before it
/// takes the catalog lock.
pub(crate) fn ddl_table_id_demand(stmt: &Statement) -> TableIdDemand {
    match stmt {
        Statement::CreateTable { .. } | Statement::CreateForeignTable { .. } => {
            TableIdDemand::Fixed(1)
        }
        // One foreign table per table the scanner discovers, which is only known
        // once the remote schema has been read.
        Statement::ImportForeignSchema { .. } => TableIdDemand::Unbounded,
        _ => TableIdDemand::None,
    }
}

pub(crate) fn ddl_unique_local_relation(
    stmt: &Statement,
) -> Option<&crabka_pgparser::ast::RelationRef> {
    match stmt {
        Statement::CreateIndex {
            unique: true,
            placement: crabka_pgparser::ast::IndexPlacement::Local,
            table,
            ..
        }
        // ADD PRIMARY KEY / ADD UNIQUE back-validates and backfills a local
        // unique index, so it must wait out in-flight writers exactly like
        // CREATE UNIQUE INDEX does.
        => Some(table),
        Statement::AlterTable { table, actions, .. }
            if actions.iter().any(|action| {
                matches!(
                action,
                crabka_pgparser::ast::AlterTableAction::AddConstraint(
                    crabka_pgparser::ast::TableConstraint {
                        kind: crabka_pgparser::ast::TableConstraintKind::PrimaryKey { .. }
                            | crabka_pgparser::ast::TableConstraintKind::Unique { .. },
                        ..
                    }
                )
                )
            }) => Some(table),
        // A relation is not visible to DML until CREATE TABLE's catalog batch
        // lands, so its inline unique-index backfill has no concurrent writer.
        _ => None,
    }
}

/// The `NOTICE` a `CASCADE` drop owes for the objects it takes with it.
///
/// PostgreSQL reports one dropped dependent inline and several as a count plus
/// a `DETAIL` line each:
///
/// ```text
/// NOTICE:  drop cascades to view d_mid
///
/// NOTICE:  drop cascades to 3 other objects
/// DETAIL:  drop cascades to view m1
/// drop cascades to view m3
/// drop cascades to view m2
/// ```
///
/// Returns `(message, detail)`, empty when the statement drops nothing beyond
/// its target -- which includes every non-`CASCADE` drop, since one that would
/// cascade is refused before it reaches here.
pub(crate) fn cascade_drop_notice(
    kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    stmt: &Statement,
) -> Result<Option<(String, Option<String>)>, ExecError> {
    let reference = match stmt {
        Statement::DropTable {
            names,
            cascade: true,
            ..
        } => match names.as_slice() {
            // `DROP TABLE a, b` cascades over the whole list; reporting it
            // needs the union in PostgreSQL's order, which the single-name
            // form does not tell us. Left alone rather than reported wrongly.
            [only] => only,
            _ => return Ok(None),
        },
        Statement::DropView {
            name,
            cascade: true,
            ..
        } => name,
        Statement::DropMaterializedView {
            names,
            cascade: true,
            ..
        } => match names.as_slice() {
            [only] => only,
            _ => return Ok(None),
        },
        // `DROP SCHEMA … CASCADE` reports the schema's own contents as well as
        // whatever outside it goes with them, so it collects its objects rather
        // than walking out from one target.
        Statement::DropSchema {
            names,
            cascade: true,
            ..
        } => {
            let mut lines = Vec::new();
            for schema in names {
                lines.extend(schema_cascade_lines(kv, resolution, schema)?);
            }
            return Ok(cascade_notice(lines));
        }
        _ => return Ok(None),
    };
    let column = None;
    let Ok(name) = resolve_relation(kv, resolution, reference, SchemaDisposition::Reference) else {
        return Ok(None);
    };
    let lines = dependent_view_chain(kv, &name, column)?
        .iter()
        .map(|(view, _)| cascade_line(kv, resolution, view))
        .collect();
    Ok(cascade_notice(lines))
}

/// The most dependent objects a `CASCADE` names to the client before the rest
/// become a count. `PostgreSQL`'s `MAX_REPORTED_DEPS`, which exists because
/// "client software may not deal well with enormous error strings".
const MAX_REPORTED_DEPS: usize = 100;

/// Fold the per-object lines into the `(message, detail)` a `CASCADE` reports.
///
/// Three shapes, all `PostgreSQL`'s: nothing dropped says nothing; a single
/// object is named inline with no `DETAIL` at all; and several become a count
/// with one `DETAIL` line each. Past [`MAX_REPORTED_DEPS`] the surplus is
/// summarized on a final line and the count still names the *total*, so
/// dropping 102 objects reads `drop cascades to 102 other objects` above 100
/// lines and `and 2 other objects (see server log for list)`.
fn cascade_notice(mut lines: Vec<String>) -> Option<(String, Option<String>)> {
    let total = lines.len();
    match total {
        0 => None,
        1 => Some((lines.remove(0), None)),
        _ => {
            let withheld = total.saturating_sub(MAX_REPORTED_DEPS);
            lines.truncate(MAX_REPORTED_DEPS);
            let mut detail = lines.join("\n");
            if withheld > 0 {
                use std::fmt::Write as _;
                let plural = if withheld == 1 { "object" } else { "objects" };
                write!(
                    detail,
                    "\nand {withheld} other {plural} (see server log for list)"
                )
                .expect("writing to a String cannot fail");
            }
            Some((
                format!("drop cascades to {total} other objects"),
                Some(detail),
            ))
        }
    }
}

/// One `drop cascades to <kind> <name>` line for a relation.
fn cascade_line(
    kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    name: &crabka_pgcatalog::RelationName,
) -> String {
    format!(
        "drop cascades to {} {}",
        relation_kind(kv, name).unwrap_or("view"),
        message_relation_name(kv, resolution, name),
    )
}

/// A relation's name as a message writes it: bare when the search path makes it
/// visible, schema-qualified when it does not, and each part quoted where a
/// bare identifier would not read back as itself — `PostgreSQL`'s
/// `quote_qualified_identifier` over `RelationIsVisible`.
pub(crate) fn message_relation_name(
    kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    name: &crabka_pgcatalog::RelationName,
) -> String {
    let bare = crabka_pgparser::ast::RelationRef::bare(name.name.clone());
    let visible = resolve_relation(kv, resolution, &bare, SchemaDisposition::Reference)
        .is_ok_and(|resolved| resolved == *name);
    let printed = crate::catalog_fn::quote_identifier(&name.name);
    if visible {
        printed
    } else {
        format!(
            "{}.{printed}",
            crate::catalog_fn::quote_identifier(&name.schema)
        )
    }
}

/// Every object `DROP SCHEMA … CASCADE` takes with it, as the lines it reports.
///
/// `PostgreSQL` walks its dependency graph out from each of the schema's own
/// objects in the order `pg_depend` recorded them — creation order — reporting
/// everything that depends on one directly after it. This reproduces that shape
/// from what the catalog here keeps: a table records the monotonic id it was
/// created with, so the schema's tables lead in creation order, each followed
/// depth-first by the views and materialized views over it, wherever those
/// live. A view or sequence that no table in the schema feeds carries no
/// creation-order record at all, so those follow in name order — the one place
/// this diverges, and it diverges only in the order of the `DETAIL` lines,
/// never in which objects appear.
fn schema_cascade_lines(
    kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    schema: &str,
) -> Result<Vec<String>, ExecError> {
    if !crabka_pgcatalog::schema_exists(kv, schema)? {
        return Ok(Vec::new());
    }
    let contents = crabka_pgcatalog::schema_contents(kv, schema)?;
    let mut tables: Vec<(crabka_pgcatalog::TableId, crabka_pgcatalog::RelationName)> = Vec::new();
    let mut others: Vec<crabka_pgcatalog::RelationName> = Vec::new();
    for name in contents {
        match crabka_pgcatalog::get_table(kv, &name) {
            Ok(table) => tables.push((table.id, name)),
            Err(_) => others.push(name),
        }
    }
    tables.sort_by_key(|(id, _)| *id);
    let roots = tables
        .into_iter()
        .map(|(_, name)| name)
        .chain(others)
        .collect::<Vec<_>>();
    let mut seen: HashSet<crabka_pgcatalog::RelationName> = HashSet::new();
    let mut lines = Vec::new();
    for root in roots {
        if seen.insert(root.clone()) {
            lines.push(cascade_line(kv, resolution, &root));
        }
        for (dependent, _) in dependent_view_chain(kv, &root, None)? {
            if seen.insert(dependent.clone()) {
                lines.push(cascade_line(kv, resolution, &dependent));
            }
        }
    }
    // A composite, enum or domain type goes with its schema too, and every one
    // of the three is `type` in this message — `DROP SCHEMA` over a domain
    // reports `drop cascades to type s.d`, not `domain`.
    let types = crabka_pgcatalog::list_user_types(kv)?;
    let visible = resolution.visible_schemas(kv)?;
    for user_type in types.iter().filter(|ty| ty.schema == schema) {
        // Type visibility is its own question — the search path is the same,
        // but what shadows a type is another *type* of that name, not a
        // relation. A type is written bare when its schema is the first visible
        // one holding a type by that name.
        let shadowing = visible.iter().find(|candidate| {
            types
                .iter()
                .any(|other| other.name == user_type.name && other.schema == **candidate)
        });
        let printed = crate::catalog_fn::quote_identifier(&user_type.name);
        let name = if shadowing.is_some_and(|first| first == schema) {
            printed
        } else {
            format!(
                "{}.{printed}",
                crate::catalog_fn::quote_identifier(&user_type.schema)
            )
        };
        lines.push(format!("drop cascades to type {name}"));
    }
    Ok(lines)
}

pub(crate) fn inheritance_merge_notices(
    kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    stmt: &Statement,
) -> Result<Vec<String>, ExecError> {
    let Statement::CreateTable { inherits, .. } = stmt else {
        return Ok(Vec::new());
    };
    let mut seen = std::collections::HashSet::new();
    let mut notices = Vec::new();
    for parent in inherits {
        let name = resolve_relation(kv, resolution, parent, SchemaDisposition::Reference)?;
        // A parent this cannot read is not reported here. The notices are
        // cosmetic and this runs ahead of the definition, so raising the lookup
        // failure would hand back `relation does not exist` for a name the
        // definition refuses by kind — which is how `INHERITS (<view>)` came to
        // claim the view was absent.
        let Ok(table) = crabka_pgcatalog::get_table(kv, &name) else {
            continue;
        };
        for column in table.columns {
            if !seen.insert(column.name.clone()) && !notices.contains(&column.name) {
                notices.push(column.name);
            }
        }
    }
    Ok(notices)
}

fn table_requires_unique_local_serialization(
    catalog_kv: &dyn Kv,
    table_name: &crabka_pgcatalog::RelationName,
) -> Result<UniqueLocalSerialization, ExecError> {
    let table = match crabka_pgcatalog::get_table(catalog_kv, table_name) {
        Ok(table) => table,
        Err(crabka_pgcatalog::CatalogError::UndefinedTable(_))
            if crabka_pgcatalog::get_view(catalog_kv, table_name).is_ok() =>
        {
            return Ok(UniqueLocalSerialization::None);
        }
        Err(error) => return Err(error.into()),
    };
    if table.sharded {
        return Ok(UniqueLocalSerialization::None);
    }
    let indexes = crabka_pgcatalog::list_table_indexes(catalog_kv, table_name)?;
    for index in indexes {
        if index.unique && index.placement != crabka_pgcatalog::IndexPlacement::Local {
            return Err(ExecError::Unsupported(
                "unique global indexes are not supported until global enforcement exists".into(),
            ));
        }
    }
    Ok(UniqueLocalSerialization::Shared(table.id))
}

fn reject_unwritable_local_index(table: &Table) -> Result<(), ExecError> {
    if table.sharded {
        return Err(ExecError::Unsupported(
            "local index maintenance for sharded timestamp writes is blocked on G-6".into(),
        ));
    }
    Ok(())
}

fn local_index_backfill_ops(
    kv: &dyn Kv,
    table: &Table,
    index: &crabka_pgcatalog::Index,
    own_xid: Option<u64>,
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    let all_committed = all_committed_snapshot();
    // `own_xid` makes the open transaction's own uncommitted rows visible to the
    // back-validation; the all-committed snapshot alone does not, because the
    // scan still asks the commit log and this transaction is in progress there.
    let rows = scan_live(kv, kv, &all_committed, &all_committed, own_xid, table)?;
    local_index_backfill_ops_for_rows(&rows, table, index)
}

/// Backfill index entries for already-scanned live rows.
///
/// A UNIQUE index back-validates the existing data: a duplicate non-NULL key
/// fails the index *build* with 23505 before any op is committed. Rows with a
/// NULL key column are not indexed, which matches SQL NULL-distinct
/// semantics.
fn local_index_backfill_ops_for_rows(
    rows: &[(u64, u64, Vec<Datum>)],
    table: &Table,
    index: &crabka_pgcatalog::Index,
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    let mut seen = HashSet::new();
    let mut ops = Vec::with_capacity(rows.len());
    for (rowid, _xmin, row) in rows {
        for values in index_entries(table, index, row)? {
            if values.iter().any(Datum::is_null) {
                continue;
            }
            if index.unique && !seen.insert(values.clone()) {
                return Err(ExecError::UniqueIndexBuildViolation(index.name.clone()));
            }
            ops.push(crabka_pgkv::WriteOp::Put {
                key: crabka_pgkv::key::secondary_index_entry_key(
                    table.id, index.id, &values, *rowid,
                ),
                value: Vec::new(),
            });
        }
    }
    Ok(ops)
}

type PendingUniqueKey = (crabka_pgcatalog::IndexId, Vec<Datum>);

async fn enforce_unique_local_index_updates(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    indexes: &[crabka_pgcatalog::Index],
    rowid: u64,
    old_row: &[Datum],
    new_row: &[Datum],
    writes: &mut StatementWrites,
) -> Result<(), ExecError> {
    for index in indexes
        .iter()
        .filter(|index| index.unique && index.exclusion_operators().is_none())
    {
        let old_values = indexed_values(table, index, old_row)?;
        let new_values = indexed_values(table, index, new_row)?;
        if old_values == new_values {
            // The indexed key is untouched: no probe, and — crucially for
            // write throughput — no key lock (a PK-preserving UPDATE takes
            // only its row lock).
            continue;
        }
        enforce_unique_local_index(write_ctx, table, index, rowid, new_values, writes).await?;
    }
    for index in indexes
        .iter()
        .filter(|index| index.exclusion_operators().is_some())
    {
        let old_values = indexed_values(table, index, old_row)?;
        let new_values = indexed_values(table, index, new_row)?;
        if old_values != new_values {
            enforce_exclusion_constraint(write_ctx, table, index, rowid, new_values, writes)
                .await?;
        }
    }
    Ok(())
}

async fn enforce_unique_local_indexes(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    indexes: &[crabka_pgcatalog::Index],
    rowid: u64,
    row: &[Datum],
    writes: &mut StatementWrites,
) -> Result<(), ExecError> {
    for index in indexes
        .iter()
        .filter(|index| index.unique && index.exclusion_operators().is_none())
    {
        let values = indexed_values(table, index, row)?;
        enforce_unique_local_index(write_ctx, table, index, rowid, values, writes).await?;
    }
    for index in indexes
        .iter()
        .filter(|index| index.exclusion_operators().is_some())
    {
        let values = indexed_values(table, index, row)?;
        enforce_exclusion_constraint(write_ctx, table, index, rowid, values, writes).await?;
    }
    Ok(())
}

/// Refuse an empty range in the `WITHOUT OVERLAPS` column of a temporal key
/// (23514).
///
/// An empty range overlaps nothing, so every such row would pass the constraint
/// and the key would silently stop being a key. `PostgreSQL` checks this at
/// write time rather than as a `CHECK`, and only for `WITHOUT OVERLAPS` — a
/// hand-written `EXCLUDE … WITH &&` happily stores empty ranges.
fn reject_empty_without_overlaps(
    table: &Table,
    index: &crabka_pgcatalog::Index,
    values: &[Datum],
) -> Result<(), ExecError> {
    if !index.without_overlaps {
        return Ok(());
    }
    let (Some(column), Some(value)) = (index.columns.last(), values.last()) else {
        return Ok(());
    };
    let empty = match value {
        Datum::Range(range) => range.empty,
        Datum::Multirange(multirange) => multirange.ranges.is_empty(),
        _ => false,
    };
    if empty {
        return Err(ExecError::EmptyWithoutOverlapsValue {
            column: column.clone(),
            relation: table.name.name.clone(),
        });
    }
    Ok(())
}

async fn enforce_exclusion_constraint(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    index: &crabka_pgcatalog::Index,
    rowid: u64,
    values: Vec<Datum>,
    writes: &mut StatementWrites,
) -> Result<(), ExecError> {
    reject_empty_without_overlaps(table, index, &values)?;
    // Boxed: this scan's future is large, and the enclosing write path is
    // itself reached recursively (a set-returning function calling a query
    // calling a write), so inlining it here would grow every frame of that
    // recursion.
    let Some(holder) = Box::pin(exclusion_conflict(
        write_ctx,
        table,
        index,
        Some(rowid),
        &values,
        writes,
    ))
    .await?
    else {
        if index.exclusion_operators().is_some() && !values.iter().any(Datum::is_null) {
            writes
                .pending_exclusion_keys
                .entry(index.id)
                .or_default()
                .push((rowid, values));
        }
        return Ok(());
    };
    Err(exclusion_violation(
        write_ctx, table, index, &values, &holder,
    ))
}

/// The key of a live row this one cannot coexist with under `index`, or `None`
/// when it is free to be stored.
///
/// Shared by enforcement and by `ON CONFLICT` arbitration, which need the same
/// answer and differ only in what they do with it: a violation, or a skipped
/// row. `self_rowid` is the row being written, excluded from its own check;
/// arbitration passes `None` because the proposed row has no version yet.
///
/// A NULL anywhere in the key cannot conflict — `PostgreSQL`'s exclusion
/// operators are strict, so a NULL comparison is unknown, not true.
async fn exclusion_conflict(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    index: &crabka_pgcatalog::Index,
    self_rowid: Option<u64>,
    values: &[Datum],
    writes: &StatementWrites,
) -> Result<Option<Vec<Datum>>, ExecError> {
    let Some(operators) = index.exclusion_operators() else {
        return Ok(None);
    };
    if values.iter().any(Datum::is_null) {
        return Ok(None);
    }
    // ponytail: This deliberately serializes per constraint. A spatial lock
    // structure can replace it when GiST indexes become physical rather than
    // catalog-only; correctness needs only this one coarse key today.
    write_ctx
        .lockmgr
        .acquire_key_as(
            crate::lockmgr::LockKey::UniqueKey(crabka_pgkv::key::secondary_index_entry_prefix(
                table.id,
                index.id,
                &[],
            )),
            crate::lockmgr::LockMode::Exclusive,
            write_ctx.lock_owner,
            write_ctx.lock_wait_cap,
        )
        .await
        .map_err(lock_acquire_error)?;

    let current_visibility = all_committed_snapshot();
    let rows = scan_live(
        write_ctx.kv,
        write_ctx.global,
        &current_visibility,
        &current_visibility,
        Some(write_ctx.xid),
        table,
    )?;
    for (holder_rowid, _xmin, holder_row) in rows {
        if Some(holder_rowid) == self_rowid || !writes.holder_still_holds(index.id, holder_rowid) {
            continue;
        }
        let holder = indexed_values(table, index, &holder_row)?;
        if exclusion_keys_conflict(&operators, values, &holder)? {
            return Ok(Some(holder));
        }
    }
    if let Some(pending) = writes.pending_exclusion_keys.get(&index.id) {
        for (holder_rowid, holder) in pending {
            if Some(*holder_rowid) != self_rowid
                && exclusion_keys_conflict(&operators, values, holder)?
            {
                return Ok(Some(holder.clone()));
            }
        }
    }
    Ok(None)
}

fn exclusion_keys_conflict(
    operators: &[crabka_pgcatalog::ExclusionOperator],
    left: &[Datum],
    right: &[Datum],
) -> Result<bool, ExecError> {
    for ((operator, left), right) in operators.iter().zip(left).zip(right) {
        if left.is_null() || right.is_null() {
            return Ok(false);
        }
        let conflicts = match operator {
            crabka_pgcatalog::ExclusionOperator::Equal => {
                crabka_pgtypes::ops::compare(left, right)? == Some(std::cmp::Ordering::Equal)
            }
            crabka_pgcatalog::ExclusionOperator::Overlaps => match (left, right) {
                (Datum::Range(left), Datum::Range(right)) => {
                    crabka_pgtypes::range::overlaps(left, right)?
                }
                (Datum::Multirange(left), Datum::Multirange(right)) => {
                    crabka_pgtypes::multirange::overlaps(left, right)?
                }
                (Datum::Multirange(left), Datum::Range(right)) => {
                    crabka_pgtypes::multirange::overlaps_range(left, right)?
                }
                (Datum::Range(left), Datum::Multirange(right)) => {
                    crabka_pgtypes::multirange::overlaps_range(right, left)?
                }
                _ => return Err(ExecError::UndefinedFunction("operator &&".into())),
            },
        };
        if !conflicts {
            return Ok(false);
        }
    }
    Ok(true)
}

fn exclusion_violation(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    index: &crabka_pgcatalog::Index,
    proposed: &[Datum],
    existing: &[Datum],
) -> ExecError {
    let columns = index.columns.join(", ");
    let render = |values: &[Datum]| {
        values
            .iter()
            .map(|value| {
                String::from_utf8_lossy(&crabka_pgtypes::encoding::encode_text_in(
                    value,
                    write_ctx.eval_ctx.output_style(),
                ))
                .into_owned()
            })
            .collect::<Vec<_>>()
            .join(", ")
    };
    ExecError::Remote(
        crabka_pgwire::error::PgError::error(
            "23P01",
            format!(
                "conflicting key value violates exclusion constraint \"{}\"",
                index.name
            ),
        )
        .with_detail(format!(
            "Key ({columns})=({}) conflicts with existing key ({columns})=({}).",
            render(proposed),
            render(existing)
        ))
        .with_schema(table.name.schema.clone())
        .with_table(table.name.name.clone())
        .with_constraint(index.name.clone()),
    )
}

async fn enforce_unique_local_index(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    index: &crabka_pgcatalog::Index,
    rowid: u64,
    values: Vec<Datum>,
    writes: &mut StatementWrites,
) -> Result<(), ExecError> {
    if values.iter().any(Datum::is_null) {
        // SQL unique ignores NULLs: nothing to enforce, so no key lock either.
        return Ok(());
    }
    // The claim spans the whole statement, so a `WITH` item and the body cannot
    // both write the same key.
    let pending_key = (index.id, values.clone());
    if !writes.pending_unique_keys.insert(pending_key) {
        return Err(ExecError::UniqueViolation(index.name.clone()));
    }
    let holders = lock_and_probe_unique_key(write_ctx, table, index, &values).await?;
    // A holder whose key an earlier part of this statement freed is a version
    // this command has already superseded: PostgreSQL's uniqueness check does
    // not see it either.
    if holders
        .iter()
        .any(|holder| holder.rowid != rowid && writes.holder_still_holds(index.id, holder.rowid))
    {
        return Err(ExecError::UniqueViolation(index.name.clone()));
    }
    Ok(())
}

/// Take `values`' unique-key lock and return the rows that currently hold that
/// key.
///
/// This is the lock-and-probe half of unique enforcement, shared with
/// `ON CONFLICT` arbitration.
///
/// Serializes check-then-write PER KEY: takes this key's exclusive lock (in the
/// row-lock manager, so it shares the deadlock wait-for graph and is released
/// with the row locks at COMMIT/ROLLBACK) before probing. Without it, two
/// concurrent writers of the same key would both pass the probe, because
/// neither sees the other's uncommitted version, and both would commit. A
/// waiter that wakes here
/// after the holder's terminal outcome probes the then-current committed state:
/// a holder if it committed, none if it rolled back.
///
/// The probe reads exactly this key instead of scanning the whole table, under
/// the scan path's visibility (all-committed local + global snapshots plus our
/// own xid), and `lookup_local_index_equal` resolves each candidate rowid
/// through MVCC and re-checks its visible row's values. So dead entries left by
/// old versions or aborted writers never count.
///
/// `acquire_key` is idempotent for a holder xid, so a caller that already locked
/// this key (arbitration, before the insert path re-enforces uniqueness) can
/// call again without self-deadlocking.
async fn lock_and_probe_unique_key(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    index: &crabka_pgcatalog::Index,
    values: &[Datum],
) -> Result<Vec<ScannedRow>, ExecError> {
    write_ctx
        .lockmgr
        .acquire_key_as(
            crate::lockmgr::LockKey::UniqueKey(crabka_pgkv::key::secondary_index_entry_prefix(
                table.id, index.id, values,
            )),
            crate::lockmgr::LockMode::Exclusive,
            write_ctx.lock_owner,
            write_ctx.lock_wait_cap,
        )
        .await
        .map_err(lock_acquire_error)?;
    let mvcc = write_ctx.mvcc_read();
    let current_visibility = all_committed_snapshot();
    let probe = MvccReadContext {
        kv: mvcc.kv,
        global: mvcc.global,
        global_snapshot: &current_visibility,
        snapshot: &current_visibility,
        own: mvcc.own,
    };
    lookup_local_index_equal(&probe, table, index, values)
}

/// The unique local indexes that arbitrate an `ON CONFLICT` clause, resolved
/// once per statement (before the row loop) from the clause's conflict target.
///
/// - `Columns` matches every unique local index whose column SET equals the
///   inference set. PostgreSQL's inference is order-insensitive even though an
///   index's columns are ordered, so `ON CONFLICT (b, a)` arbitrates a
///   `UNIQUE (a, b)` index. No match is 42P10.
/// - `Columns` with an index predicate (`ON CONFLICT (c) WHERE …`) is refused
///   (0A000): partial indexes do not exist here, so nothing could ever match it.
/// - `OnConstraint` matches by index name, restricted to indexes that back a
///   constraint, because PostgreSQL rejects `ON CONSTRAINT` naming a plain
///   index.
///   No match is 42704.
/// - `None` (reachable only with `DO NOTHING`; the parser rejects a bare
///   `DO UPDATE`) arbitrates every unique local index. An empty result is legal:
///   a table with no unique index simply never conflicts.
///
/// Global unique indexes never reach here, because `writable_local_indexes`
/// refuses them for every write on the table.
fn resolve_arbiter_indexes(
    table: &Table,
    local_indexes: &[crabka_pgcatalog::Index],
    target: &crabka_pgparser::ast::OnConflictTarget,
) -> Result<Vec<crabka_pgcatalog::Index>, ExecError> {
    use crabka_pgparser::ast::OnConflictTarget;

    // Inference by column list arbitrates on equality alone, so an
    // exclusion-enforced index can never satisfy it — `ON CONFLICT (id,
    // valid_at)` against a `WITHOUT OVERLAPS` key is 42P10 in PostgreSQL, not a
    // match. A bare `DO NOTHING` names no columns and does catch them.
    let equality = || {
        local_indexes
            .iter()
            .filter(|index| index.unique && index.exclusion_operators().is_none())
    };
    let arbitrable = || {
        local_indexes
            .iter()
            .filter(|index| index.unique || index.exclusion_operators().is_some())
    };
    match target {
        OnConflictTarget::None => Ok(arbitrable().cloned().collect()),
        OnConflictTarget::Columns {
            index_predicate: Some(_),
            ..
        } => Err(ExecError::Unsupported(
            "ON CONFLICT inference predicates are not supported".into(),
        )),
        OnConflictTarget::Columns {
            columns,
            index_predicate: None,
        } => {
            for column in columns {
                if table.column_index(column).is_none() {
                    return Err(ExecError::UndefinedColumn(column.clone()));
                }
            }
            let wanted: BTreeSet<&str> = columns.iter().map(String::as_str).collect();
            let arbiters: Vec<_> = equality()
                .filter(|index| {
                    index
                        .columns
                        .iter()
                        .map(String::as_str)
                        .collect::<BTreeSet<_>>()
                        == wanted
                })
                .cloned()
                .collect();
            if arbiters.is_empty() {
                return Err(ExecError::OnConflictNoArbiter);
            }
            Ok(arbiters)
        }
        OnConflictTarget::OnConstraint(name) => local_indexes
            .iter()
            .find(|index| index.constraint.is_some() && index.name == *name)
            .map(|index| vec![index.clone()])
            .ok_or_else(|| ExecError::UndefinedConstraint {
                name: name.clone(),
                table: table.name.to_string(),
            }),
    }
}

/// What one `VALUES` row of an `INSERT … ON CONFLICT` should do, decided by
/// [`arbitrate_insert_row`].
enum InsertRowPlan {
    /// No arbiter conflicts: insert the proposed row through the normal path.
    Insert,
    /// `DO NOTHING` on a conflict: the row is skipped entirely. There are no
    /// ops, no RETURNING row, and it does not count towards the command tag.
    Skip,
    /// `DO UPDATE` on a conflict: the stored row to update, already locked and
    /// re-read under [`eval_plan_qual`].
    Update {
        rowid: u64,
        cur_key_xid: u64,
        cur_xmin: u64,
        cur_row: Vec<Datum>,
    },
}

/// Decide what an `INSERT … ON CONFLICT` does with one proposed row.
///
/// Probes the arbiter indexes in catalog order (`list_table_indexes` sorts by
/// name, so the choice of conflicting index is deterministic) and stops at the
/// first conflict. An arbiter whose key holds a NULL cannot conflict, because
/// SQL unique treats NULLs as distinct. That matches the enforcement path's own
/// short-circuit.
///
/// A key already claimed by an earlier row of THIS statement lives only in the
/// pending op batch, invisible to a KV probe, so it is checked separately:
/// `DO NOTHING` skips the row and `DO UPDATE` raises 21000. That reproduces
/// PostgreSQL's `INSERT … VALUES (1), (1)` semantics exactly.
///
/// Termination: the outer loop restarts only after adding a holder rowid to
/// `discarded` (its row vanished under the lock, or no longer carries the
/// arbiter key). Every probed key is held under an exclusive key lock for the
/// rest of the transaction, so the holder sets can only shrink and no new
/// holder can appear. `discarded` grows strictly on each restart, bounded by
/// the rows already in the table.
async fn arbitrate_insert_row(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    arbiters: &[crabka_pgcatalog::Index],
    on_conflict: &crabka_pgparser::ast::OnConflict,
    proposed: &[Datum],
    writes: &StatementWrites,
) -> Result<InsertRowPlan, ExecError> {
    use crabka_pgparser::ast::OnConflictAction;

    let do_update = matches!(on_conflict.action, OnConflictAction::DoUpdate { .. });
    // An exclusion-enforced arbiter has no single conflicting row to update:
    // the proposed row may overlap several at once. PostgreSQL refuses the
    // combination outright, before it looks at any data.
    if do_update
        && arbiters
            .iter()
            .any(|index| index.exclusion_operators().is_some())
    {
        return Err(ExecError::Unsupported(
            "ON CONFLICT DO UPDATE not supported with exclusion constraints".into(),
        ));
    }
    let mut discarded: HashSet<u64> = HashSet::new();
    'arbitration: loop {
        for index in arbiters {
            let values = indexed_values(table, index, proposed)?;
            if values.iter().any(Datum::is_null) {
                continue;
            }
            // An overlap conflict is not a key collision, so it is found by the
            // same scan enforcement uses rather than by a key probe. Only
            // `DO NOTHING` reaches here — `DO UPDATE` was refused above.
            if index.exclusion_operators().is_some() {
                if Box::pin(exclusion_conflict(
                    write_ctx, table, index, None, &values, writes,
                ))
                .await?
                .is_some()
                {
                    return Ok(InsertRowPlan::Skip);
                }
                continue;
            }
            if writes
                .pending_unique_keys
                .contains(&(index.id, values.clone()))
            {
                if do_update {
                    return Err(ExecError::OnConflictAffectsRowTwice);
                }
                return Ok(InsertRowPlan::Skip);
            }
            let holders = lock_and_probe_unique_key(write_ctx, table, index, &values).await?;
            // The proposed row has no version of its own yet, so every visible
            // holder is a genuine conflict.
            // A holder whose key an earlier part of this statement freed no
            // longer conflicts: that version has already been superseded.
            let Some(holder) = holders.into_iter().find(|holder| {
                !discarded.contains(&holder.rowid)
                    && writes.holder_still_holds(index.id, holder.rowid)
            }) else {
                continue;
            };
            if !do_update {
                return Ok(InsertRowPlan::Skip);
            }
            if writes.is_claimed(table.id, holder.rowid) {
                return Err(ExecError::OnConflictAffectsRowTwice);
            }
            // The probe deliberately reads all-committed visibility, so it finds
            // rows committed after our snapshot. `eval_plan_qual`'s own 40001
            // check keys off xmax stamps and would not catch a freshly inserted
            // row that our snapshot cannot see, so REPEATABLE READ needs this
            // explicit guard — without it the upsert would silently update a row
            // it cannot read.
            if write_ctx.repeatable_read
                && holder.xmin != write_ctx.xid
                && !snapshot_can_see(write_ctx.snapshot, holder.xmin)
            {
                return Err(ExecError::SerializationFailure);
            }
            // Key lock first, then row lock — the established order everywhere
            // on the write path, so upserts add no new deadlock shapes.
            write_ctx
                .lockmgr
                .acquire_as(
                    table.id,
                    holder.rowid,
                    crate::lockmgr::LockMode::Exclusive,
                    write_ctx.lock_owner,
                    write_ctx.lock_wait_cap,
                )
                .await
                .map_err(lock_acquire_error)?;
            // READ COMMITTED: the probe reads all-committed visibility, so a
            // holder committed while we waited on the key lock is real but
            // invisible to our statement snapshot. `eval_plan_qual`'s own
            // read-committed refresh only fires on an `xmax` stamp, and a
            // concurrent INSERT leaves none — so re-read such a holder under a
            // fresh snapshot. Discarding it instead would fall through to the
            // insert path and raise 23505, breaking PostgreSQL's guarantee that
            // ON CONFLICT DO UPDATE yields an atomic insert-or-update outcome
            // even under high concurrency.
            let refreshed;
            let mutation = if !write_ctx.repeatable_read
                && holder.xmin != write_ctx.xid
                && !snapshot_can_see(write_ctx.snapshot, holder.xmin)
            {
                refreshed = write_ctx.procarray.snapshot();
                MutationContext {
                    snapshot: &refreshed,
                    ..write_ctx.mutation()
                }
            } else {
                write_ctx.mutation()
            };
            let Some((cur_key_xid, cur_xmin, cur_row)) =
                eval_plan_qual(&mutation, table, holder.rowid)?
            else {
                // Concurrently deleted: re-arbitrate without it.
                discarded.insert(holder.rowid);
                continue 'arbitration;
            };
            if indexed_values(table, index, &cur_row)? != values {
                // The row under the lock no longer carries the arbiter key.
                discarded.insert(holder.rowid);
                continue 'arbitration;
            }
            return Ok(InsertRowPlan::Update {
                rowid: holder.rowid,
                cur_key_xid,
                cur_xmin,
                cur_row,
            });
        }
        return Ok(InsertRowPlan::Insert);
    }
}

/// One locked row's in-place replacement: the version this write operates on
/// (`cur_key_xid`/`cur_xmin`/`cur_row`, as returned by [`eval_plan_qual`]) and
/// the post-image to store.
struct LockedRowUpdate<'a> {
    rowid: u64,
    cur_key_xid: u64,
    cur_xmin: u64,
    cur_row: &'a [Datum],
    next: &'a [Datum],
}

/// Stage the writes that replace a locked row with `next`.
///
/// Those are NOT NULL and unique enforcement, the referential checks the new
/// image owes, the MVCC version ops, index entries, and opportunistic chain
/// pruning. `UPDATE`, `MERGE`'s update action and `INSERT … ON CONFLICT DO
/// UPDATE` share this. Their stored-row mutation is identical once the row is
/// locked and the post-image computed, so all three reach the foreign-key hook
/// through this one site.
///
/// `fk` is the statement's resolved foreign-key context. A referential action
/// that re-enters here passes an empty one, because the drain derives the
/// follow-on checks a cascaded update owes from the row it hands back.
async fn apply_locked_row_update(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    local_indexes: &[crabka_pgcatalog::Index],
    fk: &crate::fk::StatementFkContext,
    update: &LockedRowUpdate<'_>,
    writes: &mut StatementWrites,
    ops: &mut Vec<crabka_pgkv::WriteOp>,
) -> Result<(), ExecError> {
    let LockedRowUpdate {
        rowid,
        cur_key_xid,
        cur_xmin,
        cur_row,
        next,
    } = *update;
    enforce_not_null(table, next)?;
    enforce_unique_local_index_updates(
        write_ctx,
        table,
        local_indexes,
        rowid,
        cur_row,
        next,
        writes,
    )
    .await?;
    // Append only — the probe needs the KV and the lock manager, and it must not
    // run until the statement's rows exist. A side whose key is unchanged queues
    // nothing, which is what keeps a non-key update of a hot parent row off the
    // key lock entirely.
    if !fk.is_empty() {
        writes.fk_checks.after_update(fk, rowid, cur_row, next)?;
    }
    // Whatever keys the superseded version held and this one does not are free
    // for a later part of the same statement to claim.
    writes.release_row_keys(table, local_indexes, rowid, cur_row, Some(next))?;
    let xid = write_ctx.xid;
    if cur_xmin == xid {
        // Updating my own uncommitted version: overwrite in place
        // (last-write-wins within the txn; no new tuple, xmax stays
        // invalid). PostgreSQL uses cmin/cmax here; we have no command
        // ids, so in-place replacement is the faithful observable result.
        ops.push(crabka_pgkv::WriteOp::Put {
            key: crabka_pgmvcc::version::version_key_xid(table.id, rowid, xid),
            value: encode_table_tuple(table, xid, crabka_pgmvcc::xid::INVALID_XID, next),
        });
    } else {
        // Supersede a committed version: stamp its xmax, write a new
        // tuple. The stamp targets the version's PHYSICAL key
        // (`cur_key_xid`) — for a frozen tuple the header xmin
        // (`FROZEN_XID`) no longer names its key.
        ops.push(crabka_pgkv::WriteOp::Put {
            key: crabka_pgmvcc::version::version_key_xid(table.id, rowid, cur_key_xid),
            value: encode_table_tuple(table, cur_xmin, xid, cur_row),
        });
        ops.push(crabka_pgkv::WriteOp::Put {
            key: crabka_pgmvcc::version::version_key_xid(table.id, rowid, xid),
            value: encode_table_tuple(table, xid, crabka_pgmvcc::xid::INVALID_XID, next),
        });
    }
    ops.extend(local_index_entry_ops(table, local_indexes, rowid, next)?);
    // Opportunistic per-rowid chain pruning (local engines only):
    // we hold this row's exclusive lock and just re-read its chain,
    // so reclaim its dead versions in the same commit batch. The
    // versions this statement writes (`cur_xmin`, `xid`) are never
    // pruned, and `next`'s indexed values count as survivors.
    if let Some(horizon) = write_ctx.prune_horizon {
        ops.extend(
            prune_rowid_chain_ops(
                write_ctx.kv,
                table,
                local_indexes,
                &ChainPruneRequest {
                    rowid,
                    horizon,
                    keep_xids: &[cur_key_xid, xid],
                    new_row: Some(next),
                    freeze_below: None,
                },
            )?
            .ops,
        );
    }
    Ok(())
}

/// One locked row's tombstone: the version this delete operates on, exactly as
/// [`eval_plan_qual`] returned it.
struct LockedRowDelete<'a> {
    rowid: u64,
    cur_key_xid: u64,
    cur_xmin: u64,
    cur_row: &'a [Datum],
}

/// Stage the writes that delete a locked row.
///
/// Those are the unique keys it frees, the MVCC tombstone, and opportunistic
/// chain pruning. `DELETE` and a cascaded `ON DELETE CASCADE` share this. Their
/// stored-row mutation is identical once the row is locked and re-read.
///
/// Queues no referential check of its own: the caller knows whether this delete
/// is the statement's (which queues through [`crate::fk::FkCheckQueue`]) or a
/// referential action's (whose follow-on checks the drain derives itself).
fn apply_locked_row_delete(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    local_indexes: &[crabka_pgcatalog::Index],
    delete: &LockedRowDelete<'_>,
    writes: &mut StatementWrites,
    ops: &mut Vec<crabka_pgkv::WriteOp>,
) -> Result<(), ExecError> {
    let LockedRowDelete {
        rowid,
        cur_key_xid,
        cur_xmin,
        cur_row,
    } = *delete;
    let xid = write_ctx.xid;
    // The row's unique keys are free for a later part of this statement to
    // claim, even though its superseded version is still in the KV for the probe
    // to find.
    writes.release_row_keys(table, local_indexes, rowid, cur_row, None)?;
    if cur_xmin == xid {
        // Deleting my own uncommitted version: PostgreSQL stamps xmax=xid so it
        // is invisible to me. version_key is the same key; overwrite it with
        // xmax set.
        ops.push(crabka_pgkv::WriteOp::Put {
            key: crabka_pgmvcc::version::version_key_xid(table.id, rowid, xid),
            value: encode_table_tuple(table, xid, xid, cur_row),
        });
    } else {
        // Set xmax = my xid on the matched version (keep its row bytes),
        // targeting its PHYSICAL key — see `apply_locked_row_update`.
        ops.push(crabka_pgkv::WriteOp::Put {
            key: crabka_pgmvcc::version::version_key_xid(table.id, rowid, cur_key_xid),
            value: encode_table_tuple(table, cur_xmin, xid, cur_row),
        });
    }
    // Opportunistic per-rowid chain pruning (local engines only). The tombstoned
    // current version survives (its xmax is our in-progress xid), so its index
    // entries stay; an engine-level `vacuum` reclaims the chain once the delete
    // commits below a future horizon.
    if let Some(horizon) = write_ctx.prune_horizon {
        ops.extend(
            prune_rowid_chain_ops(
                write_ctx.kv,
                table,
                local_indexes,
                &ChainPruneRequest {
                    rowid,
                    horizon,
                    keep_xids: &[cur_key_xid, xid],
                    new_row: None,
                    freeze_below: None,
                },
            )?
            .ops,
        );
    }
    Ok(())
}

/// One `ON CONFLICT DO UPDATE` application: the clause's assignments and filter,
/// the locked stored row they run against, and the proposed row bound as
/// `excluded`.
struct ConflictUpdate<'a> {
    assignments: &'a [(String, Expr)],
    filter: Option<&'a Expr>,
    rowid: u64,
    cur_key_xid: u64,
    cur_xmin: u64,
    cur_row: &'a [Datum],
    proposed: &'a [Datum],
}

/// Run `DO UPDATE`'s filter and assignments against a locked conflicting row and
/// stage the resulting update. Returns the post-image (for RETURNING), or `None`
/// when the `WHERE` is not true. That row is then neither inserted nor updated
/// and produces no RETURNING row, though its row and key locks stay held, as
/// PostgreSQL's do.
///
/// Both the filter and the assignment right-hand sides evaluate against
/// [`Scope::insert_conflict`] over the stored row concatenated with the proposed
/// row, so `excluded.c` reads the proposed value and `t.c` the stored one. Every
/// column name appears under both qualifiers, which makes a bare reference
/// ambiguous (42702). That is PostgreSQL's behavior, where `DO UPDATE SET
/// v = v + 1` is an error and must be written `t.v` or `excluded.v`.
async fn apply_insert_conflict_update(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    local_indexes: &[crabka_pgcatalog::Index],
    fk: &crate::fk::StatementFkContext,
    update: &ConflictUpdate<'_>,
    writes: &mut StatementWrites,
    ops: &mut Vec<crabka_pgkv::WriteOp>,
) -> Result<Option<Vec<Datum>>, ExecError> {
    let ctx = write_ctx.eval_ctx;
    // `ON CONFLICT DO UPDATE` reaches its row through the arbiter index probe,
    // not through `write_candidate_rows`, so it has no share of the structural
    // USING gate or of the privilege test that sits beside it, and needs both
    // named here. `SELECT` on top of the `INSERT` and `UPDATE` the surrounding
    // insert path already demanded, because this arm hands the *stored* row to
    // the `DO UPDATE SET` expressions and to `RETURNING`, which is a read of it.
    crate::privilege::require(
        &write_ctx.privileges(),
        &table.name,
        &table.owner,
        crate::privilege::RelationKind::Table,
        crate::privilege::Privilege::Select,
    )?;
    // PostgreSQL raises rather than skipping: quietly declining to update a row
    // the caller has just been told exists would itself disclose the row's
    // existence, and the caller would see neither an insert nor an update.
    crate::rls::RowSecurityCheck::compile(
        &write_ctx.rls(),
        table,
        crabka_pgcatalog::policy::PolicyCommand::Update,
        crate::rls::CheckSubject::TargetRow,
    )?
    .permit_row(table, update.cur_row, ctx)?;
    let scope = Scope::insert_conflict(table);
    let mut bindings = update.cur_row.to_vec();
    bindings.extend_from_slice(update.proposed);
    if !row_matches(update.filter, &scope, &bindings, ctx)? {
        return Ok(None);
    }
    let mut next = update.cur_row.to_vec();
    for (column, expr) in update.assignments {
        // Assignment targets are unqualified column names of the target table,
        // resolved exactly as the UPDATE arm resolves its own (42703 on miss).
        let idx = table
            .column_index(column)
            .ok_or_else(|| ExecError::UndefinedColumn(column.clone()))?;
        let value = eval_assignment_value(expr, table.columns[idx].ty, &scope, &bindings, ctx)?;
        next[idx] = coerce(value, table.columns[idx].ty, ctx)?;
    }
    let updated_columns = update
        .assignments
        .iter()
        .map(|(column, _)| column.clone())
        .collect::<Vec<_>>();
    let Some(next) = crate::trigger::fire_before_row(
        write_ctx.catalog_kv,
        crate::trigger::WriteTarget {
            table,
            check: &write_ctx.row_check(
                table,
                crabka_pgcatalog::policy::PolicyCommand::Update,
                &updated_columns,
            )?,
        },
        crate::trigger::DmlEvent::Update,
        &updated_columns,
        Some(update.cur_row),
        Some(next),
        ctx,
    )?
    else {
        return Ok(None);
    };
    apply_locked_row_update(
        write_ctx,
        table,
        local_indexes,
        fk,
        &LockedRowUpdate {
            rowid: update.rowid,
            cur_key_xid: update.cur_key_xid,
            cur_xmin: update.cur_xmin,
            cur_row: update.cur_row,
            next: &next,
        },
        writes,
        ops,
    )
    .await?;
    crate::trigger::fire_after_row(
        write_ctx.catalog_kv,
        table,
        crate::trigger::DmlEvent::Update,
        &updated_columns,
        Some(update.cur_row),
        Some(&next),
        ctx,
    )?;
    Ok(Some(next))
}

fn all_committed_snapshot() -> crabka_pgmvcc::visibility::Snapshot {
    crabka_pgmvcc::visibility::Snapshot {
        xmin: 0,
        xmax: u64::MAX,
        xip: Vec::new(),
    }
}

fn local_index_entry_ops(
    table: &Table,
    indexes: &[crabka_pgcatalog::Index],
    rowid: u64,
    row: &[Datum],
) -> Result<Vec<crabka_pgkv::WriteOp>, ExecError> {
    let mut ops = Vec::new();
    for index in indexes {
        for values in index_entries(table, index, row)? {
            ops.push(crabka_pgkv::WriteOp::Put {
                key: crabka_pgkv::key::secondary_index_entry_key(
                    table.id, index.id, &values, rowid,
                ),
                value: Vec::new(),
            });
        }
    }
    Ok(ops)
}

fn index_entries(
    table: &Table,
    index: &crabka_pgcatalog::Index,
    row: &[Datum],
) -> Result<Vec<Vec<Datum>>, ExecError> {
    if index
        .columns
        .iter()
        .any(|key| crabka_pgcatalog::index_key_expression(key).is_some())
    {
        return Ok(Vec::new());
    }
    if index.method == crabka_pgcatalog::IndexMethod::Btree {
        return indexed_values(table, index, row).map(|values| vec![values]);
    }
    if index.method != crabka_pgcatalog::IndexMethod::Gin {
        return Ok(Vec::new());
    }
    let column = table
        .column_index(&index.columns[0])
        .ok_or_else(|| ExecError::UndefinedColumn(index.columns[0].clone()))?;
    match &row[column] {
        Datum::Null => Ok(Vec::new()),
        Datum::TsVector(vector) => Ok(vector
            .0
            .iter()
            .map(|lexeme| vec![Datum::Text(lexeme.text.clone())])
            .collect()),
        got => Err(crate::func::type_error("tsvector", got)),
    }
}

fn indexed_values(
    table: &Table,
    index: &crabka_pgcatalog::Index,
    row: &[Datum],
) -> Result<Vec<Datum>, ExecError> {
    index
        .columns
        .iter()
        .map(|column| {
            let column_index = table
                .column_index(column)
                .ok_or_else(|| ExecError::UndefinedColumn(column.clone()))?;
            Ok(row[column_index].clone())
        })
        .collect()
}

/// Result of pruning one rowid's version chain.
pub(crate) struct ChainPrune {
    /// `WriteOp`s reclaiming the chain: `Delete`s for dead version keys and
    /// their orphaned local secondary-index entries, plus (for `vacuum`)
    /// `Put`s freezing surviving sub-horizon tuple headers. Empty when
    /// nothing on the chain needs work.
    pub ops: Vec<crabka_pgkv::WriteOp>,
    /// Number of tuple versions deleted by `ops`.
    pub versions: u64,
    /// Number of secondary-index entries deleted by `ops`.
    pub index_entries: u64,
    /// Number of surviving tuple versions frozen by `ops`.
    pub frozen: u64,
}

/// Delete ops reclaiming `rowid`'s dead versions (and the local secondary-index
/// entries no surviving version still needs), judged at `horizon`.
///
/// A version is dead per [`crabka_pgmvcc::gc::version_is_dead`]: its creator
/// aborted, or a transaction that committed below `horizon` deleted/superseded
/// it. `horizon` must come from `checkpoint_garbage_horizon`, which caps it at
/// the oldest running writer xid, the lowest registered snapshot pin, and the
/// first non-terminal clog entry.
///
/// Snapshot safety: every snapshot consumer registers a `GcHorizon` pin at its
/// snapshot `xmin` for as long as the snapshot is in use (REPEATABLE READ
/// transactions pin at BEGIN until COMMIT/ROLLBACK; autocommit and READ
/// COMMITTED statements pin for the statement's duration), so a version some
/// live snapshot still sees, one whose committed deleter is in that
/// snapshot's `xip` or above its `xmax`, keeps `horizon` at or below the
/// deleter's xid and is never selected here. Un-pinned readers do not exist:
/// every statement path pins before taking its snapshot, and the pin value
/// (the ProcArray xmin at pin time) is monotonically `<=` any snapshot xmin
/// taken afterwards. `MemKv`/`FjallKv` scans additionally materialize their
/// results eagerly (`KvScan` is a `Vec`), so even a scan that raced an earlier
/// horizon computation observes an atomic before-or-after state of each prune
/// batch, never a partially deleted chain.
///
/// Lock interaction: callers must hold `rowid`'s exclusive row lock (UPDATE/
/// DELETE already do; `vacuum` takes it per row). Dead version KEYS can never
/// collide with a concurrent writer's puts. A writer only writes the newest
/// committed version's key (it stamps `xmax`) and its own new key, and neither
/// is ever dead. But the survivor computation for shared index entries must
/// not race a writer that re-adds the same indexed values for this rowid.
///
/// Engine kinds: sound everywhere, because the returned ops are folded into
/// the caller's own commit batch. On replicated engines they replicate
/// through the WAL and replay deterministically. Global 2PC writes are
/// self-protecting: an undecided enlisted xid reads as `Prepared` (which
/// [`crabka_pgmvcc::gc::version_is_dead`] never treats as dead), and global
/// xids sit numerically above every local horizon.
///
/// One rowid-chain prune request (see [`prune_rowid_chain_ops`]).
pub(crate) struct ChainPruneRequest<'a> {
    /// The row whose version chain is pruned.
    pub rowid: u64,
    /// The garbage horizon (from `checkpoint_garbage_horizon`).
    pub horizon: u64,
    /// Version-key xids this batch itself (re)writes. They are never deleted
    /// or frozen, whatever their current on-disk state.
    pub keep_xids: &'a [u64],
    /// The row this batch is writing, when any; its indexed values count as
    /// survivors so a shared index entry is never deleted out from under the
    /// incoming version.
    pub new_row: Option<&'a [Datum]>,
    /// When given (`vacuum` only), additionally rewrite every surviving
    /// version whose creator committed below this floor to `FROZEN_XID`
    /// (visible to every snapshot without a clog lookup). That is the
    /// precondition for a truncation of the clog below the horizon. The freeze
    /// is invisible to every snapshot: a registered snapshot's `xmin` is at or
    /// above the
    /// horizon, so a committed sub-horizon creator was already
    /// settled-and-committed for it.
    pub freeze_below: Option<u64>,
}

/// Rate-limited write-path reclamation telemetry accumulated between
/// emissions (process-wide; see [`log_prune_engagement`]).
#[derive(Default)]
struct PruneEngagementLog {
    /// When the previous line was emitted; `None` before the first.
    last_emitted: Option<std::time::Instant>,
    /// Row chains examined since the previous line.
    rows: u64,
    /// Dead versions selected for deletion since the previous line.
    pruned: u64,
}

static PRUNE_ENGAGEMENT: std::sync::LazyLock<std::sync::Mutex<PruneEngagementLog>> =
    std::sync::LazyLock::new(|| std::sync::Mutex::new(PruneEngagementLog::default()));

/// Emit at most one `xid_chain_prune_engaged` debug line per second.
///
/// The line carries the current horizon and the chain/deletion counts
/// accumulated since the previous line. A live node that logs a low `horizon`
/// with growing `rows` and zero `pruned` shows the write path consults the
/// horizon but finds nothing dead. A non-zero `pruned` confirms end-to-end
/// reclamation.
fn log_prune_engagement(horizon: u64, pruned: u64) {
    const EMIT_EVERY: std::time::Duration = std::time::Duration::from_secs(1);
    let mut log = PRUNE_ENGAGEMENT.lock().expect("prune engagement log");
    log.rows += 1;
    log.pruned += pruned;
    let now = std::time::Instant::now();
    let due = log
        .last_emitted
        .is_none_or(|last| now.duration_since(last) >= EMIT_EVERY);
    if !due {
        return;
    }
    tracing::debug!(
        horizon,
        pruned = log.pruned,
        rows = log.rows,
        "xid_chain_prune_engaged"
    );
    log.last_emitted = Some(now);
    log.rows = 0;
    log.pruned = 0;
}

pub(crate) fn prune_rowid_chain_ops(
    kv: &dyn Kv,
    table: &Table,
    local_indexes: &[crabka_pgcatalog::Index],
    request: &ChainPruneRequest<'_>,
) -> Result<ChainPrune, ExecError> {
    let &ChainPruneRequest {
        rowid,
        horizon,
        keep_xids,
        new_row,
        freeze_below,
    } = request;
    let status = |xid| crabka_pgmvcc::clog::get(kv, xid);
    let mut dead: Vec<(Vec<u8>, Vec<Datum>)> = Vec::new();
    let mut surviving: Vec<Vec<Datum>> = Vec::new();
    let mut freeze: Vec<(Vec<u8>, Vec<u8>)> = Vec::new();
    for (key, value) in kv.scan_prefix(&crabka_pgkv::key::row_key(table.id, rowid))? {
        let (xmin, xmax, row) = crabka_pgmvcc::version::decode_tuple(&value)?;
        let key_xid = crabka_pgmvcc::version::xid_of_key(&key)?;
        if !keep_xids.contains(&key_xid)
            && crabka_pgmvcc::gc::version_is_dead(xmin, xmax, horizon, &status)?
        {
            dead.push((key, row));
            continue;
        }
        if let Some(floor) = freeze_below
            && !keep_xids.contains(&key_xid)
            && xmin != crabka_pgmvcc::xid::FROZEN_XID
            && xmin < floor
            && matches!(status(xmin)?, crabka_pgmvcc::clog::XidStatus::Committed)
        {
            freeze.push((key, value.clone()));
        }
        surviving.push(row);
    }
    log_prune_engagement(horizon, dead.len() as u64);
    if dead.is_empty() && freeze.is_empty() {
        return Ok(ChainPrune {
            ops: Vec::new(),
            versions: 0,
            index_entries: 0,
            frozen: 0,
        });
    }
    let mut ops: Vec<crabka_pgkv::WriteOp> = Vec::new();
    let frozen = freeze.len() as u64;
    for (key, value) in freeze {
        ops.push(crabka_pgkv::WriteOp::Put {
            key,
            value: crabka_pgmvcc::version::freeze_tuple_xmin(&value)?,
        });
    }
    let mut index_entries_pruned: u64 = 0;
    // An index entry key `(values, rowid)` is SHARED by every version of this
    // row carrying `values`: delete it only when no surviving version — nor
    // the row this batch is writing — still carries those values. Chains are
    // short (pruning keeps them O(1)), so linear survivor probes suffice.
    let mut removed: Vec<(crabka_pgcatalog::IndexId, Vec<Datum>)> = Vec::new();
    for index in local_indexes {
        let mut survivor_entries = Vec::new();
        for row in &surviving {
            survivor_entries.extend(index_entries(table, index, row)?);
        }
        if let Some(row) = new_row {
            survivor_entries.extend(index_entries(table, index, row)?);
        }
        for (_, row) in &dead {
            for values in index_entries(table, index, row)? {
                if survivor_entries.contains(&values)
                    || removed
                        .iter()
                        .any(|(id, prior)| *id == index.id && *prior == values)
                {
                    continue;
                }
                ops.push(crabka_pgkv::WriteOp::Delete {
                    key: crabka_pgkv::key::secondary_index_entry_key(
                        table.id, index.id, &values, rowid,
                    ),
                });
                removed.push((index.id, values));
                index_entries_pruned += 1;
            }
        }
    }
    let versions = dead.len() as u64;
    ops.extend(
        dead.into_iter()
            .map(|(key, _)| crabka_pgkv::WriteOp::Delete { key }),
    );
    Ok(ChainPrune {
        ops,
        versions,
        index_entries: index_entries_pruned,
        frozen,
    })
}

fn lookup_local_index_equal(
    mvcc: &MvccReadContext<'_>,
    table: &Table,
    index: &crabka_pgcatalog::Index,
    values: &[Datum],
) -> Result<Vec<ScannedRow>, ExecError> {
    let prefix = crabka_pgkv::key::secondary_index_entry_prefix(table.id, index.id, values);
    let entries = mvcc.kv.scan_prefix(&prefix)?;
    let mut rowids = BTreeSet::new();
    for (key, _) in entries {
        rowids.insert(crabka_pgkv::key::secondary_index_rowid_of(
            table.id, index.id, &key,
        )?);
    }

    let mut exact = Vec::new();
    for candidate in visible_rows_for_rowids(mvcc, table, rowids)? {
        if indexed_values(table, index, &candidate.row)? == values {
            exact.push(candidate);
        }
    }
    Ok(exact)
}

fn lookup_local_gin(
    mvcc: &MvccReadContext<'_>,
    table: &Table,
    index: &crabka_pgcatalog::Index,
    query: &crabka_pgtypes::TsQuery,
) -> Result<Option<Vec<ScannedRow>>, ExecError> {
    let Some(rowids) = gin_candidate_rowids(mvcc.kv, table, index, query)? else {
        return Ok(None);
    };
    let column = table
        .column_index(&index.columns[0])
        .ok_or_else(|| ExecError::UndefinedColumn(index.columns[0].clone()))?;
    Ok(Some(
        visible_rows_for_rowids(mvcc, table, rowids)?
            .into_iter()
            .filter(|candidate| {
                matches!(&candidate.row[column], Datum::TsVector(vector) if vector.matches(query))
            })
            .collect(),
    ))
}

fn gin_candidate_rowids(
    kv: &dyn Kv,
    table: &Table,
    index: &crabka_pgcatalog::Index,
    query: &crabka_pgtypes::TsQuery,
) -> Result<Option<BTreeSet<u64>>, ExecError> {
    use crabka_pgtypes::TsQuery;

    match query {
        TsQuery::Empty => Ok(Some(BTreeSet::new())),
        TsQuery::Term(term) if term.prefix => Ok(None),
        TsQuery::Term(term) => {
            let prefix = crabka_pgkv::key::secondary_index_entry_prefix(
                table.id,
                index.id,
                &[Datum::Text(term.text.clone())],
            );
            let mut rowids = BTreeSet::new();
            for (key, _) in kv.scan_prefix(&prefix)? {
                rowids.insert(crabka_pgkv::key::secondary_index_rowid_of(
                    table.id, index.id, &key,
                )?);
            }
            Ok(Some(rowids))
        }
        TsQuery::Not(_) => Ok(None),
        TsQuery::And(left, right) | TsQuery::Phrase(left, right, _) => {
            let left = gin_candidate_rowids(kv, table, index, left)?;
            let right = gin_candidate_rowids(kv, table, index, right)?;
            Ok(match (left, right) {
                (Some(left), Some(right)) => Some(&left & &right),
                (Some(candidates), None) | (None, Some(candidates)) => Some(candidates),
                (None, None) => None,
            })
        }
        TsQuery::Or(left, right) => {
            let left = gin_candidate_rowids(kv, table, index, left)?;
            let right = gin_candidate_rowids(kv, table, index, right)?;
            Ok(match (left, right) {
                (Some(left), Some(right)) => Some(&left | &right),
                _ => None,
            })
        }
    }
}

fn visible_rows_for_rowids(
    mvcc: &MvccReadContext<'_>,
    table: &Table,
    rowids: BTreeSet<u64>,
) -> Result<Vec<ScannedRow>, ExecError> {
    let mut rows = Vec::new();
    for rowid in rowids {
        let row_prefix = crabka_pgkv::key::row_key(table.id, rowid);
        let versions = mvcc
            .kv
            .scan_prefix(&row_prefix)?
            .iter()
            .map(|(_, value)| {
                let (xmin, xmax, row) = crabka_pgmvcc::version::decode_tuple(value)?;
                Ok((xmin, xmax, row))
            })
            .collect::<Result<Vec<_>, crabka_pgkv::KvError>>()?;
        let Some((xmin, row)) = find_visible_one(
            mvcc.kv,
            mvcc.global,
            mvcc.global_snapshot,
            mvcc.snapshot,
            mvcc.own,
            &versions,
        )?
        else {
            continue;
        };
        rows.push(ScannedRow { rowid, xmin, row });
    }
    Ok(rows)
}

/// Choose the index probe for an UPDATE/DELETE filter: a top-level
/// `column = literal` conjunct matching a single-column local index. Returns
/// `None`, which means a full scan, for sharded tables, for filters outside the
/// pushdown subset, and when no index matches. It reuses the SELECT path's
/// extraction, so only exact-type literals on supported column types qualify.
fn choose_write_index_probe(
    catalog_kv: &dyn Kv,
    table: &Table,
    filter: Option<&Expr>,
) -> Result<Option<(crabka_pgcatalog::Index, Datum)>, ExecError> {
    if table.sharded {
        return Ok(None);
    }
    let predicate = crate::plan_dist::predicate_for_filter(table, filter);
    choose_local_index_equality(catalog_kv, table, &predicate)
}

/// Candidate `(rowid, xmin, row)` source for UPDATE/DELETE: probe a matching
/// local index instead of scanning the whole table when the filter pins an
/// indexed column to a literal, else fall back to `scan_live`. Both paths read
/// under the statement's snapshot/gsnap/own visibility and return rows sorted
/// by rowid; the caller still applies the FULL residual filter and the
/// under-lock EvalPlanQual re-check to every candidate, so the affected rows,
/// RETURNING output, and lock order are identical to the full scan.
/// The stored rows an `UPDATE`/`DELETE`/`MERGE` may act on, after privileges
/// and row security.
///
/// This is the write side's counterpart to the read gate: an `UPDATE` that
/// could change a row a `SELECT` would not have shown is the exact hazard the
/// programme exists to avoid, so both the privilege test and the `USING` qual
/// are applied here, where every row-selecting write path already passes.
///
/// The privilege check runs before the rows are gathered, and the two decisions
/// are driven by one [`crate::privilege::WriteAction`] rather than by a
/// `PolicyCommand` beside a privilege — a caller handed both can pair them
/// wrongly, and `TRUNCATE` (a `DELETE` policy command needing the `TRUNCATE`
/// privilege) is exactly the pairing that would be got wrong.
fn write_candidate_rows(
    write_ctx: &WriteContext<'_>,
    table: &Table,
    action: crate::privilege::WriteAction,
    filter: Option<&Expr>,
    reads_target_columns: bool,
) -> Result<Vec<(u64, u64, Vec<Datum>)>, ExecError> {
    let governor = write_ctx.governor(table);
    crate::privilege::require_write(
        &write_ctx.privileges(),
        governor,
        action,
        reads_target_columns,
    )?;
    let using =
        crate::rls::RowSecurityUsing::compile(&write_ctx.rls(), governor, action.policy_command())?;
    let mut rows: Vec<(u64, u64, Vec<Datum>)> = if let Some((index, value)) =
        choose_write_index_probe(write_ctx.catalog_kv, table, filter)?
    {
        lookup_local_index_equal(&write_ctx.mvcc_read(), table, &index, &[value])?
            .into_iter()
            .map(|row| (row.rowid, row.xmin, row.row))
            .collect()
    } else {
        scan_live(
            write_ctx.kv,
            write_ctx.global,
            write_ctx.global_snapshot,
            write_ctx.snapshot,
            Some(write_ctx.xid),
            table,
        )?
    };
    // The `USING` qual, the statement's own WHERE, and any `RETURNING old.*`
    // all read these rows, so a virtual generated column has to hold its value
    // before any of them run.
    for (_, _, row) in &mut rows {
        expand_virtual_generated_row(table, row, write_ctx.eval_ctx)?;
    }
    using.retain_visible(table, rows, write_ctx.eval_ctx)
}

/// The role a timestamp write is authorized as.
///
/// The same `PUBLIC` → bootstrap-superuser resolution
/// [`ForeignCtx::effective_role`] applies, spelled here because this path is
/// given an [`crate::clock::EvalCtx`] and no `ForeignCtx` at all.
fn timestamp_write_role(ctx: &crate::clock::EvalCtx) -> String {
    if ctx.current_user == crabka_pgcatalog::PUBLIC_ROLE {
        crabka_pgcatalog::BOOTSTRAP_ROLE.to_string()
    } else {
        ctx.current_user.clone()
    }
}

/// Build timestamp-transaction writes for sharded-table autocommit DML.
pub(crate) fn execute_timestamp_write(
    catalog_kv: &dyn Kv,
    kv: &dyn Kv,
    seq: &crate::seq::SequenceManager,
    stmt: &Statement,
    ctx: &crate::clock::EvalCtx,
) -> Result<TimestampWritePlan, ExecError> {
    let resolution = ctx.resolution();
    match stmt {
        Statement::Insert { returning, .. }
        | Statement::Update { returning, .. }
        | Statement::Delete { returning, .. }
            if returning.is_some() =>
        {
            return Err(ExecError::Unsupported(
                "RETURNING on sharded timestamp writes is not supported".into(),
            ));
        }
        _ => {}
    }
    // A sharded write is planned against exactly one relation, so it cannot
    // descend an inheritance tree the way the ordinary write path does. Left
    // alone it would silently write the parent's own rows and report a count
    // that omits the children's — the very wrong answer the tree write exists
    // to remove — so the combination is refused until the timestamp planner
    // can carry more than one relation.
    if let Statement::Update { table, only, .. } | Statement::Delete { table, only, .. } = stmt
        && !*only
    {
        let name = resolve_relation(catalog_kv, resolution, table, SchemaDisposition::Reference)?;
        if crate::inheritance::has_children(catalog_kv, &name)? {
            return Err(ExecError::Unsupported(format!(
                "UPDATE/DELETE on sharded table \"{name}\" is not supported while it has \
                 inheritance children: the statement would have to write every relation below it, \
                 and a sharded write is planned against one. Write ONLY \"{name}\", or each child, \
                 instead"
            )));
        }
    }
    // ON CONFLICT arbitration probes and locks a unique key on the local range;
    // a sharded table's unique keys live on other ranges, so the conflict can
    // neither be seen nor locked here. Refused permanently, like RETURNING.
    if let Statement::Insert {
        on_conflict: Some(_),
        ..
    } = stmt
    {
        return Err(ExecError::Unsupported(
            "ON CONFLICT on sharded timestamp writes is not supported".into(),
        ));
    }

    let table_name = match stmt {
        Statement::Insert { table, .. }
        | Statement::Update { table, .. }
        | Statement::Delete { table, .. } => table,
        _ => {
            return Err(ExecError::Unsupported(
                "not a timestamp write statement".into(),
            ));
        }
    };
    let table_name = &resolve_relation(
        catalog_kv,
        resolution,
        table_name,
        SchemaDisposition::Reference,
    )?;
    let table = crabka_pgcatalog::get_table(catalog_kv, table_name)?;
    if !table_uses_global_visibility(&table) {
        return Err(ExecError::Unsupported(
            "timestamp writes require a sharded table".into(),
        ));
    }
    // Privileges are not exempt the way row security is: a sharded relation
    // still has an owner and still has grants, and this path writes it without
    // ever reaching `WriteContext::row_check`. The role comes off the `EvalCtx`
    // because that is the only session context a timestamp write is given.
    crate::privilege::require(
        &crate::privilege::PrivilegeCtx::new(catalog_kv, &timestamp_write_role(ctx)),
        &table.name,
        &table.owner,
        crate::privilege::RelationKind::Table,
        crate::privilege::Privilege::for_written_row(match stmt {
            Statement::Insert { .. } => crabka_pgcatalog::policy::PolicyCommand::Insert,
            Statement::Update { .. } => crabka_pgcatalog::policy::PolicyCommand::Update,
            _ => crabka_pgcatalog::policy::PolicyCommand::Delete,
        }),
    )?;
    // The row-security exemption this path's writes carry
    // (`CheckExemption::ShardedRelation`) is only sound because a sharded
    // relation cannot be put under row security. Re-asserted here rather than
    // assumed, so a future path that sets the flag fails loudly instead of
    // writing unchecked rows.
    if table.row_security {
        return Err(ExecError::Unsupported(format!(
            "row-level security on sharded relation \"{}\" is not supported",
            table.name.name
        )));
    }
    let indexes = crabka_pgcatalog::list_table_indexes(catalog_kv, &table.name)?;
    let global_indexes: Vec<_> = indexes
        .iter()
        .filter(|index| index.placement == crabka_pgcatalog::IndexPlacement::Global)
        .collect();
    if global_indexes.iter().any(|index| index.unique) {
        return Err(ExecError::Unsupported(
            "unique global indexes are not supported until global enforcement exists".into(),
        ));
    }
    let local_indexes_present = indexes
        .iter()
        .any(|index| index.placement == crabka_pgcatalog::IndexPlacement::Local);
    if local_indexes_present {
        return Err(ExecError::Unsupported(
            "local index maintenance for sharded timestamp writes is blocked on G-6".into(),
        ));
    }

    match stmt {
        Statement::Insert {
            columns, source, ..
        } => {
            // A sharded write's rows must be known without a read: the feeding
            // query forms have no timestamp-domain plan yet.
            let crabka_pgparser::ast::InsertSource::Values(rows) = source else {
                return Err(ExecError::Unsupported(
                    "INSERT ... SELECT / DEFAULT VALUES on sharded tables is not supported".into(),
                ));
            };
            crate::trigger::fire_statement(
                catalog_kv,
                &table,
                crate::trigger::DmlEvent::Insert,
                crabka_pgcatalog::trigger::TriggerTiming::Before,
                &[],
                ctx,
            )?;
            let plan = execute_timestamp_insert(
                catalog_kv,
                kv,
                seq,
                &table,
                &global_indexes,
                columns,
                rows,
                ctx,
            )?;
            crate::trigger::fire_statement(
                catalog_kv,
                &table,
                crate::trigger::DmlEvent::Insert,
                crabka_pgcatalog::trigger::TriggerTiming::After,
                &[],
                ctx,
            )?;
            Ok(plan)
        }
        Statement::Update {
            assignments,
            from,
            filter,
            ..
        } => {
            if !from.is_empty() {
                return Err(ExecError::Unsupported(
                    "UPDATE ... FROM on sharded tables is not supported".into(),
                ));
            }
            let updated = assignments
                .iter()
                .flat_map(|assignment| assignment.targets.iter().cloned())
                .collect::<Vec<_>>();
            crate::trigger::fire_statement(
                catalog_kv,
                &table,
                crate::trigger::DmlEvent::Update,
                crabka_pgcatalog::trigger::TriggerTiming::Before,
                &updated,
                ctx,
            )?;
            let plan = execute_timestamp_update(
                catalog_kv,
                kv,
                &table,
                &global_indexes,
                assignments,
                filter.as_ref(),
                ctx,
            )?;
            crate::trigger::fire_statement(
                catalog_kv,
                &table,
                crate::trigger::DmlEvent::Update,
                crabka_pgcatalog::trigger::TriggerTiming::After,
                &updated,
                ctx,
            )?;
            Ok(plan)
        }
        Statement::Delete { using, filter, .. } => {
            if !using.is_empty() {
                return Err(ExecError::Unsupported(
                    "DELETE ... USING on sharded tables is not supported".into(),
                ));
            }
            crate::trigger::fire_statement(
                catalog_kv,
                &table,
                crate::trigger::DmlEvent::Delete,
                crabka_pgcatalog::trigger::TriggerTiming::Before,
                &[],
                ctx,
            )?;
            let plan = execute_timestamp_delete(
                catalog_kv,
                kv,
                &table,
                &global_indexes,
                filter.as_ref(),
                ctx,
            )?;
            crate::trigger::fire_statement(
                catalog_kv,
                &table,
                crate::trigger::DmlEvent::Delete,
                crabka_pgcatalog::trigger::TriggerTiming::After,
                &[],
                ctx,
            )?;
            Ok(plan)
        }
        _ => Err(ExecError::Unsupported(
            "this statement is not supported on sharded tables".into(),
        )),
    }
}

#[allow(clippy::too_many_arguments)]
fn execute_timestamp_insert(
    catalog_kv: &dyn Kv,
    kv: &dyn Kv,
    seq: &crate::seq::SequenceManager,
    table: &Table,
    global_indexes: &[&crabka_pgcatalog::Index],
    columns: &Option<Vec<String>>,
    rows: &[Vec<Expr>],
    ctx: &crate::clock::EvalCtx,
) -> Result<TimestampWritePlan, ExecError> {
    if rows.is_empty() {
        return Ok(TimestampWritePlan {
            result: command("INSERT 0 0"),
            writes: Vec::new(),
            commit_ops: Vec::new(),
        });
    }
    let width = rows.first().map_or(0, Vec::len);
    if rows.iter().any(|row| row.len() != width) {
        return Err(ExecError::ValuesColumnCount);
    }
    let target_idx = resolve_insert_targets(table, columns, width)?;
    let proposed_rows = rows.len() as u64;
    let (start, seq_op) = seq.alloc(kv, table.id, proposed_rows)?;
    let mut writes = Vec::with_capacity(rows.len());
    for (rowid, row_exprs) in (start..).zip(rows.iter()) {
        let full = build_insert_row(table, &target_idx, row_exprs, ctx)?;
        let Some(full) = crate::trigger::fire_before_row(
            catalog_kv,
            crate::trigger::WriteTarget {
                table,
                check: &crate::rls::WriteChecks::exempt(
                    crate::rls::CheckExemption::ShardedRelation,
                ),
            },
            crate::trigger::DmlEvent::Insert,
            &[],
            None,
            Some(full),
            ctx,
        )?
        else {
            continue;
        };
        let bucket = hash_bucket_for_row(table, &full)?;
        crate::trigger::fire_after_row(
            catalog_kv,
            table,
            crate::trigger::DmlEvent::Insert,
            &[],
            None,
            Some(&full),
            ctx,
        )?;
        writes.push(TimestampWrite {
            table_id: table.id,
            bucket,
            rowid,
            global_index_intents: global_index_intents_for_row(
                table,
                global_indexes,
                rowid,
                &full,
            )?,
            row: full,
            delete: false,
        });
    }
    let n_rows = writes.len();
    Ok(TimestampWritePlan {
        result: command(&format!("INSERT 0 {n_rows}")),
        writes,
        commit_ops: seq_op.into_iter().collect(),
    })
}

fn execute_timestamp_update(
    catalog_kv: &dyn Kv,
    kv: &dyn Kv,
    table: &Table,
    global_indexes: &[&crabka_pgcatalog::Index],
    assignments: &[crabka_pgparser::ast::Assignment],
    filter: Option<&Expr>,
    ctx: &crate::clock::EvalCtx,
) -> Result<TimestampWritePlan, ExecError> {
    let scope = Scope::single(table, &table.name.name);
    // The sharded write path evaluates assignments without a read, so only the
    // single-expression form is available here.
    let targets = assignments
        .iter()
        .map(
            |assignment| match (&assignment.targets[..], &assignment.value) {
                ([column], crabka_pgparser::ast::AssignmentValue::Expr(expr)) => table
                    .column_index(column)
                    .map(|index| (index, expr))
                    .ok_or_else(|| ExecError::UndefinedColumn(column.clone())),
                _ => Err(ExecError::Unsupported(
                    "multi-column SET on sharded tables is not supported".into(),
                )),
            },
        )
        .collect::<Result<Vec<_>, ExecError>>()?;
    let rows = scan_ts_live_interval(kv, kv, table, ReadTimestamp::MAX, None, RowInterval::ALL)?;
    let filter = crate::bind::bind_optional(filter, &scope)?;
    let filter = filter.as_ref().map(crate::bind::BoundExpr::expr);
    let mut writes = Vec::new();
    for ScannedRow { rowid, row, .. } in rows {
        if !row_matches(filter, &scope, &row, ctx)? {
            continue;
        }
        let mut next = row.clone();
        for (index, expr) in &targets {
            let value = eval_assignment_value(expr, table.columns[*index].ty, &scope, &row, ctx)?;
            next[*index] = coerce(value, table.columns[*index].ty, ctx)?;
        }
        finish_written_row(table, &mut next, ctx)?;
        let updated = assignments
            .iter()
            .flat_map(|assignment| assignment.targets.iter().cloned())
            .collect::<Vec<_>>();
        let Some(next) = crate::trigger::fire_before_row(
            catalog_kv,
            crate::trigger::WriteTarget {
                table,
                check: &crate::rls::WriteChecks::exempt(
                    crate::rls::CheckExemption::ShardedRelation,
                ),
            },
            crate::trigger::DmlEvent::Update,
            &updated,
            Some(&row),
            Some(next),
            ctx,
        )?
        else {
            continue;
        };
        let old_bucket = hash_bucket_for_row(table, &row)?;
        let bucket = hash_bucket_for_row(table, &next)?;
        let global_index_intents =
            global_index_update_intents_for_row(table, global_indexes, rowid, &row, &next)?;
        if old_bucket != bucket {
            writes.push(TimestampWrite {
                table_id: table.id,
                bucket: old_bucket,
                rowid,
                global_index_intents: Vec::new(),
                row: row.clone(),
                delete: true,
            });
        }
        crate::trigger::fire_after_row(
            catalog_kv,
            table,
            crate::trigger::DmlEvent::Update,
            &updated,
            Some(&row),
            Some(&next),
            ctx,
        )?;
        writes.push(TimestampWrite {
            table_id: table.id,
            bucket,
            rowid,
            global_index_intents,
            row: next,
            delete: false,
        });
    }
    Ok(TimestampWritePlan {
        result: command(&format!(
            "UPDATE {}",
            writes.iter().filter(|write| !write.delete).count()
        )),
        writes,
        commit_ops: Vec::new(),
    })
}

fn execute_timestamp_delete(
    catalog_kv: &dyn Kv,
    kv: &dyn Kv,
    table: &Table,
    global_indexes: &[&crabka_pgcatalog::Index],
    filter: Option<&Expr>,
    ctx: &crate::clock::EvalCtx,
) -> Result<TimestampWritePlan, ExecError> {
    let scope = Scope::single(table, &table.name.name);
    let rows = scan_ts_live_interval(kv, kv, table, ReadTimestamp::MAX, None, RowInterval::ALL)?;
    let filter = crate::bind::bind_optional(filter, &scope)?;
    let filter = filter.as_ref().map(crate::bind::BoundExpr::expr);
    let mut writes = Vec::new();
    for ScannedRow { rowid, row, .. } in rows {
        if !row_matches(filter, &scope, &row, ctx)? {
            continue;
        }
        if crate::trigger::fire_before_row(
            catalog_kv,
            crate::trigger::WriteTarget {
                table,
                check: &crate::rls::WriteChecks::exempt(crate::rls::CheckExemption::RemovesRows),
            },
            crate::trigger::DmlEvent::Delete,
            &[],
            Some(&row),
            None,
            ctx,
        )?
        .is_none()
        {
            continue;
        }
        let global_index_intents =
            global_index_delete_intents_for_row(table, global_indexes, rowid, &row)?;
        let bucket = hash_bucket_for_row(table, &row)?;
        crate::trigger::fire_after_row(
            catalog_kv,
            table,
            crate::trigger::DmlEvent::Delete,
            &[],
            Some(&row),
            None,
            ctx,
        )?;
        writes.push(TimestampWrite {
            table_id: table.id,
            bucket,
            rowid,
            row,
            delete: true,
            global_index_intents,
        });
    }
    Ok(TimestampWritePlan {
        result: command(&format!("DELETE {}", writes.len())),
        writes,
        commit_ops: Vec::new(),
    })
}

fn hash_bucket_for_row(table: &Table, row: &[Datum]) -> Result<Option<u32>, ExecError> {
    let Some(crabka_pgcatalog::ShardingStrategy::Hash(hash)) = &table.sharding else {
        return Ok(None);
    };
    // A row's bucket is the hash of the one shard column, which is the arity
    // `SHARDED BY HASH` accepts. A wider catalog entry — attachable through the
    // catalog API, which does not gate arity — has no row encoding here: the
    // gateway derives a statement's route from every hash column's bytes, so a
    // row placed under the hash of the first column alone would sit in a range
    // that routing never visits. Refuse the write instead of misplacing it.
    let [column] = hash.columns.as_slice() else {
        return Err(ExecError::Unsupported(
            "hash sharding requires exactly one hash column".into(),
        ));
    };
    let index = table
        .column_index(column)
        .ok_or_else(|| ExecError::Unsupported("hash sharding catalog column mismatch".into()))?;
    let bytes = match &row[index] {
        Datum::Int4(value) => value.to_be_bytes().to_vec(),
        Datum::Int8(value) => value.to_be_bytes().to_vec(),
        Datum::Text(value) => value.as_bytes().to_vec(),
        Datum::Bytea(value) => value.clone(),
        // A `regclass` hashes on its oid: the name it renders is derived from
        // the catalog, so only the oid is stable enough to place a row.
        Datum::Regclass(value) => value.oid.to_be_bytes().to_vec(),
        Datum::Null => Vec::new(),
        _ => {
            return Err(ExecError::Unsupported(
                "hash shard key type is not supported".into(),
            ));
        }
    };
    crabka_pgkv::key::hash_bucket(&bytes, hash.buckets)
        .map(Some)
        .ok_or_else(|| ExecError::Unsupported("invalid hash sharding bucket count".into()))
}

fn global_index_intents_for_row(
    table: &Table,
    indexes: &[&crabka_pgcatalog::Index],
    rowid: u64,
    row: &[Datum],
) -> Result<Vec<crate::timestamp_txn::GlobalIndexIntent>, ExecError> {
    indexes
        .iter()
        .map(|index| {
            let indexed_values = index
                .columns
                .iter()
                .map(|column| {
                    let column_index = table
                        .column_index(column)
                        .ok_or_else(|| ExecError::UndefinedColumn(column.clone()))?;
                    Ok(row[column_index].clone())
                })
                .collect::<Result<Vec<_>, ExecError>>()?;
            Ok(crate::timestamp_txn::GlobalIndexIntent {
                index_id: index.id,
                indexed_values,
                base_table_id: table.id,
                base_rowid: rowid,
                unique: index.unique,
                delete: false,
            })
        })
        .collect()
}

fn global_index_update_intents_for_row(
    table: &Table,
    indexes: &[&crabka_pgcatalog::Index],
    rowid: u64,
    old_row: &[Datum],
    new_row: &[Datum],
) -> Result<Vec<crate::timestamp_txn::GlobalIndexIntent>, ExecError> {
    let mut intents = Vec::new();
    for index in indexes {
        let old_values = indexed_values(table, index, old_row)?;
        let new_values = indexed_values(table, index, new_row)?;
        if old_values == new_values {
            continue;
        }
        intents.push(crate::timestamp_txn::GlobalIndexIntent {
            index_id: index.id,
            indexed_values: old_values,
            base_table_id: table.id,
            base_rowid: rowid,
            unique: index.unique,
            delete: true,
        });
        intents.push(crate::timestamp_txn::GlobalIndexIntent {
            index_id: index.id,
            indexed_values: new_values,
            base_table_id: table.id,
            base_rowid: rowid,
            unique: index.unique,
            delete: false,
        });
    }
    Ok(intents)
}

fn global_index_delete_intents_for_row(
    table: &Table,
    indexes: &[&crabka_pgcatalog::Index],
    rowid: u64,
    row: &[Datum],
) -> Result<Vec<crate::timestamp_txn::GlobalIndexIntent>, ExecError> {
    indexes
        .iter()
        .map(|index| {
            Ok(crate::timestamp_txn::GlobalIndexIntent {
                index_id: index.id,
                indexed_values: indexed_values(table, index, row)?,
                base_table_id: table.id,
                base_rowid: rowid,
                unique: index.unique,
                delete: true,
            })
        })
        .collect()
}

/// Was `xid` settled (committed or aborted) before `snapshot` was taken? True
/// iff `xid` was neither still running at, nor started after, the snapshot.
/// This mirrors the negation of `Snapshot::is_running`.
fn snapshot_can_see(snapshot: &crabka_pgmvcc::visibility::Snapshot, xid: u64) -> bool {
    xid < snapshot.xmax && !snapshot.xip.contains(&xid)
}

/// The global-aware clog resolver handed to `satisfies_mvcc`. Given this range's
/// local xid `Li`, reads this range's clog (`local`); a terminal status is
/// returned unchanged (today's single-range behavior). A `Prepared(Li -> g)`
/// marker is deref'd to range 0's global clog (`global`): if `g` is still
/// in-doubt as of the reader's global snapshot (`gsnap`) it reports `InProgress`
/// (the cross-range row is invisible until the global commit decision); once `g`
/// is settled relative to `gsnap`, range 0's global-clog status for `g` is the
/// answer. So both ranges' Prepared rows flip visible together at the single
/// `Committed(g)` instant.
///
/// For a single-range (non-GTM) engine the caller passes `global = local` and
/// `gsnap = NO_GLOBAL_SNAPSHOT()`; no `Prepared` tuple ever exists there, so the
/// `Prepared` arm is unreachable and behavior is byte-for-byte unchanged.
pub(crate) fn global_status<'a>(
    local: &'a dyn crabka_pgkv::Kv,
    global: &'a dyn crabka_pgkv::Kv,
    gsnap: &'a crabka_pgmvcc::visibility::Snapshot,
) -> impl Fn(u64) -> Result<crabka_pgmvcc::clog::XidStatus, crabka_pgkv::KvError> + 'a {
    use crabka_pgmvcc::clog::XidStatus;
    move |xid| match crabka_pgmvcc::clog::get(local, xid)? {
        XidStatus::Prepared(g) => {
            if g >= gsnap.xmax || gsnap.xip.binary_search(&g).is_ok() {
                Ok(XidStatus::InProgress) // global txn in-doubt as of my global snapshot
            } else {
                Ok(crabka_pgmvcc::clog::get(global, g)?) // settled: range 0's global decision
            }
        }
        other => Ok(other),
    }
}

/// Find the single version of `rowid` visible to `snap` (with own-xid
/// read-your-writes) among already-decoded `versions`. Mirrors `scan_live`'s
/// per-version `satisfies_mvcc` check, but over one rowid's versions.
///
/// Returns the greatest-xmin live version. The MVCC at-most-one-live invariant
/// means at most one version of a rowid is live under any one snapshot, so the
/// selection is unambiguous; choosing the max explicitly (rather than relying on
/// ascending scan order) makes it order-independent and is debug-asserted to see
/// at most one live version.
fn find_visible_one(
    kv: &dyn Kv,
    global: &dyn Kv,
    gsnap: &crabka_pgmvcc::visibility::Snapshot,
    snap: &crabka_pgmvcc::visibility::Snapshot,
    own: Option<u64>,
    versions: &[(u64, u64, Vec<crabka_pgtypes::Datum>)],
) -> Result<Option<(u64, Vec<crabka_pgtypes::Datum>)>, ExecError> {
    let mut visible: Option<(u64, Vec<crabka_pgtypes::Datum>)> = None;
    let mut live_count: usize = 0;
    for (xmin, xmax, row) in versions {
        if crabka_pgmvcc::visibility::satisfies_mvcc(
            *xmin,
            *xmax,
            snap,
            own,
            global_status(kv, global, gsnap),
        )? {
            live_count += 1;
            // Keep the greatest-xmin live version EXPLICITLY. The MVCC at-most-one-live
            // invariant means there is normally exactly one; selecting the max removes the
            // hidden dependence on ascending scan order, so a future scan-order change can
            // never silently return a stale shadow (e.g. an aborted re-attempt's
            // `Prepared(Li_old -> g)` tuple that resolves invisible anyway).
            // NB: `is_none_or`, NOT `map_or(true, …)` — the latter trips
            // `clippy::unnecessary_map_or` under the workspace's `-D warnings` gate.
            if visible.as_ref().is_none_or(|(cur, _)| *xmin > *cur) {
                visible = Some((*xmin, row.clone()));
            }
        }
    }
    debug_assert!(
        live_count <= 1,
        "find_visible_one: {live_count} live versions for one rowid under one snapshot \
         — MVCC at-most-one-live invariant violated"
    );
    Ok(visible)
}

/// One decoded version of a row chain, keyed by the xid suffix of its
/// PHYSICAL version key. The key xid normally equals the header `xmin`, but a
/// frozen tuple keeps its original key while its header reads `FROZEN_XID`.
/// Writers must stamp `xmax` on the physical key, never one reconstructed
/// from the header.
struct ChainVersion {
    key_xid: u64,
    xmin: u64,
    xmax: u64,
    row: Vec<crabka_pgtypes::Datum>,
}

/// The version of `rowid` a write should operate on, as
/// `(key_xid, xmin, row)`.
///
/// After locking the row, re-read its current versions. Returns the version to
/// operate on, or None to skip. Under REPEATABLE READ, a row changed by a txn
/// that committed after our snapshot is a serialization failure (40001). Under
/// READ COMMITTED, re-find the latest live version (a fresh snapshot).
fn eval_plan_qual(
    mutation: &MutationContext<'_>,
    table: &crabka_pgcatalog::Table,
    rowid: u64,
) -> Result<Option<(u64, u64, Vec<crabka_pgtypes::Datum>)>, ExecError> {
    let kv = mutation.kv;
    let global = mutation.global;
    let procarray = mutation.procarray;
    let snapshot = mutation.snapshot;
    let xid = mutation.xid;
    let repeatable_read = mutation.repeatable_read;
    // Re-scan just this rowid's versions from disk.
    let prefix = crabka_pgkv::key::row_key(table.id, rowid);
    let scanned = kv.scan_prefix(&prefix)?;
    let mut versions: Vec<ChainVersion> = Vec::with_capacity(scanned.len());
    for (k, v) in &scanned {
        let (xmn, xmx, row) = crabka_pgmvcc::version::decode_tuple(v)?;
        versions.push(ChainVersion {
            key_xid: crabka_pgmvcc::version::xid_of_key(k)?,
            xmin: xmn,
            xmax: xmx,
            row,
        });
    }
    // Resolve this row's `Prepared(Li -> g)` markers against a SETTLED global view
    // — range 0's global clog read directly — NOT the statement's pre-lock global
    // snapshot (`gsnap`). We hold this row's lock, and a cross-range participant
    // releases a row's lock only AFTER its global decision is durable
    // (commit_release/abort_release run post-decision). So every global txn `g`
    // with a `Prepared` marker on THIS row's versions has already settled in
    // range 0's global clog; a still-in-doubt `g` could not have left a marker
    // here (it would still hold this lock, so we could not have acquired it).
    // Reading the global clog directly under the lock is therefore exact — and is
    // the read-committed-under-lock analogue of how the LOCAL clog is read
    // directly. Using `gsnap` would be stale: a `g` that committed while we were
    // blocked on the lock still appears in-doubt in `gsnap.xip`, hiding its just-
    // committed supersede and losing the update across the 2PC boundary. A settled
    // Snapshot (xmin 0, xmax MAX, empty xip) drives `global_status`'s in-doubt gate
    // (`g >= xmax || xip.contains(g)`) always false, so it reads `clog::get` for g.
    // The LOCAL `snapshot`/`fresh` handling below is unchanged — it is about local
    // creation ordering and is already correct.
    let settled_global = crabka_pgmvcc::visibility::Snapshot {
        xmin: 0,
        xmax: u64::MAX,
        xip: Vec::new(),
    };
    // Is the row's latest committed version deleted/superseded by a transaction
    // NOT visible to our txn snapshot (committed AFTER it), other than ourselves?
    // The resolver derefs a Prepared(xmx -> g) deleter to range 0's global
    // decision so a cross-range supersede is detected exactly when it commits.
    let resolve = global_status(kv, global, &settled_global);
    let changed_since_snapshot = versions.iter().any(|version| {
        version.xmax != crabka_pgmvcc::xid::INVALID_XID
            && version.xmax != xid
            && matches!(
                resolve(version.xmax),
                Ok(crabka_pgmvcc::clog::XidStatus::Committed)
            )
            && !snapshot_can_see(snapshot, version.xmax)
    });
    let mut found = if changed_since_snapshot {
        if repeatable_read {
            return Err(ExecError::SerializationFailure);
        }
        // READ COMMITTED: re-find the latest live version under a FRESH snapshot.
        let fresh = procarray.snapshot();
        find_visible_one_keyed(kv, global, &settled_global, &fresh, Some(xid), &versions)?
    } else {
        // No concurrent committed change: find the version visible to our snapshot.
        find_visible_one_keyed(kv, global, &settled_global, snapshot, Some(xid), &versions)?
    };
    // This version came straight off the disk, where a virtual generated column
    // is a NULL placeholder. Callers re-check the statement's qual against it
    // and may hand it to `RETURNING old.*`, so it is completed here rather than
    // at each of them.
    if let Some((_, _, row)) = &mut found {
        expand_virtual_generated_row(table, row, mutation.eval_ctx)?;
    }
    Ok(found)
}

/// [`find_visible_one`] over [`ChainVersion`]s, additionally returning the
/// visible version's PHYSICAL key xid so callers stamp the key that actually
/// exists (a frozen tuple's header `xmin` no longer names its key).
fn find_visible_one_keyed(
    kv: &dyn Kv,
    global: &dyn Kv,
    gsnap: &crabka_pgmvcc::visibility::Snapshot,
    snap: &crabka_pgmvcc::visibility::Snapshot,
    own: Option<u64>,
    versions: &[ChainVersion],
) -> Result<Option<(u64, u64, Vec<crabka_pgtypes::Datum>)>, ExecError> {
    let mut visible: Option<(u64, u64, Vec<crabka_pgtypes::Datum>)> = None;
    let mut live_count: usize = 0;
    for version in versions {
        if crabka_pgmvcc::visibility::satisfies_mvcc(
            version.xmin,
            version.xmax,
            snap,
            own,
            global_status(kv, global, gsnap),
        )? {
            live_count += 1;
            // Keep the greatest live version — by header xmin, then by key xid
            // (frozen tuples all read xmin == FROZEN_XID; their key xids still
            // order them). See find_visible_one for the invariant discussion.
            if visible.as_ref().is_none_or(|(cur_key, cur_xmin, _)| {
                (version.xmin, version.key_xid) > (*cur_xmin, *cur_key)
            }) {
                visible = Some((version.key_xid, version.xmin, version.row.clone()));
            }
        }
    }
    debug_assert!(
        live_count <= 1,
        "find_visible_one_keyed: {live_count} live versions for one rowid under one snapshot \
         — MVCC at-most-one-live invariant violated"
    );
    Ok(visible)
}

/// The jsonpath type an assignment target stores, if it stores one — the two
/// types whose input function is not reachable as a cast arm.
fn jsonpath_assignment_base(target: ColumnType) -> Option<ColumnType> {
    let base = target.storage_type();
    matches!(
        base,
        ColumnType::JsonPath | ColumnType::Array(crabka_pgtypes::ElemType::JsonPath)
    )
    .then_some(base)
}

/// Resolve a bare string literal — a value PostgreSQL still types `unknown` —
/// against the type it is being assigned to.
///
/// `unknown` has no storage and no operators of its own: an unadorned `'…'`
/// takes the assignment target's type, parsed by that type's input function.
/// That is what makes `SET id = '[11,12)'` an `int4range` and `FOR VALUES IN
/// ('[1,2)')` an `int4range` bound. It applies to the *literal* only — a
/// genuine `text` expression keeps its type, so `SET int_col = text_col` is
/// still 42804.
///
/// The resolution is an assignment, not an explicit cast: `'abcd'` into a
/// `varchar(3)` is 22001, where `'abcd'::varchar(3)` would have truncated.
fn resolve_unknown_literal(
    text: &str,
    target: ColumnType,
    ctx: &crate::clock::EvalCtx,
) -> Result<Datum, ExecError> {
    // A domain literal is parsed by the *base* type's input function; the
    // domain's own constraints are [`coerce`]'s job, on the parsed value.
    let base = match target {
        ColumnType::Domain(domain) => *domain.base,
        other => other,
    };
    let value = Datum::Text(text.to_owned());
    if let Some(jsonpath) = jsonpath_assignment_base(base) {
        return crate::eval::cast_value_in(&value, jsonpath, ctx.output_style());
    }
    match base {
        // `bytea_in` is the escape/hex decoder rather than a cast arm.
        ColumnType::Bytea => Ok(Datum::Bytea(crate::session::decode_bytea_text(text)?)),
        // The session's styles, not the canonical ones: PostgreSQL runs the
        // target type's input function here, and `date_in`/`timestamp_in` read
        // `DateStyle`'s field order. A stored `'97/02/10'` has to mean what the
        // same literal means when it is written as a cast.
        _ => Ok(crabka_pgtypes::cast::cast_assign_in(
            &value,
            base,
            ctx.output_style(),
        )?),
    }
}

/// Evaluate an assignment's right-hand side, giving an unadorned string literal
/// the `unknown` treatment of [`resolve_unknown_literal`]. Every other
/// expression evaluates on its own and then faces [`coerce`]'s assignment
/// rules, which callers apply to this function's result.
fn eval_assignment_value(
    expr: &Expr,
    target: ColumnType,
    scope: &Scope,
    values: &[Datum],
    ctx: &crate::clock::EvalCtx,
) -> Result<Datum, ExecError> {
    match expr {
        Expr::StringLiteral(text) => resolve_unknown_literal(text, target, ctx),
        _ => crate::eval::eval(expr, scope, values, ctx),
    }
}

/// Coerce an evaluated value into a target column type (assignment context). `ctx`
/// supplies the session zone for any temporal numeric conversion.
pub(crate) fn coerce(
    value: crabka_pgtypes::Datum,
    target: crabka_pgtypes::ColumnType,
    ctx: &crate::clock::EvalCtx,
) -> Result<crabka_pgtypes::Datum, ExecError> {
    use crabka_pgtypes::{ColumnType, Datum, TypeError, string::Coercion};
    // Assignment to a domain column coerces to the domain's base type and then
    // has to satisfy the domain's own constraints — PostgreSQL applies them at
    // every assignment, not only at an explicit cast.
    if let ColumnType::Domain(domain) = target {
        let base = coerce(value, *domain.base, ctx)?;
        crate::usertype::check_domain(target, &base, ctx)?;
        return Ok(base);
    }
    // Assignment to a composite column accepts a record of the same shape, and
    // a `record` built by a bare `ROW(…)` is coerced field by field into the
    // target's attribute types.
    if let (Datum::Record(_), ColumnType::Record(Some(_))) = (&value, target) {
        return Ok(crabka_pgtypes::cast::cast_in(
            &value,
            target,
            ctx.output_style(),
        )?);
    }
    if let (Datum::Enum(e), ColumnType::Enum(named)) = (&value, target)
        && e.ty == named
    {
        return Ok(value);
    }
    // The eleven `reg*` types share one datum, which carries the oid and the
    // rendering but not which of them produced it — so a store has only the
    // target column's type to go on. That is enough: the row encoding keeps the
    // oid and nothing else, and the name is re-derived from the *column's* type
    // on the way out. The value passes through unchanged, which keeps a stored
    // `regclass` DEFAULT deparsing as the literal it was written as.
    if matches!(&value, Datum::Regclass(_)) && target.is_reg() {
        return Ok(value);
    }
    if target == ColumnType::JsonPath {
        return match value {
            Datum::Null => Ok(Datum::Null),
            Datum::JsonPath(text) => Ok(Datum::JsonPath(text)),
            other => Err(ExecError::TypeMismatch(format!(
                "column is of type jsonpath but expression is of type {}",
                other.column_type().map_or("unknown", ColumnType::name),
            ))),
        };
    }
    if target == ColumnType::Array(crabka_pgtypes::ElemType::JsonPath) {
        return match value {
            Datum::Null => Ok(Datum::Null),
            Datum::Array(array) if array.elem == crabka_pgtypes::ElemType::JsonPath => {
                Ok(Datum::Array(array))
            }
            other => Err(ExecError::TypeMismatch(format!(
                "column is of type jsonpath[] but expression is of type {}",
                other.column_type().map_or("unknown", ColumnType::name),
            ))),
        };
    }
    // SP32: assignment to a `numeric` column — any numeric-family value (int4/
    // int8/float8/numeric) converts, applying the column's `(p,s)` modifier (round
    // + overflow). A `text` value still needs an explicit cast (handled by the
    // catch-all below); NULL falls through to the `(Null, _)` arm.
    if target.is_numeric()
        && matches!(
            value,
            Datum::Int4(_) | Datum::Int8(_) | Datum::Float8(_) | Datum::Numeric(_)
        )
    {
        return Ok(crabka_pgtypes::cast::cast_in(
            &value,
            target,
            ctx.output_style(),
        )?);
    }
    Ok(match (value, target) {
        (Datum::Null, _) => Datum::Null,
        (Datum::Bool(b), ColumnType::Bool) => Datum::Bool(b),
        (Datum::Int4(n), ColumnType::Int4) => Datum::Int4(n),
        (Datum::Int4(n), ColumnType::Int8) => Datum::Int8(i64::from(n)),
        (Datum::Int8(n), ColumnType::Int8) => Datum::Int8(n),
        (Datum::Int8(n), ColumnType::Int4) => i32::try_from(n)
            .map(Datum::Int4)
            .map_err(|_| TypeError::Overflow)?,
        (Datum::Text(s), ColumnType::Text) => Datum::Text(s),
        (Datum::Text(s), ColumnType::Varchar(limit)) => Datum::Text(
            crabka_pgtypes::string::apply_varchar_typmod(&s, limit, Coercion::Assignment)?,
        ),
        (Datum::Text(s), ColumnType::Char(limit)) => Datum::Text(
            crabka_pgtypes::string::apply_char_typmod(&s, limit, Coercion::Assignment)?,
        ),
        (value, target @ (ColumnType::Varchar(_) | ColumnType::Char(_))) => {
            crabka_pgtypes::cast::cast_assign_in(&value, target, ctx.output_style())?
        }
        (Datum::Text(s), ColumnType::Uuid) => {
            Datum::Text(crabka_pgtypes::uuid::UuidBytes::parse(&s)?.to_canonical_text())
        }
        (Datum::Bytea(bytes), ColumnType::Bytea) => Datum::Bytea(bytes),
        (Datum::Text(s), ColumnType::Bytea) => Datum::Bytea(crate::session::decode_bytea_text(&s)?),
        // SP30: float8 assignment casts. int → float8 is the standard widening;
        // float8 → int rounds half-to-even (PG's float→int assignment cast) and
        // range-checks (out of range / non-finite → 22003).
        (Datum::Float8(f), ColumnType::Float8) => Datum::Float8(f),
        (Datum::Int4(n), ColumnType::Float8) => Datum::Float8(f64::from(n)),
        (Datum::Int8(n), ColumnType::Float8) => Datum::Float8(n as f64),
        (Datum::Float8(f), ColumnType::Int4) => {
            let r = f.round_ties_even();
            if r.is_finite() && (i32::MIN as f64..=i32::MAX as f64).contains(&r) {
                Datum::Int4(r as i32)
            } else {
                return Err(TypeError::Overflow.into());
            }
        }
        (Datum::Float8(f), ColumnType::Int8) => {
            let r = f.round_ties_even();
            if r.is_finite() && (i64::MIN as f64..=i64::MAX as f64).contains(&r) {
                Datum::Int8(r as i64)
            } else {
                return Err(TypeError::Overflow.into());
            }
        }
        // SP32: assignment of a numeric value into a non-numeric numeric-family
        // column (→ numeric column is handled by the pre-check above). numeric→int
        // rounds half-away-from-zero with a range check (22003); numeric→float8 may
        // become ±Infinity for an out-of-range magnitude.
        (Datum::Numeric(d), ColumnType::Float8) => {
            Datum::Float8(crabka_pgtypes::numeric::to_f64(&d))
        }
        (Datum::Numeric(d), ColumnType::Int4) => {
            crabka_pgtypes::numeric::to_i32(&d).map(Datum::Int4)?
        }
        (Datum::Numeric(d), ColumnType::Int8) => {
            crabka_pgtypes::numeric::to_i64(&d).map(Datum::Int8)?
        }
        // SP37: date/time assignment — same-type pass-through (no implicit
        // cross-type coercion between temporal types; mismatches hit the catch-all).
        (Datum::Date(d), ColumnType::Date) => Datum::Date(d),
        (Datum::Time(t), ColumnType::Time) => Datum::Time(t),
        (Datum::Timestamp(ts), ColumnType::Timestamp) => Datum::Timestamp(ts),
        (Datum::Timestamptz(ts), ColumnType::Timestamptz) => Datum::Timestamptz(ts),
        (Datum::Interval(iv), ColumnType::Interval) => Datum::Interval(iv),
        // jsonb / array assignment. A string value runs the target type's input
        // function (`jsonb_in` / `array_in` — 22P02 on malformed input), the same
        // literal-assignment shape the `uuid` and `bytea` arms above use; an
        // array value converts element-wise so `ARRAY[1,2]` (int4[]) stores into
        // a `bigint[]` column. `cast` implements all four conversions.
        // `bit(n)` rejects a length mismatch on a store and `bit varying(n)`
        // an over-long value, where the explicit cast the catch-all would use
        // pads or truncates silently.
        (value @ Datum::BitString(_), ty @ (ColumnType::Bit(_) | ColumnType::VarBit(_))) => {
            crabka_pgtypes::cast::cast_assign_in(&value, ty, ctx.output_style())?
        }
        // `json → jsonb` and `jsonb → json` are assignment-level casts in
        // `pg_cast`, so storing one in a column of the other is allowed and runs
        // the target's input function over the source's output.
        (
            value @ (Datum::Text(_) | Datum::Jsonb(_) | Datum::Json(_)),
            ty @ (ColumnType::Jsonb | ColumnType::Json),
        )
        | (value @ (Datum::Text(_) | Datum::Array(_)), ty @ ColumnType::Array(_)) => {
            // `cast_assign_in`, because this is a store: an over-long element
            // of a `varchar(n)[]` column is 22001, not a silent truncation.
            crabka_pgtypes::cast::cast_assign_in(&value, ty, ctx.output_style())?
        }
        (v, target) => {
            // Assignment-context implicit casts — PostgreSQL's pg_cast
            // castcontext 'i'/'a' pairs (crabka subset): notably
            // timestamptz ↔ timestamp and date → timestamp/timestamptz, all
            // rotated through the session time zone. Anything outside that
            // strict subset (e.g. int ↔ text) keeps erroring with 42804.
            if let Some(from) = v.column_type()
                && crabka_pgtypes::cast::assignment_cast_allowed(from, target)
            {
                return Ok(crabka_pgtypes::cast::cast_in(
                    &v,
                    target,
                    ctx.output_style(),
                )?);
            }
            return Err(ExecError::TypeMismatch(format!(
                "column is of type {} but expression is of type {}",
                target.name(),
                v.column_type().map(|t| t.name()).unwrap_or("unknown"),
            )));
        }
    })
}

/// Scan a table's visible rows under `snapshot` (and the caller's own xid for
/// read-your-writes). Returns `(rowid, xmin, row)` for the one visible version
/// of each live row, sorted by rowid.
pub(crate) fn scan_live(
    kv: &dyn Kv,
    global: &dyn Kv,
    gsnap: &crabka_pgmvcc::visibility::Snapshot,
    snapshot: &crabka_pgmvcc::visibility::Snapshot,
    own: Option<u64>,
    table: &crabka_pgcatalog::Table,
) -> Result<Vec<(u64, u64, Vec<crabka_pgtypes::Datum>)>, ExecError> {
    scan_live_interval(kv, global, gsnap, snapshot, own, table, RowInterval::ALL).map(|rows| {
        rows.into_iter()
            .map(|row| (row.rowid, row.xmin, row.row))
            .collect()
    })
}

/// Scan visible rows within a rowid interval under `snapshot`, sorted by rowid.
pub(crate) fn scan_live_interval(
    kv: &dyn Kv,
    global: &dyn Kv,
    gsnap: &crabka_pgmvcc::visibility::Snapshot,
    snapshot: &crabka_pgmvcc::visibility::Snapshot,
    own: Option<u64>,
    table: &crabka_pgcatalog::Table,
    interval: RowInterval,
) -> Result<Vec<ScannedRow>, ExecError> {
    let scanned = scan_table_for_catalog_interval(kv, table, interval)?;
    let mut out: Vec<ScannedRow> = Vec::new();
    let mut i = 0;
    while i < scanned.len() {
        crate::session::check_query_canceled()?;
        let prefix = crabka_pgmvcc::version::row_prefix_of(&scanned[i].0)?.to_vec();
        let rowid = physical_rowid(table, &prefix)?;
        if !interval.contains(rowid) {
            while i < scanned.len()
                && crabka_pgmvcc::version::row_prefix_of(&scanned[i].0)? == prefix.as_slice()
            {
                i += 1;
            }
            continue;
        }
        let mut visible: Option<(u64, Vec<crabka_pgtypes::Datum>)> = None;
        let mut live_count: usize = 0;
        while i < scanned.len()
            && crabka_pgmvcc::version::row_prefix_of(&scanned[i].0)? == prefix.as_slice()
        {
            let (xmin, xmax, row) = crabka_pgmvcc::version::decode_tuple(&scanned[i].1)?;
            if crabka_pgmvcc::visibility::satisfies_mvcc(
                xmin,
                xmax,
                snapshot,
                own,
                global_status(kv, global, gsnap),
            )? {
                live_count += 1;
                // `is_none_or`, NOT `map_or(true, …)` — see find_visible_one above.
                if visible.as_ref().is_none_or(|(cur, _)| xmin > *cur) {
                    visible = Some((xmin, row));
                }
            }
            i += 1;
        }
        debug_assert!(
            live_count <= 1,
            "scan_live: {live_count} live versions for rowid {rowid} under one snapshot \
             — MVCC at-most-one-live invariant violated"
        );
        if let Some((xmin, row)) = visible {
            out.push(ScannedRow { rowid, xmin, row });
        }
    }
    out.sort_by_key(|row| row.rowid);
    Ok(out)
}

/// Scan timestamp-transaction versions within a rowid interval under `read_ts`.
pub(crate) fn scan_ts_live_interval(
    kv: &dyn Kv,
    primary_kv: &dyn Kv,
    table: &crabka_pgcatalog::Table,
    read_ts: ReadTimestamp,
    own_start_ts: Option<TimestampTransactionId>,
    interval: RowInterval,
) -> Result<Vec<ScannedRow>, ExecError> {
    let scanned = scan_table_for_catalog_interval(kv, table, interval)?;
    let mut out = Vec::new();
    let mut i = 0;
    while i < scanned.len() {
        crate::session::check_query_canceled()?;
        let prefix = crabka_pgmvcc::version::row_prefix_of(&scanned[i].0)?.to_vec();
        let rowid = physical_rowid(table, &prefix)?;
        let bucket = physical_bucket(table, &prefix)?;
        if !interval.contains(rowid) {
            while i < scanned.len()
                && crabka_pgmvcc::version::row_prefix_of(&scanned[i].0)? == prefix.as_slice()
            {
                i += 1;
            }
            continue;
        }

        let mut visible: Option<(u64, u64, Option<Vec<crabka_pgtypes::Datum>>)> = None;
        while i < scanned.len()
            && crabka_pgmvcc::version::row_prefix_of(&scanned[i].0)? == prefix.as_slice()
        {
            let version = crabka_pgmvcc::version::decode_ts_tuple(&scanned[i].1)?;
            let start_ts = TimestampTransactionId::new(version.start_ts).map_err(|error| {
                ExecError::Unsupported(format!("invalid timestamp intent start timestamp: {error}"))
            })?;
            // Corrupt or unreadable descriptor metadata is never a legacy version:
            // failing closed prevents an unverified participant write becoming visible.
            let descriptor =
                crate::timestamp_txn::read_timestamp_txn_descriptor(primary_kv, start_ts)?;
            let verified_distributed_intent = match descriptor.as_ref() {
                Some(descriptor) => crate::timestamp_txn::local_intent_matches_descriptor(
                    kv, descriptor, table.id, bucket, rowid,
                )?,
                None => false,
            };
            let descriptor_operation = descriptor.as_ref().is_some_and(|descriptor| {
                crate::timestamp_txn::local_terminal_operation_matches_descriptor(
                    descriptor, table.id, bucket, rowid,
                )
            });
            // Per-range local sequences reuse stamp values, so an unrelated
            // transaction's descriptor can sit at this version's start
            // timestamp. A descriptor that names this row neither as a
            // verified intent nor as a terminal operation belongs to such a
            // colliding transaction; treating it as authoritative would fence
            // a committed single-shard row invisible.
            let primary_decision = (verified_distributed_intent || descriptor_operation)
                .then(|| descriptor.as_ref().map(|descriptor| descriptor.decision))
                .flatten();
            let candidate = match (version.state, primary_decision, verified_distributed_intent) {
                (
                    crabka_pgmvcc::version::TsVersionState::Intent,
                    Some(PrimaryTxnDecision::Pending),
                    true,
                ) if own_start_ts == Some(start_ts) => Some((u64::MAX, Some(version.row))),
                // A range-0 commit decision makes every prewritten intent logically
                // visible, even if this particular participant has not yet completed
                // its idempotent physical resolution.
                (
                    crabka_pgmvcc::version::TsVersionState::Intent,
                    Some(PrimaryTxnDecision::Committed(commit_ts)),
                    true,
                ) if commit_ts.get() <= read_ts.get() => Some((commit_ts.get(), Some(version.row))),
                (
                    crabka_pgmvcc::version::TsVersionState::Committed { commit_ts },
                    Some(PrimaryTxnDecision::Committed(primary_commit_ts)),
                    _,
                ) if commit_ts == primary_commit_ts.get() && commit_ts <= read_ts.get() => {
                    descriptor_operation.then_some((commit_ts, Some(version.row)))
                }
                (
                    crabka_pgmvcc::version::TsVersionState::Deleted { commit_ts },
                    Some(PrimaryTxnDecision::Committed(primary_commit_ts)),
                    _,
                ) if commit_ts == primary_commit_ts.get() && commit_ts <= read_ts.get() => {
                    descriptor_operation.then_some((commit_ts, None))
                }
                // Legacy/single-range timestamp versions have no descriptor.
                (crabka_pgmvcc::version::TsVersionState::Committed { commit_ts }, None, _)
                    if commit_ts <= read_ts.get() =>
                {
                    Some((commit_ts, Some(version.row)))
                }
                (crabka_pgmvcc::version::TsVersionState::Deleted { commit_ts }, None, _)
                    if commit_ts <= read_ts.get() =>
                {
                    Some((commit_ts, None))
                }
                _ => None,
            };
            if let Some((commit_ts, row)) = candidate
                && visible
                    .as_ref()
                    .is_none_or(|(_, current_commit_ts, _)| commit_ts > *current_commit_ts)
            {
                visible = Some((version.start_ts, commit_ts, row));
            }
            i += 1;
        }
        if let Some((start_ts, _commit_ts, Some(row))) = visible {
            out.push(ScannedRow {
                rowid,
                xmin: start_ts,
                row,
            });
        }
    }
    out.sort_by_key(|row| (row.rowid, row.xmin));
    Ok(out)
}

fn physical_rowid(table: &Table, row_prefix: &[u8]) -> Result<u64, ExecError> {
    if matches!(
        table.sharding,
        Some(crabka_pgcatalog::ShardingStrategy::Hash(_))
    ) {
        return Ok(crabka_pgkv::key::bucket_rowid_of(table.id, row_prefix)?.1);
    }
    Ok(crabka_pgkv::key::rowid_of(table.id, row_prefix)?)
}

fn physical_bucket(table: &Table, row_prefix: &[u8]) -> Result<Option<u32>, ExecError> {
    if matches!(
        table.sharding,
        Some(crabka_pgcatalog::ShardingStrategy::Hash(_))
    ) {
        return Ok(Some(
            crabka_pgkv::key::bucket_rowid_of(table.id, row_prefix)?.0,
        ));
    }
    Ok(None)
}

fn scan_table_for_catalog_interval(
    kv: &dyn Kv,
    table: &Table,
    interval: RowInterval,
) -> Result<crabka_pgkv::KvScan, ExecError> {
    if matches!(
        table.sharding,
        Some(crabka_pgcatalog::ShardingStrategy::Hash(_))
    ) {
        return scan_table_interval(kv, table.id, RowInterval::ALL);
    }
    scan_table_interval(kv, table.id, interval)
}

pub(crate) fn scan_table_interval(
    kv: &dyn Kv,
    table_id: u32,
    interval: RowInterval,
) -> Result<crabka_pgkv::KvScan, ExecError> {
    let start = interval.start.map_or_else(
        || crabka_pgkv::key::table_prefix(table_id),
        |rowid| crabka_pgkv::key::row_key(table_id, rowid),
    );
    let end = interval.end.map_or_else(
        || {
            let mut end = crabka_pgkv::key::table_prefix(table_id);
            let last = end.last_mut().expect("table prefix is non-empty");
            *last = last.checked_add(1).expect("primary index has a successor");
            end
        },
        |rowid| crabka_pgkv::key::row_key(table_id, rowid),
    );
    Ok(kv.scan_range(&start, &end)?)
}

/// Evaluate an optional WHERE predicate against a row (NULL => false, like SELECT).
pub(crate) fn row_matches(
    filter: Option<&Expr>,
    scope: &Scope,
    row: &[crabka_pgtypes::Datum],
    ctx: &crate::clock::EvalCtx,
) -> Result<bool, ExecError> {
    match filter {
        None => Ok(true),
        Some(f) => match crate::eval::eval(f, scope, row, ctx)? {
            crabka_pgtypes::Datum::Bool(b) => Ok(b),
            crabka_pgtypes::Datum::Null => Ok(false),
            _ => Err(ExecError::TypeMismatch(
                "argument of WHERE must be type boolean".into(),
            )),
        },
    }
}

/// SP40 Task 14: extract per-partition offset bounds from a single-foreign-table
/// query's top-level `WHERE` for pushdown into the Kafka foreign scan.
///
/// Walks the top-level `AND` chain of the filter and, for every `_partition = N`
/// constraint, collects the `_offset` range comparisons scoped to that partition
/// into [`ScanBounds`]. This is a PURE OPTIMIZATION: anything not representable in
/// `ScanBounds` (a bare `_offset` with no `_partition =`, a `_timestamp`/`LIMIT`
/// constraint, an `OR`, a non-envelope predicate) is simply omitted here and
/// remains a residual `WHERE` filter applied locally after the scan. Callers MUST
/// keep evaluating the full `WHERE`; pushed bounds must never change results.
///
/// Conversions (the scan reads `[start, end)` per partition):
/// - `_offset >= a` → start `a`; `_offset > a` → start `a + 1` (inclusive lower).
/// - `_offset <= b` → end `b + 1`; `_offset < b` → end `b` (exclusive upper).
/// - `_offset BETWEEN a AND b` → start `a`, end `b + 1` (PG bounds are inclusive).
///
/// Only offset bounds anchored to a concrete `_partition = N` are emitted: under
/// this `ScanBounds` shape (`Vec<(partition, offset)>`) a partition-less offset
/// cannot target a partition, so it stays residual.
#[must_use]
pub(crate) fn extract_scan_bounds(filter: Option<&Expr>) -> ScanBounds {
    let mut bounds = ScanBounds::default();
    let Some(filter) = filter else {
        return bounds;
    };

    // Flatten the top-level AND chain into its conjuncts. An OR or any other
    // shape is left intact (and thus never matches a comparison below), so it
    // contributes nothing — it remains a residual filter.
    let mut conjuncts = Vec::new();
    collect_conjuncts(filter, &mut conjuncts);

    // Resolve the single `_partition = N` anchor, if exactly one is present. With
    // zero (or conflicting/multiple) partition equalities we cannot scope offsets
    // to a partition, so we push nothing and let WHERE do all the work.
    let mut partition: Option<i32> = None;
    for c in &conjuncts {
        if let Some(p) = match_partition_eq(c) {
            match partition {
                None => partition = Some(p),
                Some(prev) if prev == p => {}
                // Two different `_partition =` values → unsatisfiable as written;
                // don't try to push, let the residual WHERE return zero rows.
                Some(_) => return ScanBounds::default(),
            }
        }
    }
    let Some(partition) = partition else {
        return bounds;
    };

    // Tightest inclusive-start / exclusive-end across all offset conjuncts.
    let mut start: Option<i64> = None;
    let mut end: Option<i64> = None;
    let mut tighten_start = |v: i64| {
        start = Some(start.map_or(v, |cur: i64| cur.max(v)));
    };
    let mut tighten_end = |v: i64| {
        end = Some(end.map_or(v, |cur: i64| cur.min(v)));
    };

    for c in &conjuncts {
        match match_offset_bound(c) {
            Some(OffsetBound::StartIncl(v)) => tighten_start(v),
            Some(OffsetBound::EndExcl(v)) => tighten_end(v),
            Some(OffsetBound::Between { start: s, end: e }) => {
                tighten_start(s);
                tighten_end(e);
            }
            None => {}
        }
    }

    if let Some(s) = start {
        bounds.start_offsets.push((partition, s));
    }
    if let Some(e) = end {
        bounds.end_offsets.push((partition, e));
    }
    bounds
}

/// Flatten a top-level `AND` chain into its leaf conjuncts (depth-first). A node
/// that is not an `AND` is itself one conjunct.
fn collect_conjuncts<'a>(expr: &'a Expr, out: &mut Vec<&'a Expr>) {
    if let Expr::Binary {
        op: crabka_pgparser::ast::BinaryOp::And,
        left,
        right,
    } = expr
    {
        collect_conjuncts(left, out);
        collect_conjuncts(right, out);
    } else {
        out.push(expr);
    }
}

/// An envelope-column reference by bare name (`_partition`/`_offset`/…). Envelope
/// columns are unqualified in practice; a table-qualified `t._offset` also matches
/// on the bare name (the qualifier is the single foreign table in scope).
fn envelope_col(expr: &Expr) -> Option<&str> {
    match expr {
        Expr::Column { name, .. } => Some(name.as_str()),
        _ => None,
    }
}

/// Parse an integer literal expression to `i64`. Only bare/negated integer
/// literals are recognized (offsets/partitions are integers); anything else
/// (params, casts, non-integers) is not pushable and returns `None`.
fn int_literal(expr: &Expr) -> Option<i64> {
    match expr {
        Expr::IntLiteral(s) => s.parse::<i64>().ok(),
        Expr::Unary {
            op: crabka_pgparser::ast::UnaryOp::Neg,
            expr,
        } => int_literal(expr).map(|v| -v),
        _ => None,
    }
}

/// Match `_partition = N` (either operand order) and return `N`.
fn match_partition_eq(expr: &Expr) -> Option<i32> {
    let Expr::Binary {
        op: crabka_pgparser::ast::BinaryOp::Eq,
        left,
        right,
    } = expr
    else {
        return None;
    };
    let v = if envelope_col(left) == Some("_partition") {
        int_literal(right)?
    } else if envelope_col(right) == Some("_partition") {
        int_literal(left)?
    } else {
        return None;
    };
    i32::try_from(v).ok()
}

/// An offset constraint normalized to the scan's `[start, end)` convention.
enum OffsetBound {
    /// Inclusive lower offset.
    StartIncl(i64),
    /// Exclusive upper offset.
    EndExcl(i64),
    /// `BETWEEN a AND b` → inclusive `start`, exclusive `end`.
    Between { start: i64, end: i64 },
}

/// Match an `_offset` comparison / BETWEEN and normalize it to an [`OffsetBound`].
/// Returns `None` for anything that is not an `_offset` range constraint. The
/// comparison is recognized with the column on either side (the operator is
/// mirrored when the column is on the right).
fn match_offset_bound(expr: &Expr) -> Option<OffsetBound> {
    use crabka_pgparser::ast::BinaryOp;
    match expr {
        Expr::Binary { op, left, right } => {
            // Normalize to `_offset <op> literal` by mirroring when reversed.
            let (op, lit) = if envelope_col(left) == Some("_offset") {
                (*op, int_literal(right)?)
            } else if envelope_col(right) == Some("_offset") {
                (mirror_op(*op)?, int_literal(left)?)
            } else {
                return None;
            };
            match op {
                BinaryOp::Ge => Some(OffsetBound::StartIncl(lit)),
                BinaryOp::Gt => Some(OffsetBound::StartIncl(lit + 1)),
                BinaryOp::Le => Some(OffsetBound::EndExcl(lit + 1)),
                BinaryOp::Lt => Some(OffsetBound::EndExcl(lit)),
                _ => None,
            }
        }
        Expr::Between {
            expr,
            low,
            high,
            negated: false,
        } if envelope_col(expr) == Some("_offset") => {
            let lo = int_literal(low)?;
            let hi = int_literal(high)?;
            Some(OffsetBound::Between {
                start: lo,
                end: hi + 1,
            })
        }
        _ => None,
    }
}

/// Mirror a comparison operator for the reversed-operand form (`5 < _offset`
/// means `_offset > 5`). Only the inequalities used for offset bounds are mapped.
fn mirror_op(op: crabka_pgparser::ast::BinaryOp) -> Option<crabka_pgparser::ast::BinaryOp> {
    use crabka_pgparser::ast::BinaryOp;
    match op {
        BinaryOp::Lt => Some(BinaryOp::Gt),
        BinaryOp::Le => Some(BinaryOp::Ge),
        BinaryOp::Gt => Some(BinaryOp::Lt),
        BinaryOp::Ge => Some(BinaryOp::Le),
        _ => None,
    }
}

/// SP40 Task 14: is the FROM clause exactly one foreign base table? Only then is
/// offset pushdown applicable. A join, a comma-FROM (cross join), or a derived
/// table all keep the full-scan path. A scanner must be registered (otherwise the
/// foreign read errors anyway) and the single table's catalog entry must have
/// `foreign` metadata. Non-foreign ordinary tables return `false` (unchanged).
fn is_single_foreign_table(
    catalog_kv: &dyn Kv,
    from: &[crabka_pgparser::ast::TableExpr],
    ctes: &crate::cte::CteContext,
    fctx: ForeignCtx,
) -> bool {
    if fctx.scanner.is_none() {
        return false;
    }
    let resolution = fctx.resolution;
    let [
        crabka_pgparser::ast::TableExpr::Table {
            name,
            columns: None,
            sample: None,
            ..
        },
    ] = from
    else {
        return false;
    };
    if name.schema.is_none() && ctes.lookup(&name.name).is_some() {
        return false;
    }
    resolve_relation(catalog_kv, resolution, name, SchemaDisposition::Reference).is_ok_and(|name| {
        crabka_pgcatalog::get_table(catalog_kv, &name).is_ok_and(|t| t.foreign.is_some())
    })
}

/// Build the relation for one FROM list (comma items folded as cross joins).
fn build_from(
    read_ctx: &crate::subquery::SubCtx<'_>,
    from: &[crabka_pgparser::ast::TableExpr],
    // SP40 Task 14: pushed-down offset bounds for the single-foreign-table case.
    // `Some` only when `from` is exactly one entry (set by `select_to_relation`);
    // joins/comma-FROM never see it and keep the full-scan + local-filter path.
    bounds: Option<&ScanBounds>,
    scan_plan: Option<&crate::plan_dist::DistributedScanPlan>,
    filter: Option<&Expr>,
) -> Result<Relation, ExecError> {
    let mut iter = from.iter();
    let first = iter
        .next()
        .ok_or_else(|| ExecError::Unsupported("build_from on empty FROM".into()))?;
    // Nothing of this query level is in scope for its first item, so the only
    // aggregate the level rule can reject there is one that reads no variable at
    // all — which an empty scope answers exactly.
    reject_from_clause_aggregates(
        read_ctx,
        first,
        &crabka_pgparser::ast::JoinConstraint::None,
        &Scope::empty(),
    )?;
    let mut acc = build_table_expr(read_ctx, first, bounds, scan_plan, filter)?;
    for te in iter {
        // A comma-FROM (multiple tables) is a cross join — no single-table
        // pushdown applies, so subsequent items always scan in full.
        acc = append_from_item(
            read_ctx,
            acc,
            te,
            crabka_pgparser::ast::JoinKind::Cross,
            &crabka_pgparser::ast::JoinConstraint::None,
            filter,
        )?;
    }
    Ok(acc)
}

/// The relationship between a reference that failed to resolve and the scope one
/// query level out that could have supplied it — all that separates
/// `PostgreSQL`'s wordings for an out-of-reach FROM-clause entry.
#[derive(Clone, Copy)]
enum OuterReference {
    /// A sibling FROM item of the same query level. `LATERAL` would bring it
    /// into view, so `PostgreSQL` offers that as the remedy.
    Sibling,
    /// The relation an `UPDATE`/`DELETE` is targeting, named from a `FROM` or
    /// `USING` item that was not written `LATERAL`. No remedy exists.
    Target,
    /// The same target, named from an item that *was* written `LATERAL`. The
    /// name is then found and rejected rather than never found, which in
    /// `PostgreSQL` is a different check and a differently shaped message.
    LateralTarget,
}

/// Was `LATERAL` written on this FROM item?
///
/// Only the keyword counts, not the implicit laterality of a function item: it
/// is what `PostgreSQL` uses to decide whether the target relation's name is
/// looked up at all, and so which of the two prohibitions reports it.
fn item_is_lateral(te: &crabka_pgparser::ast::TableExpr) -> bool {
    use crabka_pgparser::ast::TableExpr;
    match te {
        TableExpr::Derived { lateral, .. } | TableExpr::Function { lateral, .. } => *lateral,
        TableExpr::JsonTable(table) => table.lateral,
        TableExpr::Table { .. } => false,
        TableExpr::Join { left, right, .. } => item_is_lateral(left) || item_is_lateral(right),
    }
}

impl OuterReference {
    fn note(self) -> crate::error::FromEntryNote {
        use crate::error::FromEntryNote;
        match self {
            Self::Sibling => FromEntryNote::MarkSubqueryLateral,
            Self::Target => FromEntryNote::TargetRelation,
            Self::LateralTarget => FromEntryNote::LateralTargetRelation,
        }
    }
}

/// The qualifier of the one visible column in `scope` named `name`.
///
/// `None` when no column or more than one carries the name: `PostgreSQL` names a
/// single inaccessible match and says "there are columns named …" for several,
/// and the several case is not one this engine reaches yet.
fn sole_owner(scope: &Scope, name: &str) -> Option<String> {
    let mut owner = None;
    for column in &scope.columns {
        if column.name != name {
            continue;
        }
        // A USING/NATURAL-coalesced column belongs to the join rather than to
        // one table, so there is no name to put in the explanation.
        let qualifier = column.qualifier.as_deref()?;
        if qualifier.starts_with('$') {
            continue;
        }
        if owner.is_some() {
            return None;
        }
        owner = Some(qualifier.to_owned());
    }
    owner
}

/// Re-word a resolution failure that `outer` explains.
///
/// gres resolves a FROM item against its own scope alone, so a reference to an
/// entry one query level out fails with the bare "missing FROM-clause entry" or
/// "column does not exist". `PostgreSQL` searches the whole range table before
/// reporting and says so when it finds the name somewhere the reference cannot
/// see. Only the error already on its way out is rewritten — a name `outer` does
/// not supply passes through untouched.
fn explain_outer_reference(error: ExecError, outer: &Scope, kind: OuterReference) -> ExecError {
    match error {
        ExecError::MissingFromEntry(table)
            if outer
                .columns
                .iter()
                .any(|column| column.qualifier.as_deref() == Some(table.as_str())) =>
        {
            ExecError::InvalidFromEntry {
                table,
                note: kind.note(),
            }
        }
        ExecError::UndefinedColumn(column) => match sole_owner(outer, &column) {
            // Written `LATERAL`, the target relation's name does resolve, and
            // what rejects it names the relation rather than the column.
            Some(table) if matches!(kind, OuterReference::LateralTarget) => {
                ExecError::InvalidFromEntry {
                    table,
                    note: kind.note(),
                }
            }
            Some(table) => ExecError::InaccessibleColumn {
                column,
                table,
                lateral_would_help: matches!(kind, OuterReference::Sibling),
            },
            None => ExecError::UndefinedColumn(column),
        },
        other => other,
    }
}

/// Reject an aggregate in `te` — or in the join constraint attaching it — that
/// `PostgreSQL` assigns to the query level whose FROM clause `outer` describes.
///
/// Runs once per FROM item rather than once per row: a lateral item over a
/// ten-thousand-row outer relation is rebuilt ten thousand times, and the level
/// an aggregate inside it belongs to is a property of the text, not the row.
fn reject_from_clause_aggregates(
    read_ctx: &crate::subquery::SubCtx<'_>,
    te: &crabka_pgparser::ast::TableExpr,
    constraint: &crabka_pgparser::ast::JoinConstraint,
    outer: &Scope,
) -> Result<(), ExecError> {
    FromClauseAggregatePass {
        levels: AggregateLevels {
            read_ctx,
            statement: outer,
        },
    }
    .check(te, constraint)
}

/// Join one more FROM item onto the accumulated relation.
///
/// An ordinary item materializes once and joins; a lateral one is rebuilt for
/// every accumulated row, with that row's values substituted for the outer
/// column references inside it.
fn append_from_item(
    read_ctx: &crate::subquery::SubCtx<'_>,
    acc: Relation,
    te: &crabka_pgparser::ast::TableExpr,
    kind: crabka_pgparser::ast::JoinKind,
    constraint: &crabka_pgparser::ast::JoinConstraint,
    filter: Option<&Expr>,
) -> Result<Relation, ExecError> {
    reject_from_clause_aggregates(read_ctx, te, constraint, &acc.scope)?;
    if !is_lateral_item(te, &acc.scope) {
        let mut acc = acc;
        // Without `LATERAL` the items already in `acc` are out of this one's
        // reach, so a name only they supply is the thing to report, not a name
        // that is simply missing. An item that *was* written `LATERAL` somewhere
        // inside is excluded: `PostgreSQL` offers the remedy only when it is not
        // already taken, and a failure under one is this engine's own.
        let mut next = build_table_expr(read_ctx, te, None, None, None).map_err(|error| {
            if item_is_lateral(te) {
                error
            } else {
                explain_outer_reference(error, &acc.scope, OuterReference::Sibling)
            }
        })?;
        if let Some(filter) = filter {
            push_local_where(&mut acc, &mut next, kind, filter, read_ctx.eval_ctx)?;
        }
        let pushed_constraint = filter
            .filter(|filter| {
                matches!(kind, crabka_pgparser::ast::JoinKind::Cross)
                    && matches!(constraint, crabka_pgparser::ast::JoinConstraint::None)
                    && immutable_row_predicate(filter)
                    && {
                        let mut scope = acc.scope.clone();
                        scope.columns.extend(next.scope.columns.iter().cloned());
                        crate::eval::check_predicate_resolves(filter, &scope).is_ok()
                    }
            })
            .map(|filter| crabka_pgparser::ast::JoinConstraint::On(filter.clone()));
        return join_relations(
            acc,
            next,
            kind,
            pushed_constraint.as_ref().unwrap_or(constraint),
            read_ctx.eval_ctx,
            read_ctx.join_policy(),
        );
    }
    lateral_join(read_ctx, acc, te, kind, constraint)
}

/// Apply immutable top-level WHERE conjuncts that bind to exactly one join side
/// before materializing an inner/cross product. The complete WHERE is evaluated
/// again after FROM, so this optimization cannot weaken filtering.
/// Apply the single-relation conjuncts of a `WHERE` to one side *before* the
/// join, so the join walks the rows that can still survive it.
///
/// This only ever pre-applies a filter the caller runs again over the joined
/// relation, so it can never keep a row the full `WHERE` would drop. What it
/// must not do is drop a row the `WHERE` would have kept, and that is what the
/// join kind decides: a predicate on a *null-preserved* side is safe, because
/// such a row carries its own columns unchanged into the output whether it
/// matched or was NULL-padded, so it fails the predicate either way. A
/// predicate on the *nullable* side is not — dropping those rows early would
/// suppress the NULL-padded row the outer join owes for an unmatched partner.
fn push_local_where(
    left: &mut Relation,
    right: &mut Relation,
    kind: crabka_pgparser::ast::JoinKind,
    filter: &Expr,
    ctx: &crate::clock::EvalCtx,
) -> Result<(), ExecError> {
    use crabka_pgparser::ast::JoinKind;
    let (push_left, push_right) = match kind {
        JoinKind::Inner | JoinKind::Cross => (true, true),
        JoinKind::Left => (true, false),
        JoinKind::Right => (false, true),
        JoinKind::Full => return Ok(()),
    };
    let mut conjuncts = Vec::new();
    collect_conjuncts(filter, &mut conjuncts);
    for conjunct in conjuncts {
        if !immutable_row_predicate(conjunct) || !leakproof_predicate(conjunct) {
            continue;
        }
        let left_only = expr_references_scope(conjunct, &left.scope)
            && crate::eval::check_predicate_resolves(conjunct, &left.scope).is_ok();
        let right_only = expr_references_scope(conjunct, &right.scope)
            && crate::eval::check_predicate_resolves(conjunct, &right.scope).is_ok();
        match (left_only, right_only) {
            (true, false) if push_left => filter_relation(left, conjunct, ctx)?,
            (false, true) if push_right => filter_relation(right, conjunct, ctx)?,
            _ => {}
        }
    }
    Ok(())
}

/// Whether a predicate may be evaluated *before* the rows a security policy
/// would hide — `PostgreSQL`'s `proleakproof`.
///
/// Row-level security makes the difference observable: the upstream
/// `rowsecurity` test defines an `f_leak(text)` that `RAISE NOTICE`s whatever it
/// is handed, and asserts it never sees a row the policy filters out. Pushing a
/// call to it under the policy would print exactly those titles. Casts and
/// division can leak through their error messages the same way, so only
/// columns, literals and the total operators are allowed across.
fn leakproof_predicate(expr: &Expr) -> bool {
    let mut leakproof = true;
    crate::grouping::visit_expr(expr, &mut |node| {
        leakproof &= !matches!(
            node,
            Expr::Func(_)
                | Expr::Cast { .. }
                | Expr::ScalarSubquery(_)
                | Expr::Exists(_)
                | Expr::InSubquery { .. }
                | Expr::Quantified { .. }
                | Expr::ArraySubquery(_)
        ) && !matches!(
            node,
            Expr::Binary {
                op: crabka_pgparser::ast::BinaryOp::Div | crabka_pgparser::ast::BinaryOp::Mod,
                ..
            }
        );
    });
    leakproof
}

fn immutable_row_predicate(expr: &Expr) -> bool {
    let mut immutable = !crate::agg::contains_aggregate(expr);
    crate::grouping::visit_expr(expr, &mut |node| {
        immutable &= !matches!(
            node,
            Expr::ScalarSubquery(_)
                | Expr::Exists(_)
                | Expr::InSubquery { .. }
                | Expr::Quantified { .. }
                | Expr::ArraySubquery(_)
        ) && !matches!(node, Expr::Func(call) if !is_immutable_function(&call.name));
    });
    immutable
}

fn filter_relation(
    relation: &mut Relation,
    predicate: &Expr,
    ctx: &crate::clock::EvalCtx,
) -> Result<(), ExecError> {
    let rows = std::mem::take(&mut relation.rows);
    let predicate = crate::bind::BoundExpr::new(predicate, &relation.scope)?;
    for row in rows {
        if row_matches(Some(predicate.expr()), &relation.scope, &row, ctx)? {
            relation.rows.push(row);
        }
    }
    Ok(())
}

/// Is this FROM item correlated with the columns already in scope?
///
/// `LATERAL` says so explicitly; `PostgreSQL` also makes a *function* item
/// lateral implicitly, so `FROM t, unnest(t.tags)` needs no keyword. A derived
/// table is never implicitly lateral. A reference to an earlier item without
/// `LATERAL` is an error there, and a reference left alone produces it.
fn is_lateral_item(te: &crabka_pgparser::ast::TableExpr, outer: &Scope) -> bool {
    use crabka_pgparser::ast::TableExpr;
    match te {
        TableExpr::Derived { lateral, .. } => *lateral,
        TableExpr::Function {
            lateral, functions, ..
        } => {
            *lateral
                || functions
                    .iter()
                    .flat_map(|call| call.args.iter())
                    .any(|arg| expr_references_scope(arg, outer))
        }
        // `JSON_TABLE` is implicitly lateral in PostgreSQL exactly as a function
        // item is, so a context or PASSING expression that reads an earlier item
        // makes it correlated whether or not the keyword was written.
        TableExpr::JsonTable(table) => crate::jsontable::references_scope(table, outer),
        TableExpr::Table { .. } | TableExpr::Join { .. } => false,
    }
}

/// Re-evaluate `te` once per accumulated row and concatenate the results.
///
/// Each iteration joins a one-row left relation against the specialized right
/// side, so `ON`/`USING`/`NATURAL` matching and LEFT-join NULL padding are the
/// ordinary join code. So `LEFT JOIN LATERAL` keeps an outer row whose lateral
/// side produced nothing, exactly as `PostgreSQL` does.
///
/// `RIGHT`/`FULL JOIN LATERAL` is only an error when the lateral item *does*
/// reference the other side: `PostgreSQL` accepts the keyword itself and runs
/// the join, because an item that reads nothing from the left needs no left row
/// to be evaluated against.
fn lateral_join(
    read_ctx: &crate::subquery::SubCtx<'_>,
    acc: Relation,
    te: &crabka_pgparser::ast::TableExpr,
    kind: crabka_pgparser::ast::JoinKind,
    constraint: &crabka_pgparser::ast::JoinConstraint,
) -> Result<Relation, ExecError> {
    use crabka_pgparser::ast::JoinKind;
    let ctx = read_ctx.eval_ctx;
    let mut binder =
        LateralBinder::new(read_ctx.catalog_kv, read_ctx.fctx.resolution, read_ctx.ctes);
    if matches!(kind, JoinKind::Right | JoinKind::Full) {
        let nulls = vec![Datum::Null; acc.scope.width()];
        let (specialized, referenced) = binder.bind(te, &acc.scope, &nulls);
        if let Some(relation) = referenced {
            // A lateral reference on the nullable side would have to be evaluated
            // for rows that do not exist yet, so PostgreSQL rejects the reference
            // rather than the join.
            return Err(ExecError::InvalidFromEntry {
                table: relation,
                note: crate::error::FromEntryNote::CombiningJoinType,
            });
        }
        // Nothing was correlated, so the item is an ordinary relation.
        let right = build_table_expr(read_ctx, &specialized, None, None, None)?;
        return join_relations(acc, right, kind, constraint, ctx, read_ctx.join_policy());
    }
    let mut rows: Vec<Vec<Datum>> = Vec::new();
    let mut scope: Option<Scope> = None;
    let mut bytes = 0usize;
    struct CachedRight {
        specialized: crabka_pgparser::ast::TableExpr,
        relation: Relation,
        index: PreparedJoinIndex,
    }
    let mut cache: Vec<CachedRight> = Vec::new();
    let mut cache_bytes = 0usize;
    for outer_row in &acc.rows {
        let (specialized, _) = binder.bind(te, &acc.scope, outer_row);
        let one = Relation {
            scope: acc.scope.clone(),
            rows: vec![outer_row.clone()],
        };
        let joined = if let Some(cached) = cache
            .iter()
            .find(|cached| cached.specialized == specialized)
        {
            join_relations_prepared(
                one,
                &cached.relation,
                kind,
                constraint,
                ctx,
                read_ctx.join_policy(),
                &cached.index,
            )?
        } else {
            let right = build_table_expr(read_ctx, &specialized, None, None, None)?;
            let right_bytes = right
                .rows
                .iter()
                .map(|row| crate::scanner::datum_row_bytes(row))
                .sum::<usize>();
            // ponytail: cap memoization; a planner-level lateral flattening is
            // the upgrade if workloads need more than 64 stable variants.
            let retained_without_index = cache_bytes.saturating_add(right_bytes);
            let mut index = if lateral_cacheable(te)
                && cache.len() < 64
                && !crate::scanner::exceeds_query_memory(
                    retained_without_index,
                    read_ctx.blocking_query_memory,
                ) {
                let remaining = read_ctx
                    .blocking_query_memory
                    .bytes_u64()
                    .saturating_sub(u64::try_from(retained_without_index).unwrap_or(u64::MAX));
                Some(prepare_join_index(
                    &acc,
                    &right,
                    constraint,
                    ctx,
                    crabka_units::ByteSize::from_bytes(remaining),
                )?)
            } else {
                None
            };
            let retained_bytes = right_bytes
                .saturating_add(index.as_ref().map_or(0, PreparedJoinIndex::estimated_bytes));
            // Memoizing the inner relation deliberately does NOT require the
            // index over the outer one. Re-running `build_table_expr` is the
            // expensive half — for a lateral over `tenk1` it is a full scan per
            // outer row — while an index-less entry still skips that and probes
            // by scanning a relation that is usually a row or two. Requiring
            // the index meant that under the 20 MiB policy the certification
            // runs with, nothing was ever cached and `memoize` took 41% of the
            // suite's wall clock.
            let can_cache = lateral_cacheable(te)
                && cache.len() < 64
                && !crate::scanner::exceeds_query_memory(
                    cache_bytes.saturating_add(retained_bytes),
                    read_ctx.blocking_query_memory,
                );
            if can_cache {
                let index = index.take().unwrap_or_else(PreparedJoinIndex::none);
                cache.push(CachedRight {
                    specialized,
                    relation: right,
                    index,
                });
                cache_bytes = cache_bytes.saturating_add(retained_bytes);
                let cached = cache.last().expect("the cache entry was just pushed");
                join_relations_prepared(
                    one,
                    &cached.relation,
                    kind,
                    constraint,
                    ctx,
                    read_ctx.join_policy(),
                    &cached.index,
                )?
            } else if let Some(index) = index {
                let mut index = index;
                index.discard_index();
                join_relations_prepared(
                    one,
                    &right,
                    kind,
                    constraint,
                    ctx,
                    read_ctx.join_policy(),
                    &index,
                )?
            } else {
                join_relations(one, right, kind, constraint, ctx, read_ctx.join_policy())?
            }
        };
        for row in &joined.rows {
            bytes = bytes.saturating_add(crate::scanner::datum_row_bytes(row));
        }
        if crate::scanner::exceeds_query_memory(bytes, read_ctx.blocking_query_memory) {
            return Err(crate::scanner::memory_budget_exceeded());
        }
        rows.extend(joined.rows);
        scope = Some(joined.scope);
    }
    // With no outer rows there is nothing to correlate against, but the output
    // still needs the lateral side's columns: build it once against a row of
    // NULLs, which yields its schema without depending on any outer value.
    let scope = match scope {
        Some(scope) => scope,
        None => {
            let nulls = vec![Datum::Null; acc.scope.width()];
            let (specialized, _) = binder.bind(te, &acc.scope, &nulls);
            let right = build_table_expr(read_ctx, &specialized, None, None, None)?;
            join_relations(
                Relation {
                    scope: acc.scope.clone(),
                    rows: Vec::new(),
                },
                right,
                kind,
                constraint,
                ctx,
                read_ctx.join_policy(),
            )?
            .scope
        }
    };
    Ok(Relation { scope, rows })
}

fn lateral_cacheable(te: &crabka_pgparser::ast::TableExpr) -> bool {
    use crabka_pgparser::ast::{DistinctClause, QueryBody, SetExpr, TableExpr};
    let TableExpr::Derived {
        subquery,
        lateral: true,
        ..
    } = te
    else {
        return false;
    };
    let SetExpr::Query(QueryBody::Select(select)) = &subquery.body else {
        return false;
    };
    subquery.with.is_none()
        && subquery.order_by.is_empty()
        && subquery.limit.is_none()
        && subquery
            .offset
            .as_ref()
            .is_none_or(|offset| matches!(offset, Expr::IntLiteral(value) if value == "0"))
        && subquery.locking.is_none()
        && select.from.len() == 1
        && matches!(&select.from[0], TableExpr::Table { .. })
        && matches!(select.distinct, DistinctClause::All)
        && select.group_by.is_empty()
        && select.grouping.is_none()
        && select.having.is_none()
        && select.windows.is_empty()
        && select.window_calls.is_empty()
        && select.order_by.is_empty()
        && select.limit.is_none()
        && select.offset.is_none()
        && select.locking.is_none()
        && select.projection.iter().all(|item| match item {
            SelectItem::Wildcard | SelectItem::QualifiedWildcard(_) => true,
            SelectItem::Expr { expr, .. } => lateral_cacheable_expr(expr),
        })
        && select.filter.as_ref().is_none_or(lateral_cacheable_expr)
}

fn lateral_cacheable_expr(expr: &Expr) -> bool {
    match expr {
        Expr::IntLiteral(_)
        | Expr::NumericLiteral(_)
        | Expr::StringLiteral(_)
        | Expr::BitStringLiteral(_)
        | Expr::BoolLiteral(_)
        | Expr::NullLiteral
        | Expr::Column { .. }
        | Expr::Param(_)
        | Expr::Const { .. } => true,
        Expr::Unary { expr, .. } | Expr::Cast { expr, .. } | Expr::Collate { expr, .. } => {
            lateral_cacheable_expr(expr)
        }
        Expr::Binary { left, right, .. } => {
            lateral_cacheable_expr(left) && lateral_cacheable_expr(right)
        }
        _ => false,
    }
}

/// Does `expr` name a column that resolves in `scope`?
///
/// Only a reference that actually binds counts, so an unqualified name that is
/// ambiguous or missing is left for ordinary resolution to report.
pub(crate) fn expr_references_scope(expr: &Expr, scope: &Scope) -> bool {
    if let Expr::Column { table, name } = expr {
        return scope.resolve(table.as_deref(), name).is_ok();
    }
    // A subquery argument is over-approximated: a shadowed reference inside one
    // would still count. That only ever adds the per-row rebuild, which produces
    // the same rows as materializing once.
    expr_children(expr)
        .into_iter()
        .any(|child| expr_references_scope(child, scope))
}

/// The immediate sub-expressions of `expr` — including those reached through a
/// subquery, which are visited by way of the subquery's own clauses.
pub(crate) fn expr_children(expr: &Expr) -> Vec<&Expr> {
    let mut owned: Vec<&Expr> = Vec::new();
    match expr {
        Expr::Unary { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Quantified { expr, .. }
        | Expr::InSubquery { expr, .. } => owned.push(expr),
        Expr::Binary { left, right, .. } => owned.extend([left.as_ref(), right.as_ref()]),
        Expr::Func(call) => {
            if let FuncArgs::Exprs(args) = &call.args {
                owned.extend(args);
            }
            // An aggregate's sort keys are sub-expressions like any other: they
            // name columns (which privilege collection must see), they may hold
            // a subquery (which planning must reach), and they are part of what
            // a stored view depends on.
            owned.extend(call.order_by.iter().map(|item| &item.expr));
            owned.extend(call.filter.iter().map(std::convert::AsRef::as_ref));
        }
        Expr::InList { expr, list, .. } => {
            owned.push(expr);
            owned.extend(list);
        }
        Expr::Between {
            expr, low, high, ..
        } => owned.extend([expr.as_ref(), low.as_ref(), high.as_ref()]),
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            owned.extend([expr.as_ref(), pattern.as_ref()]);
            owned.extend(escape.iter().map(std::convert::AsRef::as_ref));
        }
        Expr::Case {
            operand,
            whens,
            else_result,
        } => {
            owned.extend(operand.iter().map(std::convert::AsRef::as_ref));
            owned.extend(whens.iter().flat_map(|(when, then)| [when, then]));
            owned.extend(else_result.iter().map(std::convert::AsRef::as_ref));
        }
        Expr::QuantifiedArray { expr, array, .. } => {
            owned.extend([expr.as_ref(), array.as_ref()]);
        }
        Expr::ArrayLiteral(items) | Expr::Row(items) => owned.extend(items),
        Expr::Subscript { base, index } => owned.extend([base.as_ref(), index.as_ref()]),
        Expr::ArrayRef { base, subscripts } => {
            owned.push(base.as_ref());
            owned.extend(subscripts.iter().flat_map(ArraySubscript::bounds));
        }
        Expr::ArraySubquery(_) => {}
        Expr::FieldSelect { base, .. } | Expr::FieldSelectAll(base) => owned.push(base.as_ref()),
        Expr::SqlJson(json) => owned.extend(json.children()),
        Expr::IntLiteral(_)
        | Expr::NumericLiteral(_)
        | Expr::StringLiteral(_)
        | Expr::BitStringLiteral(_)
        | Expr::BoolLiteral(_)
        | Expr::NullLiteral
        | Expr::Column { .. }
        | Expr::Param(_)
        | Expr::Default
        | Expr::ScalarSubquery(_)
        | Expr::Exists(_)
        | Expr::Const { .. } => {}
    }
    owned
}

/// The mutable counterpart of [`expr_children`].
pub(crate) fn expr_children_mut(expr: &mut Expr) -> Vec<&mut Expr> {
    let mut owned: Vec<&mut Expr> = Vec::new();
    match expr {
        Expr::Unary { expr, .. }
        | Expr::Cast { expr, .. }
        | Expr::Collate { expr, .. }
        | Expr::IsNull { expr, .. }
        | Expr::Quantified { expr, .. }
        | Expr::InSubquery { expr, .. } => owned.push(expr),
        Expr::Binary { left, right, .. } => owned.extend([left.as_mut(), right.as_mut()]),
        Expr::Func(call) => {
            if let FuncArgs::Exprs(args) = &mut call.args {
                owned.extend(args);
            }
            owned.extend(call.order_by.iter_mut().map(|item| &mut item.expr));
            owned.extend(call.filter.iter_mut().map(std::convert::AsMut::as_mut));
        }
        Expr::InList { expr, list, .. } => {
            owned.push(expr);
            owned.extend(list);
        }
        Expr::Between {
            expr, low, high, ..
        } => owned.extend([expr.as_mut(), low.as_mut(), high.as_mut()]),
        Expr::Like {
            expr,
            pattern,
            escape,
            ..
        } => {
            owned.extend([expr.as_mut(), pattern.as_mut()]);
            owned.extend(escape.iter_mut().map(std::convert::AsMut::as_mut));
        }
        Expr::Case {
            operand,
            whens,
            else_result,
        } => {
            owned.extend(operand.iter_mut().map(std::convert::AsMut::as_mut));
            owned.extend(whens.iter_mut().flat_map(|(when, then)| [when, then]));
            owned.extend(else_result.iter_mut().map(std::convert::AsMut::as_mut));
        }
        Expr::QuantifiedArray { expr, array, .. } => {
            owned.extend([expr.as_mut(), array.as_mut()]);
        }
        Expr::ArrayLiteral(items) | Expr::Row(items) => owned.extend(items),
        Expr::Subscript { base, index } => owned.extend([base.as_mut(), index.as_mut()]),
        Expr::ArrayRef { base, subscripts } => {
            owned.push(base.as_mut());
            owned.extend(subscripts.iter_mut().flat_map(ArraySubscript::bounds_mut));
        }
        Expr::ArraySubquery(_) => {}
        Expr::FieldSelect { base, .. } | Expr::FieldSelectAll(base) => owned.push(base.as_mut()),
        Expr::SqlJson(json) => owned.extend(json.children_mut()),
        Expr::IntLiteral(_)
        | Expr::NumericLiteral(_)
        | Expr::StringLiteral(_)
        | Expr::BitStringLiteral(_)
        | Expr::BoolLiteral(_)
        | Expr::NullLiteral
        | Expr::Column { .. }
        | Expr::Param(_)
        | Expr::Default
        | Expr::ScalarSubquery(_)
        | Expr::Exists(_)
        | Expr::Const { .. } => {}
    }
    owned
}

/// The query expressions directly under `expr` (its subqueries).
///
/// [`expr_children`] stops at a subquery, because an inner query is its own
/// scope; a walk that has to see inside one — collecting the relations a view
/// body reads, say — continues through here.
pub(crate) fn query_children(expr: &Expr) -> Vec<&crabka_pgparser::ast::QueryExpr> {
    match expr {
        Expr::ScalarSubquery(query) | Expr::ArraySubquery(query) | Expr::Exists(query) => {
            vec![query]
        }
        Expr::InSubquery { subquery, .. } | Expr::Quantified { subquery, .. } => vec![subquery],
        _ => Vec::new(),
    }
}

/// The mutable counterpart of [`query_children`].
pub(crate) fn query_children_mut(expr: &mut Expr) -> Vec<&mut crabka_pgparser::ast::QueryExpr> {
    match expr {
        Expr::ScalarSubquery(query) | Expr::ArraySubquery(query) | Expr::Exists(query) => {
            vec![query]
        }
        Expr::InSubquery { subquery, .. } | Expr::Quantified { subquery, .. } => vec![subquery],
        _ => Vec::new(),
    }
}

/// The read handles a bind pass needs to describe an inner FROM clause, plus the
/// per-lateral-join cache of those descriptions.
///
/// The FROM structure of a lateral item is identical for every outer row, so the
/// blocks are described once (in walk order) and reused for the remaining rows.
struct LateralBinder<'a> {
    catalog_kv: &'a dyn Kv,
    resolution: &'a crate::relname::ResolutionScope,
    ctes: &'a crate::cte::CteContext,
    /// The column names each query block's FROM provides, in walk order, per
    /// walked expression. `None` for a block whose FROM could not be described.
    ///
    /// The index is only meaningful within one expression: a statement that
    /// defers several correlated expressions walks a different set of query
    /// blocks for each, and one shared cache would hand the second expression
    /// the first one's FROM.
    described: Vec<Vec<Option<Vec<String>>>>,
    /// Which walked expression [`described`](Self::described) is caching for.
    walk: usize,
    /// Uncorrelated subqueries nested in a deferred lazy expression. Each is
    /// initialized on first use and then reused for the rest of the statement.
    initplans: Vec<LazyInitPlan>,
    /// Narrow correlated scalar lookups, materialized only if their expression
    /// is reached and then reused for the rest of the statement.
    scalar_lookups: Vec<CorrelatedScalarLookup>,
}

const INITPLAN_MARKER: &str = "\0crabka_initplan";
const INITPLAN_LHS_MARKER: &str = "\0crabka_initplan_lhs";
const SCALAR_LOOKUP_MARKER: &str = "\0crabka_scalar_lookup";

struct LazyInitPlan {
    template: Expr,
    result_type: ColumnType,
    resolved: Option<Expr>,
}

struct CorrelatedScalarLookup {
    query: crabka_pgparser::ast::QueryExpr,
    /// The inner relation, behind the proof that the session may read it and
    /// that no policy filters it.
    ///
    /// This scan answers every outer row out of one hash of the whole inner
    /// relation, so it has to be the whole relation the session is entitled
    /// to — there is no per-row read left for a gate to sit in front of.
    /// Keeping the relation only inside the proof is what stops a later edit
    /// scanning it without one; [`plan_correlated_scalar_lookup`] is the only
    /// place the proof is obtained, and it declines the pushdown when it
    /// cannot be.
    table: crate::rls::UnrestrictedRelation,
    key_column: usize,
    result_column: usize,
    result_type: ColumnType,
    outer_on_left: bool,
    state: CorrelatedScalarLookupState,
}

fn build_correlated_scalar_lookup(
    read_ctx: &crate::subquery::SubCtx<'_>,
    plan: &CorrelatedScalarLookup,
) -> Result<CorrelatedScalarLookupState, ExecError> {
    // The gated relation, which is the only one this function can name.
    let table = plan.table.get();
    // The lookup projects columns straight out of storage, where a virtual
    // generated column is a NULL placeholder; the ordinary scan materializes it.
    if has_virtual_generated(table) {
        return Ok(CorrelatedScalarLookupState::Fallback);
    }
    let projected_columns = if plan.key_column == plan.result_column {
        vec![plan.key_column]
    } else {
        vec![plan.key_column, plan.result_column]
    };
    let projected_regclass_columns = projected_columns
        .iter()
        .enumerate()
        .filter_map(|(projected, source)| {
            holds_reg(table.columns[*source].ty).map(|kind| (projected, kind))
        })
        .collect::<Vec<_>>();
    let result_column = usize::from(plan.key_column != plan.result_column);
    let scanned = match crate::scanner::collect_cursor_bounded(
        read_ctx.range_scanner,
        ScanRequest {
            local: read_ctx.kv,
            global: read_ctx.global,
            global_snapshot: read_ctx.gsnap,
            snapshot: read_ctx.snapshot,
            own_xid: read_ctx.own,
            read_ts: None,
            own_start_ts: None,
            table,
            interval: RowInterval::ALL,
            predicate: PredicatePushdown::FullScan,
            projection: crate::ProjectionPushdown::Columns(projected_columns),
            partial_aggregate: None,
            top_k: None,
        },
        read_ctx.blocking_query_memory,
    ) {
        Ok(rows) => rows,
        Err(ExecError::Unsupported(_)) => return Ok(CorrelatedScalarLookupState::Fallback),
        Err(ExecError::Remote(error)) if error.code == "53200" => {
            return Ok(CorrelatedScalarLookupState::Fallback);
        }
        Err(error) => return Err(error),
    };
    let mut rows: Vec<Vec<Datum>> = scanned.into_iter().map(|row| row.row).collect();
    resolve_regclass_at(read_ctx.catalog_kv, &projected_regclass_columns, &mut rows)?;
    let saw_rows = !rows.is_empty();
    let mut values = HashMap::new();
    let mut bytes = rows.iter().fold(0usize, |used, row| {
        used.saturating_add(std::mem::size_of::<ScannedRow>())
            .saturating_add(crate::scanner::datum_row_bytes(row))
    });
    if crate::scanner::exceeds_query_memory(bytes, read_ctx.blocking_query_memory) {
        return Ok(CorrelatedScalarLookupState::Fallback);
    }
    for row in &rows {
        let Some(key) = row.first() else {
            return Err(ExecError::Unsupported(
                "correlated scalar lookup key is outside the scanned row".into(),
            ));
        };
        if key.is_null() {
            continue;
        }
        if !crate::join::hashes_like_it_compares(key) {
            return Ok(CorrelatedScalarLookupState::Fallback);
        }
        if values.contains_key(key) {
            continue;
        }
        let Some(value) = row.get(result_column) else {
            return Err(ExecError::Unsupported(
                "correlated scalar lookup result is outside the scanned row".into(),
            ));
        };
        bytes = bytes
            .saturating_add(crate::scanner::datum_row_bytes(std::slice::from_ref(key)))
            .saturating_add(crate::scanner::datum_row_bytes(std::slice::from_ref(value)));
        if crate::scanner::exceeds_query_memory(bytes, read_ctx.blocking_query_memory) {
            return Ok(CorrelatedScalarLookupState::Fallback);
        }
        values.insert(key.clone(), value.clone());
    }
    Ok(CorrelatedScalarLookupState::Ready { values, saw_rows })
}

fn resolve_correlated_scalar_fallback(
    read_ctx: &crate::subquery::SubCtx<'_>,
    plan: &CorrelatedScalarLookup,
    key_expr: &Expr,
) -> Result<Expr, ExecError> {
    let mut query = plan.query.clone();
    let crabka_pgparser::ast::SetExpr::Query(crabka_pgparser::ast::QueryBody::Select(select)) =
        &mut query.body
    else {
        unreachable!("a scalar lookup plan always has one SELECT body")
    };
    let Expr::Binary { left, right, .. } = select
        .filter
        .as_mut()
        .expect("a scalar lookup plan always has an equality filter")
    else {
        unreachable!("a scalar lookup plan always has an equality filter")
    };
    if plan.outer_on_left {
        **left = key_expr.clone();
    } else {
        **right = key_expr.clone();
    }
    crate::subquery::resolve_expr(read_ctx, &Expr::ScalarSubquery(Box::new(query)))
}

enum CorrelatedScalarLookupState {
    Uninitialized,
    Ready {
        values: HashMap<Datum, Datum>,
        saw_rows: bool,
    },
    Fallback,
}

impl<'a> LateralBinder<'a> {
    fn new(
        catalog_kv: &'a dyn Kv,
        resolution: &'a crate::relname::ResolutionScope,
        ctes: &'a crate::cte::CteContext,
    ) -> Self {
        Self {
            catalog_kv,
            resolution,
            ctes,
            described: Vec::new(),
            walk: 0,
            initplans: Vec::new(),
            scalar_lookups: Vec::new(),
        }
    }

    /// Bind the next expression against its own block-description cache.
    fn walking(&mut self, walk: usize) {
        self.walk = walk;
    }

    fn with_initplans(mut self, initplans: Vec<LazyInitPlan>) -> Self {
        self.initplans = initplans;
        self
    }

    fn with_scalar_lookups(mut self, scalar_lookups: Vec<CorrelatedScalarLookup>) -> Self {
        self.scalar_lookups = scalar_lookups;
        self
    }

    /// Replace every reference to an outer column inside `te` with that column's
    /// value from `row`, yielding a FROM item that no longer depends on the outer
    /// relation and can be built by the ordinary path. Also reports the outer
    /// relation the item referenced, which names the `42P10` a `RIGHT`/`FULL`
    /// join raises for a lateral reference it cannot evaluate.
    ///
    /// A reference is substituted only when it cannot bind to a FROM item
    /// *inside* `te`: a qualifier re-introduced there shadows the outer one, and
    /// an unqualified name is substituted only when no enclosing FROM supplies a
    /// column of that name. `PostgreSQL` resolves the inner query level first
    /// and falls back to the lateral scope.
    fn bind(
        &mut self,
        te: &crabka_pgparser::ast::TableExpr,
        outer: &Scope,
        row: &[Datum],
    ) -> (crabka_pgparser::ast::TableExpr, Option<String>) {
        let mut bound = te.clone();
        let ctes = self.ctes.child();
        let mut pass = BindPass {
            binder: self,
            outer,
            row,
            visited: 0,
            referenced: None,
            substituted: false,
            ctes,
            error: None,
        };
        let shadow = Shadow::default();
        pass.table_expr(&mut bound, &shadow);
        let referenced = pass.referenced;
        (bound, referenced)
    }

    /// Specialize one query expression against an enclosing row. The boolean
    /// reports whether any outer value was substituted; unlike `referenced`, it
    /// also covers USING/NATURAL-coalesced columns, whose scope binding has no
    /// relation qualifier.
    fn bind_query(
        &mut self,
        query: &crabka_pgparser::ast::QueryExpr,
        outer: &Scope,
        row: &[Datum],
    ) -> Result<(crabka_pgparser::ast::QueryExpr, bool), ExecError> {
        let mut bound = query.clone();
        let ctes = self.ctes.child();
        let mut pass = BindPass {
            binder: self,
            outer,
            row,
            visited: 0,
            referenced: None,
            substituted: false,
            ctes,
            error: None,
        };
        pass.query(&mut bound, &Shadow::default());
        match pass.error {
            Some(error) => Err(error),
            None => Ok((bound, pass.substituted)),
        }
    }

    /// Specialize an expression and every query nested inside it against an
    /// enclosing row.
    fn bind_expr(
        &mut self,
        expr: &Expr,
        outer: &Scope,
        row: &[Datum],
    ) -> Result<(Expr, bool), ExecError> {
        let mut bound = expr.clone();
        let ctes = self.ctes.child();
        let mut pass = BindPass {
            binder: self,
            outer,
            row,
            visited: 0,
            referenced: None,
            substituted: false,
            ctes,
            error: None,
        };
        pass.expr(&mut bound, &Shadow::default());
        match pass.error {
            Some(error) => Err(error),
            None => Ok((bound, pass.substituted)),
        }
    }

    fn resolve_initplan(
        &mut self,
        read_ctx: &crate::subquery::SubCtx<'_>,
        index: usize,
        lhs: Option<&Expr>,
    ) -> Result<Expr, ExecError> {
        let plan = self
            .initplans
            .get_mut(index)
            .ok_or_else(|| ExecError::Unsupported("invalid deferred subquery marker".into()))?;
        if plan.resolved.is_none() {
            plan.resolved = Some(crate::subquery::resolve_expr(read_ctx, &plan.template)?);
        }
        let mut resolved = plan
            .resolved
            .clone()
            .expect("the deferred subquery was just initialized");
        if let Some(lhs) = lhs {
            substitute_initplan_lhs(&mut resolved, lhs);
        }
        Ok(resolved)
    }

    fn resolve_scalar_lookup(
        &mut self,
        read_ctx: &crate::subquery::SubCtx<'_>,
        index: usize,
        key_expr: &Expr,
    ) -> Result<Expr, ExecError> {
        let plan = self.scalar_lookups.get(index).ok_or_else(|| {
            ExecError::Unsupported("invalid correlated scalar lookup marker".into())
        })?;
        if matches!(&plan.state, CorrelatedScalarLookupState::Uninitialized) {
            let state = build_correlated_scalar_lookup(read_ctx, plan)?;
            self.scalar_lookups[index].state = state;
        }
        let plan = &self.scalar_lookups[index];
        match &plan.state {
            CorrelatedScalarLookupState::Uninitialized => unreachable!("lookup was initialized"),
            CorrelatedScalarLookupState::Fallback => {
                resolve_correlated_scalar_fallback(read_ctx, plan, key_expr)
            }
            CorrelatedScalarLookupState::Ready { values, saw_rows } => {
                if !saw_rows {
                    return Ok(Expr::Const {
                        value: Datum::Null,
                        ty: plan.result_type,
                    });
                }
                let resolved_key_expr = crate::subquery::resolve_expr(read_ctx, key_expr)?;
                let key =
                    crate::eval::eval(&resolved_key_expr, &Scope::empty(), &[], read_ctx.eval_ctx)?;
                if key.is_null() {
                    return Ok(Expr::Const {
                        value: Datum::Null,
                        ty: plan.result_type,
                    });
                }
                if !crate::join::hashes_like_it_compares(&key) {
                    return resolve_correlated_scalar_fallback(read_ctx, plan, key_expr);
                }
                Ok(Expr::Const {
                    value: values.get(&key).cloned().unwrap_or(Datum::Null),
                    ty: plan.result_type,
                })
            }
        }
    }
}

/// One walk of a lateral item, substituting `row`'s values into it.
struct BindPass<'a, 'b> {
    binder: &'a mut LateralBinder<'b>,
    outer: &'a Scope,
    row: &'a [Datum],
    /// How many query blocks this pass has described so far, which indexes the
    /// binder's cache.
    visited: usize,
    /// The outer relation whose column was first substituted, if any.
    referenced: Option<String>,
    /// Whether any outer column was substituted, including an unqualified
    /// coalesced column whose scope binding has no relation qualifier.
    substituted: bool,
    /// Query-local CTEs visible at the current query block.
    ctes: crate::cte::CteContext,
    /// A bindable ambiguous outer reference must retain 42702 instead of being
    /// left for the inner scope to misreport as an undefined column.
    error: Option<ExecError>,
}

/// The FROM-item names visible at the point being rewritten, which take
/// precedence over the outer relation's.
#[derive(Debug, Clone)]
struct Shadow {
    qualifiers: Vec<String>,
    /// The unqualified column names the enclosing FROM clauses supply. `None`
    /// once some enclosing FROM could not be described, which leaves every
    /// unqualified name to inner resolution rather than guessing.
    columns: Option<Vec<String>>,
}

impl Default for Shadow {
    /// At the top of a lateral item nothing is in scope yet, so no name is
    /// shadowed. That is different from "we do not know what is in scope".
    fn default() -> Self {
        Self {
            qualifiers: Vec::new(),
            columns: Some(Vec::new()),
        }
    }
}

impl Shadow {
    /// Do the FROM clauses this shadow covers supply `name`?
    ///
    /// `None` — reachable only for a bare name — is "some covered FROM could not
    /// be described", so no level can be ruled in or out.
    fn supplies(&self, qualifier: Option<&str>, name: &str) -> Option<bool> {
        match qualifier {
            Some(qualifier) => Some(self.qualifiers.iter().any(|q| q == qualifier)),
            None => Some(self.columns.as_ref()?.iter().any(|column| column == name)),
        }
    }

    /// Widen this shadow by the names `from` introduces.
    fn extend_by(
        &mut self,
        catalog_kv: &dyn Kv,
        resolution: &crate::relname::ResolutionScope,
        ctes: &crate::cte::CteContext,
        from: &[crabka_pgparser::ast::TableExpr],
    ) {
        collect_qualifiers(from, &mut self.qualifiers);
        match from_column_names(catalog_kv, resolution, ctes, from) {
            Some(names) => {
                if let Some(columns) = &mut self.columns {
                    columns.extend(names);
                }
            }
            None => self.columns = None,
        }
    }
}

/// The unqualified column names `from` supplies, or `None` when its schema
/// cannot be described here — a FROM naming a relation that does not exist is
/// for the ordinary read path to report, not for a name-shadowing pass.
fn from_column_names(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    ctes: &crate::cte::CteContext,
    from: &[crabka_pgparser::ast::TableExpr],
) -> Option<Vec<String>> {
    if from.is_empty() {
        return Some(Vec::new());
    }
    build_from_schema_with_ctes(catalog_kv, resolution, from, ctes)
        .ok()
        .map(|relation| {
            relation
                .scope
                .columns
                .into_iter()
                .map(|column| column.name)
                .collect()
        })
}

impl BindPass<'_, '_> {
    /// The shadow in force inside a query block whose FROM list is `from`.
    fn extended(&mut self, shadow: &Shadow, from: &[crabka_pgparser::ast::TableExpr]) -> Shadow {
        let mut next = shadow.clone();
        collect_qualifiers(from, &mut next.qualifiers);
        match self.describe(from) {
            Some(names) => {
                if let Some(columns) = &mut next.columns {
                    columns.extend(names);
                }
            }
            None => next.columns = None,
        }
        next
    }

    /// The column names `from` supplies, cached across outer rows.
    fn describe(&mut self, from: &[crabka_pgparser::ast::TableExpr]) -> Option<Vec<String>> {
        let index = self.visited;
        self.visited += 1;
        let walk = self.binder.walk;
        if walk >= self.binder.described.len() {
            self.binder.described.resize_with(walk + 1, Vec::new);
        }
        if index >= self.binder.described[walk].len() {
            let names = from_column_names(
                self.binder.catalog_kv,
                self.binder.resolution,
                &self.ctes,
                from,
            );
            self.binder.described[walk].push(names);
        }
        self.binder.described[walk][index].clone()
    }

    fn table_expr(&mut self, te: &mut crabka_pgparser::ast::TableExpr, shadow: &Shadow) {
        use crabka_pgparser::ast::TableExpr;
        match te {
            TableExpr::Table { .. } => {}
            TableExpr::Derived { subquery, .. } => self.query(subquery, shadow),
            TableExpr::Function { functions, .. } => {
                for call in functions {
                    for arg in &mut call.args {
                        self.expr(arg, shadow);
                    }
                }
            }
            TableExpr::JsonTable(table) => {
                for expr in table.exprs_mut() {
                    self.expr(expr, shadow);
                }
            }
            TableExpr::Join {
                left,
                right,
                constraint,
                ..
            } => {
                let inner = self.extended(shadow, std::slice::from_ref(left));
                let inner = self.extended(&inner, std::slice::from_ref(right));
                self.table_expr(left, shadow);
                self.table_expr(right, shadow);
                if let crabka_pgparser::ast::JoinConstraint::On(expr) = constraint {
                    self.expr(expr, &inner);
                }
            }
        }
    }

    fn query(&mut self, query: &mut crabka_pgparser::ast::QueryExpr, shadow: &Shadow) {
        let parent_ctes = self.ctes.clone();
        // A CTE inside a lateral item may reference the outer row too, so the
        // WITH list is part of the walk. Describe each bound item in declaration
        // order so the query body can distinguish its columns from outer ones.
        if let Some(with) = &mut query.with {
            for cte in &mut with.ctes {
                match &mut cte.body {
                    crabka_pgparser::ast::CteBody::Query(body) => self.query(body, shadow),
                    // A data-modifying CTE is not a lateral read path; leaving it
                    // alone keeps the reference to be reported by name resolution.
                    crabka_pgparser::ast::CteBody::Dml(_) => {}
                }
                if let Ok(relation) = crate::cte::describe_cte_relation(
                    self.binder.catalog_kv,
                    self.binder.resolution,
                    cte,
                    with.recursive,
                    &self.ctes,
                ) {
                    self.ctes.insert(cte.name.clone(), relation);
                }
            }
        }
        self.set_expr(&mut query.body, shadow);
        let order_shadow = match &query.body {
            crabka_pgparser::ast::SetExpr::Query(crabka_pgparser::ast::QueryBody::Select(
                select,
            )) => {
                let mut inner = self.extended(shadow, &select.from);
                if let Some(columns) = &mut inner.columns {
                    columns.extend(select.projection.iter().filter_map(|item| match item {
                        SelectItem::Expr { expr, alias } => {
                            Some(alias.clone().unwrap_or_else(|| derived_name(expr)))
                        }
                        _ => None,
                    }));
                }
                inner
            }
            // A set operation or nested query exposes its output columns to the
            // tail ORDER BY. If that shape cannot be described cheaply here,
            // leave bare names to its own resolver instead of mistaking them for
            // outer references.
            _ => Shadow {
                qualifiers: shadow.qualifiers.clone(),
                columns: None,
            },
        };
        for item in &mut query.order_by {
            self.expr(&mut item.expr, &order_shadow);
        }
        for expr in query.limit.iter_mut().chain(query.offset.iter_mut()) {
            self.expr(expr, shadow);
        }
        self.ctes = parent_ctes;
    }

    fn set_expr(&mut self, body: &mut crabka_pgparser::ast::SetExpr, shadow: &Shadow) {
        use crabka_pgparser::ast::{QueryBody, SetExpr};
        match body {
            SetExpr::Query(QueryBody::Select(select)) => {
                let inner = self.extended(shadow, &select.from);
                for item in &mut select.from {
                    self.table_expr(item, shadow);
                }
                for expr in select_exprs_mut(select) {
                    self.expr(expr, &inner);
                }
            }
            SetExpr::Query(QueryBody::Values(values)) => {
                for value_row in &mut values.rows {
                    for expr in value_row {
                        self.expr(expr, shadow);
                    }
                }
            }
            SetExpr::Query(QueryBody::Nested(nested)) => self.query(nested, shadow),
            SetExpr::SetOp { left, right, .. } => {
                self.set_expr(left, shadow);
                self.set_expr(right, shadow);
            }
        }
    }

    fn expr(&mut self, expr: &mut Expr, shadow: &Shadow) {
        if let Expr::Column { table, name } = expr {
            let bindable = match table {
                Some(qualifier) => !shadow.qualifiers.iter().any(|q| q == qualifier),
                None => shadow
                    .columns
                    .as_ref()
                    .is_some_and(|columns| !columns.iter().any(|column| column == name)),
            };
            if bindable {
                match self.outer.resolve(table.as_deref(), name) {
                    Ok(index) => {
                        self.substituted = true;
                        if self.referenced.is_none() {
                            self.referenced = self.outer.columns[index].qualifier.clone();
                        }
                        *expr = Expr::Const {
                            value: self.row[index].clone(),
                            ty: self.outer.ty_at(index),
                        };
                    }
                    Err(error @ ExecError::AmbiguousColumn(_)) if self.error.is_none() => {
                        self.error = Some(error);
                    }
                    // A bare name that is no outer column may still name an
                    // outer *relation*, and then it is that relation's whole
                    // row — the same range-table fallback `eval` takes for a
                    // reference it can resolve in place. Without it a
                    // correlated subquery reported 42703 for a whole row every
                    // uncorrelated path already answered.
                    Err(ExecError::UndefinedColumn(_)) => self.whole_row(expr, shadow),
                    Err(_) => {}
                }
            }
            return;
        }
        for child in expr_children_mut(expr) {
            self.expr(child, shadow);
        }
        for query in query_children_mut(expr) {
            self.query(query, shadow);
        }
    }

    /// Substitute `expr` — a bare name that resolved to no outer column — with
    /// the whole row of the outer relation it names, when it names one.
    ///
    /// The enclosing FROM clauses are consulted first and win outright: an
    /// inner relation of the same name is what `PostgreSQL` binds, so
    /// `SELECT (SELECT count(*) FROM ca WHERE ca IS NOT NULL) FROM ca` counts
    /// the inner `ca`. `Shadow::columns` cannot answer that on its own — it
    /// holds the names a FROM *supplies*, and a relation's own name is not
    /// among them — so the qualifier list is what rules the outer row out.
    ///
    /// Only an unqualified name reaches this: `PostgreSQL` reads `s.t` as
    /// "column `t` of range-table entry `s`" and reports a missing FROM entry
    /// for `s`, never as the whole row of `s.t`.
    ///
    /// A row an outer join invented for that side has no whole row, so
    /// [`Scope::whole_row_value`] hands back NULL and the substitution carries
    /// it — which is what keeps `(,)` and NULL distinguishable in one result
    /// set. Leaving `expr` untouched when nothing matches keeps the inner
    /// scope's own 42703 exactly as it was.
    fn whole_row(&mut self, expr: &mut Expr, shadow: &Shadow) {
        let Expr::Column {
            table: None,
            name: qualifier,
        } = &*expr
        else {
            return;
        };
        if shadow.qualifiers.iter().any(|q| q == qualifier) {
            return;
        }
        let Some(value) = self.outer.refs_value(qualifier, self.row) else {
            return;
        };
        self.substituted = true;
        if self.referenced.is_none() {
            self.referenced = Some(qualifier.clone());
        }
        // The relation's composite type is not registered in `pg_type` here, so
        // a whole row carries the anonymous `record` — the same type
        // `eval::infer_type` reports for one it resolves in place.
        *expr = Expr::Const {
            value,
            ty: ColumnType::Record(None),
        };
    }
}

/// Every qualifier a FROM list introduces (alias if present, else the relation
/// or function name).
fn collect_qualifiers(from: &[crabka_pgparser::ast::TableExpr], out: &mut Vec<String>) {
    use crabka_pgparser::ast::TableExpr;
    for item in from {
        match item {
            TableExpr::Table { name, alias, .. } => {
                out.push(alias.clone().unwrap_or_else(|| name.name.clone()));
            }
            TableExpr::Derived { alias, .. } => out.push(alias.clone()),
            TableExpr::Function {
                alias, functions, ..
            } => out.push(alias.clone().unwrap_or_else(|| {
                functions
                    .first()
                    .map(|call| call.name.to_ascii_lowercase())
                    .unwrap_or_default()
            })),
            TableExpr::JsonTable(table) => out.push(
                table
                    .alias
                    .clone()
                    .unwrap_or_else(|| "json_table".to_string()),
            ),
            TableExpr::Join { left, right, .. } => {
                collect_qualifiers(std::slice::from_ref(left), out);
                collect_qualifiers(std::slice::from_ref(right), out);
            }
        }
    }
}

/// [`select_exprs_mut`]'s shared-reference twin, for the walks that only read.
fn select_exprs(select: &SelectStmt) -> Vec<&Expr> {
    let mut out: Vec<&Expr> = Vec::new();
    for item in &select.projection {
        if let SelectItem::Expr { expr, .. } = item {
            out.push(expr);
        }
    }
    out.extend(&select.filter);
    out.extend(&select.group_by);
    out.extend(&select.having);
    out.extend(select.order_by.iter().map(|item| &item.expr));
    if let crabka_pgparser::ast::DistinctClause::On(on) = &select.distinct {
        out.extend(on);
    }
    for call in &select.window_calls {
        if let FuncArgs::Exprs(args) = &call.args {
            out.extend(args);
        }
        out.extend(&call.filter);
        if let crabka_pgparser::ast::WindowRef::Spec(spec) = &call.over {
            out.extend(window_spec_exprs(spec));
        }
    }
    for window in &select.windows {
        out.extend(window_spec_exprs(&window.spec));
    }
    out
}

fn window_spec_exprs(spec: &crabka_pgparser::ast::WindowSpec) -> Vec<&Expr> {
    let mut out = Vec::new();
    out.extend(&spec.partition_by);
    out.extend(spec.order_by.iter().map(|item| &item.expr));
    if let Some(frame) = &spec.frame {
        for bound in [&frame.start, &frame.end] {
            match bound {
                crabka_pgparser::ast::FrameBound::Preceding(expr)
                | crabka_pgparser::ast::FrameBound::Following(expr) => out.push(expr),
                crabka_pgparser::ast::FrameBound::UnboundedPreceding
                | crabka_pgparser::ast::FrameBound::CurrentRow
                | crabka_pgparser::ast::FrameBound::UnboundedFollowing => {}
            }
        }
    }
    out
}

/// Every expression a SELECT evaluates against its own FROM scope.
fn select_exprs_mut(select: &mut SelectStmt) -> Vec<&mut Expr> {
    let mut out: Vec<&mut Expr> = Vec::new();
    for item in &mut select.projection {
        if let SelectItem::Expr { expr, .. } = item {
            out.push(expr);
        }
    }
    out.extend(select.filter.iter_mut());
    out.extend(select.group_by.iter_mut());
    out.extend(select.having.iter_mut());
    out.extend(select.order_by.iter_mut().map(|item| &mut item.expr));
    if let crabka_pgparser::ast::DistinctClause::On(on) = &mut select.distinct {
        out.extend(on.iter_mut());
    }
    for call in &mut select.window_calls {
        if let FuncArgs::Exprs(args) = &mut call.args {
            out.extend(args);
        }
        out.extend(call.filter.iter_mut());
        if let crabka_pgparser::ast::WindowRef::Spec(spec) = &mut call.over {
            out.extend(window_spec_exprs_mut(spec));
        }
    }
    for window in &mut select.windows {
        out.extend(window_spec_exprs_mut(&mut window.spec));
    }
    out
}

fn window_spec_exprs_mut(spec: &mut crabka_pgparser::ast::WindowSpec) -> Vec<&mut Expr> {
    let mut out = Vec::new();
    out.extend(&mut spec.partition_by);
    out.extend(spec.order_by.iter_mut().map(|item| &mut item.expr));
    if let Some(frame) = &mut spec.frame {
        for bound in [&mut frame.start, &mut frame.end] {
            match bound {
                crabka_pgparser::ast::FrameBound::Preceding(expr)
                | crabka_pgparser::ast::FrameBound::Following(expr) => out.push(expr),
                crabka_pgparser::ast::FrameBound::UnboundedPreceding
                | crabka_pgparser::ast::FrameBound::CurrentRow
                | crabka_pgparser::ast::FrameBound::UnboundedFollowing => {}
            }
        }
    }
    out
}

fn initplan_lhs_marker() -> Expr {
    Expr::Column {
        table: Some(INITPLAN_LHS_MARKER.into()),
        name: "value".into(),
    }
}

fn initplan_marker(index: usize, lhs: Option<Expr>) -> Expr {
    let mut args = vec![Expr::IntLiteral(index.to_string())];
    args.extend(lhs);
    Expr::Func(FuncCall {
        name: INITPLAN_MARKER.into(),
        distinct: false,
        args: FuncArgs::Exprs(args),
        order_by: Vec::new(),
        filter: None,
    })
}

fn initplan_parts(expr: &Expr) -> Option<(usize, Option<&Expr>)> {
    let Expr::Func(FuncCall {
        name,
        distinct: false,
        args: FuncArgs::Exprs(args),
        order_by,
        filter: None,
    }) = expr
    else {
        return None;
    };
    if name != INITPLAN_MARKER || !order_by.is_empty() {
        return None;
    }
    if !(1..=2).contains(&args.len()) {
        return None;
    }
    let Expr::IntLiteral(index) = &args[0] else {
        return None;
    };
    Some((index.parse().ok()?, args.get(1)))
}

fn scalar_lookup_marker(index: usize, key: Expr) -> Expr {
    Expr::Func(FuncCall {
        name: SCALAR_LOOKUP_MARKER.into(),
        distinct: false,
        args: FuncArgs::Exprs(vec![Expr::IntLiteral(index.to_string()), key]),
        order_by: Vec::new(),
        filter: None,
    })
}

fn scalar_lookup_parts(expr: &Expr) -> Option<(usize, &Expr)> {
    let Expr::Func(FuncCall {
        name,
        distinct: false,
        args: FuncArgs::Exprs(args),
        order_by,
        filter: None,
    }) = expr
    else {
        return None;
    };
    if name != SCALAR_LOOKUP_MARKER || args.len() != 2 || !order_by.is_empty() {
        return None;
    }
    let Expr::IntLiteral(index) = &args[0] else {
        return None;
    };
    Some((index.parse().ok()?, &args[1]))
}

fn plan_correlated_scalar_lookup(
    read_ctx: &crate::subquery::SubCtx<'_>,
    query: &crabka_pgparser::ast::QueryExpr,
    outer: &Scope,
) -> Result<Option<(CorrelatedScalarLookup, Expr)>, ExecError> {
    use crabka_pgparser::ast::{DistinctClause, QueryBody, SetExpr, TableExpr};

    if query.with.is_some()
        || !query.order_by.is_empty()
        || !matches!(query.limit, Some(Expr::IntLiteral(ref value)) if value == "1")
        || query.offset.is_some()
        || query.with_ties
        || query.locking.is_some()
    {
        return Ok(None);
    }
    let SetExpr::Query(QueryBody::Select(select)) = &query.body else {
        return Ok(None);
    };
    if !matches!(select.distinct, DistinctClause::All)
        || !select.group_by.is_empty()
        || select.grouping.is_some()
        || select.having.is_some()
        || !select.windows.is_empty()
        || !select.window_calls.is_empty()
        || !select.order_by.is_empty()
        || select.limit.is_some()
        || select.offset.is_some()
        || select.with_ties
        || select.locking.is_some()
    {
        return Ok(None);
    }
    let [SelectItem::Expr { .. }] = select.projection.as_slice() else {
        return Ok(None);
    };
    let [
        TableExpr::Table {
            name,
            alias,
            columns: None,
            sample: None,
            ..
        },
    ] = select.from.as_slice()
    else {
        return Ok(None);
    };
    if name.schema.is_none() && read_ctx.ctes.lookup(&name.name).is_some() {
        return Ok(None);
    }
    let resolved_name = resolve_relation(
        read_ctx.catalog_kv,
        read_ctx.fctx.resolution,
        name,
        SchemaDisposition::Reference,
    )?;
    let table = match crabka_pgcatalog::get_table(read_ctx.catalog_kv, &resolved_name) {
        Ok(table) => table,
        Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) => return Ok(None),
        Err(error) => return Err(error.into()),
    };
    // A materialized view whose contents have never been computed is an error
    // to read, not an empty relation, and this hash never opens the path that
    // says so: it read the empty row space and answered `NULL` for every outer
    // key, while the same subquery without the `LIMIT 1` raised 55000.
    // Declining hands both shapes to the path that refuses it.
    if table
        .materialized
        .as_ref()
        .is_some_and(|matview| !matview.populated)
        || table.sharded
        || table.sharding.is_some()
        || table.foreign.is_some()
        || crate::partition::is_partitioned(read_ctx.catalog_kv, &table.name)?
        || crate::partition::parent_of(read_ctx.catalog_kv, &table.name)?.is_some()
        || !crate::inheritance::parents_of(read_ctx.catalog_kv, &table.name)?.is_empty()
        || !crate::inheritance::children_of(read_ctx.catalog_kv, &table.name)?.is_empty()
    {
        return Ok(None);
    }
    let qualifier = alias.as_deref().unwrap_or(&table.name.name);
    let inner = Scope::single(&table, qualifier);
    let nulls = vec![Datum::Null; outer.width()];
    let mut binder =
        LateralBinder::new(read_ctx.catalog_kv, read_ctx.fctx.resolution, read_ctx.ctes);
    let (bound_query, correlated) = binder.bind_query(query, outer, &nulls)?;
    if !correlated {
        return Ok(None);
    }
    let SetExpr::Query(QueryBody::Select(bound_select)) = &bound_query.body else {
        unreachable!("binding preserves a scalar lookup SELECT body")
    };
    let [
        SelectItem::Expr {
            expr: bound_projection,
            ..
        },
    ] = bound_select.projection.as_slice()
    else {
        unreachable!("binding preserves a scalar lookup projection")
    };
    let Some(result_column) = direct_lookup_column(bound_projection, &inner) else {
        return Ok(None);
    };
    let Some(Expr::Binary {
        op: BinaryOp::Eq,
        left: original_left,
        right: original_right,
    }) = select.filter.as_ref()
    else {
        return Ok(None);
    };
    let Some(Expr::Binary {
        op: BinaryOp::Eq,
        left: bound_left,
        right: bound_right,
    }) = bound_select.filter.as_ref()
    else {
        unreachable!("binding preserves a scalar lookup equality")
    };
    let (key_column, outer_expr, outer_on_left) = if let Some(column) =
        direct_lookup_column(bound_left, &inner)
        && !lookup_expr_contains_column(bound_right)
    {
        (column, original_right.as_ref(), false)
    } else if let Some(column) = direct_lookup_column(bound_right, &inner)
        && !lookup_expr_contains_column(bound_left)
    {
        (column, original_left.as_ref(), true)
    } else {
        return Ok(None);
    };
    if !lookup_key_is_immutable(read_ctx.catalog_kv, outer_expr) {
        return Ok(None);
    }
    let key_type = table.columns[key_column].ty;
    if crate::eval::infer_type(outer_expr, outer)? != key_type {
        return Ok(None);
    }
    let result_type = table.columns[result_column].ty;
    // The two gates every other stored-relation read passes and this one did
    // not: the read permit and row security. The lookup hashes the whole inner
    // relation and answers every outer row from that hash, so an ungranted
    // relation was readable by anyone who could name a key — with
    // `generate_series` as the outer relation, by anyone at all — and a policy
    // that hid a row hid it from every path but this one.
    //
    // Declining is the whole answer. The correlated fallback re-runs the
    // subquery through `subquery::resolve_expr`, which raises the 42501 itself
    // and filters through `rls::apply_row_security` with the once-per-scan qual
    // resolution and the recursion guard this hash has nowhere to run. Nor
    // could a filtering fast path be the same fast path: the hash is built from
    // a two-column projection, while a policy qual may read any column of the
    // row, so filtering here means scanning the relation whole.
    //
    // The proof is taken by value because the plan outlives this function and
    // is read once per outer row; it is the only field the scan can reach the
    // relation through.
    let Some(table) =
        crate::rls::UnrestrictedRelation::read(&read_ctx.privileges(), &read_ctx.rls(), table)?
    else {
        return Ok(None);
    };
    Ok(Some((
        CorrelatedScalarLookup {
            query: query.clone(),
            table,
            key_column,
            result_column,
            result_type,
            outer_on_left,
            state: CorrelatedScalarLookupState::Uninitialized,
        },
        outer_expr.clone(),
    )))
}

fn plan_correlated_exists_lookup(
    read_ctx: &crate::subquery::SubCtx<'_>,
    query: &crabka_pgparser::ast::QueryExpr,
    outer: &Scope,
) -> Result<Option<(CorrelatedScalarLookup, Expr)>, ExecError> {
    use crabka_pgparser::ast::{QueryBody, SetExpr};

    if query.limit.is_some() {
        return Ok(None);
    }
    let SetExpr::Query(QueryBody::Select(select)) = &query.body else {
        return Ok(None);
    };
    if crate::grouping::is_grouping_query(select)
        || crate::srf::projection_contains_srf(&select.projection)
    {
        return Ok(None);
    }
    let Some(Expr::Binary {
        op: BinaryOp::Eq,
        left,
        right,
    }) = select.filter.as_ref()
    else {
        return Ok(None);
    };

    // For an equality match the inner key cannot be NULL, so EXISTS is the
    // same as selecting that key once and testing it for NULL. Trying both
    // operands lets the scalar planner identify the inner column without a
    // second copy of its relation-resolution rules.
    for projection in [left.as_ref(), right.as_ref()] {
        let mut scalar = query.clone();
        scalar.limit = Some(Expr::IntLiteral("1".into()));
        let SetExpr::Query(QueryBody::Select(candidate)) = &mut scalar.body else {
            unreachable!("the EXISTS lookup has one SELECT body")
        };
        candidate.projection = vec![SelectItem::Expr {
            expr: projection.clone(),
            alias: None,
        }];
        if let Some(lookup) = plan_correlated_scalar_lookup(read_ctx, &scalar, outer)? {
            return Ok(Some(lookup));
        }
    }
    Ok(None)
}

fn direct_lookup_column(expr: &Expr, scope: &Scope) -> Option<usize> {
    let Expr::Column { table, name } = expr else {
        return None;
    };
    scope.resolve(table.as_deref(), name).ok()
}

fn lookup_expr_contains_column(expr: &Expr) -> bool {
    matches!(expr, Expr::Column { .. })
        || expr_children(expr)
            .into_iter()
            .any(lookup_expr_contains_column)
}

fn lookup_key_is_immutable(catalog_kv: &dyn Kv, expr: &Expr) -> bool {
    if !immutable_row_predicate(expr) {
        return false;
    }
    let mut immutable = true;
    crate::grouping::visit_expr(expr, &mut |node| {
        let Expr::Func(call) = node else {
            return;
        };
        immutable &= match crabka_pgcatalog::routine::routines_named(catalog_kv, &call.name) {
            Ok(routines) if routines.is_empty() => is_immutable_function(&call.name),
            Ok(routines) => routines.iter().all(|routine| routine.volatility == 'i'),
            Err(_) => false,
        };
    });
    immutable
}

fn substitute_initplan_lhs(expr: &mut Expr, lhs: &Expr) {
    if matches!(
        expr,
        Expr::Column {
            table: Some(table),
            name,
        } if table == INITPLAN_LHS_MARKER && name == "value"
    ) {
        *expr = lhs.clone();
        return;
    }
    for child in expr_children_mut(expr) {
        substitute_initplan_lhs(child, lhs);
    }
}

fn direct_subquery_is_correlated(
    read_ctx: &crate::subquery::SubCtx<'_>,
    expr: &Expr,
    outer: &Scope,
) -> Result<bool, ExecError> {
    let Some(query) = direct_subquery(expr) else {
        return Ok(false);
    };
    let nulls = vec![Datum::Null; outer.width()];
    let mut binder =
        LateralBinder::new(read_ctx.catalog_kv, read_ctx.fctx.resolution, read_ctx.ctes);
    Ok(binder.bind_query(query, outer, &nulls)?.1)
}

/// Replace uncorrelated subqueries under an expression that must remain deferred
/// with on-demand initplan markers. This keeps CASE/COALESCE lazy while retaining
/// PostgreSQL's once-only execution for an initplan that is eventually selected.
fn install_lazy_initplans(
    read_ctx: &crate::subquery::SubCtx<'_>,
    expr: &Expr,
    outer: &Scope,
    deferred: bool,
    initplans: &mut Vec<LazyInitPlan>,
    scalar_lookups: &mut Vec<CorrelatedScalarLookup>,
) -> Result<Expr, ExecError> {
    let direct_correlated = direct_subquery_is_correlated(read_ctx, expr, outer)?;
    // Keep one materialized lookup per query so retained hash state stays
    // within the query's single blocking-memory budget. Additional eligible
    // subqueries remain on the ordinary correlated fallback path.
    if scalar_lookups.is_empty()
        && direct_correlated
        && let Expr::ScalarSubquery(query) = expr
        && let Some((lookup, key)) = plan_correlated_scalar_lookup(read_ctx, query, outer)?
    {
        let index = scalar_lookups.len();
        scalar_lookups.push(lookup);
        return Ok(scalar_lookup_marker(index, key));
    }
    if scalar_lookups.is_empty()
        && direct_correlated
        && let Expr::Exists(query) = expr
        && let Some((lookup, key)) = plan_correlated_exists_lookup(read_ctx, query, outer)?
    {
        let index = scalar_lookups.len();
        scalar_lookups.push(lookup);
        return Ok(Expr::IsNull {
            expr: Box::new(scalar_lookup_marker(index, key)),
            negated: true,
        });
    }
    let lazy_correlated = matches!(expr, Expr::Func(_) | Expr::Case { .. })
        && expression_contains_correlated_subquery(read_ctx, expr, outer);
    let child_deferred = deferred || direct_correlated || lazy_correlated;

    if deferred && direct_subquery(expr).is_some() && !direct_correlated {
        let (template, lhs) = match expr {
            Expr::InSubquery {
                expr: lhs,
                subquery,
                negated,
            } => (
                Expr::InSubquery {
                    expr: Box::new(initplan_lhs_marker()),
                    subquery: subquery.clone(),
                    negated: *negated,
                },
                Some(install_lazy_initplans(
                    read_ctx,
                    lhs,
                    outer,
                    true,
                    initplans,
                    scalar_lookups,
                )?),
            ),
            Expr::Quantified {
                expr: lhs,
                op,
                all,
                subquery,
            } => (
                Expr::Quantified {
                    expr: Box::new(initplan_lhs_marker()),
                    op: *op,
                    all: *all,
                    subquery: subquery.clone(),
                },
                Some(install_lazy_initplans(
                    read_ctx,
                    lhs,
                    outer,
                    true,
                    initplans,
                    scalar_lookups,
                )?),
            ),
            _ => (expr.clone(), None),
        };
        let typed = replace_subqueries_with_typed_nulls(read_ctx, &template)?;
        let result_type = crate::eval::infer_type(&typed, &Scope::empty())?;
        let index = initplans.len();
        initplans.push(LazyInitPlan {
            template,
            result_type,
            resolved: None,
        });
        return Ok(initplan_marker(index, lhs));
    }

    let mut planned = expr.clone();
    for child in expr_children_mut(&mut planned) {
        *child = install_lazy_initplans(
            read_ctx,
            child,
            outer,
            child_deferred,
            initplans,
            scalar_lookups,
        )?;
    }
    Ok(planned)
}

/// A `SELECT` with its subqueries planned: the rewritten statement plus the
/// deferred work executing it needs.
struct PlannedSubqueries {
    select: SelectStmt,
    /// The `WHERE` clause reads the source row, so it is evaluated per row.
    correlated_filter: bool,
    initplans: Vec<LazyInitPlan>,
    scalar_lookups: Vec<CorrelatedScalarLookup>,
    /// Select-list / `ORDER BY` / `DISTINCT ON` expressions that read the source
    /// row. `None` — the overwhelmingly common case — leaves projection on
    /// exactly the path it took before this existed.
    row_exprs: Option<CorrelatedRowExprs>,
}

impl PlannedSubqueries {
    /// A statement whose subqueries all folded once, ahead of the row loop.
    fn uncorrelated(select: SelectStmt) -> Self {
        Self {
            select,
            correlated_filter: false,
            initplans: Vec::new(),
            scalar_lookups: Vec::new(),
            row_exprs: None,
        }
    }
}

fn resolve_select_subqueries(
    read_ctx: &crate::subquery::SubCtx<'_>,
    select: &SelectStmt,
) -> Result<PlannedSubqueries, ExecError> {
    let correlatable_filter = select.filter.as_ref().is_some_and(contains_subquery);
    // Only a statement that actually contains a subquery in a row-local clause
    // can have a correlated one there. Everything else — every ordinary select
    // list in the system — leaves here without describing its FROM.
    if !correlatable_filter && !row_clauses_contain_subquery(select) {
        return Ok(PlannedSubqueries::uncorrelated(
            crate::subquery::resolve_in_select(read_ctx, select)?,
        ));
    }
    let scope = if select.from.is_empty() {
        Scope::empty()
    } else {
        match build_from_schema_described(
            read_ctx.catalog_kv,
            read_ctx.fctx.resolution,
            &select.from,
            read_ctx.ctes,
            Some(read_ctx.eval_ctx),
            read_ctx.refs,
        ) {
            Ok(described) => described.scope,
            // A FROM the schema pass cannot describe is not a new failure to
            // report: without a correlated WHERE this statement reached the
            // ordinary path before, and it still does. The real read below
            // raises whatever the FROM is actually wrong about.
            Err(_) if !correlatable_filter => {
                return Ok(PlannedSubqueries::uncorrelated(
                    crate::subquery::resolve_in_select(read_ctx, select)?,
                ));
            }
            Err(error) => return Err(error),
        }
    };
    let (select, row_exprs) = plan_correlated_row_exprs(read_ctx, select, &scope)?;
    if !correlatable_filter {
        return Ok(PlannedSubqueries {
            row_exprs,
            ..PlannedSubqueries::uncorrelated(crate::subquery::resolve_in_select(
                read_ctx, &select,
            )?)
        });
    }
    let (select, correlated_filter, initplans, scalar_lookups) =
        prepare_correlated_subqueries(read_ctx, &select, &scope)?;
    Ok(PlannedSubqueries {
        select,
        correlated_filter,
        initplans,
        scalar_lookups,
        row_exprs,
    })
}

/// Does any clause evaluated once per source row hold a subquery?
///
/// The select list, `ORDER BY` and `DISTINCT ON` are the clauses whose
/// expressions [`plan_correlated_row_exprs`] can defer; a subquery anywhere
/// else is either folded once or handled by the `WHERE` path.
fn row_clauses_contain_subquery(select: &SelectStmt) -> bool {
    select.projection.iter().any(|item| match item {
        SelectItem::Expr { expr, .. } => contains_subquery(expr),
        SelectItem::Wildcard | SelectItem::QualifiedWildcard(_) => false,
    }) || select
        .order_by
        .iter()
        .any(|item| contains_subquery(&item.expr))
        || select
            .distinct
            .on_exprs()
            .is_some_and(|on| on.iter().any(contains_subquery))
}

/// Row-local expressions that read the source row, and the hidden relation
/// columns they are materialized into.
#[derive(Default)]
struct CorrelatedRowExprs {
    /// The original expressions, used to give two clauses that spell the same
    /// correlated expression the same hidden column — which is what lets
    /// `DISTINCT ON (expr) … ORDER BY expr` still recognize its own key.
    sources: Vec<Expr>,
    /// One planned expression per hidden column, in column order.
    exprs: Vec<Expr>,
    /// The hidden scope bindings the markers resolve through, in the same order.
    bindings: Vec<ColumnBinding>,
    initplans: Vec<LazyInitPlan>,
    scalar_lookups: Vec<CorrelatedScalarLookup>,
}

impl CorrelatedRowExprs {
    /// Reserve a hidden column for `expr` if it reads `outer`, returning the
    /// marker that stands in for it. `None` leaves the expression where it is.
    fn defer(
        &mut self,
        read_ctx: &crate::subquery::SubCtx<'_>,
        expr: &Expr,
        outer: &Scope,
    ) -> Result<Option<Expr>, ExecError> {
        if !contains_subquery(expr) || !validate_correlated_subqueries(read_ctx, expr, outer)? {
            return Ok(None);
        }
        if let Some(index) = self.sources.iter().position(|source| source == expr) {
            return Ok(Some(correlated_marker(index)));
        }
        let planned = install_lazy_initplans(
            read_ctx,
            expr,
            outer,
            false,
            &mut self.initplans,
            &mut self.scalar_lookups,
        )?;
        // Resolve the siblings that do not read the source row once, here, so
        // only the correlated subtrees are left to run per row.
        let planned = crate::subquery::resolve_expr_skipping(read_ctx, &planned, &mut |node| {
            let candidate = scalar_lookup_parts(node).is_some()
                || direct_subquery(node).is_some()
                || matches!(node, Expr::Func(_) | Expr::Case { .. });
            scalar_lookup_parts(node).is_some()
                || candidate && expression_contains_correlated_subquery(read_ctx, node, outer)
        })?;
        let ty = correlated_expr_type(
            read_ctx,
            &planned,
            outer,
            &self.initplans,
            &self.scalar_lookups,
        )?;
        let index = self.exprs.len();
        self.sources.push(expr.clone());
        self.exprs.push(planned);
        self.bindings.push(ColumnBinding {
            exposure: Exposure::Output,
            qualifier: Some(crate::scope::CORRELATED_QUALIFIER.to_string()),
            name: index.to_string(),
            ty,
        });
        Ok(Some(correlated_marker(index)))
    }
}

/// Replace every source-row reference inside a select-list sub-select with a
/// NULL of the referenced column's type, so the sub-select can be *described*
/// without the row it would need to be *run*.
///
/// A sub-select's FROM can read the source row — `generate_series(1,
/// array_upper(p.attrs, 1))` — and describing that FROM needs the reference's
/// type, not its value. Only the sub-selects are rewritten: the references
/// outside them already resolve against `scope`, and turning one into a constant
/// would rename the output column it labels.
pub(crate) fn describable_projection(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    ctes: &crate::cte::CteContext,
    projection: &[SelectItem],
    scope: &Scope,
) -> Result<Vec<SelectItem>, ExecError> {
    let nulls = vec![Datum::Null; scope.width()];
    let mut binder = LateralBinder::new(catalog_kv, resolution, ctes);
    projection
        .iter()
        .enumerate()
        .map(|(walk, item)| {
            let SelectItem::Expr { expr, alias } = item else {
                return Ok(item.clone());
            };
            binder.walking(walk);
            let mut expr = expr.clone();
            bind_subqueries_to_row(&mut binder, &mut expr, scope, &nulls)?;
            Ok(SelectItem::Expr {
                expr,
                alias: alias.clone(),
            })
        })
        .collect()
}

fn bind_subqueries_to_row(
    binder: &mut LateralBinder<'_>,
    expr: &mut Expr,
    scope: &Scope,
    row: &[Datum],
) -> Result<(), ExecError> {
    for query in query_children_mut(expr) {
        *query = binder.bind_query(query, scope, row)?.0;
    }
    for child in expr_children_mut(expr) {
        bind_subqueries_to_row(binder, child, scope, row)?;
    }
    Ok(())
}

/// The static type of a deferred expression: the type it infers to once every
/// outer reference is a NULL of its column's type and every subquery a NULL of
/// the type its projection describes to.
fn correlated_expr_type(
    read_ctx: &crate::subquery::SubCtx<'_>,
    planned: &Expr,
    outer: &Scope,
    initplans: &[LazyInitPlan],
    scalar_lookups: &[CorrelatedScalarLookup],
) -> Result<ColumnType, ExecError> {
    let nulls = vec![Datum::Null; outer.width()];
    let mut binder =
        LateralBinder::new(read_ctx.catalog_kv, read_ctx.fctx.resolution, read_ctx.ctes);
    let (bound, _) = binder.bind_expr(planned, outer, &nulls)?;
    let typed = type_without_evaluating_subqueries(read_ctx, &bound, initplans, scalar_lookups)?;
    crate::eval::infer_type(&typed, outer)
}

/// Does any clause [`plan_correlated_row_exprs`] would defer call an aggregate
/// belonging to `select`'s own query level?
fn defers_statement_level_aggregate(
    read_ctx: &crate::subquery::SubCtx<'_>,
    select: &SelectStmt,
    outer: &Scope,
) -> bool {
    let pass = OuterAggregatePass {
        levels: AggregateLevels {
            read_ctx,
            statement: outer,
        },
    };
    select.projection.iter().any(|item| match item {
        SelectItem::Expr { expr, .. } => pass.expr(expr, &[]),
        SelectItem::Wildcard | SelectItem::QualifiedWildcard(_) => false,
    }) || select
        .order_by
        .iter()
        .any(|item| pass.expr(&item.expr, &[]))
        || select
            .distinct
            .on_exprs()
            .is_some_and(|on| on.iter().any(|expr| pass.expr(expr, &[])))
}

/// Finds an aggregate that `PostgreSQL` would assign to the *enclosing* query
/// level rather than to the sub-select it is written in.
///
/// `check_agg_arguments` gives an aggregate the level of the innermost variable
/// its arguments read, ignoring variables local to sub-selects *inside* those
/// arguments. So in
///
/// ```sql
/// SELECT (SELECT max((SELECT i.b FROM inner i WHERE i.a = o.a))) FROM outer o
/// ```
///
/// the only variable `max` reads is `o.a`, one level further out than the
/// sub-select `max` is written in, so the aggregate belongs to the OUTER query —
/// which becomes a grouping query and folds to a single row. Materializing that
/// select-list expression into a per-row hidden column would answer one row per
/// `outer` row instead, which is why the shape has to be recognized before
/// deferral rather than after.
///
/// A name the pass cannot attribute to a level answers "yes" too: declining to
/// defer keeps the missing-FROM-clause error the statement already gets, and an
/// old error beats a new wrong answer.
struct OuterAggregatePass<'a, 'b> {
    levels: AggregateLevels<'a, 'b>,
}

/// Which levels an aggregate's arguments read, to the one resolution the passes
/// over [`AggregateLevels`] need.
#[derive(Default)]
struct AggregateReach {
    /// A variable resolving to the statement's own FROM.
    statement: bool,
    /// A variable resolving to one of the sub-selects in between.
    enclosing: bool,
    /// A variable belonging to no level this pass could describe.
    unknown: bool,
}

/// `PostgreSQL`'s `check_agg_arguments` reduced to the question both aggregate
/// passes ask: does an aggregate written under some enclosing sub-selects take
/// its level from `statement`'s own FROM clause?
///
/// The two callers differ only in what they do with an unattributable name —
/// [`OuterAggregatePass`] declines to defer, [`FromClauseAggregatePass`] declines
/// to reject — so the walk itself reports what it found and leaves the policy to
/// them.
struct AggregateLevels<'a, 'b> {
    read_ctx: &'a crate::subquery::SubCtx<'b>,
    /// The statement's own FROM: the level whose variables settle the question.
    statement: &'a Scope,
}

impl OuterAggregatePass<'_, '_> {
    /// Walk `expr`, written inside the sub-selects whose FROM clauses are
    /// `enclosing` (outermost first). An empty `enclosing` puts `expr` at the
    /// statement's own level, where an aggregate is already
    /// [`crate::grouping::is_grouping_query`]'s business.
    fn expr(&self, expr: &Expr, enclosing: &[&[crabka_pgparser::ast::TableExpr]]) -> bool {
        if !enclosing.is_empty()
            && let Expr::Func(call) = expr
            && crate::agg::is_aggregate_name(&call.name)
            && self.belongs_to_statement(call, enclosing)
        {
            return true;
        }
        expr_children(expr)
            .into_iter()
            .any(|child| self.expr(child, enclosing))
            || direct_subquery(expr).is_some_and(|query| self.query(query, enclosing))
    }

    fn query(
        &self,
        query: &crabka_pgparser::ast::QueryExpr,
        enclosing: &[&[crabka_pgparser::ast::TableExpr]],
    ) -> bool {
        // A tail ORDER BY / LIMIT is evaluated at the query's own level, so it
        // walks under whatever FROM its body introduces. A set operation has no
        // single such FROM; its branches each describe their own.
        let body_from = match &query.body {
            crabka_pgparser::ast::SetExpr::Query(crabka_pgparser::ast::QueryBody::Select(
                select,
            )) => select.from.as_slice(),
            _ => &[],
        };
        let inner = [enclosing, &[body_from]].concat();
        self.set_expr(&query.body, enclosing)
            || query
                .order_by
                .iter()
                .map(|item| &item.expr)
                .chain(&query.limit)
                .chain(&query.offset)
                .any(|expr| self.expr(expr, &inner))
            || query
                .with
                .iter()
                .flat_map(|with| &with.ctes)
                .any(|cte| match &cte.body {
                    crabka_pgparser::ast::CteBody::Query(body) => self.query(body, enclosing),
                    // A data-modifying CTE is not a read path this rewrite ever
                    // reaches; whatever it references is resolved elsewhere.
                    crabka_pgparser::ast::CteBody::Dml(_) => false,
                })
    }

    fn set_expr(
        &self,
        body: &crabka_pgparser::ast::SetExpr,
        enclosing: &[&[crabka_pgparser::ast::TableExpr]],
    ) -> bool {
        use crabka_pgparser::ast::{QueryBody, SetExpr};
        match body {
            SetExpr::Query(QueryBody::Select(select)) => {
                let inner = [enclosing, &[select.from.as_slice()]].concat();
                select_exprs(select)
                    .into_iter()
                    .any(|expr| self.expr(expr, &inner))
                    || select
                        .from
                        .iter()
                        .any(|item| self.table_expr(item, enclosing))
            }
            SetExpr::Query(QueryBody::Values(values)) => values
                .rows
                .iter()
                .flatten()
                .any(|expr| self.expr(expr, enclosing)),
            SetExpr::Query(QueryBody::Nested(nested)) => self.query(nested, enclosing),
            SetExpr::SetOp { left, right, .. } => {
                self.set_expr(left, enclosing) || self.set_expr(right, enclosing)
            }
        }
    }

    /// A FROM item is described by its own level, so a sub-select inside one
    /// sits one level down from the query the item belongs to — not inside it.
    fn table_expr(
        &self,
        te: &crabka_pgparser::ast::TableExpr,
        enclosing: &[&[crabka_pgparser::ast::TableExpr]],
    ) -> bool {
        use crabka_pgparser::ast::TableExpr;
        match te {
            TableExpr::Table { .. } => false,
            TableExpr::Derived { subquery, .. } => self.query(subquery, enclosing),
            TableExpr::Function { functions, .. } => functions
                .iter()
                .flat_map(|call| &call.args)
                .any(|arg| self.expr(arg, enclosing)),
            TableExpr::JsonTable(table) => table
                .exprs()
                .into_iter()
                .any(|expr| self.expr(expr, enclosing)),
            TableExpr::Join {
                left,
                right,
                constraint,
                ..
            } => {
                let inner = [
                    enclosing,
                    &[std::slice::from_ref(left.as_ref())],
                    &[std::slice::from_ref(right.as_ref())],
                ]
                .concat();
                self.table_expr(left, enclosing)
                    || self.table_expr(right, enclosing)
                    || matches!(constraint, crabka_pgparser::ast::JoinConstraint::On(on)
                        if self.expr(on, &inner))
            }
        }
    }

    /// Does this aggregate call, written under the `enclosing` sub-selects,
    /// belong to the statement's own level?
    fn belongs_to_statement(
        &self,
        call: &FuncCall,
        enclosing: &[&[crabka_pgparser::ast::TableExpr]],
    ) -> bool {
        let reach = self.levels.reach_of(call, enclosing);
        reach.unknown || (reach.statement && !reach.enclosing)
    }
}

impl AggregateLevels<'_, '_> {
    /// Which levels the arguments of `call`, written under the `enclosing`
    /// sub-selects (outermost first), read.
    fn reach_of(
        &self,
        call: &FuncCall,
        enclosing: &[&[crabka_pgparser::ast::TableExpr]],
    ) -> AggregateReach {
        let mut covered = Shadow::default();
        for from in enclosing {
            covered.extend_by(
                self.read_ctx.catalog_kv,
                self.read_ctx.fctx.resolution,
                self.read_ctx.ctes,
                from,
            );
        }
        let mut reach = AggregateReach::default();
        // `count(*)` reads nothing, so it belongs where it is written.
        if let FuncArgs::Exprs(args) = &call.args {
            for arg in args {
                self.reach(arg, &covered, &Shadow::default(), &mut reach);
            }
        }
        // `FILTER (WHERE …)` is levelled with the arguments it filters.
        if let Some(filter) = &call.filter {
            self.reach(filter, &covered, &Shadow::default(), &mut reach);
        }
        reach
    }

    /// Record which levels `expr` — an aggregate argument — reads.
    ///
    /// `covered` holds the names the enclosing sub-selects supply; `local` those
    /// supplied by sub-selects *within* the argument, whose variables
    /// `check_agg_arguments` ignores outright.
    fn reach(&self, expr: &Expr, covered: &Shadow, local: &Shadow, reach: &mut AggregateReach) {
        if let Expr::Column { table, name } = expr {
            let qualifier = table.as_deref();
            let local = local.supplies(qualifier, name);
            let covered = covered.supplies(qualifier, name);
            // Local to a sub-select of the argument, which is exactly what
            // `check_agg_arguments` ignores.
            if local == Some(true) {
                return;
            }
            if covered == Some(true) {
                reach.enclosing = true;
                return;
            }
            // Past every level in between. A name the statement's own FROM does
            // not supply is read at no level this decision turns on, so leaving
            // a FROM in between undescribed costs nothing for it.
            if self.statement.resolve(qualifier, name).is_err() {
                return;
            }
            // It resolves here — unless a FROM in between that could not be
            // described supplies it too, which is what cannot be settled.
            if local.is_none() || covered.is_none() {
                reach.unknown = true;
            } else {
                reach.statement = true;
            }
            return;
        }
        for child in expr_children(expr) {
            self.reach(child, covered, local, reach);
        }
        if let Some(query) = direct_subquery(expr) {
            self.reach_query(query, covered, local, reach);
        }
    }

    fn reach_query(
        &self,
        query: &crabka_pgparser::ast::QueryExpr,
        covered: &Shadow,
        local: &Shadow,
        reach: &mut AggregateReach,
    ) {
        let crabka_pgparser::ast::SetExpr::Query(crabka_pgparser::ast::QueryBody::Select(select)) =
            &query.body
        else {
            // A set operation or nested body reads names this pass does not lay
            // out; leave the aggregate unattributed rather than guess.
            reach.unknown = true;
            return;
        };
        let mut inner = local.clone();
        inner.extend_by(
            self.read_ctx.catalog_kv,
            self.read_ctx.fctx.resolution,
            self.read_ctx.ctes,
            &select.from,
        );
        for expr in select_exprs(select) {
            self.reach(expr, covered, &inner, reach);
        }
        for expr in query.order_by.iter().map(|item| &item.expr) {
            self.reach(expr, covered, &inner, reach);
        }
    }
}

/// Where an aggregate that belongs to the query level owning a FROM clause was
/// written, which is all that separates `PostgreSQL`'s three messages for it.
#[derive(Clone, Copy)]
enum FromAggregateSite {
    /// A sub-select used as a FROM item.
    Subselect,
    /// The arguments of a function (or `JSON_TABLE`) used as a FROM item.
    Function,
    /// A join's `ON` condition.
    JoinCondition,
}

impl FromAggregateSite {
    /// `PostgreSQL` words each site separately rather than through
    /// `ParseExprKindName`, so the strings are spelled out here too.
    fn message(self) -> &'static str {
        match self {
            Self::Subselect => {
                "aggregate functions are not allowed in FROM clause of their own query level"
            }
            Self::Function => "aggregate functions are not allowed in functions in FROM",
            Self::JoinCondition => "aggregate functions are not allowed in JOIN conditions",
        }
    }
}

/// The expression-kind context one aggregate is judged in: the FROM-clause
/// construct it was reached through, and whether it is written at the level that
/// owns the clause rather than inside a sub-select somewhere below it.
#[derive(Clone, Copy)]
struct FromAggregateContext {
    site: FromAggregateSite,
    /// An aggregate reading no variable keeps the level it is written at, so
    /// this is what decides whether that level is the one being checked.
    owning_level: bool,
}

impl FromAggregateContext {
    /// The same site, one query level down.
    fn nested(self) -> Self {
        Self {
            owning_level: false,
            ..self
        }
    }
}

/// Rejects an aggregate that `PostgreSQL` assigns to the query level whose FROM
/// clause is being built.
///
/// `check_agglevels_and_constraints` walks up to the level the aggregate's
/// arguments give it and asks what *that* level is transforming; a level in the
/// middle of its own FROM clause refuses. So
/// `SELECT 1 FROM t a, LATERAL (SELECT max(a.i) FROM u) ss` is an error while
/// `SELECT 1 FROM t a, LATERAL (SELECT max(u.i) FROM u) ss` is not — only the
/// first aggregate reads a variable of the level that owns the FROM clause. It
/// is the level, not the `LATERAL` keyword, that decides: `max(a.i + u.i)`
/// takes the *innermost* level its arguments read and so is allowed.
///
/// Levels below this one need no walk of their own here. A nested FROM item is
/// its own FROM clause, checked when that query builds, so the pass only ever
/// asks whether the level lands exactly here.
struct FromClauseAggregatePass<'a, 'b> {
    levels: AggregateLevels<'a, 'b>,
}

/// Does `te` write any aggregate call at all?
///
/// A pure AST walk with no catalog reads, which is what keeps
/// [`FromClauseAggregatePass`] free for the FROM clauses — nearly all of them —
/// that cannot trip the rule.
fn from_item_calls_aggregate(te: &crabka_pgparser::ast::TableExpr) -> bool {
    use crabka_pgparser::ast::{JoinConstraint, TableExpr};
    match te {
        TableExpr::Table { .. } => false,
        TableExpr::Derived { subquery, .. } => query_calls_aggregate(subquery),
        TableExpr::Function { functions, .. } => functions
            .iter()
            .flat_map(|call| &call.args)
            .any(expr_calls_aggregate),
        TableExpr::JsonTable(table) => table.exprs().into_iter().any(expr_calls_aggregate),
        TableExpr::Join {
            left,
            right,
            constraint,
            ..
        } => {
            from_item_calls_aggregate(left)
                || from_item_calls_aggregate(right)
                || matches!(constraint, JoinConstraint::On(on) if expr_calls_aggregate(on))
        }
    }
}

/// The [`from_item_calls_aggregate`] pre-filter over one expression, following
/// sub-selects because an aggregate inside one can still belong out here.
fn expr_calls_aggregate(expr: &Expr) -> bool {
    if let Expr::Func(call) = expr
        && crate::agg::is_aggregate_name(&call.name)
    {
        return true;
    }
    expr_children(expr).into_iter().any(expr_calls_aggregate)
        || direct_subquery(expr).is_some_and(query_calls_aggregate)
}

/// The [`from_item_calls_aggregate`] pre-filter over one query expression.
fn query_calls_aggregate(query: &crabka_pgparser::ast::QueryExpr) -> bool {
    use crabka_pgparser::ast::{CteBody, QueryBody, SetExpr};
    fn body(set: &SetExpr) -> bool {
        match set {
            SetExpr::Query(QueryBody::Select(select)) => {
                select_exprs(select).into_iter().any(expr_calls_aggregate)
                    || select.from.iter().any(from_item_calls_aggregate)
            }
            SetExpr::Query(QueryBody::Values(values)) => {
                values.rows.iter().flatten().any(expr_calls_aggregate)
            }
            SetExpr::Query(QueryBody::Nested(nested)) => query_calls_aggregate(nested),
            SetExpr::SetOp { left, right, .. } => body(left) || body(right),
        }
    }
    body(&query.body)
        || query
            .order_by
            .iter()
            .map(|item| &item.expr)
            .chain(&query.limit)
            .chain(&query.offset)
            .any(expr_calls_aggregate)
        || query
            .with
            .iter()
            .flat_map(|with| &with.ctes)
            .any(|cte| match &cte.body {
                CteBody::Query(body) => query_calls_aggregate(body),
                CteBody::Dml(_) => false,
            })
}

impl FromClauseAggregatePass<'_, '_> {
    /// Check one FROM item, and the join constraint that attaches it, against
    /// the level rule.
    fn check(
        &self,
        te: &crabka_pgparser::ast::TableExpr,
        constraint: &crabka_pgparser::ast::JoinConstraint,
    ) -> Result<(), ExecError> {
        if let crabka_pgparser::ast::JoinConstraint::On(on) = constraint {
            self.expr(on, &[], Self::owning(FromAggregateSite::JoinCondition))?;
        }
        self.table_expr(te)
    }

    fn owning(site: FromAggregateSite) -> FromAggregateContext {
        FromAggregateContext {
            site,
            owning_level: true,
        }
    }

    /// A FROM item is transformed at the level that owns it, so nothing its own
    /// FROM clause introduces is in scope for it yet — which is why `enclosing`
    /// starts empty however deep the join tree is.
    fn table_expr(&self, te: &crabka_pgparser::ast::TableExpr) -> Result<(), ExecError> {
        use crabka_pgparser::ast::{JoinConstraint, TableExpr};
        if !from_item_calls_aggregate(te) {
            return Ok(());
        }
        match te {
            TableExpr::Table { .. } => Ok(()),
            // A sub-select that is not `LATERAL` cannot see this query level at
            // all, so a reference reaching it is a scope error and never gets as
            // far as being levelled — `PostgreSQL` reports the reference.
            TableExpr::Derived {
                subquery,
                lateral: true,
                ..
            } => self.query(
                subquery,
                &[],
                Self::owning(FromAggregateSite::Subselect).nested(),
            ),
            TableExpr::Derived { .. } => Ok(()),
            TableExpr::Function { functions, .. } => functions
                .iter()
                .flat_map(|call| &call.args)
                .try_for_each(|arg| self.expr(arg, &[], Self::owning(FromAggregateSite::Function))),
            TableExpr::JsonTable(table) => table.exprs().into_iter().try_for_each(|expr| {
                self.expr(expr, &[], Self::owning(FromAggregateSite::Function))
            }),
            TableExpr::Join {
                left,
                right,
                constraint,
                ..
            } => {
                self.table_expr(left)?;
                self.table_expr(right)?;
                match constraint {
                    JoinConstraint::On(on) => {
                        self.expr(on, &[], Self::owning(FromAggregateSite::JoinCondition))
                    }
                    JoinConstraint::Using(_) | JoinConstraint::Natural | JoinConstraint::None => {
                        Ok(())
                    }
                }
            }
        }
    }

    fn expr(
        &self,
        expr: &Expr,
        enclosing: &[&[crabka_pgparser::ast::TableExpr]],
        ctx: FromAggregateContext,
    ) -> Result<(), ExecError> {
        if let Expr::Func(call) = expr
            && crate::agg::is_aggregate_name(&call.name)
            && self.belongs_to_this_level(call, enclosing, ctx)
        {
            return Err(ExecError::FunctionError {
                sqlstate: "42803",
                message: ctx.site.message().into(),
            });
        }
        expr_children(expr)
            .into_iter()
            .try_for_each(|child| self.expr(child, enclosing, ctx))?;
        match direct_subquery(expr) {
            Some(query) => self.query(query, enclosing, ctx.nested()),
            None => Ok(()),
        }
    }

    fn query(
        &self,
        query: &crabka_pgparser::ast::QueryExpr,
        enclosing: &[&[crabka_pgparser::ast::TableExpr]],
        ctx: FromAggregateContext,
    ) -> Result<(), ExecError> {
        use crabka_pgparser::ast::{CteBody, QueryBody, SetExpr};
        // A tail ORDER BY / LIMIT is evaluated at the query's own level, so it
        // walks under whatever FROM its body introduces. A set operation has no
        // single such FROM; its branches each describe their own.
        let body_from = match &query.body {
            SetExpr::Query(QueryBody::Select(select)) => select.from.as_slice(),
            _ => &[],
        };
        let inner = [enclosing, &[body_from]].concat();
        self.set_expr(&query.body, enclosing, ctx)?;
        query
            .order_by
            .iter()
            .map(|item| &item.expr)
            .chain(&query.limit)
            .chain(&query.offset)
            .try_for_each(|expr| self.expr(expr, &inner, ctx))?;
        query
            .with
            .iter()
            .flat_map(|with| &with.ctes)
            .try_for_each(|cte| match &cte.body {
                CteBody::Query(body) => self.query(body, enclosing, ctx),
                // A data-modifying CTE is a write path, not a FROM item this
                // level's rule reaches.
                CteBody::Dml(_) => Ok(()),
            })
    }

    fn set_expr(
        &self,
        body: &crabka_pgparser::ast::SetExpr,
        enclosing: &[&[crabka_pgparser::ast::TableExpr]],
        ctx: FromAggregateContext,
    ) -> Result<(), ExecError> {
        use crabka_pgparser::ast::{QueryBody, SetExpr};
        match body {
            SetExpr::Query(QueryBody::Select(select)) => {
                let inner = [enclosing, &[select.from.as_slice()]].concat();
                select_exprs(select)
                    .into_iter()
                    .try_for_each(|expr| self.expr(expr, &inner, ctx))?;
                // A FROM item of this sub-select belongs to *its* level, so it
                // keeps the enclosing chain the sub-select itself sits in.
                select
                    .from
                    .iter()
                    .try_for_each(|item| self.nested_table_expr(item, enclosing, ctx))
            }
            SetExpr::Query(QueryBody::Values(values)) => values
                .rows
                .iter()
                .flatten()
                .try_for_each(|expr| self.expr(expr, enclosing, ctx)),
            SetExpr::Query(QueryBody::Nested(nested)) => self.query(nested, enclosing, ctx),
            SetExpr::SetOp { left, right, .. } => {
                self.set_expr(left, enclosing, ctx)?;
                self.set_expr(right, enclosing, ctx)
            }
        }
    }

    /// A FROM item of a sub-select *inside* the item being checked. Its own
    /// aggregates are the inner level's business — this walk is only looking for
    /// one whose arguments reach back out to the level owning the FROM clause,
    /// so the site stays the one the outermost item fixed.
    fn nested_table_expr(
        &self,
        te: &crabka_pgparser::ast::TableExpr,
        enclosing: &[&[crabka_pgparser::ast::TableExpr]],
        ctx: FromAggregateContext,
    ) -> Result<(), ExecError> {
        use crabka_pgparser::ast::{JoinConstraint, TableExpr};
        let ctx = ctx.nested();
        match te {
            TableExpr::Table { .. } => Ok(()),
            TableExpr::Derived {
                subquery,
                lateral: true,
                ..
            } => self.query(subquery, enclosing, ctx),
            TableExpr::Derived { .. } => Ok(()),
            TableExpr::Function { functions, .. } => functions
                .iter()
                .flat_map(|call| &call.args)
                .try_for_each(|arg| self.expr(arg, enclosing, ctx)),
            TableExpr::JsonTable(table) => table
                .exprs()
                .into_iter()
                .try_for_each(|expr| self.expr(expr, enclosing, ctx)),
            TableExpr::Join {
                left,
                right,
                constraint,
                ..
            } => {
                self.nested_table_expr(left, enclosing, ctx)?;
                self.nested_table_expr(right, enclosing, ctx)?;
                match constraint {
                    JoinConstraint::On(on) => {
                        let inner = [
                            enclosing,
                            &[std::slice::from_ref(left.as_ref())],
                            &[std::slice::from_ref(right.as_ref())],
                        ]
                        .concat();
                        self.expr(on, &inner, ctx)
                    }
                    JoinConstraint::Using(_) | JoinConstraint::Natural | JoinConstraint::None => {
                        Ok(())
                    }
                }
            }
        }
    }

    /// Does this aggregate take its level from the query that owns the FROM
    /// clause being built?
    fn belongs_to_this_level(
        &self,
        call: &FuncCall,
        enclosing: &[&[crabka_pgparser::ast::TableExpr]],
        ctx: FromAggregateContext,
    ) -> bool {
        let reach = self.levels.reach_of(call, enclosing);
        // A name no level could be found for leaves the aggregate's level
        // unsettled, and an aggregate this pass cannot place is one it must not
        // reject — the statement keeps whatever error it already had.
        if reach.unknown || reach.enclosing {
            return false;
        }
        // A variable of the owning query's own FROM fixes the level outright.
        // With no variable at all the aggregate keeps the level it is written
        // at, which settles it only for one written in the FROM clause itself.
        reach.statement || ctx.owning_level
    }
}

/// Rewrite every select-list, `ORDER BY` and `DISTINCT ON` expression that reads
/// the source row into a reference to a hidden column, and return the plan that
/// fills those columns in.
///
/// Doing it as a rewrite rather than by threading a subquery context down into
/// the projection is what keeps an ordinary select list on its existing path:
/// once the statement carries no correlated expression, nothing downstream can
/// tell this pass ran.
fn plan_correlated_row_exprs(
    read_ctx: &crate::subquery::SubCtx<'_>,
    select: &SelectStmt,
    outer: &Scope,
) -> Result<(SelectStmt, Option<CorrelatedRowExprs>), ExecError> {
    // With no source row there is nothing to correlate to. Grouping is excluded
    // for a different reason: its output row is a fold of many source rows, and
    // a hidden column carrying one source row's value would not survive it.
    // `PostgreSQL` allows the shape when the correlation only reads grouped
    // columns; here it keeps reporting the missing FROM entry it reports today.
    if outer.width() == 0 || crate::grouping::is_grouping_query(select) {
        return Ok((select.clone(), None));
    }
    // An aggregate written inside a sub-select can belong to THIS query level,
    // which makes the statement a grouping query that [`is_grouping_query`]
    // cannot see because no aggregate is written at this level. Deferring then
    // answers one row per source row where `PostgreSQL` folds them to one, so
    // such a statement stays on the ordinary path with the rest of them.
    if defers_statement_level_aggregate(read_ctx, select, outer) {
        return Ok((select.clone(), None));
    }
    let mut plan = CorrelatedRowExprs::default();
    let mut rewritten = select.clone();
    for item in &mut rewritten.projection {
        let SelectItem::Expr { expr, alias } = item else {
            continue;
        };
        let Some(marker) = plan.defer(read_ctx, expr, outer)? else {
            continue;
        };
        // The marker is a column reference, and an unaliased item is labelled
        // after its expression — so the label has to be pinned before the
        // expression it was derived from is gone.
        if alias.is_none() {
            *alias = Some(derived_name(expr));
        }
        *expr = marker;
    }
    for item in &mut rewritten.order_by {
        if let Some(marker) = plan.defer(read_ctx, &item.expr, outer)? {
            item.expr = marker;
        }
    }
    if let crabka_pgparser::ast::DistinctClause::On(on) = &mut rewritten.distinct {
        for expr in on {
            if let Some(marker) = plan.defer(read_ctx, expr, outer)? {
                *expr = marker;
            }
        }
    }
    if plan.exprs.is_empty() {
        return Ok((select.clone(), None));
    }
    Ok((rewritten, Some(plan)))
}

/// The reference standing in for the deferred expression at `index`.
fn correlated_marker(index: usize) -> Expr {
    Expr::Column {
        table: Some(crate::scope::CORRELATED_QUALIFIER.to_string()),
        name: index.to_string(),
    }
}

/// Is this binding one of the hidden columns [`plan_correlated_row_exprs`] adds?
/// `SELECT *` must not expand to them.
fn is_correlated_binding(c: &ColumnBinding) -> bool {
    c.qualifier.as_deref() == Some(crate::scope::CORRELATED_QUALIFIER)
}

/// Does a select list or `ORDER BY` refer to a hidden correlated column?
fn select_mentions_correlated_marker(s: &SelectStmt) -> bool {
    s.projection.iter().any(|item| match item {
        SelectItem::Expr { expr, .. } => expr_mentions_correlated_marker(expr),
        SelectItem::Wildcard | SelectItem::QualifiedWildcard(_) => false,
    }) || s
        .order_by
        .iter()
        .any(|item| expr_mentions_correlated_marker(&item.expr))
}

fn expr_mentions_correlated_marker(expr: &Expr) -> bool {
    matches!(
        expr,
        Expr::Column { table: Some(table), .. } if table == crate::scope::CORRELATED_QUALIFIER
    ) || expr_children(expr)
        .into_iter()
        .any(expr_mentions_correlated_marker)
}

/// Evaluate the deferred expressions for every source row, appending their
/// values as the hidden columns the rewritten statement refers to.
///
/// Each row is bound and folded exactly the way a correlated `WHERE` is, so a
/// dead CASE branch or an unselected COALESCE argument still does not run its
/// subquery, and an uncorrelated subquery nested under one runs once.
fn materialize_correlated_row_exprs(
    read_ctx: &crate::subquery::SubCtx<'_>,
    plan: CorrelatedRowExprs,
    scope: &mut Scope,
    rows: &mut [Vec<Datum>],
) -> Result<(), ExecError> {
    let CorrelatedRowExprs {
        sources: _,
        exprs,
        bindings,
        initplans,
        scalar_lookups,
    } = plan;
    let mut binder =
        LateralBinder::new(read_ctx.catalog_kv, read_ctx.fctx.resolution, read_ctx.ctes)
            .with_initplans(initplans)
            .with_scalar_lookups(scalar_lookups);
    for row in rows.iter_mut() {
        let mut values = Vec::with_capacity(exprs.len());
        for (walk, expr) in exprs.iter().enumerate() {
            binder.walking(walk);
            let (bound, _) = binder.bind_expr(expr, scope, row)?;
            let folded =
                fold_correlated_lazy_expressions(read_ctx, &bound, scope, row, &mut binder)?;
            let initialized = resolve_lazy_initplans(read_ctx, &folded, &mut binder)?;
            let resolved = crate::subquery::resolve_expr(read_ctx, &initialized)?;
            values.push(crate::eval::eval(&resolved, scope, row, read_ctx.eval_ctx)?);
        }
        row.extend(values);
    }
    scope.columns.extend(bindings);
    Ok(())
}

/// Resolve a SELECT while deferring only WHERE subtrees that read the SELECT's
/// source row. Ordinary siblings retain the existing once-only resolution.
///
/// Other clauses deliberately stay on their existing path. Projection, HAVING,
/// and window expressions run at different stages; evaluating them here would
/// incorrectly execute a subquery for rows an earlier stage discards.
fn prepare_correlated_subqueries(
    read_ctx: &crate::subquery::SubCtx<'_>,
    select: &SelectStmt,
    outer: &Scope,
) -> Result<
    (
        SelectStmt,
        bool,
        Vec<LazyInitPlan>,
        Vec<CorrelatedScalarLookup>,
    ),
    ExecError,
> {
    let mut without_filter = select.clone();
    let filter = without_filter.filter.take();
    let mut resolved = crate::subquery::resolve_in_select(read_ctx, &without_filter)?;
    let correlated = filter
        .as_ref()
        .map(|filter| validate_correlated_subqueries(read_ctx, filter, outer))
        .transpose()?
        .unwrap_or(false);
    let mut initplans = Vec::new();
    let mut scalar_lookups = Vec::new();
    resolved.filter = filter
        .as_ref()
        .map(|filter| {
            let planned = install_lazy_initplans(
                read_ctx,
                filter,
                outer,
                false,
                &mut initplans,
                &mut scalar_lookups,
            )?;
            crate::subquery::resolve_expr_skipping(read_ctx, &planned, &mut |node| {
                let candidate = scalar_lookup_parts(node).is_some()
                    || direct_subquery(node).is_some()
                    || matches!(node, Expr::Func(_) | Expr::Case { .. });
                scalar_lookup_parts(node).is_some()
                    || candidate && expression_contains_correlated_subquery(read_ctx, node, outer)
            })
        })
        .transpose()?;
    if correlated {
        let nulls = vec![Datum::Null; outer.width()];
        let mut binder =
            LateralBinder::new(read_ctx.catalog_kv, read_ctx.fctx.resolution, read_ctx.ctes);
        let (bound, _) = binder.bind_expr(
            resolved
                .filter
                .as_ref()
                .expect("a correlated filter is present"),
            outer,
            &nulls,
        )?;
        let typed =
            type_without_evaluating_subqueries(read_ctx, &bound, &initplans, &scalar_lookups)?;
        crate::eval::check_predicate_resolves(&typed, outer)?;
        let result_type = crate::eval::infer_type(&typed, outer)?;
        if result_type != ColumnType::Bool {
            return Err(ExecError::TypeMismatch(format!(
                "argument of WHERE must be type boolean, not type {}",
                result_type.name()
            )));
        }
    }
    Ok((resolved, correlated, initplans, scalar_lookups))
}

fn validate_correlated_subqueries(
    read_ctx: &crate::subquery::SubCtx<'_>,
    expr: &Expr,
    outer: &Scope,
) -> Result<bool, ExecError> {
    let mut correlated = false;
    if let Some(query) = direct_subquery(expr) {
        let nulls = vec![Datum::Null; outer.width()];
        let mut binder =
            LateralBinder::new(read_ctx.catalog_kv, read_ctx.fctx.resolution, read_ctx.ctes);
        let (bound, direct_correlated) = binder.bind_query(query, outer, &nulls)?;
        let fields = crate::query::describe_query_expr_with_ctes(
            read_ctx.catalog_kv,
            read_ctx.fctx.resolution,
            &bound,
            read_ctx.ctes,
        )?;
        if !matches!(expr, Expr::Exists(_)) && fields.len() != 1 {
            return Err(ExecError::SubqueryColumns);
        }
        correlated |= direct_correlated;
    }
    for child in expr_children(expr) {
        correlated |= validate_correlated_subqueries(read_ctx, child, outer)?;
    }
    Ok(correlated)
}

fn contains_subquery(expr: &Expr) -> bool {
    direct_subquery(expr).is_some() || expr_children(expr).into_iter().any(contains_subquery)
}

fn contains_pending_subquery(expr: &Expr) -> bool {
    initplan_parts(expr).is_some()
        || scalar_lookup_parts(expr).is_some()
        || direct_subquery(expr).is_some()
        || expr_children(expr)
            .into_iter()
            .any(contains_pending_subquery)
}

fn expression_contains_correlated_subquery(
    read_ctx: &crate::subquery::SubCtx<'_>,
    expr: &Expr,
    outer: &Scope,
) -> bool {
    if scalar_lookup_parts(expr).is_some() {
        return true;
    }
    if let Some(query) = direct_subquery(expr) {
        let nulls = vec![Datum::Null; outer.width()];
        let mut binder =
            LateralBinder::new(read_ctx.catalog_kv, read_ctx.fctx.resolution, read_ctx.ctes);
        if binder
            .bind_query(query, outer, &nulls)
            .is_ok_and(|(_, correlated)| correlated)
        {
            return true;
        }
    }
    expr_children(expr)
        .into_iter()
        .any(|child| expression_contains_correlated_subquery(read_ctx, child, outer))
}

fn direct_subquery(expr: &Expr) -> Option<&crabka_pgparser::ast::QueryExpr> {
    match expr {
        Expr::ScalarSubquery(query) | Expr::ArraySubquery(query) | Expr::Exists(query) => {
            Some(query)
        }
        Expr::InSubquery { subquery, .. } | Expr::Quantified { subquery, .. } => Some(subquery),
        _ => None,
    }
}

fn row_matches_correlated(
    read_ctx: &crate::subquery::SubCtx<'_>,
    filter: Option<&Expr>,
    outer: &Scope,
    row: &[Datum],
    binder: &mut LateralBinder<'_>,
) -> Result<bool, ExecError> {
    let Some(filter) = filter else {
        return Ok(true);
    };
    let (bound, correlated) = binder.bind_expr(filter, outer, row)?;
    debug_assert!(correlated);
    let lazy = fold_correlated_lazy_expressions(read_ctx, &bound, outer, row, binder)?;
    let initialized = resolve_lazy_initplans(read_ctx, &lazy, binder)?;
    let resolved = crate::subquery::resolve_expr(read_ctx, &initialized)?;
    row_matches(Some(&resolved), outer, row, read_ctx.eval_ctx)
}

/// Fold lazy expressions containing deferred subqueries one selected branch or
/// argument at a time. Eager subquery rewriting must not execute a dead CASE
/// branch, an unused COALESCE argument, or the right operand of a boolean
/// connective the left operand has already settled.
fn fold_correlated_lazy_expressions(
    read_ctx: &crate::subquery::SubCtx<'_>,
    expr: &Expr,
    scope: &Scope,
    row: &[Datum],
    binder: &mut LateralBinder<'_>,
) -> Result<Expr, ExecError> {
    // A boolean connective settles on its left operand alone whenever the
    // three-valued table has a wildcard row for it: `false AND anything` is
    // false and `true OR anything` is true, for `anything` including NULL. The
    // right operand's subqueries are then dead and must not run — the whole
    // point of a `WHERE cheap_predicate AND EXISTS (expensive)` is that the
    // expensive half is reached only by the rows the cheap half admits.
    //
    // The short-circuit in `eval` cannot do this job. Everything reaching the
    // evaluator here has already been through `subquery::resolve_expr`, which
    // executes every subquery in the tree before the connective is looked at,
    // so by then the work is spent. Laziness has to happen where subqueries
    // are still unresolved, which is here.
    if let Expr::Binary {
        op: op @ (BinaryOp::And | BinaryOp::Or),
        left,
        right,
    } = expr
        && contains_pending_subquery(right)
    {
        let value = eval_correlated_child(read_ctx, left, scope, row, binder)?;
        let settled = match (op, &value) {
            (BinaryOp::And, Datum::Bool(false)) => Some(false),
            (BinaryOp::Or, Datum::Bool(true)) => Some(true),
            _ => None,
        };
        if let Some(settled) = settled {
            return Ok(Expr::Const {
                value: Datum::Bool(settled),
                ty: ColumnType::Bool,
            });
        }
        // Undecided: the right operand still decides the answer, so it is
        // folded as usual. The left operand is carried across as the constant
        // it just evaluated to, so its own subqueries run once, not twice.
        let typed = type_without_evaluating_subqueries(
            read_ctx,
            left,
            &binder.initplans,
            &binder.scalar_lookups,
        )?;
        let left_type = crate::eval::infer_type(&typed, scope)?;
        return Ok(Expr::Binary {
            op: *op,
            left: Box::new(Expr::Const {
                value,
                ty: left_type,
            }),
            right: Box::new(fold_correlated_lazy_expressions(
                read_ctx, right, scope, row, binder,
            )?),
        });
    }

    if let Expr::Func(call) = expr
        && call.name == "coalesce"
        && contains_pending_subquery(expr)
    {
        let typed = type_without_evaluating_subqueries(
            read_ctx,
            expr,
            &binder.initplans,
            &binder.scalar_lookups,
        )?;
        if let Expr::Func(typed_call) = &typed
            && typed_call.name == "coalesce"
            && crate::routine::plpgsql_declared_call_type(read_ctx.catalog_kv, typed_call)?
                .is_none()
        {
            let result_type = crate::eval::infer_type(&typed, scope)?;
            let value = crate::func::eval_scalar(call, None, read_ctx.eval_ctx, |arg| {
                eval_correlated_child(read_ctx, arg, scope, row, binder)
            })?;
            return Ok(Expr::Const {
                value: crate::eval::cast_value(&value, result_type, &read_ctx.eval_ctx.time_zone)?,
                ty: result_type,
            });
        }
    }

    if let Expr::Case {
        operand,
        whens,
        else_result,
    } = expr
        && contains_pending_subquery(expr)
    {
        let typed = type_without_evaluating_subqueries(
            read_ctx,
            expr,
            &binder.initplans,
            &binder.scalar_lookups,
        )?;
        let result_type = crate::eval::infer_type(&typed, scope)?;
        let selected = if let Some(operand) = operand {
            let value = eval_correlated_child(read_ctx, operand, scope, row, binder)?;
            let mut selected = None;
            for (when, then) in whens {
                let candidate = eval_correlated_child(read_ctx, when, scope, row, binder)?;
                if crate::eval::apply_binary(
                    crabka_pgparser::ast::BinaryOp::Eq,
                    &value,
                    &candidate,
                    read_ctx.eval_ctx,
                )? == Datum::Bool(true)
                {
                    selected = Some(then);
                    break;
                }
            }
            selected.or(else_result.as_deref())
        } else {
            let mut selected = None;
            for (when, then) in whens {
                match eval_correlated_child(read_ctx, when, scope, row, binder)? {
                    Datum::Bool(true) => {
                        selected = Some(then);
                        break;
                    }
                    Datum::Bool(false) | Datum::Null => {}
                    _ => {
                        return Err(ExecError::TypeMismatch(
                            "argument of CASE/WHEN must be type boolean".into(),
                        ));
                    }
                }
            }
            selected.or(else_result.as_deref())
        };
        let value = match selected {
            Some(selected) => eval_correlated_child(read_ctx, selected, scope, row, binder)?,
            None => Datum::Null,
        };
        return Ok(Expr::Const {
            value: crate::eval::cast_value(&value, result_type, &read_ctx.eval_ctx.time_zone)?,
            ty: result_type,
        });
    }

    let mut folded = expr.clone();
    for child in expr_children_mut(&mut folded) {
        *child = fold_correlated_lazy_expressions(read_ctx, child, scope, row, binder)?;
    }
    Ok(folded)
}

fn eval_correlated_child(
    read_ctx: &crate::subquery::SubCtx<'_>,
    expr: &Expr,
    scope: &Scope,
    row: &[Datum],
    binder: &mut LateralBinder<'_>,
) -> Result<Datum, ExecError> {
    let folded = fold_correlated_lazy_expressions(read_ctx, expr, scope, row, binder)?;
    let initialized = resolve_lazy_initplans(read_ctx, &folded, binder)?;
    let resolved = crate::subquery::resolve_expr(read_ctx, &initialized)?;
    crate::eval::eval(&resolved, scope, row, read_ctx.eval_ctx)
}

fn resolve_lazy_initplans(
    read_ctx: &crate::subquery::SubCtx<'_>,
    expr: &Expr,
    binder: &mut LateralBinder<'_>,
) -> Result<Expr, ExecError> {
    if let Some((index, key)) = scalar_lookup_parts(expr) {
        let resolved = binder.resolve_scalar_lookup(read_ctx, index, key)?;
        return resolve_lazy_initplans(read_ctx, &resolved, binder);
    }
    if let Some((index, lhs)) = initplan_parts(expr) {
        let resolved = binder.resolve_initplan(read_ctx, index, lhs)?;
        return resolve_lazy_initplans(read_ctx, &resolved, binder);
    }
    let mut initialized = expr.clone();
    for child in expr_children_mut(&mut initialized) {
        *child = resolve_lazy_initplans(read_ctx, child, binder)?;
    }
    Ok(initialized)
}

fn replace_initplan_markers_with_typed_nulls(
    expr: &Expr,
    initplans: &[LazyInitPlan],
    scalar_lookups: &[CorrelatedScalarLookup],
) -> Result<Expr, ExecError> {
    if let Some((index, _)) = scalar_lookup_parts(expr) {
        let plan = scalar_lookups.get(index).ok_or_else(|| {
            ExecError::Unsupported("invalid correlated scalar lookup marker".into())
        })?;
        return Ok(Expr::Const {
            value: Datum::Null,
            ty: plan.result_type,
        });
    }
    if let Some((index, _)) = initplan_parts(expr) {
        let plan = initplans
            .get(index)
            .ok_or_else(|| ExecError::Unsupported("invalid deferred subquery marker".into()))?;
        return Ok(Expr::Const {
            value: Datum::Null,
            ty: plan.result_type,
        });
    }
    let mut typed = expr.clone();
    for child in expr_children_mut(&mut typed) {
        *child = replace_initplan_markers_with_typed_nulls(child, initplans, scalar_lookups)?;
    }
    Ok(typed)
}

fn type_without_evaluating_subqueries(
    read_ctx: &crate::subquery::SubCtx<'_>,
    expr: &Expr,
    initplans: &[LazyInitPlan],
    scalar_lookups: &[CorrelatedScalarLookup],
) -> Result<Expr, ExecError> {
    let typed = replace_initplan_markers_with_typed_nulls(expr, initplans, scalar_lookups)?;
    let typed = replace_subqueries_with_typed_nulls(read_ctx, &typed)?;
    let typed = crate::subquery::resolve_expr_skipping(read_ctx, &typed, &mut |node| {
        direct_subquery(node).is_some()
    })?;
    replace_subqueries_with_typed_nulls(read_ctx, &typed)
}

/// Replace subquery nodes with typed NULLs without executing them, so CASE can
/// determine its common result type before choosing a branch.
fn replace_subqueries_with_typed_nulls(
    read_ctx: &crate::subquery::SubCtx<'_>,
    expr: &Expr,
) -> Result<Expr, ExecError> {
    let typed_null = |query: &crabka_pgparser::ast::QueryExpr| {
        let fields = crate::query::describe_query_expr_with_ctes(
            read_ctx.catalog_kv,
            read_ctx.fctx.resolution,
            query,
            read_ctx.ctes,
        )?;
        if fields.len() != 1 {
            return Err(ExecError::SubqueryColumns);
        }
        column_type_from_oid(fields[0].type_oid)
    };
    match expr {
        Expr::ScalarSubquery(query) => Ok(Expr::Const {
            value: Datum::Null,
            ty: typed_null(query)?,
        }),
        Expr::ArraySubquery(query) => {
            let ty = typed_null(query)?;
            let elem = crabka_pgtypes::ElemType::from_column_type(ty).ok_or_else(|| {
                ExecError::Unsupported(format!("arrays of {} are not supported", ty.name()))
            })?;
            Ok(Expr::Const {
                value: Datum::Null,
                ty: ColumnType::Array(elem),
            })
        }
        Expr::Exists(query) => {
            crate::query::describe_query_expr_with_ctes(
                read_ctx.catalog_kv,
                read_ctx.fctx.resolution,
                query,
                read_ctx.ctes,
            )?;
            Ok(Expr::Const {
                value: Datum::Null,
                ty: ColumnType::Bool,
            })
        }
        Expr::InSubquery { subquery, .. } | Expr::Quantified { subquery, .. } => {
            typed_null(subquery)?;
            Ok(Expr::Const {
                value: Datum::Null,
                ty: ColumnType::Bool,
            })
        }
        _ => {
            let mut typed = expr.clone();
            for child in expr_children_mut(&mut typed) {
                *child = replace_subqueries_with_typed_nulls(read_ctx, child)?;
            }
            Ok(typed)
        }
    }
}

/// How far below the relation it names a statement is asking to reach.
///
/// `PostgreSQL` spells this with one keyword — `ONLY` — and the engine used to
/// carry it as the one boolean the parser produces. That is why `ONLY` was
/// ignored on a partitioned parent: the keyword answers two independent
/// questions at once, and the engine's own tree walks need the two answers to
/// differ.
///
/// * An inheritance parent stores rows of its own, and its descendants store
///   more. `ONLY` asks for the parent's.
/// * A partitioned parent stores no rows at all. Its leaves store them, and
///   `ONLY` therefore asks for nothing.
///
/// A walk that has already enumerated the inheritance descendants must not
/// enumerate them again — it would read every relation once per path to it
/// through a multiple-inheritance DAG — but it still has to reach a partitioned
/// relation's leaves. Written as one boolean those two are the same value, and
/// they are not the same request: `TRUNCATE parted` desugars to an unfiltered
/// `DELETE` that says "do not walk inheritance", and reading that as the user's
/// `ONLY` empties nothing at all.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Reach {
    /// Everything at or below the named relation: its own rows, its inheritance
    /// descendants', and the leaves' of any partitioned relation among them.
    /// What a statement that omitted `ONLY` asks for.
    Tree,
    /// The rows the named relation stores itself, and nothing below it. What
    /// `ONLY` asks for. A partitioned parent stores none, so `ONLY` over one
    /// reads and writes nothing — which is what `PostgreSQL` does.
    OwnRows,
    /// The named relation's own rows, plus its leaves' if it is partitioned, but
    /// no inheritance walk: the caller has already done that walk. Only the
    /// engine's own tree walks and desugarings ask for this; no SQL spells it.
    Storage,
}

impl Reach {
    /// What the statement itself asks for, before any engine rewrite.
    fn of(stmt: &Statement) -> Self {
        match stmt {
            Statement::Update { only: true, .. } | Statement::Delete { only: true, .. } => {
                Reach::OwnRows
            }
            _ => Reach::Tree,
        }
    }

    /// Whether a partitioned relation reached this way expands into its leaves.
    fn spans_partitions(self) -> bool {
        match self {
            Reach::Tree | Reach::Storage => true,
            Reach::OwnRows => false,
        }
    }
}

/// Read a partitioned parent as the append of its leaf partitions.
///
/// Each leaf is scanned through the ordinary base-table path and its rows are
/// permuted into the parent's column order. A leaf attached by `ATTACH
/// PARTITION` may declare the same columns in a different order, and
/// `PostgreSQL` maps them by name.
fn partitioned_scan(
    read_ctx: &crate::subquery::SubCtx<'_>,
    parent: &Table,
    qualifier: &str,
    permit: &crate::privilege::ReadPermit,
) -> Result<crate::rls::RawScan, ExecError> {
    let tableoid = crate::scope::wants_tableoid(read_ctx.refs);
    let mut tree = crate::rls::RawScan::tree_of(parent, qualifier, tableoid);
    for leaf in crate::partition::leaves_of(read_ctx.catalog_kv, &parent.name)? {
        let leaf_table = crabka_pgcatalog::get_table(read_ctx.catalog_kv, &leaf)?;
        let ordinals = tree_ordinals(parent, &leaf_table, tableoid)?;
        // Straight to the scan, not back through `build_table_expr`: re-entering
        // there would run each leaf through the row-security gate under the
        // LEAF's policies, and then run the whole append through it again under
        // the parent's. PostgreSQL applies the parent's policies to the tree and
        // none of the children's, so the leaf's rows must arrive here ungated.
        // Its privileges likewise: the leaf is read under the parent's permit,
        // because reading a partitioned relation is not a read of each leaf.
        let leaf_scan = scan_stored_relation(
            read_ctx,
            &leaf_table,
            &leaf.name,
            Reach::Storage,
            None,
            None,
            &crate::privilege::ReadPermit::inherited(permit),
        )?;
        tree.absorb(leaf_scan, &ordinals);
    }
    Ok(tree)
}

/// Read a table and all inheritance descendants as rows shaped like the parent.
fn inherited_scan(
    read_ctx: &crate::subquery::SubCtx<'_>,
    parent: &Table,
    qualifier: &str,
    permit: &crate::privilege::ReadPermit,
) -> Result<crate::rls::RawScan, ExecError> {
    let mut relations = vec![parent.name.clone()];
    relations.extend(crate::inheritance::descendants(
        read_ctx.catalog_kv,
        &parent.name,
    )?);
    let tableoid = crate::scope::wants_tableoid(read_ctx.refs);
    let mut tree = crate::rls::RawScan::tree_of(parent, qualifier, tableoid);
    for relation_name in relations {
        let table = crabka_pgcatalog::get_table(read_ctx.catalog_kv, &relation_name)?;
        let ordinals = tree_ordinals(parent, &table, tableoid)?;
        // See `partitioned_scan`: the child's rows are governed by the parent's
        // policies and read under the parent's permit, so they must not pass
        // through either gate on their own.
        let child = scan_stored_relation(
            read_ctx,
            &table,
            &relation_name.name,
            Reach::Storage,
            None,
            None,
            &crate::privilege::ReadPermit::inherited(permit),
        )?;
        tree.absorb(child, &ordinals);
    }
    Ok(tree)
}

/// Every way the executor reads the rows of one stored relation, behind one
/// signature.
///
/// The `TableExpr::Table` arm used to have five separate `return Ok(Relation)`
/// exits for a stored relation — the inheritance scan, the partition scan, the
/// foreign scan, the local-index fast path and the ordinary MVCC scan — and a
/// sixth would have been added the same way. They all funnel through here now,
/// and here is the only place that can produce a [`crate::rls::RawScan`], whose
/// only exit in turn is [`crate::rls::apply_row_security`]. A new scan path
/// either goes through the gate or does not compile.
///
/// Wrapping `build_table_expr` instead would have been wrong: `inherited_scan`
/// and `partitioned_scan` read each child relation, so a wrapper would apply the
/// gate once per child under that child's policies and then again over the
/// append under the parent's.
///
/// The [`crate::privilege::ReadPermit`] is the same idea one layer up: it is
/// unforgeable outside `privilege`, so this function cannot be reached without
/// someone having asked whether the session may read the relation at all. The
/// tree scans hand their parent's permit down rather than taking one of their
/// own, because `PostgreSQL` checks the ACL of the relation the query named and
/// none of its descendants'.
fn scan_stored_relation(
    read_ctx: &crate::subquery::SubCtx<'_>,
    t: &Table,
    qualifier: &str,
    reach: Reach,
    bounds: Option<&ScanBounds>,
    scan_plan: Option<&crate::plan_dist::DistributedScanPlan>,
    permit: &crate::privilege::ReadPermit,
) -> Result<crate::rls::RawScan, ExecError> {
    let catalog_kv = read_ctx.catalog_kv;
    if reach == Reach::Tree && !crate::inheritance::children_of(catalog_kv, &t.name)?.is_empty() {
        return inherited_scan(read_ctx, t, qualifier, permit);
    }
    // A partitioned parent owns no rows: reading it is an append over its
    // leaves. Doing this before every other scan path is what keeps a
    // partitioned relation from silently answering empty.
    //
    // Under `ONLY` there is nothing to append, and the fall-through below reads
    // the parent's own — empty — row space, which is the answer `PostgreSQL`
    // gives. This test used to run whatever the statement said, so `SELECT *
    // FROM ONLY parted` returned the leaves' rows and `DELETE FROM ONLY parted`
    // destroyed them.
    if reach.spans_partitions() && crate::partition::is_partitioned(catalog_kv, &t.name)? {
        return partitioned_scan(read_ctx, t, qualifier, permit);
    }
    let mut scope = Scope::single(t, qualifier);
    // The oid this relation stamps on every row it yields, when the statement
    // spells `tableoid` and nothing otherwise. Taken once, before the rows: it
    // is a catalog fact about the relation, not about any row of it.
    let stamp = crate::scope::wants_tableoid(read_ctx.refs)
        .then(|| crate::catalog_rel::table_relation_oid(t.id))
        .transpose()?
        .map(Datum::Int4);
    if stamp.is_some() {
        scope.push_tableoid(qualifier);
    }
    // SP40: a foreign table reads through the registered scanner, not the local
    // MVCC version store. `build_from` materializes BEFORE WHERE, so this scan
    // runs even for `WHERE false` — there is no skip path.
    if let Some(meta) = &t.foreign {
        let scanner = read_ctx.fctx.scanner.ok_or_else(|| {
            ExecError::Unsupported("foreign tables require the `kafka` feature".into())
        })?;
        let server = crabka_pgcatalog::get_server(catalog_kv, &meta.server)?;
        // A per-user mapping is optional: fall back to no credentials when the
        // current user has none registered for this server.
        let mapping = crabka_pgcatalog::get_user_mapping(
            catalog_kv,
            read_ctx.fctx.current_user,
            &meta.server,
        )
        .ok();
        // SP40 Task 14: pass the pushed-down slice when present (single foreign
        // table). The residual WHERE still re-filters locally, so results are
        // identical whether or not the scan honors `bounds`.
        let default_bounds = ScanBounds::default();
        let scan_bounds = bounds.unwrap_or(&default_bounds);
        let mut rows =
            scanner.scan(t, &server, mapping.as_ref(), scan_bounds, read_ctx.eval_ctx)?;
        resolve_scanned_regclass(catalog_kv, t, &mut rows)?;
        expand_virtual_generated(t, &mut rows, read_ctx.eval_ctx)?;
        return Ok(crate::rls::RawScan::of_relation(
            t,
            scope,
            stamped(rows, stamp.as_ref()),
        ));
    }
    let default_scan_plan = crate::plan_dist::DistributedScanPlan::default();
    // A pushed-down predicate, projection, aggregate or top-K reads the row as
    // it sits in storage, where a `VIRTUAL` generated column is a NULL
    // placeholder. Such a relation is scanned whole and filtered above the
    // scan, after `expand_virtual_generated` has produced the real values.
    let requested = if has_virtual_generated(t) {
        &default_scan_plan
    } else {
        scan_plan.unwrap_or(&default_scan_plan)
    };
    let decision = crate::rls::decide(
        &read_ctx.rls(),
        t,
        crabka_pgcatalog::policy::PolicyCommand::Select,
    )?;
    // Sanitize where the `ScanRequest` is built rather than trusting each caller
    // to have stripped its own plan: an aggregate folded inside the scanner sums
    // rows the qual has not removed yet, and a top-K truncates before it runs.
    let sanitized = crate::rls::sanitize_scan_plan(&decision, requested);
    let distributed_plan = sanitized.as_ref().unwrap_or(requested);
    if let Some(unrestricted) = crate::rls::UnrestrictedTable::from_decision(permit, &decision, t)
        && let Some(rows) = try_scan_with_local_index(read_ctx, unrestricted, distributed_plan)?
    {
        let mut rows: Vec<Vec<Datum>> = rows.into_iter().map(|scanned| scanned.row).collect();
        resolve_scanned_regclass(catalog_kv, t, &mut rows)?;
        expand_virtual_generated(t, &mut rows, read_ctx.eval_ctx)?;
        return Ok(crate::rls::RawScan::of_relation(
            t,
            scope,
            stamped(rows, stamp.as_ref()),
        ));
    }
    let scan_request = ScanRequest {
        local: read_ctx.kv,
        global: read_ctx.global,
        global_snapshot: read_ctx.gsnap,
        snapshot: read_ctx.snapshot,
        own_xid: read_ctx.own,
        read_ts: None,
        own_start_ts: None,
        table: t,
        interval: RowInterval::ALL,
        predicate: distributed_plan.predicate.clone(),
        projection: distributed_plan.projection.clone(),
        partial_aggregate: distributed_plan.partial_aggregate.clone(),
        top_k: distributed_plan.top_k.clone(),
    };
    let rows = match crate::scanner::collect_cursor_bounded(
        read_ctx.range_scanner,
        scan_request,
        read_ctx.blocking_query_memory,
    ) {
        Ok(rows) => rows,
        Err(error) if should_retry_without_scan_pushdown(&error, distributed_plan) => {
            crate::scanner::collect_cursor_bounded(
                read_ctx.range_scanner,
                ScanRequest {
                    local: read_ctx.kv,
                    global: read_ctx.global,
                    global_snapshot: read_ctx.gsnap,
                    snapshot: read_ctx.snapshot,
                    own_xid: read_ctx.own,
                    read_ts: None,
                    own_start_ts: None,
                    table: t,
                    interval: RowInterval::ALL,
                    predicate: PredicatePushdown::FullScan,
                    projection: crate::ProjectionPushdown::All,
                    partial_aggregate: None,
                    top_k: None,
                },
                read_ctx.blocking_query_memory,
            )?
        }
        Err(error) => return Err(error),
    }
    .into_iter()
    .map(|scanned| scanned.row)
    .collect();
    let mut rows: Vec<Vec<Datum>> = rows;
    resolve_scanned_regclass(catalog_kv, t, &mut rows)?;
    expand_virtual_generated(t, &mut rows, read_ctx.eval_ctx)?;
    Ok(crate::rls::RawScan::of_relation(
        t,
        scope,
        stamped(rows, stamp.as_ref()),
    ))
}

/// `rows`, each extended by `stamp` when the scan carries one.
///
/// The stamp goes on AFTER `resolve_scanned_regclass` and
/// `expand_virtual_generated`, both of which read a row by the ordinals of the
/// relation's declared columns and would mistake a longer row for a corrupt
/// one.
fn stamped(mut rows: Vec<Vec<Datum>>, stamp: Option<&Datum>) -> Vec<Vec<Datum>> {
    if let Some(oid) = stamp {
        for row in &mut rows {
            row.push(oid.clone());
        }
    }
    rows
}

/// [`column_mapping`] for a tree scan, extended by the hidden `tableoid` when
/// the statement asks for one.
///
/// `source.columns.len()` is where the child's own scan appended its stamp,
/// whether the child was a plain relation ([`Scope::single`]) or a nested tree
/// ([`crate::rls::RawScan::tree_of`]) — both scopes are exactly the child's
/// declared width before the system column goes on. Reading it through the same
/// permutation as every user column is what makes an inheritance grandchild and
/// a sub-partitioned leaf report THEMSELVES: each level stamps its own oid, and
/// the level above only carries it up.
fn tree_ordinals(parent: &Table, source: &Table, tableoid: bool) -> Result<Vec<usize>, ExecError> {
    let mut ordinals = column_mapping(parent, source)?;
    if tableoid {
        ordinals.push(source.columns.len());
    }
    Ok(ordinals)
}

/// For each of `target`'s columns, the ordinal of the same-named column in
/// `source`, the permutation that rewrites a `source`-shaped row into a
/// `target`-shaped one. A partition and its parent always declare the same
/// column names, but `ATTACH PARTITION` maps them by name, not by position.
pub(crate) fn column_mapping(target: &Table, source: &Table) -> Result<Vec<usize>, ExecError> {
    target
        .columns
        .iter()
        .map(|column| {
            source
                .column_index(&column.name)
                .ok_or_else(|| ExecError::ChildMissingColumn(column.name.clone()))
        })
        .collect()
}

/// `row` read through `ordinals`: `ordinals[i]` is the index in `row` of the
/// result's `i`th column, as [`column_mapping`] computes it. An index the
/// source row does not have reads as NULL.
pub(crate) fn permuted_row(row: &[Datum], ordinals: &[usize]) -> Vec<Datum> {
    ordinals
        .iter()
        .map(|ordinal| row.get(*ordinal).cloned().unwrap_or(Datum::Null))
        .collect()
}

/// `row` permuted by `ordinals`, or handed straight back when there are none —
/// which is how a relation reshapes rows it read from itself, whose mapping is
/// the identity and whose permutation would be a copy.
fn reshape_row(row: Vec<Datum>, ordinals: Option<&[usize]>) -> Vec<Datum> {
    match ordinals {
        Some(ordinals) => permuted_row(&row, ordinals),
        None => row,
    }
}

/// The leaf partition a row of `parent`'s shape belongs to, together with the
/// row permuted into that leaf's own column order.
///
/// A row no partition accepts is `PostgreSQL`'s 23514, raised here rather than
/// reported upwards, because only this frame knows *which* relation declined
/// it. In a multi-level tree that is the sub-partitioned child the row reached,
/// not the parent the statement named, and the key quoted alongside it is that
/// child's own key — which need not share a single column with the parent's.
/// Naming the root instead would report a key the row never failed against.
fn route_row_to_leaf(
    write_ctx: &WriteContext<'_>,
    parent: &Table,
    row: &[Datum],
) -> Result<(Table, Vec<Datum>), ExecError> {
    let kv = write_ctx.catalog_kv;
    let Some(scheme) = crate::partition::scheme_of(kv, &parent.name)? else {
        return Ok((parent.clone(), row.to_vec()));
    };
    let partitions = crate::partition::partitions_of(kv, &parent.name)?;
    let Some(chosen) = crate::partition::route(&scheme, &partitions, row)? else {
        return Err(ExecError::NoPartitionForRow {
            relation: parent.name.to_string(),
            key: may_describe_key(write_ctx, parent)
                .then(|| crate::partition::key_description(&scheme, row, write_ctx.eval_ctx))
                .transpose()?,
        });
    };
    let child = crabka_pgcatalog::get_table(kv, &chosen.name)?;
    let child_row = permuted_row(row, &column_mapping(&child, parent)?);
    route_row_to_leaf(write_ctx, &child, &child_row)
}

/// Read one base-relation `FROM` item: a CTE, a transition relation, a virtual
/// catalog relation, a view, or a stored relation.
///
/// Split out of [`build_table_expr`]'s match rather than written inline. That
/// function recurses — through a join side, a derived table, and a `plpgsql`
/// set-returning function that calls itself — and in an unoptimized build a
/// frame holds slots for every arm's locals whether that arm ran or not, so an
/// arm this size is paid at every level of the recursion.
fn build_base_table(
    read_ctx: &crate::subquery::SubCtx<'_>,
    te: &crabka_pgparser::ast::TableExpr,
    bounds: Option<&ScanBounds>,
    scan_plan: Option<&crate::plan_dist::DistributedScanPlan>,
) -> Result<Relation, ExecError> {
    use crabka_pgparser::ast::TableExpr;
    let TableExpr::Table {
        name,
        only,
        alias,
        columns,
        sample,
    } = te
    else {
        return Err(ExecError::Unsupported(
            "build_base_table expects a base relation".into(),
        ));
    };
    let catalog_kv = read_ctx.catalog_kv;
    let resolution = read_ctx.fctx.resolution;
    let ctes = read_ctx.ctes;
    let ctx = read_ctx.eval_ctx;
    // A base-table alias may rename the leading columns (`t AS q(x, y)`),
    // exactly like a derived table's. The rename applies to whatever the
    // name resolves to — a CTE, a view, a catalog relation, or a stored
    // table — so it wraps the ordinary build rather than duplicating it.
    if let Some(names) = columns {
        let base = build_table_expr(
            read_ctx,
            &TableExpr::Table {
                name: name.clone(),
                only: *only,
                alias: alias.clone(),
                columns: None,
                sample: sample.clone(),
            },
            bounds,
            scan_plan,
            None,
        )?;
        let qualifier = alias.clone().unwrap_or_else(|| name.to_string());
        return crate::values::requalify_derived(base, &qualifier, &Some(names.clone()));
    }
    if let Some(sample) = sample {
        let base = build_table_expr(
            read_ctx,
            &TableExpr::Table {
                name: name.clone(),
                only: *only,
                alias: alias.clone(),
                columns: columns.clone(),
                sample: None,
            },
            bounds,
            scan_plan,
            None,
        )?;
        return apply_tablesample(base, sample, ctx);
    }
    // A CTE is never schema-qualified, so `public.t` names the stored
    // relation even where a CTE `t` is in scope, as PostgreSQL does.
    if name.schema.is_none()
        && let Some(rel) = ctes.lookup(&name.name)
    {
        let qualifier = alias.as_deref().unwrap_or(&name.name);
        return Ok(crate::cte::requalify_cte(rel, qualifier));
    }
    if name.schema.is_none()
        && let Some(runtime) = &ctx.transition_relations
        && let Some(transition) = runtime
            .lock()
            .expect("transition relation mutex")
            .get(&name.name)
            .cloned()
    {
        let qualifier = alias.as_deref().unwrap_or(&name.name);
        return Ok(Relation {
            scope: Scope {
                columns: transition
                    .columns
                    .into_iter()
                    .map(|(name, ty)| ColumnBinding {
                        exposure: Exposure::Output,
                        qualifier: Some(qualifier.to_string()),
                        name,
                        ty,
                    })
                    .collect(),
            },
            rows: transition.rows,
        });
    }
    let name = &resolve_relation(catalog_kv, resolution, name, SchemaDisposition::Reference)?;
    if let Some(rel) = virtual_catalog_relation(catalog_kv, name, alias.as_deref(), ctx)? {
        return Ok(rel);
    }
    match crabka_pgcatalog::get_view(catalog_kv, name) {
        Ok(view) => {
            // A view carries its own ACL, and it is checked *before* the
            // identity switch below — under whatever role reached this view,
            // which for a nested view is the outer view's owner. This check is
            // what makes owner rights safe: the body may read relations the
            // caller cannot, so the caller must have been granted the view.
            crate::privilege::require(
                &read_ctx.privileges(),
                &view.name,
                &view.owner,
                crate::privilege::RelationKind::View,
                crate::privilege::Privilege::Select,
            )?;
            let statement = crabka_pgparser::parse(&view.definition)?;
            let [Statement::Query(query)] = statement.as_slice() else {
                return Err(ExecError::Unsupported(
                    "stored view definition is not a query".into(),
                ));
            };
            // The body then runs as the view's owner — for privileges and for
            // which row-security policies apply, which move together because
            // they are the same field. `security_invoker` keeps the caller's
            // identity, which is the whole meaning of the option.
            //
            // `EvalCtx` is not touched, so `CURRENT_USER` inside the body
            // still names the invoker, as it does in PostgreSQL: only the
            // identity decisions are made under changes.
            let body_role = if view.options.security_invoker {
                read_ctx.security_role
            } else {
                view.owner.as_str()
            };
            // The body's unqualified names resolve with the view's own schema
            // searched first, not in the reader's scope. `CREATE VIEW s.v AS
            // SELECT … FROM t` records `t` as text, so reading `s.v` from a
            // session whose `search_path` does not name `s` would otherwise
            // fail to find the very relation the view was built on.
            let body_scope = read_ctx.fctx.resolution.for_stored_body(&view.name.schema);
            let role_ctx = read_ctx.with_security_role(body_role);
            let body_ctx = role_ctx.with_resolution(&body_scope);
            let relation = crate::query::query_to_relation(&body_ctx, query)?;
            let qualifier = alias.as_deref().unwrap_or(&view.name.name);
            return requalify_view_relation(relation, &view, qualifier);
        }
        Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) => {}
        Err(error) => return Err(error.into()),
    }
    // Consulted only once `get_table` has missed, so an ordinary read pays no
    // second catalog lookup for it.
    let t = crabka_pgcatalog::get_table(catalog_kv, name)
        .map_err(|error| open_wrong_kind(catalog_kv, name).unwrap_or_else(|| error.into()))?;
    // An unpopulated materialized view is refused here, at the one place every
    // stored-relation read passes, rather than in each of the planner's
    // pushdowns: the refusal has to hold whichever path a query takes, and a
    // pushdown that pruned the projection would otherwise return zero rows for
    // `count(*)` while the general path errored.
    require_populated(&t)?;
    let qualifier = alias.as_deref().unwrap_or(&t.name.name);
    // One scan, one gate, and one permit. Every stored-relation read the
    // executor does arrives here; `RawScan` cannot become a `Relation` any
    // other way, and `scan_stored_relation` cannot be called without the
    // permit. The permit is taken before the scan rather than after it so a
    // denied read reads nothing at all — PostgreSQL checks permissions at
    // executor start, and a check after the scan would let a leaky operator in
    // the `WHERE` observe rows the caller may not see.
    let permit = crate::privilege::ReadPermit::acquire(&read_ctx.privileges(), &t)?;
    let reach = if *only { Reach::OwnRows } else { Reach::Tree };
    let raw = scan_stored_relation(read_ctx, &t, qualifier, reach, bounds, scan_plan, &permit)?;
    crate::rls::apply_row_security(read_ctx, raw)
}

fn build_table_expr(
    read_ctx: &crate::subquery::SubCtx<'_>,
    te: &crabka_pgparser::ast::TableExpr,
    // SP40 Task 14: pushed-down offset bounds, `Some` only for a single foreign
    // base table. Applied verbatim to the foreign scan; `None` ⇒ full scan.
    bounds: Option<&ScanBounds>,
    scan_plan: Option<&crate::plan_dist::DistributedScanPlan>,
    // The statement's `WHERE`, so a join can pre-apply its single-relation
    // conjuncts to a null-preserved side. Only ever an optimization: the caller
    // applies the same predicate again to the relation this returns.
    filter: Option<&Expr>,
) -> Result<Relation, ExecError> {
    let ctx = read_ctx.eval_ctx;
    use crabka_pgparser::ast::TableExpr;
    match te {
        table @ TableExpr::Table { .. } => build_base_table(read_ctx, table, bounds, scan_plan),
        TableExpr::Join {
            left,
            right,
            kind,
            constraint,
        } => {
            if let Some(relation) =
                try_distributed_inner_equi_join(read_ctx, left, right, *kind, constraint)?
            {
                return Ok(relation);
            }
            // A join is never a single foreign table: each side scans in full and
            // the join predicate / residual WHERE filters locally.
            //
            // The `WHERE` only descends into the left side while every join it
            // passes through preserves that side. Under a `RIGHT`/`FULL` join
            // the left is nullable, and dropping its rows early would turn a
            // matched row into a NULL-padded one — which a predicate like
            // `a.x IS NULL` would then wrongly admit.
            let nested_filter = match kind {
                crabka_pgparser::ast::JoinKind::Inner
                | crabka_pgparser::ast::JoinKind::Cross
                | crabka_pgparser::ast::JoinKind::Left => filter,
                crabka_pgparser::ast::JoinKind::Right | crabka_pgparser::ast::JoinKind::Full => {
                    None
                }
            };
            let l = build_table_expr(read_ctx, left, None, None, nested_filter)?;
            // A lateral right side sees the left side's columns, so it is rebuilt
            // per left row instead of materialized once.
            append_from_item(read_ctx, l, right, *kind, constraint, filter)
        }
        TableExpr::Derived {
            subquery,
            alias,
            columns,
            ..
        } => {
            let inner = crate::query::query_to_relation_with_ctes(read_ctx, subquery)?;
            crate::values::requalify_derived(inner, alias, columns)
        }
        // P2: a user-defined SQL function in FROM position is a parameterized
        // derived table — its body runs under the caller's own read context.
        // Built-in set-returning functions stay with the `srf` registry.
        TableExpr::Function {
            functions,
            with_ordinality,
            alias,
            column_aliases,
            ..
        } if crate::routine::expands_as_table(read_ctx.catalog_kv, functions) => {
            if let Some((columns, rows)) =
                crate::routine::eval_plpgsql_table_function(&functions[0], ctx)?
            {
                return crate::srf::user_function_relation(
                    &functions[0].name,
                    columns,
                    rows,
                    *with_ordinality,
                    alias.as_deref(),
                    column_aliases,
                    functions[0].column_defs.as_deref(),
                );
            }
            if *with_ordinality {
                return Err(ExecError::Unsupported(
                    "WITH ORDINALITY over a user-defined function is not supported".into(),
                ));
            }
            let (query, names) =
                crate::routine::table_function_expansion(read_ctx.catalog_kv, &functions[0])?;
            let inner = crate::query::query_to_relation_with_ctes(read_ctx, &query)?;
            let columns = column_aliases.clone().or(Some(names));
            crate::values::requalify_derived(
                inner,
                alias.as_deref().unwrap_or(&functions[0].name),
                &columns,
            )
        }
        TableExpr::Function {
            functions,
            with_ordinality,
            rows_from,
            alias,
            column_aliases,
            ..
        } => crate::srf::from_item(
            functions,
            *with_ordinality,
            *rows_from,
            alias.as_deref(),
            column_aliases,
            ctx,
        ),
        TableExpr::JsonTable(table) => crate::jsontable::from_item(table, ctx),
    }
}

/// Apply a `TABLESAMPLE` clause to an already-materialized base-table relation.
///
/// `PostgreSQL` samples physical pages (`SYSTEM`) or individual rows
/// (`BERNOULLI`); crabka has no page layout to sample, so both methods draw rows
/// independently at the given probability. The percentage checks, the `42704`
/// for an unknown method, and the deterministic 0% / 100% ends match
/// `PostgreSQL` exactly; which rows a partial sample returns does not.
fn apply_tablesample(
    relation: Relation,
    sample: &crabka_pgparser::ast::TableSample,
    ctx: &crate::clock::EvalCtx,
) -> Result<Relation, ExecError> {
    if !matches!(sample.method.as_str(), "system" | "bernoulli") {
        return Err(ExecError::FunctionError {
            sqlstate: "42704",
            message: format!("tablesample method {} does not exist", sample.method),
        });
    }
    let percent = crate::eval::eval(&sample.percent, &Scope::empty(), &[], ctx)?;
    if percent.is_null() {
        return Err(ExecError::FunctionError {
            sqlstate: "2202H",
            message: "TABLESAMPLE parameter cannot be null".into(),
        });
    }
    let Datum::Float8(percent) =
        crabka_pgtypes::cast::cast(&percent, ColumnType::Float8, &ctx.time_zone)?
    else {
        return Err(ExecError::TypeMismatch(
            "TABLESAMPLE percentage must be numeric".into(),
        ));
    };
    if !(0.0..=100.0).contains(&percent) {
        return Err(ExecError::FunctionError {
            sqlstate: "2202H",
            message: "sample percentage must be between 0 and 100".into(),
        });
    }
    let seed = match &sample.repeatable {
        Some(expr) => {
            let value = crate::eval::eval(expr, &Scope::empty(), &[], ctx)?;
            if value.is_null() {
                // A null seed is invalid_tablesample_repeat, NOT the
                // invalid_tablesample_argument a null/out-of-range percentage is.
                return Err(ExecError::FunctionError {
                    sqlstate: "2202G",
                    message: "TABLESAMPLE REPEATABLE parameter cannot be null".into(),
                });
            }
            let Datum::Float8(seed) =
                crabka_pgtypes::cast::cast(&value, ColumnType::Float8, &ctx.time_zone)?
            else {
                return Err(ExecError::TypeMismatch(
                    "TABLESAMPLE seed must be numeric".into(),
                ));
            };
            seed.to_bits()
        }
        None => 0x9E37_79B9_7F4A_7C15,
    };
    let Relation { scope, rows } = relation;
    // A xorshift over (seed, row ordinal): repeatable across runs for a given
    // seed, and independent of how the rows were physically stored.
    let threshold = percent / 100.0;
    let sampled = rows
        .into_iter()
        .enumerate()
        .filter(|(index, _)| {
            let ordinal = u64::try_from(*index).unwrap_or(u64::MAX);
            let mut state = seed ^ ordinal.wrapping_mul(0x9E37_79B9_7F4A_7C15);
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            // The top 32 bits convert to f64 exactly, so the draw needs no
            // lossy cast.
            let bucket = u32::try_from(state >> 32).unwrap_or(u32::MAX);
            f64::from(bucket) / f64::from(u32::MAX) < threshold
        })
        .map(|(_, row)| row)
        .collect();
    Ok(Relation {
        scope,
        rows: sampled,
    })
}

fn try_distributed_inner_equi_join(
    read_ctx: &crate::subquery::SubCtx<'_>,
    left_expr: &crabka_pgparser::ast::TableExpr,
    right_expr: &crabka_pgparser::ast::TableExpr,
    kind: crabka_pgparser::ast::JoinKind,
    constraint: &crabka_pgparser::ast::JoinConstraint,
) -> Result<Option<Relation>, ExecError> {
    let catalog_kv = read_ctx.catalog_kv;
    let resolution = read_ctx.fctx.resolution;
    let gsnap = read_ctx.gsnap;
    let snapshot = read_ctx.snapshot;
    let own = read_ctx.own;
    let ctes = read_ctx.ctes;
    let range_scanner = read_ctx.range_scanner;
    use crabka_pgparser::ast::{BinaryOp, Expr, JoinConstraint, JoinKind, TableExpr};

    if kind != JoinKind::Inner {
        return Ok(None);
    }
    let (
        TableExpr::Table {
            name: left_name,
            alias: left_alias,
            columns: None,
            sample: None,
            ..
        },
        TableExpr::Table {
            name: right_name,
            alias: right_alias,
            columns: None,
            sample: None,
            ..
        },
    ) = (left_expr, right_expr)
    else {
        return Ok(None);
    };
    if (left_name.schema.is_none() && ctes.lookup(&left_name.name).is_some())
        || (right_name.schema.is_none() && ctes.lookup(&right_name.name).is_some())
    {
        return Ok(None);
    }
    let left_name = &resolve_relation(
        catalog_kv,
        resolution,
        left_name,
        SchemaDisposition::Reference,
    )?;
    let right_name = &resolve_relation(
        catalog_kv,
        resolution,
        right_name,
        SchemaDisposition::Reference,
    )?;
    let JoinConstraint::On(Expr::Binary {
        op: BinaryOp::Eq,
        left: key_left,
        right: key_right,
    }) = constraint
    else {
        return Ok(None);
    };
    let table =
        |name: &crabka_pgcatalog::RelationName| match crabka_pgcatalog::get_table(catalog_kv, name)
        {
            Ok(table) => Ok(Some(table)),
            Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) => Ok(None),
            Err(error) => Err(ExecError::from(error)),
        };
    let Some(left_table) = table(left_name)? else {
        return Ok(None);
    };
    let Some(right_table) = table(right_name)? else {
        return Ok(None);
    };
    if !left_table.sharded
        || !right_table.sharded
        || left_table.foreign.is_some()
        || right_table.foreign.is_some()
        // The scanner joins remotely on the rows as they sit in storage, where
        // a virtual generated column is a NULL placeholder. Such a relation
        // falls back to the ordinary scan, which materializes it first.
        || has_virtual_generated(&left_table)
        || has_virtual_generated(&right_table)
    {
        return Ok(None);
    }
    // The scanner joins both relations remotely and returns joined tuples, so
    // neither side's rows ever pass a row-security qual. Both sides must be
    // proven unrestricted, and the proofs shadow the raw tables so the rest of
    // this function cannot reach around them.
    let rls = read_ctx.rls();
    let privileges = read_ctx.privileges();
    let (Some(left_table), Some(right_table)) = (
        crate::rls::UnrestrictedTable::read(&privileges, &rls, &left_table)?,
        crate::rls::UnrestrictedTable::read(&privileges, &rls, &right_table)?,
    ) else {
        return Ok(None);
    };
    let (left_table, right_table) = (left_table.get(), right_table.get());
    let left_qualifier = left_alias.as_deref().unwrap_or(&left_table.name.name);
    let right_qualifier = right_alias.as_deref().unwrap_or(&right_table.name.name);
    fn qualified_key(expr: &Expr) -> Option<(&str, &str)> {
        let Expr::Column {
            table: Some(table),
            name,
        } = expr
        else {
            return None;
        };
        Some((table.as_str(), name.as_str()))
    }
    let (Some((first_table, first_column)), Some((second_table, second_column))) =
        (qualified_key(key_left), qualified_key(key_right))
    else {
        return Ok(None);
    };
    let (left_column, right_column) =
        if first_table == left_qualifier && second_table == right_qualifier {
            (first_column, second_column)
        } else if first_table == right_qualifier && second_table == left_qualifier {
            (second_column, first_column)
        } else {
            return Ok(None);
        };
    let Some(left_key) = left_table
        .columns
        .iter()
        .position(|column| column.name == left_column)
    else {
        return Ok(None);
    };
    let Some(right_key) = right_table
        .columns
        .iter()
        .position(|column| column.name == right_column)
    else {
        return Ok(None);
    };
    let planned =
        range_scanner.join_strategy_for_keys(left_table, right_table, &[left_key], &[right_key]);
    let strategy = match planned {
        crate::plan_dist::JoinStrategy::Broadcast { small_table_id }
            if small_table_id == u64::from(left_table.id) =>
        {
            JoinExecutionStrategy::BroadcastLeft
        }
        crate::plan_dist::JoinStrategy::Broadcast { small_table_id }
            if small_table_id == u64::from(right_table.id) =>
        {
            JoinExecutionStrategy::BroadcastRight
        }
        crate::plan_dist::JoinStrategy::Broadcast { .. } => JoinExecutionStrategy::Gather,
        crate::plan_dist::JoinStrategy::CoPartitioned
            if hash_sharding_matches_join_keys(
                left_table,
                right_table,
                left_column,
                right_column,
            ) =>
        {
            JoinExecutionStrategy::CoPartitioned
        }
        crate::plan_dist::JoinStrategy::CoPartitioned => JoinExecutionStrategy::Gather,
        crate::plan_dist::JoinStrategy::Gather => JoinExecutionStrategy::Gather,
    };
    // Folded onto the enclosing read span rather than carried on one of this
    // join's own: the strategy is a property of how the statement ran, and a
    // span that declares no such field ignores this.
    tracing::Span::current().record("pg.join_strategy", strategy.as_str());
    let join_snapshot = |source: &crabka_pgmvcc::visibility::Snapshot| JoinSnapshot {
        xmin: source.xmin,
        xmax: source.xmax,
        xip: source.xip.clone(),
    };
    let request = JoinRangeRequest {
        local_snapshot: join_snapshot(snapshot),
        global_snapshot: join_snapshot(gsnap),
        read_ts: 1,
        own_xid: own,
        own_start_ts: None,
        kind: ScannerJoinKind::Inner,
        left_keys: vec![left_key],
        right_keys: vec![right_key],
        strategy,
        left: JoinTableInterval {
            table_id: u64::from(left_table.id),
            table_name: left_table.name.to_string(),
            interval: RowInterval::ALL,
        },
        right: JoinTableInterval {
            table_id: u64::from(right_table.id),
            table_name: right_table.name.to_string(),
            interval: RowInterval::ALL,
        },
        broadcast_rows: matches!(
            strategy,
            JoinExecutionStrategy::BroadcastLeft | JoinExecutionStrategy::BroadcastRight
        )
        .then(Vec::new),
        left_filter: PredicatePushdown::FullScan,
        right_filter: PredicatePushdown::FullScan,
        projection: Vec::new(),
    };
    let result = match range_scanner.join(request) {
        Ok(result) => result,
        Err(ExecError::Unsupported(_)) => return Ok(None),
        Err(error) => return Err(error),
    };
    result
        .validate()
        .map_err(|error| ExecError::Unsupported(error.to_string()))?;
    let rows = result
        .rows
        .into_iter()
        .map(|JoinRow { tuple }| {
            crabka_pgmvcc::version::decode_tuple(&tuple)
                .map(|(_, _, row)| row)
                .map_err(ExecError::from)
        })
        .collect::<Result<Vec<_>, _>>()?;
    // The join result is the left table's columns followed by the right's, so
    // the right table's `regclass` columns sit past the left's width.
    let mut rows = rows;
    let mut regclass_columns = regclass_column_indexes(left_table, 0);
    regclass_columns.extend(regclass_column_indexes(
        right_table,
        left_table.columns.len(),
    ));
    resolve_regclass_at(read_ctx.catalog_kv, &regclass_columns, &mut rows)?;
    let mut scope = Scope::single(left_table, left_qualifier);
    scope
        .columns
        .extend(Scope::single(right_table, right_qualifier).columns);
    Ok(Some(Relation { scope, rows }))
}

fn hash_sharding_matches_join_keys(
    left: &Table,
    right: &Table,
    left_column: &str,
    right_column: &str,
) -> bool {
    use crabka_pgcatalog::ShardingStrategy;

    let (Some(ShardingStrategy::Hash(left_hash)), Some(ShardingStrategy::Hash(right_hash))) =
        (&left.sharding, &right.sharding)
    else {
        return false;
    };
    left_hash.columns.as_slice() == [left_column] && right_hash.columns.as_slice() == [right_column]
}

/// An equality or full-text probe over a local index, for a relation proven not
/// to be under row security.
///
/// It takes an [`crate::rls::UnrestrictedTable`] rather than a `&Table` because
/// an index probe returns the rows the index points at, which is not the same
/// set as the rows a policy admits. A relation with policies has no
/// `UnrestrictedTable` to offer and falls through to the ordinary gated scan.
fn try_scan_with_local_index(
    read_ctx: &crate::subquery::SubCtx<'_>,
    unrestricted: crate::rls::UnrestrictedTable<'_>,
    plan: &crate::plan_dist::DistributedScanPlan,
) -> Result<Option<Vec<ScannedRow>>, ExecError> {
    let table = unrestricted.get();
    if table.sharded || plan.partial_aggregate.is_some() {
        return Ok(None);
    }
    if let Some(predicate) = &plan.text_search
        && let Some(index) = choose_local_gin_index(read_ctx.catalog_kv, table, predicate.column)?
        && let Some(rows) = lookup_local_gin(
            &MvccReadContext {
                kv: read_ctx.kv,
                global: read_ctx.global,
                global_snapshot: read_ctx.gsnap,
                snapshot: read_ctx.snapshot,
                own: read_ctx.own,
            },
            table,
            &index,
            &predicate.query,
        )?
    {
        return Ok(Some(rows));
    }
    let Some((index, value)) =
        choose_local_index_equality(read_ctx.catalog_kv, table, &plan.predicate)?
    else {
        return Ok(None);
    };
    let rows = lookup_local_index_equal(
        &MvccReadContext {
            kv: read_ctx.kv,
            global: read_ctx.global,
            global_snapshot: read_ctx.gsnap,
            snapshot: read_ctx.snapshot,
            own: read_ctx.own,
        },
        table,
        &index,
        &[value],
    )?;
    crate::scanner::apply_executable_scan_pushdown(
        rows,
        &plan.predicate,
        &plan.projection,
        None,
        plan.top_k.as_ref(),
    )
    .map(Some)
}

fn choose_local_gin_index(
    catalog_kv: &dyn Kv,
    table: &Table,
    column: usize,
) -> Result<Option<crabka_pgcatalog::Index>, ExecError> {
    Ok(
        crabka_pgcatalog::list_table_indexes(catalog_kv, &table.name)?
            .into_iter()
            .find(|index| {
                index.placement == crabka_pgcatalog::IndexPlacement::Local
                    && index.method == crabka_pgcatalog::IndexMethod::Gin
                    && index.columns.len() == 1
                    && table.column_index(&index.columns[0]) == Some(column)
            }),
    )
}

fn choose_local_index_equality(
    catalog_kv: &dyn Kv,
    table: &Table,
    predicate: &PredicatePushdown,
) -> Result<Option<(crabka_pgcatalog::Index, Datum)>, ExecError> {
    let PredicatePushdown::Conjunctive(predicates) = predicate else {
        return Ok(None);
    };
    let indexes = crabka_pgcatalog::list_table_indexes(catalog_kv, &table.name)?;
    for predicate in predicates
        .iter()
        .filter(|predicate| predicate.op == crate::PredicateOp::Eq && !predicate.value.is_null())
    {
        let Some(index) = indexes.iter().find(|index| {
            index.placement == crabka_pgcatalog::IndexPlacement::Local
                && index.method == crabka_pgcatalog::IndexMethod::Btree
                && index.columns.len() == 1
                && table.column_index(&index.columns[0]) == Some(predicate.column)
        }) else {
            continue;
        };
        return Ok(Some((index.clone(), predicate.value.clone())));
    }
    Ok(None)
}

fn should_retry_without_scan_pushdown(
    error: &ExecError,
    plan: &crate::plan_dist::DistributedScanPlan,
) -> bool {
    if plan.partial_aggregate.is_some() || plan.top_k.is_some() {
        return false;
    }
    if *plan == crate::plan_dist::DistributedScanPlan::default() {
        return false;
    }
    let message = error.clone().into_pg().message;
    message.contains("pushdown") || message.contains("full scans")
}

fn try_execute_partial_aggregate_pushdown(
    read_ctx: &crate::subquery::SubCtx<'_>,
    s: &SelectStmt,
) -> Result<Option<Relation>, ExecError> {
    if !is_plain_partial_aggregate_select(s) {
        return Ok(None);
    }
    let Some((table, qualifier)) = single_sharded_base_table(
        read_ctx.catalog_kv,
        read_ctx.fctx.resolution,
        s,
        read_ctx.ctes,
    )?
    else {
        return Ok(None);
    };
    // The range owners fold the aggregate over every visible row, which is not
    // the same set as the rows a policy admits, and a sum cannot be un-summed
    // afterwards. Shadowing the raw table with the proof leaves no way to reach
    // it unproven.
    let Some(table) =
        crate::rls::UnrestrictedTable::read(&read_ctx.privileges(), &read_ctx.rls(), &table)?
    else {
        return Ok(None);
    };
    let table = table.get();
    // As in `local_streaming_aggregate_plan`: the range owners fold over stored
    // bytes, which hold nothing for a virtual generated column.
    if has_virtual_generated(table) {
        return Ok(None);
    }
    let spec = if s.group_by.is_empty() {
        crate::plan_dist::plan_scan(table, s.filter.as_ref(), &s.projection).partial_aggregate
    } else {
        crate::plan_dist::grouped_partial_aggregate_for_select(table, &s.projection, &s.group_by)
    };
    let Some(spec) = spec else {
        return Ok(None);
    };
    let predicate = match crate::plan_dist::strict_predicate_for_filter(table, s.filter.as_ref()) {
        Ok(predicate) => predicate,
        Err(_) => return Ok(None),
    };
    let scope = Scope::single(table, &qualifier);
    let (fields, _out_exprs, tys) = resolve_projection(&s.projection, &scope)?;
    let rows = read_ctx.range_scanner.scan(ScanRequest {
        local: read_ctx.kv,
        global: read_ctx.global,
        global_snapshot: read_ctx.gsnap,
        snapshot: read_ctx.snapshot,
        own_xid: read_ctx.own,
        read_ts: None,
        own_start_ts: None,
        table,
        interval: RowInterval::ALL,
        predicate,
        projection: crate::ProjectionPushdown::All,
        partial_aggregate: Some(spec.clone()),
        top_k: None,
    })?;
    let rows = crate::scanner::finalize_partial_aggregate_rows(rows, &spec)?;
    let out_scope = Scope {
        columns: fields
            .iter()
            .zip(&tys)
            .map(|(field, ty)| ColumnBinding {
                exposure: Exposure::Output,
                qualifier: None,
                name: field.name.clone(),
                ty: *ty,
            })
            .collect(),
    };
    Ok(Some(Relation {
        scope: out_scope,
        rows: rows.into_iter().map(|row| row.row).collect(),
    }))
}

/// Count one direct local INNER/LEFT join without retaining its output rows.
/// The narrow shape keeps every other aggregate query on the ordinary grouping
/// path; in particular, a WHERE/FILTER/HAVING needs materialized joined rows.
fn try_execute_local_join_count(
    read_ctx: &crate::subquery::SubCtx<'_>,
    s: &SelectStmt,
) -> Result<Option<Relation>, ExecError> {
    if s.filter.is_some() || !s.group_by.is_empty() || !select_modifiers_allow_partial_aggregate(s)
    {
        return Ok(None);
    }
    let [
        SelectItem::Expr {
            expr: Expr::Func(call),
            ..
        },
    ] = s.projection.as_slice()
    else {
        return Ok(None);
    };
    if call.name != "count"
        || call.distinct
        || !matches!(call.args, FuncArgs::Star)
        || call.filter.is_some()
    {
        return Ok(None);
    }
    let [
        crabka_pgparser::ast::TableExpr::Join {
            left,
            right,
            kind:
                kind @ (crabka_pgparser::ast::JoinKind::Inner | crabka_pgparser::ast::JoinKind::Left),
            constraint,
        },
    ] = s.from.as_slice()
    else {
        return Ok(None);
    };
    if !is_plain_local_join_table(read_ctx, left)? || !is_plain_local_join_table(read_ctx, right)? {
        return Ok(None);
    }

    let left = build_table_expr(read_ctx, left, None, None, None)?;
    let right = build_table_expr(read_ctx, right, None, None, None)?;
    let count = count_join_rows(
        &left,
        &right,
        *kind,
        constraint,
        read_ctx.eval_ctx,
        read_ctx.blocking_query_memory,
    )?;
    let (fields, _, types) = resolve_projection(&s.projection, &Scope::empty())?;
    Ok(Some(Relation {
        scope: projected_scope(&fields, &types),
        rows: vec![vec![Datum::Int8(count)]],
    }))
}

fn is_plain_local_join_table(
    read_ctx: &crate::subquery::SubCtx<'_>,
    expression: &crabka_pgparser::ast::TableExpr,
) -> Result<bool, ExecError> {
    let crabka_pgparser::ast::TableExpr::Table {
        name,
        columns: None,
        sample: None,
        ..
    } = expression
    else {
        return Ok(false);
    };
    if name.schema.is_none() && read_ctx.ctes.lookup(&name.name).is_some() {
        return Ok(false);
    }
    let Some(table) = scan_plan_table(read_ctx.catalog_kv, read_ctx.fctx.resolution, name)? else {
        return Ok(false);
    };
    // The counting path returns a count and no rows, so nothing downstream can
    // filter it: a side under row security keeps the ordinary path, which
    // materializes both sides through the gate and counts the same join.
    Ok(!table.sharded
        && crate::rls::UnrestrictedTable::read(&read_ctx.privileges(), &read_ctx.rls(), &table)?
            .is_some())
}

/// Stream a supported local aggregate through per-page partial-aggregate
/// folding, instead of a fold over every visible row after it is materialized.
///
/// Fires on exactly one ordinary non-sharded base table when every projection
/// item decomposes into scalar expressions over pushdown-model aggregate calls
/// (`CAST(count(*) AS BIGINT)`, `COALESCE(sum(x), 0)`, `sum(a) / count(*)`, …
/// — or the narrow grouped shape), with a WHERE that parses into the strict
/// pushdown predicate subset (or, for `count(*)`, an OR of two such filters).
/// Everything else — `DISTINCT`, `HAVING`, bare ungrouped columns, aggregates
/// over non-column arguments, whole-row reads, non-pushdown filters — keeps the
/// materializing scan and its whole-result memory budget.
fn try_execute_local_streaming_aggregate(
    read_ctx: &crate::subquery::SubCtx<'_>,
    s: &SelectStmt,
) -> Result<Option<Relation>, ExecError> {
    if !is_streamable_aggregate_select(s) {
        return Ok(None);
    }
    let Some((table, qualifier)) = single_local_base_table(
        read_ctx.catalog_kv,
        read_ctx.fctx.resolution,
        s,
        read_ctx.ctes,
    )?
    else {
        return Ok(None);
    };
    // The fold happens page by page inside the scanner, over every visible row,
    // before any policy qual could have removed one. Shadowing keeps the raw
    // table out of reach for the rest of the function.
    let Some(table) =
        crate::rls::UnrestrictedTable::read(&read_ctx.privileges(), &read_ctx.rls(), &table)?
    else {
        return Ok(None);
    };
    let table = table.get();
    let Some(plan) = local_streaming_aggregate_plan(table, s) else {
        return Ok(None);
    };
    let predicates = match crate::plan_dist::strict_predicate_for_filter(table, s.filter.as_ref()) {
        Ok(predicate) => vec![predicate],
        Err(_) => {
            let Some(predicates) = count_star_or_predicates(table, s, &plan) else {
                return Ok(None);
            };
            Vec::from(predicates)
        }
    };
    // An equality probe over a local index reads less than any table scan:
    // keep that existing path (and its materializing budget) for those filters.
    if predicates.len() == 1
        && choose_local_index_equality(read_ctx.catalog_kv, table, &predicates[0])?.is_some()
    {
        return Ok(None);
    }
    let scope = Scope::single(table, &qualifier);
    let (fields, out_exprs, tys) = resolve_projection(&s.projection, &scope)?;
    let states = predicates
        .into_iter()
        .map(|predicate| {
            crate::scanner::collect_partial_aggregates_bounded(
                read_ctx.range_scanner,
                ScanRequest {
                    local: read_ctx.kv,
                    global: read_ctx.global,
                    global_snapshot: read_ctx.gsnap,
                    snapshot: read_ctx.snapshot,
                    own_xid: read_ctx.own,
                    read_ts: None,
                    own_start_ts: None,
                    table,
                    interval: RowInterval::ALL,
                    predicate,
                    projection: crate::ProjectionPushdown::All,
                    partial_aggregate: None,
                    top_k: None,
                },
                plan.specs(),
                crate::scanner::BLOCKING_QUERY_MEMORY,
            )
        })
        .collect::<Result<Vec<_>, _>>()?;
    let rows = match &plan {
        StreamingAggregatePlan::Scalar { calls, specs } => {
            let values = match <[Vec<Vec<ScannedRow>>; 1]>::try_from(states) {
                Ok([states]) => finalize_scalar_streaming_aggregates(states, specs)?,
                Err(states) => {
                    let Ok(states) = <[Vec<Vec<ScannedRow>>; 3]>::try_from(states) else {
                        return Err(invalid_scalar_aggregate_shape());
                    };
                    finalize_count_star_union(states, specs)?
                }
            };
            vec![crate::agg::eval_over_aggregate_values(
                &out_exprs,
                &scope,
                calls,
                &values,
                read_ctx.eval_ctx,
            )?]
        }
        StreamingAggregatePlan::Grouped(spec) => {
            let Ok([states]) = <[Vec<Vec<ScannedRow>>; 1]>::try_from(states) else {
                return Err(ExecError::Unsupported(
                    "grouped partial aggregate streaming expects one predicate".into(),
                ));
            };
            let Ok([state]) = <[Vec<ScannedRow>; 1]>::try_from(states) else {
                return Err(ExecError::Unsupported(
                    "grouped partial aggregate streaming expects exactly one spec".into(),
                ));
            };
            crate::scanner::finalize_partial_aggregate_rows(state, spec)?
                .into_iter()
                .map(|row| row.row)
                .collect()
        }
    };
    let out_scope = Scope {
        columns: fields
            .iter()
            .zip(&tys)
            .map(|(field, ty)| ColumnBinding {
                exposure: Exposure::Output,
                qualifier: None,
                name: field.name.clone(),
                ty: *ty,
            })
            .collect(),
    };
    Ok(Some(Relation {
        scope: out_scope,
        rows,
    }))
}

/// The one safe disjunction for local streaming: `count(*)` over two strict
/// predicates. Three bounded scans compute `left + right - intersection`
/// without materializing the matching rows.
fn count_star_or_predicates(
    table: &Table,
    s: &SelectStmt,
    plan: &StreamingAggregatePlan,
) -> Option<[PredicatePushdown; 3]> {
    let StreamingAggregatePlan::Scalar { calls, specs } = plan else {
        return None;
    };
    let ([call], [spec]) = (calls.as_slice(), specs.as_slice()) else {
        return None;
    };
    if call.name != "count"
        || call.distinct
        || !matches!(call.args, FuncArgs::Star)
        || call.filter.is_some()
        || spec.function != crate::PartialAggregateFunction::Count
        || spec.column.is_some()
    {
        return None;
    }
    let Expr::Binary {
        op: BinaryOp::Or,
        left,
        right,
    } = s.filter.as_ref()?
    else {
        return None;
    };
    let PredicatePushdown::Conjunctive(left) =
        crate::plan_dist::strict_predicate_for_filter(table, Some(left)).ok()?
    else {
        return None;
    };
    let PredicatePushdown::Conjunctive(right) =
        crate::plan_dist::strict_predicate_for_filter(table, Some(right)).ok()?
    else {
        return None;
    };
    let mut intersection = left.clone();
    intersection.extend(right.iter().cloned());
    Some([
        PredicatePushdown::Conjunctive(left),
        PredicatePushdown::Conjunctive(right),
        PredicatePushdown::Conjunctive(intersection),
    ])
}

fn finalize_count_star_union(
    [left, right, intersection]: [Vec<Vec<ScannedRow>>; 3],
    specs: &[crate::PartialAggregateSpec],
) -> Result<Vec<Datum>, ExecError> {
    let [spec] = specs else {
        return Err(invalid_scalar_aggregate_shape());
    };
    let count = |states| -> Result<i64, ExecError> {
        let values = finalize_scalar_streaming_aggregates(states, std::slice::from_ref(spec))?;
        let [Datum::Int8(count)] = values.as_slice() else {
            return Err(invalid_scalar_aggregate_shape());
        };
        Ok(*count)
    };
    let (left, right, intersection) = (count(left)?, count(right)?, count(intersection)?);
    if intersection > left || intersection > right {
        return Err(invalid_scalar_aggregate_shape());
    }
    let count = (left - intersection)
        .checked_add(right)
        .ok_or_else(|| ExecError::Unsupported("streamed COUNT union exceeds int8 range".into()))?;
    Ok(vec![Datum::Int8(count)])
}

/// How the local streaming path computes a supported aggregate SELECT.
enum StreamingAggregatePlan {
    /// No GROUP BY: stream one partial spec per distinct aggregate call, then
    /// evaluate each projection expression over the finalized values.
    Scalar {
        /// Deduped aggregate calls, aligned index-for-index with `specs` (and
        /// with the finalized values fed to the outer-expression evaluation).
        calls: Vec<crabka_pgparser::ast::FuncCall>,
        specs: Vec<crate::PartialAggregateSpec>,
    },
    /// The narrow grouped shape: one spec whose finalized rows ARE the output
    /// rows. Those rows are the group key columns, then the aggregate, ordered
    /// by key.
    Grouped(crate::PartialAggregateSpec),
}

impl StreamingAggregatePlan {
    fn specs(&self) -> &[crate::PartialAggregateSpec] {
        match self {
            Self::Scalar { specs, .. } => specs,
            Self::Grouped(spec) => std::slice::from_ref(spec),
        }
    }
}

/// Decompose the SELECT into a streaming plan: the single grouped spec for the
/// grouped shape; with no GROUP BY, the deduped aggregate calls (each inside
/// the pushdown model) with everything around them scalar expressions to
/// evaluate over the finalized values. `None` when any part falls outside the
/// model, and the caller then keeps the materializing scan.
fn local_streaming_aggregate_plan(table: &Table, s: &SelectStmt) -> Option<StreamingAggregatePlan> {
    // The fold runs inside the scanner, over the rows as they sit in storage,
    // where a virtual generated column is a NULL placeholder. Such a relation
    // takes the ordinary path, which materializes the value first.
    if has_virtual_generated(table) {
        return None;
    }
    if !s.group_by.is_empty() {
        return crate::plan_dist::grouped_partial_aggregate_for_select(
            table,
            &s.projection,
            &s.group_by,
        )
        .map(StreamingAggregatePlan::Grouped);
    }
    let mut calls = Vec::new();
    for item in &s.projection {
        let SelectItem::Expr { expr, .. } = item else {
            return None;
        };
        if !crate::agg::collect_streamable_aggregate_calls(expr, &mut calls) {
            return None;
        }
    }
    // No aggregate anywhere means this is not an aggregate query at all (one
    // output row per table row) — never a streaming-fold candidate.
    if calls.is_empty() {
        return None;
    }
    let specs = calls
        .iter()
        .map(|call| crate::plan_dist::partial_aggregate_for_call(table, call))
        .collect::<Option<Vec<_>>>()?;
    Some(StreamingAggregatePlan::Scalar { calls, specs })
}

/// Finalize each scalar spec's streamed partial state into the aggregate's
/// SQL-visible value, in spec order.
fn finalize_scalar_streaming_aggregates(
    states: Vec<Vec<ScannedRow>>,
    specs: &[crate::PartialAggregateSpec],
) -> Result<Vec<Datum>, ExecError> {
    states
        .into_iter()
        .zip(specs)
        .map(|(state, spec)| {
            let finalized = crate::scanner::finalize_partial_aggregate_rows(state, spec)?;
            let [ScannedRow { row, .. }] = finalized.as_slice() else {
                return Err(invalid_scalar_aggregate_shape());
            };
            let [value] = row.as_slice() else {
                return Err(invalid_scalar_aggregate_shape());
            };
            Ok(value.clone())
        })
        .collect()
}

fn invalid_scalar_aggregate_shape() -> ExecError {
    ExecError::Unsupported("scalar partial aggregate produced an invalid merged shape".into())
}

/// Match a FROM that is exactly one ordinary local base table.
///
/// CTE, view, virtual-catalog, sharded, and foreign relations all resolve
/// through their own scan paths, so they deliberately return `None` here.
fn single_local_base_table(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    s: &SelectStmt,
    ctes: &crate::cte::CteContext,
) -> Result<Option<(Table, String)>, ExecError> {
    let [
        crabka_pgparser::ast::TableExpr::Table {
            name,
            only,
            alias,
            columns: None,
            sample: None,
            ..
        },
    ] = s.from.as_slice()
    else {
        return Ok(None);
    };
    if name.schema.is_none() && ctes.lookup(&name.name).is_some() {
        return Ok(None);
    }
    let name = &resolve_relation(catalog_kv, resolution, name, SchemaDisposition::Reference)?;
    if is_virtual_relation(name) {
        return Ok(None);
    }
    match crabka_pgcatalog::get_view(catalog_kv, name) {
        Ok(_) => return Ok(None),
        Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) => {}
        Err(error) => return Err(error.into()),
    }
    let table = match crabka_pgcatalog::get_table(catalog_kv, name) {
        Ok(table) => table,
        Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) => return Ok(None),
        Err(error) => return Err(error.into()),
    };
    // An unpopulated materialized view is an error to read, and the pushdowns
    // are exactly where that would go unnoticed: a fold over the row space
    // never opens the general scan path, so `count(*)` would answer zero for a
    // relation the general path refuses.
    require_populated(&table)?;
    // A partitioned parent owns no rows of its own: the streaming fold would
    // read its empty row space and answer for the whole hierarchy.
    if table.sharded
        || table.foreign.is_some()
        || crate::partition::is_partitioned(catalog_kv, name)?
        || reads_inheritance_children(catalog_kv, *only, name)?
    {
        return Ok(None);
    }
    let qualifier = alias.clone().unwrap_or_else(|| table.name.name.clone());
    Ok(Some((table, qualifier)))
}

/// Whether reading `name` here means reading rows this relation does not
/// physically hold — an inheritance parent named without `ONLY`.
///
/// The aggregate pushdowns fold over exactly one relation's row space, so a
/// parent whose children hold rows would report its own rows only, while a
/// plain `SELECT` over the same FROM returns the whole tree. `ONLY` asks for
/// just the parent's rows, which is what the pushdown already computes.
///
/// The wire path's streaming cursor asks it for the same reason: it scans one
/// relation's row space too, so a parent named without `ONLY` is a shape it
/// cannot serve.
pub(crate) fn reads_inheritance_children(
    catalog_kv: &dyn Kv,
    only: bool,
    name: &crabka_pgcatalog::RelationName,
) -> Result<bool, ExecError> {
    if only {
        return Ok(false);
    }
    // The cheap form on purpose: the answer is a boolean, and every read of an
    // ordinary childless relation asks it. `children_of` would decode a name
    // list to throw it away.
    crate::inheritance::has_children(catalog_kv, name)
}

/// Match a FROM that is exactly one sharded base table.
///
/// CTE, view, virtual-catalog, local, and foreign relations all resolve
/// through their own scan paths, so they deliberately return `None` here, and
/// so does a relation that does not exist at all, whose undefined-table
/// error surfaces from the materializing path instead.
fn single_sharded_base_table(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    s: &SelectStmt,
    ctes: &crate::cte::CteContext,
) -> Result<Option<(Table, String)>, ExecError> {
    let [
        crabka_pgparser::ast::TableExpr::Table {
            name,
            only,
            alias,
            columns: None,
            sample: None,
            ..
        },
    ] = s.from.as_slice()
    else {
        return Ok(None);
    };
    if name.schema.is_none() && ctes.lookup(&name.name).is_some() {
        return Ok(None);
    }
    let name = &resolve_relation(catalog_kv, resolution, name, SchemaDisposition::Reference)?;
    if is_virtual_relation(name) {
        return Ok(None);
    }
    match crabka_pgcatalog::get_view(catalog_kv, name) {
        Ok(_) => return Ok(None),
        Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) => {}
        Err(error) => return Err(error.into()),
    }
    let table = match crabka_pgcatalog::get_table(catalog_kv, name) {
        Ok(table) => table,
        Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) => return Ok(None),
        Err(error) => return Err(error.into()),
    };
    require_populated(&table)?;
    if !table.sharded
        || table.foreign.is_some()
        || reads_inheritance_children(catalog_kv, *only, name)?
    {
        return Ok(None);
    }
    let qualifier = alias.clone().unwrap_or_else(|| table.name.name.clone());
    Ok(Some((table, qualifier)))
}

fn is_plain_partial_aggregate_select(s: &SelectStmt) -> bool {
    if !select_modifiers_allow_partial_aggregate(s) {
        return false;
    }
    let Some(SelectItem::Expr {
        expr: Expr::Func(call),
        ..
    }) = s.projection.last()
    else {
        return false;
    };
    if call.distinct {
        return false;
    }
    matches!(call.name.as_str(), "count" | "sum" | "avg" | "min" | "max")
        && matches!(&call.args, FuncArgs::Star | FuncArgs::Exprs(_))
}

/// Cheap AST pre-filter for the local streaming path: the modifier shape the
/// partial-aggregate model supports, every projection item an expression, and
/// an aggregate call somewhere in the projection. The per-item decomposition in
/// `local_streaming_aggregate_plan` does the precise streamability check.
fn is_streamable_aggregate_select(s: &SelectStmt) -> bool {
    select_modifiers_allow_partial_aggregate(s)
        && s.projection.iter().any(|item| match item {
            SelectItem::Expr { expr, .. } => crate::agg::contains_aggregate(expr),
            SelectItem::Wildcard | SelectItem::QualifiedWildcard(_) => false,
        })
}

/// No `DISTINCT` / `HAVING` / `LIMIT` / `OFFSET`, and an ORDER BY only as the
/// exact ascending echo of the GROUP BY key (the order the grouped partial
/// fold already produces).
fn select_modifiers_allow_partial_aggregate(s: &SelectStmt) -> bool {
    // A window query needs every row the WHERE kept, unaggregated: the window
    // node runs above the grouping, so no partial-aggregate scan may replace it.
    if crate::window::has_window_calls(s) {
        return false;
    }
    // A grouping-set clause folds each row into several groups; the partial
    // aggregate model has one group key per row, so it cannot express it.
    if s.grouping.is_some() {
        return false;
    }
    if s.distinct.dedups() || s.having.is_some() || s.limit.is_some() || s.offset.is_some() {
        return false;
    }
    s.order_by.is_empty()
        || (s.order_by.len() == s.group_by.len()
            && s.order_by
                .iter()
                .zip(&s.group_by)
                .all(|(order, group)| order.asc && order.expr == *group))
}

/// The scan plan for a `SELECT` whose `FROM` is exactly one stored relation.
///
/// Split out of `select_to_relation_with_ctes` rather than written inline: that
/// function sits on the recursion path of a `plpgsql` set-returning function
/// calling itself, and in an unoptimized build every local it holds is
/// multiplied by the recursion depth.
fn single_table_scan_plan(
    read_ctx: &crate::subquery::SubCtx<'_>,
    s: &SelectStmt,
) -> Result<Option<crate::plan_dist::DistributedScanPlan>, ExecError> {
    let [
        crabka_pgparser::ast::TableExpr::Table {
            name,
            alias,
            columns: None,
            sample: None,
            ..
        },
    ] = s.from.as_slice()
    else {
        return Ok(None);
    };
    if name.schema.is_some() || read_ctx.ctes.lookup(&name.name).is_some() {
        return Ok(None);
    }
    let Some(table) = scan_plan_table(read_ctx.catalog_kv, read_ctx.fctx.resolution, name)? else {
        return Ok(None);
    };
    let mut plan = crate::plan_dist::plan_scan(&table, s.filter.as_ref(), &s.projection);
    plan.projection = crate::ProjectionPushdown::All;
    plan.partial_aggregate = None;
    let qualifier = alias.as_deref().unwrap_or(&table.name.name);
    plan.top_k = top_k_pushdown_for_relation(read_ctx, &table, qualifier, s)?;
    Ok(Some(plan))
}

/// The per-range top-K request for a relation proven not to be under row
/// security.
///
/// Top-K truncates the row set inside the scanner, before any policy qual runs,
/// so a restricted relation must not have one. It takes the proof rather than a
/// `&Table` so that is a compile error rather than a review comment;
/// [`crate::rls::sanitize_scan_plan`] strips a top-K at the scan-request
/// construction site as well, since a plan can reach that site from more than
/// one caller.
fn top_k_pushdown_for_relation(
    read_ctx: &crate::subquery::SubCtx<'_>,
    table: &Table,
    qualifier: &str,
    s: &SelectStmt,
) -> Result<Option<crate::TopKSpec>, ExecError> {
    // A statement that reads `tableoid` keeps the full scan. The pushdown below
    // resolves the select list and ORDER BY against a bare `Scope::single`,
    // which has no system column, so it would report the 42703 the ordinary
    // path is about to answer — and its `table.columns[column]` lookup indexes
    // the DECLARED columns by a scope index, which a system column sits one
    // past.
    if crate::scope::wants_tableoid(read_ctx.refs) {
        return Ok(None);
    }
    let Some(unrestricted) =
        crate::rls::UnrestrictedTable::read(&read_ctx.privileges(), &read_ctx.rls(), table)?
    else {
        return Ok(None);
    };
    top_k_pushdown_for_select(unrestricted, qualifier, s)
}

fn top_k_pushdown_for_select(
    unrestricted: crate::rls::UnrestrictedTable<'_>,
    qualifier: &str,
    s: &SelectStmt,
) -> Result<Option<crate::TopKSpec>, ExecError> {
    let table = unrestricted.get();
    // A select-list set-returning function expands each source row into many, so
    // a LIMIT pushed onto the SOURCE scan would cut rows the expansion still owes.
    if !table.sharded
        || !is_top_k_candidate(s)
        || crate::srf::projection_contains_srf(&s.projection)
    {
        return Ok(None);
    }
    if crate::plan_dist::strict_predicate_for_filter(table, s.filter.as_ref()).is_err() {
        return Ok(None);
    }
    // A correlated select-list or ORDER BY expression lives in a hidden column
    // materialized ABOVE the scan, which the base-table scope this pushdown
    // resolves against does not carry. Such a query keeps the full scan.
    if select_mentions_correlated_marker(s) {
        return Ok(None);
    }
    let scope = Scope::single(table, qualifier);
    let (fields, out_exprs, _tys) = resolve_projection(&s.projection, &scope)?;
    let mut order_by = Vec::with_capacity(s.order_by.len());
    for order_item in &s.order_by {
        let order_key = resolve_select_order_key(order_item, &scope, &fields, &out_exprs, false)?;
        let Some(column) = top_k_column_index(&scope, &out_exprs, &order_key)? else {
            return Ok(None);
        };
        let order_column = &table.columns[column];
        if !order_column.not_null || !is_top_k_column_type_supported(order_column.ty) {
            return Ok(None);
        }
        order_by.push(crate::TopKColumn {
            column,
            asc: order_item.asc,
        });
    }
    let limit = u64::try_from(constant_limit(s).expect("candidate has a positive limit"))
        .map_err(|_| ExecError::Unsupported("top-k LIMIT is outside u64 range".into()))?;
    Ok(Some(crate::TopKSpec { order_by, limit }))
}

fn is_top_k_candidate(s: &SelectStmt) -> bool {
    // A window function sees the rows before LIMIT, so a top-k scan that stops
    // early would change its result.
    if crate::window::has_window_calls(s) {
        return false;
    }
    if s.distinct.dedups()
        || !s.group_by.is_empty()
        || s.having.is_some()
        || s.offset.is_some()
        || s.with_ties
        || crate::agg::is_aggregate_query(s)
        || s.order_by.is_empty()
    {
        return false;
    }
    constant_limit(s).is_some_and(|limit| limit > 0)
}

/// The `LIMIT` as a plain integer constant, or `None` when it is absent or is an
/// expression. Scan pushdown runs before evaluation, so only a literal count can
/// bound the scan; anything else keeps the full-scan path and is applied to the
/// materialized rows.
fn constant_limit(s: &SelectStmt) -> Option<i64> {
    match s.limit.as_ref()? {
        Expr::IntLiteral(text) => text.parse().ok(),
        _ => None,
    }
}

fn top_k_column_index(
    scope: &Scope,
    out_exprs: &[Expr],
    order_key: &SelectOrderKey,
) -> Result<Option<usize>, ExecError> {
    let expr = match order_key {
        SelectOrderKey::Output(index) => &out_exprs[*index],
        SelectOrderKey::SourceExpr(expr) => expr,
    };
    let Expr::Column {
        table: qualifier,
        name,
    } = expr
    else {
        return Ok(None);
    };
    let column = scope.resolve(qualifier.as_deref(), name)?;
    Ok(Some(column))
}

fn is_top_k_column_type_supported(ty: ColumnType) -> bool {
    matches!(ty, ColumnType::Int4 | ColumnType::Int8 | ColumnType::Text)
}

pub(crate) fn table_uses_global_visibility(table: &Table) -> bool {
    table.sharded
}

/// Refuse `SHARDED BY HASH (col)` on a column whose values the shard-key hasher
/// cannot turn into bytes, at CREATE TABLE rather than at every INSERT.
///
/// A missing hash column is *not* reported here, because the catalog's own
/// validation raises the undefined-column error for that.
fn ensure_hash_shard_key_types_are_supported(
    columns: &[Column],
    sharding: Option<&crabka_pgcatalog::ShardingStrategy>,
) -> Result<(), ExecError> {
    let Some(crabka_pgcatalog::ShardingStrategy::Hash(hash)) = sharding else {
        return Ok(());
    };
    for column in hash
        .columns
        .iter()
        .filter_map(|name| columns.iter().find(|column| column.name == *name))
    {
        if !hash_shard_key_type_is_supported(column.ty) {
            return Err(ExecError::Unsupported(format!(
                "hash shard key column \"{}\" of type {} is not supported",
                column.name,
                column.ty.name()
            )));
        }
    }
    Ok(())
}

/// The column types [`hash_bucket_for_row`] can hash: those stored as an
/// `Int4`, `Int8`, `Text`, or `Bytea` datum. Everything else would fail on the
/// write path, so a table is never created with such a key: `boolean`,
/// `double precision`, `numeric`, the date/time types, `jsonb`, and arrays.
fn hash_shard_key_type_is_supported(ty: ColumnType) -> bool {
    matches!(
        ty,
        ColumnType::Int4
            | ColumnType::Int8
            | ColumnType::Text
            | ColumnType::Varchar(_)
            | ColumnType::Char(_)
            | ColumnType::Bytea
            | ColumnType::Uuid
            | ColumnType::Regclass
    )
}

fn hash_sharding_from_ast(
    sharding: &crabka_pgparser::ast::ShardingSpec,
) -> Result<crabka_pgcatalog::ShardingStrategy, ExecError> {
    match sharding {
        crabka_pgparser::ast::ShardingSpec::Hash(hash) => {
            // Redundant for SQL input: the grammar refuses a `SHARDED BY HASH`
            // list of any length but one outright (42601), so this never fires
            // for a parsed statement. It is the gate for the callers that build
            // the AST directly, and it matches the arity the row encoder in
            // [`hash_bucket_for_row`] has an encoding for — one column, the
            // only arity that agrees with the route the gateway computes.
            if hash.columns.len() != 1 {
                return Err(ExecError::Unsupported(
                    "hash sharding requires exactly one column".into(),
                ));
            }
            if hash.buckets == 0 || !hash.buckets.is_power_of_two() {
                return Err(ExecError::Unsupported(
                    "hash sharding bucket count must be a power of two".into(),
                ));
            }
            Ok(crabka_pgcatalog::ShardingStrategy::Hash(
                crabka_pgcatalog::HashSharding {
                    columns: hash.columns.clone(),
                    buckets: hash.buckets,
                    co_location_group: hash.co_location_group.clone(),
                },
            ))
        }
    }
}

/// Run a SELECT to a `Relation` with an already-evaluated CTE scope. `WITH`
/// belongs to `QueryExpr`; this function handles the SELECT body under that scope.
pub(crate) fn select_to_relation_with_ctes(
    read_ctx: &crate::subquery::SubCtx<'_>,
    s: &SelectStmt,
) -> Result<Relation, ExecError> {
    // The whole-row references of THIS statement, which narrow the hidden
    // liveness markers its outer joins carry. Established before anything below
    // reads a relation, and replacing whatever the caller reached here with, so
    // a view body, a derived table or a correlated subquery is measured by its
    // own text and never by the text that reached it — a narrower set inherited
    // from an enclosing statement would be a marker missing where this one reads
    // it.
    //
    // Read off the statement as written rather than as rewritten below: subquery
    // resolution only folds subqueries into constants and internally qualified
    // markers, so the references it leaves are a subset of these, and collecting
    // first is what puts every read path under this statement's own set.
    let refs = crate::scope::StatementRefs::of_select(s);
    let read_ctx = &read_ctx.with_refs(&refs);
    let catalog_kv = read_ctx.catalog_kv;
    let ctes = read_ctx.ctes;
    let ctx = read_ctx.eval_ctx;
    let fctx = read_ctx.fctx;
    reject_nested_relation_locking(s)?;

    // Correlated WHERE subqueries need the current source row, while
    // uncorrelated ones must retain SP34's once-only folding. Only queries whose
    // WHERE contains a subquery pay for the schema description used to tell the
    // two apart.
    let PlannedSubqueries {
        select: resolved,
        correlated_filter: correlated,
        initplans,
        scalar_lookups,
        row_exprs,
    } = resolve_select_subqueries(read_ctx, s)?;
    let s = &resolved;
    crate::window::reject_misplaced_calls(s)?;
    crate::grouping::reject_misplaced_calls(s)?;
    let relation = if s.from.is_empty() {
        reject_from_less_wildcard(&s.projection)?;
        Relation {
            scope: Scope::empty(),
            rows: vec![vec![]],
        }
    } else {
        // SP40 Task 14: when the FROM is EXACTLY one foreign base table, extract
        // `_partition`/`_offset` bounds from the WHERE and push them into the
        // scan. The WHERE is still applied below, so this only ever reads less —
        // it never changes the result set.
        let pushed = if is_single_foreign_table(catalog_kv, &s.from, ctes, fctx) {
            Some(extract_scan_bounds(s.filter.as_ref()))
        } else {
            None
        };
        // Each of the three folds the aggregate against a bare `Scope::single`,
        // which carries no system column. A statement that reads `tableoid`
        // takes the ordinary read path instead — the only one that builds the
        // column — rather than reporting the 42703 that path is about to
        // answer.
        if !crate::scope::wants_tableoid(read_ctx.refs) {
            if let Some(relation) = try_execute_partial_aggregate_pushdown(read_ctx, s)? {
                return Ok(relation);
            }
            if let Some(relation) = try_execute_local_streaming_aggregate(read_ctx, s)? {
                return Ok(relation);
            }
            if let Some(relation) = try_execute_local_join_count(read_ctx, s)? {
                return Ok(relation);
            }
        }
        let scan_plan = single_table_scan_plan(read_ctx, s)?;
        build_from(
            read_ctx,
            &s.from,
            pushed.as_ref(),
            scan_plan.as_ref(),
            s.filter.as_ref(),
        )?
    };
    let mut binder = correlated.then(|| {
        LateralBinder::new(catalog_kv, read_ctx.fctx.resolution, read_ctx.ctes)
            .with_initplans(initplans)
            .with_scalar_lookups(scalar_lookups)
    });
    // The uncorrelated filter is the same expression for every row, so its
    // column references are resolved once here instead of once per row.
    let bound_filter = if binder.is_none() {
        crate::bind::bind_optional(s.filter.as_ref(), &relation.scope)?
    } else {
        None
    };
    let mut kept = Vec::new();
    for row in &relation.rows {
        let matches = if let Some(binder) = &mut binder {
            row_matches_correlated(read_ctx, s.filter.as_ref(), &relation.scope, row, binder)?
        } else {
            row_matches(
                bound_filter.as_ref().map(crate::bind::BoundExpr::expr),
                &relation.scope,
                row,
                ctx,
            )?
        };
        if matches {
            kept.push(row.clone());
        }
    }
    // A correlated select-list / ORDER BY / DISTINCT ON expression is evaluated
    // here, once per surviving source row, and parked in a hidden column. The
    // clauses below then see plain column references and run unchanged.
    let mut scope = relation.scope;
    if let Some(row_exprs) = row_exprs {
        materialize_correlated_row_exprs(read_ctx, row_exprs, &mut scope, &mut kept)?;
    }
    // Window functions run above WHERE/GROUP BY/HAVING and below DISTINCT/ORDER
    // BY/LIMIT, so they own the whole projection shape for the queries that use
    // them (including the grouped ones).
    let (fields, out_exprs, tys) = if crate::window::has_window_calls(s) {
        let (fields, tys, rows) = crate::window::execute(s, &scope, kept, ctx)?;
        return Ok(Relation {
            scope: projected_scope(&fields, &tys),
            rows,
        });
    } else {
        resolve_projection(&s.projection, &scope)?
    };
    let out_scope = projected_scope(&fields, &tys);
    let rows = if crate::grouping::is_grouping_query(s) {
        crate::srf::reject_in_aggregate(&out_exprs)?;
        crate::grouping::aggregate_rows(s, &scope, kept, ctx)?
    } else {
        project_rows_ordered(s, &scope, &fields, &out_exprs, kept, ctx)?
    };
    Ok(Relation {
        scope: out_scope,
        rows,
    })
}

/// A FROM item with any lateral reference to `outer` replaced by a NULL of that
/// column's type, so a schema-only describe can resolve it. Non-lateral items
/// pass through untouched.
fn lateral_schema_item(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    ctes: &crate::cte::CteContext,
    te: &crabka_pgparser::ast::TableExpr,
    outer: &Scope,
) -> crabka_pgparser::ast::TableExpr {
    if !is_lateral_item(te, outer) {
        return te.clone();
    }
    let nulls = vec![Datum::Null; outer.width()];
    LateralBinder::new(catalog_kv, resolution, ctes)
        .bind(te, outer, &nulls)
        .0
}

pub(crate) fn build_from_schema_with_ctes(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    from: &[crabka_pgparser::ast::TableExpr],
    ctes: &crate::cte::CteContext,
) -> Result<Relation, ExecError> {
    build_from_schema_described(catalog_kv, resolution, from, ctes, None, None)
}

pub(crate) fn build_from_schema_with_ctes_and_context(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    from: &[crabka_pgparser::ast::TableExpr],
    ctes: &crate::cte::CteContext,
    ctx: Option<&crate::clock::EvalCtx>,
) -> Result<Relation, ExecError> {
    build_from_schema_described(catalog_kv, resolution, from, ctes, ctx, None)
}

/// The describe walk for one SELECT, which is therefore able to describe the
/// hidden `tableoid` that statement reads.
///
/// Describe and execute must agree about the column: a describe that omits it
/// answers 42703 for a statement the read path would have answered, which is
/// what `SELECT tableoid …` did under the extended protocol, inside `CREATE
/// VIEW`, inside `CREATE TABLE AS` and in a set-op branch, while the identical
/// text ran under the simple protocol.
pub(crate) fn build_from_schema_of_select(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    select: &SelectStmt,
    ctes: &crate::cte::CteContext,
) -> Result<Relation, ExecError> {
    let refs = crate::scope::StatementRefs::of_select(select);
    build_from_schema_described(
        catalog_kv,
        resolution,
        &select.from,
        ctes,
        None,
        Some(&refs),
    )
}

/// The describe walk, told which statement it is describing.
///
/// `refs` is the very thing the read path carries on its
/// [`crate::subquery::SubCtx`], and means the same here: `None` is "no statement
/// in hand", and then a stored relation is described without its `tableoid`
/// exactly as it is scanned without one. The plpgsql record and FOR-loop scopes
/// are the callers with nothing to pass.
fn build_from_schema_described(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    from: &[crabka_pgparser::ast::TableExpr],
    ctes: &crate::cte::CteContext,
    ctx: Option<&crate::clock::EvalCtx>,
    refs: Option<&crate::scope::StatementRefs>,
) -> Result<Relation, ExecError> {
    let mut iter = from.iter();
    let first = iter
        .next()
        .ok_or_else(|| ExecError::Unsupported("build_from_schema on empty FROM".into()))?;
    let mut acc =
        build_table_expr_schema_with_ctes(catalog_kv, resolution, first, ctes, ctx, refs)?;
    for te in iter {
        // A lateral item references the accumulated columns, which no schema
        // description of it on its own can resolve. Substituting NULLs of the
        // right types leaves an item the ordinary describe understands and whose
        // output columns are unchanged.
        let te = &lateral_schema_item(catalog_kv, resolution, ctes, te, &acc.scope);
        let next = build_table_expr_schema_with_ctes(catalog_kv, resolution, te, ctes, ctx, refs)?;
        // Schema-only: no rows, so no ON predicate is ever evaluated — a default
        // (UTC/epoch) eval context is correct here.
        acc = join_relations(
            acc,
            next,
            crabka_pgparser::ast::JoinKind::Cross,
            &crabka_pgparser::ast::JoinConstraint::None,
            &crate::clock::EvalCtx::test_default(),
            crate::join::JoinPolicy::default(),
        )?;
    }
    Ok(acc)
}

fn build_table_expr_schema_with_ctes(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    te: &crabka_pgparser::ast::TableExpr,
    ctes: &crate::cte::CteContext,
    ctx: Option<&crate::clock::EvalCtx>,
    refs: Option<&crate::scope::StatementRefs>,
) -> Result<Relation, ExecError> {
    use crabka_pgparser::ast::TableExpr;
    match te {
        TableExpr::Table {
            name,
            alias,
            columns,
            ..
        } => {
            if let Some(names) = columns {
                let base = build_table_expr_schema_with_ctes(
                    catalog_kv,
                    resolution,
                    &TableExpr::Table {
                        name: name.clone(),
                        only: false,
                        alias: alias.clone(),
                        columns: None,
                        sample: None,
                    },
                    ctes,
                    ctx,
                    refs,
                )?;
                let qualifier = alias.clone().unwrap_or_else(|| name.to_string());
                return crate::values::requalify_derived(base, &qualifier, &Some(names.clone()));
            }
            if name.schema.is_none()
                && let Some(rel) = ctes.lookup(&name.name)
            {
                let qualifier = alias.as_deref().unwrap_or(&name.name);
                let mut rel = crate::cte::requalify_cte(rel, qualifier);
                rel.rows.clear();
                return Ok(rel);
            }
            if name.schema.is_none()
                && let Some(runtime) = ctx.and_then(|ctx| ctx.transition_relations.as_ref())
                && let Some(transition) = runtime
                    .lock()
                    .expect("transition relation mutex")
                    .get(&name.name)
                    .cloned()
            {
                let qualifier = alias.as_deref().unwrap_or(&name.name);
                return Ok(Relation {
                    scope: Scope {
                        columns: transition
                            .columns
                            .into_iter()
                            .map(|(name, ty)| ColumnBinding {
                                exposure: Exposure::Output,
                                qualifier: Some(qualifier.to_string()),
                                name,
                                ty,
                            })
                            .collect(),
                    },
                    rows: Vec::new(),
                });
            }
            let name =
                &resolve_relation(catalog_kv, resolution, name, SchemaDisposition::Reference)?;
            if let Some(rel) = virtual_catalog_relation_schema(name, alias.as_deref()) {
                return Ok(rel);
            }
            match crabka_pgcatalog::get_view(catalog_kv, name) {
                Ok(view) => {
                    let qualifier = alias.as_deref().unwrap_or(&view.name.name);
                    return Ok(Relation {
                        scope: Scope {
                            columns: view
                                .columns
                                .iter()
                                .map(|column| ColumnBinding {
                                    exposure: Exposure::Output,
                                    qualifier: Some(qualifier.to_string()),
                                    name: column.name.clone(),
                                    ty: column.ty,
                                })
                                .collect(),
                        },
                        rows: Vec::new(),
                    });
                }
                Err(crabka_pgcatalog::CatalogError::UndefinedTable(_)) => {}
                Err(error) => return Err(error.into()),
            }
            let t = crabka_pgcatalog::get_table(catalog_kv, name).map_err(|error| {
                open_wrong_kind(catalog_kv, name).unwrap_or_else(|| error.into())
            })?;
            let qualifier = alias.as_deref().unwrap_or(&t.name.name);
            // The one arm that gets the system column. A view, a CTE, a derived
            // table, a VALUES list and a virtual catalog relation all return
            // above without one, which is what makes `SELECT tableoid FROM v`
            // the 42703 `PostgreSQL` raises rather than a column of nulls.
            let mut scope = Scope::single(&t, qualifier);
            if crate::scope::wants_tableoid(refs) {
                scope.push_tableoid(qualifier);
            }
            Ok(Relation {
                scope,
                rows: Vec::new(),
            })
        }
        TableExpr::Join {
            left,
            right,
            kind,
            constraint,
        } => {
            let l =
                build_table_expr_schema_with_ctes(catalog_kv, resolution, left, ctes, ctx, refs)?;
            let right = &lateral_schema_item(catalog_kv, resolution, ctes, right, &l.scope);
            let r =
                build_table_expr_schema_with_ctes(catalog_kv, resolution, right, ctes, ctx, refs)?;
            // Schema-only: no rows, so no ON predicate is ever evaluated.
            join_relations(
                l,
                r,
                *kind,
                constraint,
                &crate::clock::EvalCtx::test_default(),
                crate::join::JoinPolicy::default(),
            )
        }
        TableExpr::Derived {
            subquery,
            alias,
            columns,
            ..
        } => {
            let fields = crate::query::describe_query_expr_with_ctes(
                catalog_kv, resolution, subquery, ctes,
            )?;
            let bindings = fields
                .iter()
                .map(|f| {
                    Ok(ColumnBinding {
                        exposure: Exposure::Output,
                        qualifier: None,
                        name: f.name.clone(),
                        ty: column_type_from_oid(f.type_oid)?,
                    })
                })
                .collect::<Result<_, ExecError>>()?;
            let inner = Relation {
                scope: Scope { columns: bindings },
                rows: Vec::new(),
            };
            crate::values::requalify_derived(inner, alias, columns)
        }
        TableExpr::Function {
            functions,
            with_ordinality,
            rows_from,
            alias,
            column_aliases,
            ..
        } => {
            if functions.len() == 1
                && let Some((_routine, columns)) =
                    crate::routine::plpgsql_table_function_schema(catalog_kv, &functions[0])?
            {
                return crate::srf::user_function_relation(
                    &functions[0].name,
                    columns,
                    Vec::new(),
                    *with_ordinality,
                    alias.as_deref(),
                    column_aliases,
                    functions[0].column_defs.as_deref(),
                );
            }
            crate::srf::from_item_schema(
                functions,
                *with_ordinality,
                *rows_from,
                alias.as_deref(),
                column_aliases,
            )
        }
        TableExpr::JsonTable(table) => crate::jsontable::from_item_schema(table),
    }
}

fn requalify_view_relation(
    mut relation: Relation,
    view: &crabka_pgcatalog::View,
    qualifier: &str,
) -> Result<Relation, ExecError> {
    if relation.scope.width() != view.columns.len() {
        return Err(ExecError::Unsupported(
            "stored view definition does not match its catalog schema".into(),
        ));
    }
    for (binding, column) in relation.scope.columns.iter_mut().zip(&view.columns) {
        binding.qualifier = Some(qualifier.to_string());
        binding.name.clone_from(&column.name);
        binding.ty = column.ty;
    }
    Ok(relation)
}

pub(crate) const PG_CATALOG_NAMESPACE_OID: i32 = 11;
pub(crate) const INFORMATION_SCHEMA_NAMESPACE_OID: i32 = 13_370;
pub(crate) const PUBLIC_NAMESPACE_OID: i32 = 2200;
/// The database name a session falls back to when nothing told it one.
///
/// A session opened over the wire takes its name from the startup packet, and
/// that is the name every catalog projection answers with. This constant is
/// only the floor for a session that never saw a startup packet: a planning
/// context, a unit test, or an embedded caller. It is `PostgreSQL`'s own
/// `initdb` default so those contexts read the way a fresh cluster does.
///
/// Nothing may compare a written name against this constant. The question
/// "does this name mean the database I am in?" is a question about the
/// session, answered by [`crate::clock::EvalCtx::database`]; asking it of a
/// constant made `REINDEX DATABASE <the open database>` fail and
/// `postgres.public.t` resolve locally from every database at once.
pub(crate) const DEFAULT_DATABASE: &str = "postgres";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
struct BuiltinTypeRow {
    oid: i32,
    name: &'static str,
    len: i16,
    category: &'static str,
    /// `pg_type.typelem`: the element type of an array type, 0 for a scalar.
    elem: i32,
    /// `pg_type.typarray`: the array type over a scalar, 0 for an array type
    /// and for the scalars crabka has no array type for (`varchar`, `char(n)`,
    /// `regclass`). [`crabka_pgtypes::ElemType::from_column_type`] refuses
    /// those, so a pointer at an absent row would be worse than a report of
    /// none.
    array: i32,
}

/// `pg_type.oid` of `_timetz`. `ElemType` has no `timetz` variant, so crabka
/// cannot build a `timetz[]` value, but `timetz.typarray` still has to resolve
/// — the same position `_inet` and `_money` are in. `crabka_pgtypes::oids` has
/// no constant for an array type it cannot construct.
const TIMETZ_ARRAY_OID: i32 = 1270;

/// `pg_type.oid` of `_int2vector`, which is in that same position.
const INT2VECTOR_ARRAY_OID: i32 = 1006;

fn virtual_catalog_relation(
    catalog_kv: &dyn Kv,
    name: &crabka_pgcatalog::RelationName,
    alias: Option<&str>,
    ctx: &crate::clock::EvalCtx,
) -> Result<Option<Relation>, ExecError> {
    let Some(table) = virtual_table(&virtual_lookup_key(name)) else {
        return Ok(None);
    };
    let rows = virtual_catalog_rows(catalog_kv, table, ctx)?;
    Ok(Some(Relation {
        scope: Scope::single(&virtual_catalog_table(table), alias.unwrap_or(&name.name)),
        rows,
    }))
}

fn virtual_catalog_relation_schema(
    name: &crabka_pgcatalog::RelationName,
    alias: Option<&str>,
) -> Option<Relation> {
    let key = virtual_lookup_key(name);
    let table = virtual_table(&key)?;
    Some(Relation {
        scope: Scope::single(&virtual_catalog_table(table), alias.unwrap_or(&name.name)),
        rows: Vec::new(),
    })
}

/// The ordinary local relation a single-item `FROM` names, or `None` when it is
/// anything a scan plan cannot be built over (a foreign table, or no relation
/// at all).
fn scan_plan_table(
    catalog_kv: &dyn Kv,
    resolution: &crate::relname::ResolutionScope,
    reference: &crabka_pgparser::ast::RelationRef,
) -> Result<Option<Table>, ExecError> {
    let name = resolve_relation(
        catalog_kv,
        resolution,
        reference,
        SchemaDisposition::Reference,
    )?;
    Ok(crabka_pgcatalog::get_table(catalog_kv, &name)
        .ok()
        .filter(|table| table.foreign.is_none()))
}

/// The key the virtual catalog relations are held under: a bare name for
/// anything in `pg_catalog`, and `schema.name` elsewhere. This is how
/// `information_schema.tables` has always been spelled here.
fn virtual_lookup_key(name: &crabka_pgcatalog::RelationName) -> String {
    if name.schema == crate::search_path::PG_CATALOG {
        name.name.clone()
    } else {
        format!("{}.{}", name.schema, name.name)
    }
}

/// True when `name` denotes a relation the engine synthesises rather than
/// stores. The resolver consults this alongside the catalog, so an unqualified
/// `pg_class` finds the catalog relation through the implicit `pg_catalog`
/// entry exactly as `PostgreSQL` does. This includes the case where a user
/// relation of the same name exists in `public`, which the oracle confirms does
/// not shadow it.
pub(crate) fn is_virtual_relation(name: &crabka_pgcatalog::RelationName) -> bool {
    virtual_table(&virtual_lookup_key(name)).is_some()
}

/// The relation kind a synthesised relation answers to, in the word
/// `PostgreSQL` writes in a message about it, or `None` when the engine
/// synthesises no relation of that name.
///
/// The split is the same one [`virtual_pg_class_properties`] already projects
/// into `pg_class.relkind`, so a relation cannot be a table to a refusal and a
/// view to `\d`. It carries more than the word: measured over all 71
/// synthesised relations, `relkind = 'r'` holds exactly for the ones
/// `PostgreSQL` has pinned, and pinned is what its `allowSystemTableMods` guard
/// tests. So a synthesised *table* is a system catalog and a synthesised *view*
/// is an ordinary view — the two answers this whole family of statements needs.
pub(crate) fn virtual_relation_kind(name: &crabka_pgcatalog::RelationName) -> Option<&'static str> {
    let relation = virtual_table(&virtual_lookup_key(name))?;
    Some(match virtual_pg_class_properties(relation, 0).0 {
        "v" => "view",
        _ => "table",
    })
}

/// The synthesised relation `name` denotes, as the `Table` record every other
/// relation would be read from, or `None` when the engine synthesises none of
/// that name.
///
/// A statement that only needs the column list — `COMMENT ON COLUMN`, a
/// `COPY`'s target list — can then treat a synthesised relation exactly as it
/// treats a stored one, instead of carrying a second spelling for it.
pub(crate) fn virtual_relation_table(
    name: &crabka_pgcatalog::RelationName,
) -> Option<crabka_pgcatalog::Table> {
    virtual_table(&virtual_lookup_key(name)).map(virtual_catalog_table)
}

/// True when `name` is a synthesised relation `PostgreSQL` protects with
/// `allowSystemTableMods` — every synthesised relation whose kind is `table`.
///
/// Asked before any catalog read, because it needs none: the answer is a
/// property of the name.
fn is_system_catalog(name: &crabka_pgcatalog::RelationName) -> bool {
    virtual_relation_kind(name) == Some("table")
}

/// `PostgreSQL`'s `allowSystemTableMods` refusal, which every statement that
/// would write a system catalog's *definition* reports.
///
/// It is a 42501 rather than a 42809 because `PostgreSQL` words it as a
/// privilege the session does not have, not as a kind mismatch — and it names
/// the relation bare, since the name in the message is the one the statement
/// wrote.
fn system_catalog_refusal(name: &crabka_pgcatalog::RelationName) -> ExecError {
    ExecError::Remote(crabka_pgwire::error::PgError::error(
        "42501",
        format!("permission denied: \"{}\" is a system catalog", name.name),
    ))
}

/// The `allowSystemTableMods` refusal `name` owes, or `None` when it is not a
/// system catalog.
pub(crate) fn system_catalog_wrong_kind(
    name: &crabka_pgcatalog::RelationName,
) -> Option<ExecError> {
    is_system_catalog(name).then(|| system_catalog_refusal(name))
}

fn virtual_table(name: &str) -> Option<&'static str> {
    match name.strip_prefix("pg_catalog.").unwrap_or(name) {
        "pg_namespace" => Some("pg_namespace"),
        "pg_class" => Some("pg_class"),
        "pg_attribute" => Some("pg_attribute"),
        "pg_type" => Some("pg_type"),
        "pg_ts_config" => Some("pg_ts_config"),
        "pg_ts_dict" => Some("pg_ts_dict"),
        "pg_range" => Some("pg_range"),
        "pg_index" => Some("pg_index"),
        "pg_settings" => Some("pg_settings"),
        "pg_prepared_statements" => Some("pg_prepared_statements"),
        "pg_roles" => Some("pg_roles"),
        "pg_user" => Some("pg_user"),
        _ => None,
    }
    .or_else(|| match name.strip_prefix("information_schema.")? {
        "schemata" => Some("information_schema.schemata"),
        "tables" => Some("information_schema.tables"),
        "columns" => Some("information_schema.columns"),
        "triggers" => Some("information_schema.triggers"),
        "triggered_update_columns" => Some("information_schema.triggered_update_columns"),
        _ => None,
    })
    // F-2 owns the rest of the `psql`/ORM introspection surface.
    .or_else(|| crate::catalog_rel::catalog_relation(name))
}

fn virtual_catalog_table(name: &str) -> Table {
    Table {
        id: virtual_relation_oid(name) as u32,
        owner: crabka_pgcatalog::BOOTSTRAP_ROLE.into(),
        name: crabka_pgcatalog::RelationName::new(
            virtual_relation_schema(name),
            virtual_relation_name(name),
        ),
        columns: virtual_catalog_columns(name),
        sharded: false,
        row_security: false,
        force_row_security: false,
        sharding: None,
        foreign: None,
        materialized: None,
        checks: Vec::new(),
    }
}

fn virtual_catalog_columns(name: &str) -> Vec<Column> {
    use ColumnType::{Bool, Int2, Int4, Int8, Text, Timestamptz};
    match name {
        "pg_namespace" => cols(&[
            ("oid", Int4),
            ("nspname", Text),
            // `\dn` reads `nspowner` through `pg_get_userbyid`.
            ("nspowner", Int4),
            ("nspacl", ColumnType::Array(crabka_pgtypes::ElemType::Text)),
        ]),
        // PostgreSQL 18.4's column set, in catalog order: `psql`'s `\d` reads
        // relpersistence/relreplident/relchecks/relhasrules/relhastriggers/
        // relrowsecurity/relispartition/reloftype/reltablespace/relam by name,
        // and ORMs positionally `SELECT *`.
        "pg_class" => pg_class_columns(),
        "pg_attribute" => pg_attribute_columns(),
        "pg_type" => cols(&[
            ("oid", Int4),
            ("typname", Text),
            ("typlen", Int4),
            ("typcategory", Text),
            ("typnamespace", Int4),
            ("typrelid", Int4),
            // `typtype` is `"char"` (OID 18) in PostgreSQL; Text is the
            // closest synthesized type, same trade-off as `typcategory`.
            ("typtype", Text),
            // `typdelim` is `"char"` in PostgreSQL too. It is the element
            // separator of the array text literal — ',' for every type crabka
            // exposes — and drivers read it when parsing array output.
            ("typdelim", Text),
            // `typelem`/`typarray` are the two halves of the scalar ↔ array
            // link a driver walks to recognize an array OID and to find the
            // array type of a scalar.
            ("typelem", Int4),
            ("typarray", Int4),
            ("typbasetype", Int4),
            // `\d`'s collation column is `attcollation <> typcollation`, so the
            // two have to be derived the same way or every text column would
            // report a collation it does not have.
            ("typcollation", Int4),
        ]),
        "pg_ts_config" => cols(&[
            ("oid", Int4),
            ("cfgname", Text),
            ("cfgnamespace", Int4),
            ("cfgowner", Int4),
            ("cfgparser", Int4),
        ]),
        "pg_ts_dict" => cols(&[
            ("oid", Int4),
            ("dictname", Text),
            ("dictnamespace", Int4),
            ("dictowner", Int4),
            ("dicttemplate", Int4),
            ("dictinitoption", Text),
        ]),
        // PostgreSQL 18 column set, in catalog order. The oid-valued columns
        // use Int4 like every other synthesized catalog oid; the two regproc
        // columns use Text (regproc renders as a function name).
        "pg_range" => cols(&[
            ("rngtypid", Int4),
            ("rngsubtype", Int4),
            ("rngmultitypid", Int4),
            ("rngcollation", Int4),
            ("rngsubopc", Int4),
            ("rngcanonical", Text),
            ("rngsubdiff", Text),
        ]),
        // PostgreSQL 18.4's column set, in catalog order. `\d <table>` reads
        // indisclustered/indisvalid/indisreplident by name and joins
        // `indexrelid`/`indrelid` against `pg_class`.
        "pg_index" => cols(&[
            ("indexrelid", Int4),
            ("indrelid", Int4),
            ("indnatts", Int2),
            ("indnkeyatts", Int2),
            ("indisunique", Bool),
            ("indnullsnotdistinct", Bool),
            ("indisprimary", Bool),
            ("indisexclusion", Bool),
            ("indimmediate", Bool),
            ("indisclustered", Bool),
            ("indisvalid", Bool),
            ("indcheckxmin", Bool),
            ("indisready", Bool),
            ("indislive", Bool),
            ("indisreplident", Bool),
            // PostgreSQL's `int2vector` is a zero-based, space-rendered vector.
            // `OidVector` is crabka's existing representation with those same
            // catalog-facing semantics, including `indkey[0]` subscripting.
            ("indkey", ColumnType::OidVector),
            ("indcollation", Text),
            ("indclass", Text),
            ("indoption", Text),
            ("indexprs", Text),
            ("indpred", Text),
        ]),
        "pg_prepared_statements" => cols(&[
            ("name", Text),
            ("statement", Text),
            ("prepare_time", Timestamptz),
            ("parameter_types", Text),
            ("result_types", Text),
            ("from_sql", Bool),
            ("generic_plans", Int8),
            ("custom_plans", Int8),
        ]),
        "pg_settings" => cols(&[
            ("name", Text),
            ("setting", Text),
            ("unit", Text),
            ("category", Text),
            ("short_desc", Text),
            ("context", Text),
            ("vartype", Text),
            ("source", Text),
            ("min_val", Text),
            ("max_val", Text),
            ("enumvals", Text),
            ("boot_val", Text),
            ("reset_val", Text),
            ("pending_restart", Bool),
        ]),
        // PostgreSQL 18.4's column set, in catalog order — `\du` projects
        // rolinherit/rolconnlimit/rolvaliduntil positionally after the flags.
        "pg_roles" => cols(&[
            ("rolname", Text),
            ("rolsuper", Bool),
            ("rolinherit", Bool),
            ("rolcreaterole", Bool),
            ("rolcreatedb", Bool),
            ("rolcanlogin", Bool),
            ("rolreplication", Bool),
            ("rolconnlimit", Int4),
            ("rolpassword", Text),
            ("rolvaliduntil", Timestamptz),
            ("rolbypassrls", Bool),
            (
                "rolconfig",
                ColumnType::Array(crabka_pgtypes::ElemType::Text),
            ),
            ("oid", Int4),
        ]),
        "pg_user" => cols(&[("usename", Text), ("usesuper", Bool), ("usecreatedb", Bool)]),
        // The full standard projection, in PostgreSQL 18.4's column order. The
        // three `default_character_set_*` columns and `sql_path` are NULL in
        // PostgreSQL too — the standard defines them, PostgreSQL fills none.
        "information_schema.schemata" => cols(&[
            ("catalog_name", Text),
            ("schema_name", Text),
            ("schema_owner", Text),
            ("default_character_set_catalog", Text),
            ("default_character_set_schema", Text),
            ("default_character_set_name", Text),
            ("sql_path", Text),
        ]),
        // Not PostgreSQL's full 12-column list: the five NULL columns between
        // `table_type` and `is_insertable_into`, and the two after it, are not
        // synthesized here, so `is_insertable_into` sits at ordinal 5 rather
        // than 10. Every consumer names the column, and none of the absent ones
        // carries a value for an untyped relation.
        "information_schema.tables" => cols(&[
            ("table_catalog", Text),
            ("table_schema", Text),
            ("table_name", Text),
            ("table_type", Text),
            ("is_insertable_into", Text),
        ]),
        // As with `information_schema.tables`, a subset of PostgreSQL's list —
        // `is_updatable` is its 44th column and is appended here rather than
        // the 37 columns before it being synthesized.
        "information_schema.columns" => cols(&[
            ("table_schema", Text),
            ("table_name", Text),
            ("column_name", Text),
            ("ordinal_position", Int4),
            ("data_type", Text),
            ("is_nullable", Text),
            ("column_default", Text),
            ("is_updatable", Text),
        ]),
        "information_schema.triggers" => cols(&[
            ("trigger_catalog", Text),
            ("trigger_schema", Text),
            ("trigger_name", Text),
            ("event_manipulation", Text),
            ("event_object_catalog", Text),
            ("event_object_schema", Text),
            ("event_object_table", Text),
            ("action_order", Int4),
            ("action_condition", Text),
            ("action_statement", Text),
            ("action_orientation", Text),
            ("action_timing", Text),
            ("action_reference_old_table", Text),
            ("action_reference_new_table", Text),
            ("action_reference_old_row", Text),
            ("action_reference_new_row", Text),
            ("created", Timestamptz),
        ]),
        "information_schema.triggered_update_columns" => cols(&[
            ("trigger_catalog", Text),
            ("trigger_schema", Text),
            ("trigger_name", Text),
            ("event_object_catalog", Text),
            ("event_object_schema", Text),
            ("event_object_table", Text),
            ("event_object_column", Text),
        ]),
        _ => crate::catalog_rel::columns(name),
    }
}

fn cols(defs: &[(&str, ColumnType)]) -> Vec<Column> {
    defs.iter()
        .map(|(name, ty)| Column::new(*name, *ty))
        .collect()
}

