    #[tokio::test]
    async fn sequence_bounds_and_cycle_are_enforced() {
        let engine = SqlEngine::new();
        let mut session = engine.connect();
        session
            .simple_query("CREATE SEQUENCE bounded START WITH 2 MAXVALUE 3 NO CYCLE")
            .await
            .expect("create bounded");
        assert_eq!(
            single_text(
                &session
                    .simple_query("SELECT nextval('bounded')")
                    .await
                    .expect("n1")
            ),
            "2"
        );
        assert_eq!(
            single_text(
                &session
                    .simple_query("SELECT nextval('bounded')")
                    .await
                    .expect("n2")
            ),
            "3"
        );
        let err = session
            .simple_query("SELECT nextval('bounded')")
            .await
            .expect_err("limit");
        assert_eq!(err.code, "2200H");

        session
            .simple_query("CREATE SEQUENCE cyc START WITH 2 MAXVALUE 3 CYCLE")
            .await
            .expect("create cycle");
        assert_eq!(
            single_text(
                &session
                    .simple_query("SELECT nextval('cyc')")
                    .await
                    .expect("c1")
            ),
            "2"
        );
        assert_eq!(
            single_text(
                &session
                    .simple_query("SELECT nextval('cyc')")
                    .await
                    .expect("c2")
            ),
            "3"
        );
        assert_eq!(
            single_text(
                &session
                    .simple_query("SELECT nextval('cyc')")
                    .await
                    .expect("c3")
            ),
            "1"
        );
    }

